INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10367, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指专门出售咖啡、茶饮和简餐，供顾客坐下来享用的店铺。", "primary_collocate": null, "pronunciation": "kā fēi guǎn", "ipa": "kʰa˥ fei˥ kwan˨˩˦", "syllable_count": 3, "sentences": [{"text": "消费者可以在超市或咖啡馆购买咖啡产品。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我常在咖啡馆看书。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家咖啡馆的蛋糕很好吃。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们约在学校旁边的咖啡馆见面。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡馆里坐着很多人，大家都在聊天。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家小咖啡馆工作了两年。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡馆的老板是我的朋友。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们进咖啡馆坐一会儿吧。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个咖啡馆晚上十点才关门。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在咖啡馆里点了一杯热茶。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "咖啡馆", "label": "基本形"}, {"form": "咖啡館", "label": "繁体"}], "register": "中性", "sense_fingerprint": "卖咖啡茶饮简餐、可以坐下来的店", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bca74fc9-b4a9-4068-a7f1-1de1a45d97e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10367, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咖啡馆", "is_correct": true, "explanation": "咖啡馆是卖咖啡、茶饮和简餐的店，正是可以买咖啡产品的地方，与“超市”并列。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不出售咖啡产品，与“购买咖啡产品”的地点不符。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是借阅书籍的场所，不卖咖啡产品。"}, {"text": "银行", "is_correct": false, "explanation": "搭配：“购买咖啡产品”要去卖货的店，银行不卖东西，与“超市或”不搭。"}], "explanations": {"咖啡馆": "咖啡馆是卖咖啡、茶饮和简餐的店，正是可以买咖啡产品的地方，与“超市”并列。", "医院": "语义：医院不出售咖啡产品，与“购买咖啡产品”的地点不符。", "图书馆": "语义：图书馆是借阅书籍的场所，不卖咖啡产品。", "银行": "搭配：“购买咖啡产品”要去卖货的店，银行不卖东西，与“超市或”不搭。"}, "sentence_index": 0, "correct_answer": "咖啡馆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我开车去咖啡馆加了油。", "explanation": "这里应该用〈加油站〉。咖啡馆卖咖啡、茶饮和简餐，不能给汽车加油，加油要去加油站。"}, {"text": "我去咖啡馆理了个发。", "explanation": "这里应该用〈理发店〉。咖啡馆卖咖啡、茶饮和简餐，不提供理发，理发要去理发店。"}, {"text": "我去咖啡馆买了一本词典。", "explanation": "这里应该用〈书店〉。咖啡馆不卖词典，买书要去书店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10367, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "咖啡馆", "is_correct": true, "explanation": "咖啡馆是经营店铺的场所，有老板，与“我的朋友”的句意相符。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的房间，没有老板，不能说“教室的老板”。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是公共服务机构，没有老板。"}, {"text": "派出所", "is_correct": false, "explanation": "语义：派出所是政府机关，没有老板。"}], "explanations": {"咖啡馆": "咖啡馆是经营店铺的场所，有老板，与“我的朋友”的句意相符。", "教室": "语义：教室是上课的房间，没有老板，不能说“教室的老板”。", "图书馆": "语义：图书馆是公共服务机构，没有老板。", "派出所": "语义：派出所是政府机关，没有老板。"}, "sentence_index": 6, "correct_answer": "咖啡馆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚饭我们在咖啡馆吃了一顿火锅。", "explanation": "这里应该用〈餐厅〉。咖啡馆只提供咖啡、茶饮和简餐，吃火锅要去餐厅。"}, {"text": "我去咖啡馆取了两千块钱。", "explanation": "这里应该用〈银行〉。咖啡馆不办理取款，取钱要去银行。"}, {"text": "妈妈去咖啡馆拿了感冒药。", "explanation": "这里应该用〈药店〉。咖啡馆不卖药，拿感冒药要去药店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10367, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我常咖啡馆写作业。", "corrected_sentence": "周末我常在咖啡馆写作业。", "error_description": "“咖啡馆”作地点时前面要加介词“在”，应说“在咖啡馆写作业”，不能省去“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10367, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下雨了，我们先进一咖啡馆坐坐吧。", "corrected_sentence": "下雨了，我们先进一家咖啡馆坐坐吧。", "error_description": "“咖啡馆”前的数词“一”要带量词，应说“一家咖啡馆”，不能说“一咖啡馆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
