INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10374, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指卖出商品或服务的行为。", "primary_collocate": null, "pronunciation": "xiāo shòu", "ipa": "ɕjɑʊ˥ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "全球咖啡豆供应链包括种植、加工、运输、销售等多个环节。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这家公司的销售越来越好。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司做销售工作。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天是羽绒服的销售旺季。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年手机的销售比去年好。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上销售让买东西更方便。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的销售不太好，老板很着急。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她负责公司的销售和服务。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种饮料的销售速度很快，常常一上架就卖完。", "target_word": "销售", "complexity_tier": "T3", "furigana": "zhè zhǒng yǐn liào de xiāo shòu sù dù hěn kuài, cháng cháng yí shàng jià jiù mài wán.", "sentence_source": "generated"}, {"text": "他想学习销售的方法。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "销售", "label": "基本形"}, {"form": "销售额", "label": "复合词"}, {"form": "销售员", "label": "复合词"}, {"form": "銷售", "label": "繁体"}], "register": "中性", "sense_fingerprint": "卖出商品或服务这一行为或工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 3 words above tier T1 (max 2): 羽 (Zipf 3.63), 绒 (Zipf 3.24), 旺季 (Zipf 3.4)']::text[], 'bca74fc9-b4a9-4068-a7f1-1de1a45d97e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10374, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "销售", "is_correct": true, "explanation": "销售是供应链中与种植、加工、运输并列的一个环节，句意相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是供应链中的环节，不能与“种植、加工、运输”并列。"}, {"text": "收入", "is_correct": false, "explanation": "搭配：供应链的环节要用行为名词，“收入”是结果，不能与“种植、加工、运输”并列。"}, {"text": "感情", "is_correct": false, "explanation": "语义：感情不是供应链中的环节。"}], "explanations": {"销售": "销售是供应链中与种植、加工、运输并列的一个环节，句意相符。", "天气": "语义：天气不是供应链中的环节，不能与“种植、加工、运输”并列。", "收入": "搭配：供应链的环节要用行为名词，“收入”是结果，不能与“种植、加工、运输”并列。", "感情": "语义：感情不是供应链中的环节。"}, "sentence_index": 0, "correct_answer": "销售"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用销售切了一块蛋糕。", "explanation": "这里应该用〈刀〉。“销售”指卖东西的行为，不能用来切东西，切蛋糕要用刀。"}, {"text": "他洗了一个销售。", "explanation": "这里应该用〈澡〉。“销售”指卖东西的行为，不能用来洗，应说“洗了一个澡”。"}, {"text": "这件衣服的销售很合身。", "explanation": "这里应该用〈尺码〉。“销售”指卖的行为，不能用来描述衣服的大小，说衣服合身要用尺码。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "销售", "is_correct": true, "explanation": "“这个月的销售”指卖出商品的情况，不好会让老板着急，句意相符。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”不说“好”或“不太好”，不能用于这种评价。"}, {"text": "邮票", "is_correct": false, "explanation": "语义：邮票不能说“这个月的邮票不太好”，也与老板着急的生意情况无关。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：嗓音不能说明生意情况，老板不会因此着急。"}], "explanations": {"销售": "“这个月的销售”指卖出商品的情况，不好会让老板着急，句意相符。", "人口": "搭配：“人口”不说“好”或“不太好”，不能用于这种评价。", "邮票": "语义：邮票不能说“这个月的邮票不太好”，也与老板着急的生意情况无关。", "嗓音": "语义：嗓音不能说明生意情况，老板不会因此着急。"}, "sentence_index": 6, "correct_answer": "销售"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌上放着一些销售。", "explanation": "这里应该用〈商品〉。“销售”指卖的行为，不是可以放在桌上的东西。"}, {"text": "他每天早上喝一杯销售。", "explanation": "这里应该用〈牛奶〉。“销售”指卖的行为，不能喝。"}, {"text": "这家店的销售三天前就关门了。", "explanation": "这里应该用〈店铺〉。“销售”指卖的行为，不是店，关门的应该是店铺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐在超市销售工作。", "corrected_sentence": "我姐姐在超市做销售工作。", "error_description": "“销售”在这里是名词，作“工作”的定语，前面缺少动词“做”。应说“做销售工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们谈成了一销售。", "corrected_sentence": "他们谈成了一笔销售。", "error_description": "“销售”前的数词要带量词“笔”，应说“一笔销售”，不能说“一销售”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
