INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10376, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指某物最初出产于某地。", "primary_collocate": null, "pronunciation": "yuán chǎn", "ipa": "ɥɛn˧˥ ʈʂʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "虽然咖啡豆原产于非洲，但现在它已经成为全球贸易中的重要商品。", "target_word": "原产", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "尽管这种药材原产于青藏高原，但如今市场上的大部分货源都来自人工种植。", "target_word": "原产", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "香蕉原产于东南亚，现在很多地方都有。", "target_word": "原产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶叶原产于中国南方。", "target_word": "原产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土豆原产于南美洲，后来才传到欧洲。", "target_word": "原产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "标签上写着这瓶酒原产于法国。", "target_word": "原产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西红柿原产于美洲，不是中国。", "target_word": "原产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人不知道辣椒原产于哪里。", "target_word": "原产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花原产于北方，南方很少见。", "target_word": "原产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果原产于热带，怕冷。", "target_word": "原产", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原產", "label": "繁体"}], "register": "中性", "sense_fingerprint": "某物最初出产于某地，常用于“原产于”结构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0ed7dbc-a6e5-40ee-911c-fb724370c835') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原产", "is_correct": true, "explanation": "原产：表示咖啡豆最初出产的地方，与“于非洲”搭配，符合句意。"}, {"text": "位于", "is_correct": false, "explanation": "语义：位于说的是事物所处的地点，咖啡豆不会“位于”非洲，这里要说出产地。"}, {"text": "进口", "is_correct": false, "explanation": "配价：进口带宾语（进口咖啡豆），后面不能接“于+地点”，句子不成立。"}, {"text": "出身", "is_correct": false, "explanation": "搭配：出身多指人的出身来源，不能说咖啡豆出身于非洲。"}], "explanations": {"原产": "原产：表示咖啡豆最初出产的地方，与“于非洲”搭配，符合句意。", "位于": "语义：位于说的是事物所处的地点，咖啡豆不会“位于”非洲，这里要说出产地。", "进口": "配价：进口带宾语（进口咖啡豆），后面不能接“于+地点”，句子不成立。", "出身": "搭配：出身多指人的出身来源，不能说咖啡豆出身于非洲。"}, "sentence_index": 0, "correct_answer": "原产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "长江原产于青藏高原。", "explanation": "这里应该用〈发源〉。河流的起点要说“发源”，“原产”只用于物种或物产。"}, {"text": "他原产于北京。", "explanation": "这里应该用〈出生〉。说人出生的地方要用“出生”，“原产”不用于人。"}, {"text": "这句话原产于《论语》。", "explanation": "这里应该用〈出自〉。言语、作品的出处要用“出自”，“原产”只用于物产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原产", "is_correct": true, "explanation": "原产：表示西红柿最初出产的地方，与“于美洲”搭配，符合句意。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：出生用于人或动物，西红柿不能说出生于美洲。"}, {"text": "位于", "is_correct": false, "explanation": "语义：位于说的是事物所处的地点，“西红柿位于美洲”只表示所在，不是出处，句意不通。"}, {"text": "漂泊", "is_correct": false, "explanation": "语义：漂泊指随处流浪，不能描述作物的出处，与“不是中国”的对比也不合。"}], "explanations": {"原产": "原产：表示西红柿最初出产的地方，与“于美洲”搭配，符合句意。", "出生": "搭配：出生用于人或动物，西红柿不能说出生于美洲。", "位于": "语义：位于说的是事物所处的地点，“西红柿位于美洲”只表示所在，不是出处，句意不通。", "漂泊": "语义：漂泊指随处流浪，不能描述作物的出处，与“不是中国”的对比也不合。"}, "sentence_index": 6, "correct_answer": "原产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新中国原产于1949年。", "explanation": "这里应该用〈诞生〉。国家、新事物的成立要说“诞生”，“原产”只用于物种或物产。"}, {"text": "中华文明原产于黄河流域。", "explanation": "这里应该用〈起源〉。文明、思想的开端要说“起源”，“原产”只用于物产的出产地。"}, {"text": "这个词原产于拉丁语。", "explanation": "这里应该用〈来源于〉。词语、说法的出处要说“来源于”，“原产”只用于物产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种竹子的原产于亚洲南部。", "corrected_sentence": "这种竹子原产于亚洲南部。", "error_description": "错误形式：“的原产于”；正确形式：“原产于”。“原产于”是动词性短语，前面加“的”会把它误变成定语结构，句子不通。应直接说“原产于亚洲南部”，或用名词“原产地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种香料原产到印度。", "corrected_sentence": "这种香料原产于印度。", "error_description": "错误形式：“原产到”；正确形式：“原产于”。“原产”后面引出出产地要用介词“于”，“到”表示到达，不能用来表示出处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
