INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10388, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "运输成本是指将货物或人员从一个地点运送到另一个地点所产生的一切费用，包括运费、装卸费、保险费等。", "primary_collocate": null, "pronunciation": "yùn shū chéng běn", "ipa": "yn˥˩ ʂu˥ ʈʂʰɤŋ˧˥ pən˨˩˦", "syllable_count": 4, "sentences": [{"text": "虽然价格会受到天气、运输成本等因素影响，但人们还是愿意为一杯咖啡付出费用。", "target_word": "运输成本", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "运输成本越来越高，东西也越来越贵。", "target_word": "运输成本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司想办法降低运输成本。", "target_word": "运输成本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路远了，运输成本就会变高。", "target_word": "运输成本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走水路的运输成本比飞机低很多。", "target_word": "运输成本", "complexity_tier": "T3", "furigana": "zǒu shuǐlù de yùnshū chéngběn bǐ fēijī dī hěn duō", "sentence_source": "generated"}, {"text": "油价上涨以后，工厂的运输成本也增加了。", "target_word": "运输成本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板要求司机少绕路，这样可以节省运输成本。", "target_word": "运输成本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买得越多，每件东西的运输成本就越低。", "target_word": "运输成本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先算一下运输成本，再决定卖多少钱。", "target_word": "运输成本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小店老板说，山里的运输成本太高了。", "target_word": "运输成本", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "運輸成本", "label": "繁体"}], "register": "中性", "sense_fingerprint": "运输成本|运送货物或人员所产生的全部费用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3bd6d02-7b3a-476c-b3ee-298438b187a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10388, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运输成本", "is_correct": true, "explanation": "运输成本是影响价格的客观因素，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的体态特征，不属于影响商品价格的因素。"}, {"text": "句子", "is_correct": false, "explanation": "语义：句子不能作为影响价格的因素，句意不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“受到……影响”后面应是可以影响价格的客观条件，“心情”不能作为价格的影响因素。"}], "explanations": {"运输成本": "运输成本是影响价格的客观因素，符合句意。", "身高": "语义：身高是人的体态特征，不属于影响商品价格的因素。", "句子": "语义：句子不能作为影响价格的因素，句意不通。", "心情": "搭配：“受到……影响”后面应是可以影响价格的客观条件，“心情”不能作为价格的影响因素。"}, "sentence_index": 0, "correct_answer": "运输成本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这批货有一把运输成本。", "explanation": "这里应该用〈笔〉。“运输成本”是抽象的费用，量词用“笔”；“把”用于有柄的器具，不能用来计量费用。"}, {"text": "司机收下了运输成本。", "explanation": "这里应该用〈运费〉。司机收到的是客户付的运费；“运输成本”指承运方为运送所花的费用，不是收进来的钱。"}, {"text": "这家公司的运输成本很快。", "explanation": "这里应该用〈物流〉。“快”描述的是速度，适用于物流、配送；运输成本是一笔费用，不能说快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10388, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运输成本", "is_correct": true, "explanation": "“节省运输成本”指减少运送过程中的花费，符合句意。"}, {"text": "笑容", "is_correct": false, "explanation": "语义：笑容是表情，不是可以节省的费用或资源。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：友谊是情感关系，不能用“节省”来修饰。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“节省”后面接的应是时间、金钱、资源等，“颜色”不能与之搭配。"}], "explanations": {"运输成本": "“节省运输成本”指减少运送过程中的花费，符合句意。", "笑容": "语义：笑容是表情，不是可以节省的费用或资源。", "友谊": "语义：友谊是情感关系，不能用“节省”来修饰。", "颜色": "搭配：“节省”后面接的应是时间、金钱、资源等，“颜色”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "运输成本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的运输成本会唱歌。", "explanation": "这里应该用〈歌手〉。“会唱歌”描述的是人，运输成本是费用，不能用来形容它会做这种事。"}, {"text": "乘客下车时付了运输成本。", "explanation": "这里应该用〈车费〉。乘客付的是车费；运输成本是承运方花掉的费用，乘客不需要付这笔钱。"}, {"text": "司机把运输成本装进了口袋。", "explanation": "这里应该用〈工资〉。能装进口袋的是工资或收入；运输成本是支出，不能被收进口袋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只运输成本由客户承担。", "corrected_sentence": "这笔运输成本由客户承担。", "error_description": "量词错误：“运输成本”是费用，应用量词“笔”，不能用“只”（“只”多用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "运输成本降来下了，我们的利润也增加了。", "corrected_sentence": "运输成本降下来了，我们的利润也增加了。", "error_description": "补语语序错误：趋向补语应说“降下来”，不能说“降来下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
