INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10389, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指构成事物本质的成分或决定事物成败的原因、条件。", "primary_collocate": null, "pronunciation": "yīn sù", "ipa": "in˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "虽然价格会受到天气、运输成本等因素影响，但人们还是愿意为一杯咖啡付出费用。", "target_word": "因素", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "天气是影响比赛的重要因素。", "target_word": "因素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "健康的生活习惯是长寿的重要因素。", "target_word": "因素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "价格是客人选择商店的主要因素之一。", "target_word": "因素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要考虑各种因素，再做决定。", "target_word": "因素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "性格和环境都是影响孩子的因素。", "target_word": "因素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作的压力是他生病的一个因素。", "target_word": "因素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除了钱以外，还有别的因素让他换了工作。", "target_word": "因素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有去，不安全是最大的因素。", "target_word": "因素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的老师是学生进步的关键因素。", "target_word": "因素", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个因素", "label": "量词"}, {"form": "决定因素", "label": "复合"}], "register": "中性", "sense_fingerprint": "因素|构成事物或决定成败的原因、条件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3bd6d02-7b3a-476c-b3ee-298438b187a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10389, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因素", "is_correct": true, "explanation": "“等因素影响”指列举的各种影响条件，“因素”符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是影响价格的条件，与“天气、运输成本”并列不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不能影响商品价格，句意不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“等……影响”前列举的应是客观条件，“心情”不能与“天气、运输成本”并列。"}], "explanations": {"因素": "“等因素影响”指列举的各种影响条件，“因素”符合句意。", "颜色": "语义：颜色不是影响价格的条件，与“天气、运输成本”并列不通。", "歌曲": "语义：歌曲不能影响商品价格，句意不通。", "心情": "搭配：“等……影响”前列举的应是客观条件，“心情”不能与“天气、运输成本”并列。"}, "sentence_index": 0, "correct_answer": "因素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在路上捡到了一个因素。", "explanation": "这里应该用〈钱包〉。“捡到”指拾得具体物品，“因素”是条件，不能被捡到。"}, {"text": "他把因素借给了朋友。", "explanation": "这里应该用〈书〉。“借给”用于可出借的物品，“因素”是条件，不能借出。"}, {"text": "这些钱的因素是工作。", "explanation": "这里应该用〈来源〉。说钱从哪里来用“来源”；“因素”不能指钱的来源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10389, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "因素", "is_correct": true, "explanation": "“一个因素”指导致生病的一个条件，“因素”符合句意。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶不能导致生病，句意不通。"}, {"text": "外貌", "is_correct": false, "explanation": "语义：“外貌”指人的外表，不能作为导致生病的条件。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不能导致生病，“是……的一个名字”句意不通。"}], "explanations": {"因素": "“一个因素”指导致生病的一个条件，“因素”符合句意。", "花瓶": "语义：花瓶不能导致生病，句意不通。", "外貌": "语义：“外貌”指人的外表，不能作为导致生病的条件。", "名字": "语义：名字不能导致生病，“是……的一个名字”句意不通。"}, "sentence_index": 6, "correct_answer": "因素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次失败有一场因素。", "explanation": "这里应该用〈个〉。“场”用于比赛、活动等，“因素”应用量词“个”。"}, {"text": "这双鞋的因素很舒服。", "explanation": "这里应该用〈鞋子〉。“舒服”形容穿着的感觉，应说“鞋子”；“因素”不能用来形容舒适度。"}, {"text": "他的因素在教室里读书。", "explanation": "这里应该用〈学生〉。“读书”需要有行为能力的人，“因素”是条件，不能做动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10389, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气是影响航班的一棵重要因素。", "corrected_sentence": "天气是影响航班的一个重要因素。", "error_description": "量词错误：“因素”应用量词“个”，“棵”用于植物，不能用于“因素”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10389, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们终于找了出这个因素。", "corrected_sentence": "我们终于找出了这个因素。", "error_description": "趋向补语位置错误：应说“找出了”，“了”要放在补语“出”之后，不能说“找了出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10391, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收获", "is_correct": true, "explanation": "收获：与“付出”相对，指努力后得到的成果，与“为得到结果而花费”意思相反。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论：与“付出”既无反义关系，也无近义关系，词义不相关。"}, {"text": "欢迎", "is_correct": false, "explanation": "欢迎：与“付出”既无反义关系，也无近义关系，词义不相关。"}, {"text": "相信", "is_correct": false, "explanation": "相信：与“付出”既无反义关系，也无近义关系，词义不相关。"}], "correct_answer": "收获", "explanations": {"收获": "收获：与“付出”相对，指努力后得到的成果，与“为得到结果而花费”意思相反。", "讨论": "讨论：与“付出”既无反义关系，也无近义关系，词义不相关。", "欢迎": "欢迎：与“付出”既无反义关系，也无近义关系，词义不相关。", "相信": "相信：与“付出”既无反义关系，也无近义关系，词义不相关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10391, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收获", "is_correct": true, "explanation": "收获：与“付出”相对，指努力后得到的成果，与“为得到结果而花费”意思相反。"}, {"text": "观察", "is_correct": false, "explanation": "观察：与“付出”既无反义关系，也无近义关系，词义不相关。"}, {"text": "生长", "is_correct": false, "explanation": "生长：与“付出”既无反义关系，也无近义关系，词义不相关。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：与“付出”既无反义关系，也无近义关系，词义不相关。"}], "correct_answer": "收获", "explanations": {"收获": "收获：与“付出”相对，指努力后得到的成果，与“为得到结果而花费”意思相反。", "观察": "观察：与“付出”既无反义关系，也无近义关系，词义不相关。", "生长": "生长：与“付出”既无反义关系，也无近义关系，词义不相关。", "旅行": "旅行：与“付出”既无反义关系，也无近义关系，词义不相关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10391, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为了得到某种结果而花费时间、精力或金钱。", "primary_collocate": null, "pronunciation": "fù chū", "ipa": "fu˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "虽然价格会受到天气、运输成本等因素影响，但人们还是愿意为一杯咖啡付出费用。", "target_word": "付出", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他为了考试付出了很多时间。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不付出努力，就很难成功。", "target_word": "付出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她为这份工作付出了五年的青春。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想学好中文，就要付出时间和精力。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们付出很多心血，终于完成了这本书。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了买房子，他们付出了所有的钱。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛前，运动员付出了很多汗水。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要你付出，就会有好结果。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在工作上付出过很多努力，却没有人知道。", "target_word": "付出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "付出了", "label": "体标"}, {"form": "付出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "付出|为得到结果而花费时间、精力或金钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3bd6d02-7b3a-476c-b3ee-298438b187a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10391, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "付出", "is_correct": true, "explanation": "付出（fù chū）：正确答案，指为得到某种结果而花费时间、精力或金钱。"}, {"text": "付诸", "is_correct": false, "explanation": "zhū 与 chū 声母不同（zh/ch），意思是付诸（付诸实践），不是付出。"}, {"text": "浮出", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）声调不同，意思是浮出（露出水面或显现出来）。"}, {"text": "步出", "is_correct": false, "explanation": "bù 与 fù 声母不同（b/f），意思是步出（走出某处）。"}, {"text": "副处", "is_correct": false, "explanation": "chù（第四声）与 chū（第一声）声调不同，意思是副处（副职的级别）。"}], "explanations": {"付出": "付出（fù chū）：正确答案，指为得到某种结果而花费时间、精力或金钱。", "付诸": "zhū 与 chū 声母不同（zh/ch），意思是付诸（付诸实践），不是付出。", "浮出": "fú（第二声）与 fù（第四声）声调不同，意思是浮出（露出水面或显现出来）。", "步出": "bù 与 fù 声母不同（b/f），意思是步出（走出某处）。", "副处": "chù（第四声）与 chū（第一声）声调不同，意思是副处（副职的级别）。"}, "sentence_index": null, "correct_answer": "付出"}, "level_3": {"options": [{"text": "付出", "is_correct": true, "explanation": "付出：为一杯咖啡花钱，符合“愿意为一杯咖啡付出费用”的语境。"}, {"text": "收取", "is_correct": false, "explanation": "语义：“收取”是向别人收钱，句中“人们”是付钱的一方，与句意相反。"}, {"text": "储存", "is_correct": false, "explanation": "语义：“储存”指保存东西，不能说“储存费用”，与“愿意为咖啡”也不连贯。"}, {"text": "抵押", "is_correct": false, "explanation": "搭配：“抵押”的宾语多为房产、财物，不能说“抵押费用”。"}], "explanations": {"付出": "付出：为一杯咖啡花钱，符合“愿意为一杯咖啡付出费用”的语境。", "收取": "语义：“收取”是向别人收钱，句中“人们”是付钱的一方，与句意相反。", "储存": "语义：“储存”指保存东西，不能说“储存费用”，与“愿意为咖啡”也不连贯。", "抵押": "搭配：“抵押”的宾语多为房产、财物，不能说“抵押费用”。"}, "sentence_index": 0, "correct_answer": "付出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议上，他付出了一个很好的方案。", "explanation": "这里应该用〈提出〉。付出 指为得到结果而花费时间、精力或金钱，“方案”是要提出来的，不能说“付出方案”。"}, {"text": "他对这件事付出了全部责任。", "explanation": "这里应该用〈承担〉。付出 指为得到结果而花费时间、精力或金钱，“责任”要用〈承担〉，不能说“付出责任”。"}, {"text": "他拿全部积蓄付出给股市。", "explanation": "这里应该用〈投入〉。“付出给”之后的对象须是接受款项或代价的人，股市不能作为接收方；把钱投到某处要用〈投入〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10391, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "付出", "is_correct": true, "explanation": "付出：把钱花在买房子上，符合“为了买房子，他们付出了所有的钱”的语境。"}, {"text": "捐献", "is_correct": false, "explanation": "语义：“捐献”是无偿送给他人，与“为了买房子”的目的不符，句意矛盾。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：“丢弃”是扔掉，与“为了买房子”的目的矛盾，句意不通。"}, {"text": "雕刻", "is_correct": false, "explanation": "搭配：“雕刻”的宾语是木石等材料，不能说“雕刻了所有的钱”。"}], "explanations": {"付出": "付出：把钱花在买房子上，符合“为了买房子，他们付出了所有的钱”的语境。", "捐献": "语义：“捐献”是无偿送给他人，与“为了买房子”的目的不符，句意矛盾。", "丢弃": "语义：“丢弃”是扔掉，与“为了买房子”的目的矛盾，句意不通。", "雕刻": "搭配：“雕刻”的宾语是木石等材料，不能说“雕刻了所有的钱”。"}, "sentence_index": 6, "correct_answer": "付出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次实验让他付出了很多经验。", "explanation": "这里应该用〈收获〉。付出 指为某种结果花费的时间、精力，得到的经验要用〈收获〉。"}, {"text": "他终于付出了老师的认可。", "explanation": "这里应该用〈得到〉。付出 不能用来说“付出认可”，认可是别人给予的结果，要用〈得到〉。"}, {"text": "他付出了大家的尊重。", "explanation": "这里应该用〈赢得〉。付出 指为某种结果花费的代价，不能说“付出了尊重”；赢得别人的尊重要用〈赢得〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10391, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她明天会为这个节目付出了很多努力。", "corrected_sentence": "她明天会为这个节目付出很多努力。", "error_description": "体标错误：“明天会”表示将来要做的事，不能用表示完成的“了”，应说“会付出很多努力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10391, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些年，他为家庭付出了过很多心血。", "corrected_sentence": "这些年，他为家庭付出过很多心血。", "error_description": "体标错误：“付出了过”中“了”和“过”不能这样连用。表示曾经有过的经历，应说“付出过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
