INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10392, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为获得某种东西或服务而付出的钱。", "primary_collocate": null, "pronunciation": "fèi yòng", "ipa": "feɪ˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "虽然价格会受到天气、运输成本等因素影响，但人们还是愿意为一杯咖啡付出费用。", "target_word": "费用", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "住在这家酒店，每天的费用是三百元。", "target_word": "费用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子上学的费用越来越高。", "target_word": "费用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次旅行的费用，我们三个人一起付。", "target_word": "费用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先交费用，再拿药。", "target_word": "费用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看病的费用太高，他很担心。", "target_word": "费用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机修理的费用是两百块。", "target_word": "费用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "租房的费用里包括水电。", "target_word": "费用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先看一下学校的费用吧。", "target_word": "费用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次出差，坐飞机的费用比坐火车的高。", "target_word": "费用", "complexity_tier": "T3", "furigana": "zhè cì chū chāi, zuò fēijī de fèiyòng bǐ zuò huǒchē de gāo。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔费用", "label": "量词"}, {"form": "医疗费用", "label": "复合"}, {"form": "費用", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为得到东西或服务而付的钱，如住宿、看病、旅行的费用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3bd6d02-7b3a-476c-b3ee-298438b187a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10392, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "费用", "is_correct": true, "explanation": "费用：为一杯咖啡花的钱，符合“愿意为一杯咖啡付出费用”的语境。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“付出”不能带“味道”作宾语，“付出味道”搭配不成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以付出的东西，且句中的“天气”只是影响价格的因素。"}, {"text": "运输", "is_correct": false, "explanation": "语义：运输是句中影响价格的因素，不是可以付出的对象，句意不通。"}], "explanations": {"费用": "费用：为一杯咖啡花的钱，符合“愿意为一杯咖啡付出费用”的语境。", "味道": "搭配：“付出”不能带“味道”作宾语，“付出味道”搭配不成立。", "天气": "语义：天气不是可以付出的东西，且句中的“天气”只是影响价格的因素。", "运输": "语义：运输是句中影响价格的因素，不是可以付出的对象，句意不通。"}, "sentence_index": 0, "correct_answer": "费用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他收到朋友送的一笔费用作为生日礼物。", "explanation": "这里应该用〈礼金〉。费用 指为获得东西或服务而付出的钱，作为礼物送的钱要说〈礼金〉，不能说“收到一笔费用”。"}, {"text": "我们交了一只费用。", "explanation": "这里的量词应该用〈笔〉。〈只〉用于动物或成对的器物，不能计量“费用”，费用 要用“笔”计量。"}, {"text": "这件衣服的费用很漂亮。", "explanation": "这里应该用〈颜色〉。“漂亮”形容外观，费用是钱，不能说漂亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "费用", "is_correct": true, "explanation": "费用：手机修理所花的钱，正好是两百块，符合句意。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不能用金额表示“是两百块”，句意不通。"}, {"text": "地点", "is_correct": false, "explanation": "语义：“地点”不能用金额表示“是两百块”，与手机修理的意思无关。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能用金额表示，“颜色是两百块”搭配不成立。"}], "explanations": {"费用": "费用：手机修理所花的钱，正好是两百块，符合句意。", "时间": "语义：“时间”不能用金额表示“是两百块”，句意不通。", "地点": "语义：“地点”不能用金额表示“是两百块”，与手机修理的意思无关。", "颜色": "搭配：“颜色”不能用金额表示，“颜色是两百块”搭配不成立。"}, "sentence_index": 6, "correct_answer": "费用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月拿到了费用。", "explanation": "这里应该用〈工资〉。费用 指为获得东西或服务而付的钱，不是雇主付给员工的报酬。"}, {"text": "我们付了一扇费用。", "explanation": "这里的量词应该用〈笔〉。〈扇〉用于门窗，不能计量“费用”。"}, {"text": "这颗费用是两百块。", "explanation": "这里的量词应该用〈笔〉。〈颗〉用于粒状的小东西，不能计量“费用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只费用由学校出。", "corrected_sentence": "这笔费用由学校出。", "error_description": "错误：“这只费用”，“只”用于动物或成对器物，不能计量“费用”。正确应为“这笔费用”，“笔”用于款项。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他承担了这颗费用。", "corrected_sentence": "他承担了这笔费用。", "error_description": "错误：“这颗费用”，“颗”用于粒状小物，不能计量“费用”。正确应为“这笔费用”，“笔”用于款项。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
