INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10393, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指可以饮用的液体，如茶、咖啡、汽水等。", "primary_collocate": null, "pronunciation": "yǐn pǐn", "ipa": "in˨˩˦ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "咖啡不仅是一种饮品，也反映了全球经济的联系。", "target_word": "饮品", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这家店的饮品又好喝又便宜。", "target_word": "饮品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天，大家都喜欢冰的饮品。", "target_word": "饮品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "店员问我想点哪一种饮品。", "target_word": "饮品", "complexity_tier": "T3", "furigana": "diàn yuán wèn wǒ xiǎng diǎn nǎ yì zhǒng yǐn pǐn", "sentence_source": "generated"}, {"text": "孩子最好少喝甜的饮品。", "target_word": "饮品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "茶是中国人常喝的一种饮品。", "target_word": "饮品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家咖啡店新出了三种饮品。", "target_word": "饮品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "饭店送了我们一杯免费的饮品。", "target_word": "饮品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在超市买了很多饮品。", "target_word": "饮品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些饮品里，我最爱奶茶。", "target_word": "饮品", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种饮品", "label": "量词"}, {"form": "饮品店", "label": "复合"}, {"form": "飲品", "label": "繁体"}], "register": "中性", "sense_fingerprint": "可以饮用的液体总称，如茶、咖啡、汽水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3bd6d02-7b3a-476c-b3ee-298438b187a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10393, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饮品", "is_correct": true, "explanation": "正确。“饮品”指可以饮用的液体，咖啡属于这一类。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：咖啡是饮品，不是乐器。"}, {"text": "动物", "is_correct": false, "explanation": "语义：咖啡是饮品，不是动物。"}, {"text": "甘露", "is_correct": false, "explanation": "语域：“甘露”是书面雅语，指甘美的露水，不用来指咖啡这类饮料。"}], "explanations": {"饮品": "正确。“饮品”指可以饮用的液体，咖啡属于这一类。", "乐器": "语义：咖啡是饮品，不是乐器。", "动物": "语义：咖啡是饮品，不是动物。", "甘露": "语域：“甘露”是书面雅语，指甘美的露水，不用来指咖啡这类饮料。"}, "sentence_index": 0, "correct_answer": "饮品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们中午吃了很多饮品。", "explanation": "这里应该用〈食品〉。“饮品”指可以喝的东西，吃的东西要用“食品”。"}, {"text": "我在超市买了一只饮品。", "explanation": "这里应该用量词〈杯〉或〈瓶〉。“只”用于动物等，饮品不用“只”。"}, {"text": "这篇文章是一种饮品。", "explanation": "这里把〈饮品〉误用成了〈作品〉的意思；“饮品”只指可以喝的液体，文章不能是饮品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10393, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饮品", "is_correct": true, "explanation": "正确。这家咖啡店新出的三种东西是饮品。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：咖啡店不会新出“蔬菜”，这里说的是可以喝的东西。"}, {"text": "矿石", "is_correct": false, "explanation": "语义：矿石不是咖啡店会出售的东西。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能说店里新出了“身材”。"}], "explanations": {"饮品": "正确。这家咖啡店新出的三种东西是饮品。", "蔬菜": "语义：咖啡店不会新出“蔬菜”，这里说的是可以喝的东西。", "矿石": "语义：矿石不是咖啡店会出售的东西。", "身材": "体貌：身材指人的体形，不能说店里新出了“身材”。"}, "sentence_index": 6, "correct_answer": "饮品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他递给我一张饮品。", "explanation": "这里应该用量词〈杯〉。“张”用于纸张、桌子等平面的东西，饮品是液体，要用“杯”。"}, {"text": "小狗每天只吃一种饮品。", "explanation": "这里应该用〈食物〉。“饮品”是喝的，狗吃的东西要用“食物”。"}, {"text": "这盘青菜里的饮品很多。", "explanation": "这里应该用〈水分〉。“饮品”指可以喝的液体，青菜里的水分不能说成饮品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10393, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一条饮品。", "corrected_sentence": "我买了一瓶饮品。", "error_description": "错误：“一条饮品”，正确：“一瓶饮品”。“条”用于细长的东西，饮品要用“瓶”“杯”等量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10393, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家咖啡店新增了三只饮品。", "corrected_sentence": "这家咖啡店新增了三种饮品。", "error_description": "错误：“三只饮品”，正确：“三种饮品”。“只”用于动物等，饮品不用“只”，要用“种”“杯”等量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
