INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10396, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人与人、事物与事物之间相互关联、沟通或结合的关系。", "primary_collocate": null, "pronunciation": "lián xì", "ipa": "ljɛn˧˥ ɕi˥˩", "syllable_count": 2, "sentences": [{"text": "咖啡不仅是一种饮品，也反映了全球经济的联系。", "target_word": "联系", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这两件事之间有联系。", "target_word": "联系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "语言和文化有很深的联系。", "target_word": "联系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气和人的心情有联系吗？", "target_word": "联系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们之间没有什么联系。", "target_word": "联系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饭和身体健康有很大的联系。", "target_word": "联系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个国家的联系越来越多。", "target_word": "联系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书讲了人和自然的联系。", "target_word": "联系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，学习和生活有联系。", "target_word": "联系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我看不出这两个词有什么联系。", "target_word": "联系", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种联系", "label": "量词"}, {"form": "联系方式", "label": "复合"}, {"form": "聯繫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人与人、事物与事物之间相互关联的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3bd6d02-7b3a-476c-b3ee-298438b187a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10396, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "联系", "is_correct": true, "explanation": "正确：目标词是联系（lián xì）。"}, {"text": "练习", "is_correct": false, "explanation": "声调不同：liàn xí（第四声、第二声）与 lián xì（第二声、第四声）两个字的声调都不同，意思是练习。"}, {"text": "连续", "is_correct": false, "explanation": "xì 与 xù 韵母不同，意思是连续。"}, {"text": "联席", "is_correct": false, "explanation": "xì（第四声）与 xí（第二声）声调不同，意思是联席（会议）。"}], "explanations": {"联系": "正确：目标词是联系（lián xì）。", "练习": "声调不同：liàn xí（第四声、第二声）与 lián xì（第二声、第四声）两个字的声调都不同，意思是练习。", "连续": "xì 与 xù 韵母不同，意思是连续。", "联席": "xì（第四声）与 xí（第二声）声调不同，意思是联席（会议）。"}, "sentence_index": null, "correct_answer": "联系"}, "level_3": {"options": [{"text": "联系", "is_correct": true, "explanation": "正确。“联系”指事物之间相互关联的关系，这里指咖啡与全球经济的关联。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重说人或物的重量，不能用来说经济的关系。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：“乐器”与经济的关联无关，不能说“全球经济的乐器”。"}, {"text": "动物", "is_correct": false, "explanation": "语义：“动物”与经济的关联无关，不能说“全球经济的动物”。"}], "explanations": {"联系": "正确。“联系”指事物之间相互关联的关系，这里指咖啡与全球经济的关联。", "体重": "体貌：体重说人或物的重量，不能用来说经济的关系。", "乐器": "语义：“乐器”与经济的关联无关，不能说“全球经济的乐器”。", "动物": "语义：“动物”与经济的关联无关，不能说“全球经济的动物”。"}, "sentence_index": 0, "correct_answer": "联系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两根电线需要联系起来。", "explanation": "这里应该用〈连接〉。联系指事物之间的关系或沟通，电线的物理相接要用“连接”。"}, {"text": "他们之间有一幅联系。", "explanation": "这里应该用量词〈种〉。“幅”用于画、布等平面的东西，联系是抽象的关系，不能用“幅”。"}, {"text": "这台电脑是一种联系。", "explanation": "这里把〈联系〉误用成了〈设备〉的意思；“联系”是抽象的关系，电脑不能是联系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "联系", "is_correct": true, "explanation": "正确。“联系”越来越多，指两国之间的关联增加。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指人或动物的高矮，不能说“两个国家的身高越来越多”。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”不能与“越来越多”搭配，表示数量增加的是联系。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：嗓音是声音，不是两个国家之间的关系。"}], "explanations": {"联系": "正确。“联系”越来越多，指两国之间的关联增加。", "身高": "体貌：身高指人或动物的高矮，不能说“两个国家的身高越来越多”。", "味道": "搭配：“味道”不能与“越来越多”搭配，表示数量增加的是联系。", "嗓音": "语义：嗓音是声音，不是两个国家之间的关系。"}, "sentence_index": 6, "correct_answer": "联系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们俩之间有一辆联系。", "explanation": "这里应该用量词〈种〉。“辆”用于车，联系是抽象的关系，不能用“辆”。"}, {"text": "这张桌子是一种联系。", "explanation": "这里把〈联系〉误用成了〈家具〉的意思；“联系”是抽象的关系，桌子不能是联系。"}, {"text": "他把两段木头联系起来做成了椅子。", "explanation": "这里应该用〈连接〉。“联系起来”指关联或沟通，把木头连在一起要用“连接”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国之间有一台联系。", "corrected_sentence": "两国之间有一种联系。", "error_description": "错误：“一台联系”，正确：“一种联系”。“台”用于机器等，抽象的关系要用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个城市之间有一头联系。", "corrected_sentence": "这两个城市之间有一种联系。", "error_description": "错误：“一头联系”，正确：“一种联系”。“头”用于牛、猪等牲畜，抽象的关系要用“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
