INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10399, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10399, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "商品流通是指商品从生产领域向消费领域转移的过程，包括买卖、运输、仓储等环节。", "primary_collocate": null, "pronunciation": "shāng pǐn liú tōng", "ipa": "ʂɑŋ˥ pin˨˩ ljoʊ˧˥ tʰʊŋ˥", "syllable_count": 4, "sentences": [{"text": "全球咖啡豆供应链是当代国际贸易体系中最为复杂的商品流通网络之一。", "target_word": "商品流通", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "商品流通包括买卖、运输和仓储。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商品流通是连接生产和消费的桥梁。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运输不方便会影响商品流通。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家重视商品流通，修了很多新公路。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商品流通的速度快，库存就会减少。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上购物让商品流通更方便了。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "仓储是商品流通的一个环节。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商品流通过程中，运输成本很重要。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的商品流通很发达，物流公司也多。", "target_word": "商品流通", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "商品", "label": "复合"}, {"form": "流通", "label": "复合"}], "register": "书面语", "sense_fingerprint": "商品从生产到消费转移的全过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b00e750-9992-41a7-9c7a-85867ab1d091') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10399, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "商品流通", "is_correct": true, "explanation": "商品流通指商品从生产到消费的转移过程，与“最为复杂的……网络之一”相合。"}, {"text": "绘画艺术", "is_correct": false, "explanation": "语义：绘画艺术不构成国际贸易供应网络。"}, {"text": "动物世界", "is_correct": false, "explanation": "语义：动物世界与国际贸易体系无关。"}, {"text": "体育运动", "is_correct": false, "explanation": "搭配：“网络”不与“体育运动”搭配，且与供应链语境不合。"}], "explanations": {"商品流通": "商品流通指商品从生产到消费的转移过程，与“最为复杂的……网络之一”相合。", "绘画艺术": "语义：绘画艺术不构成国际贸易供应网络。", "动物世界": "语义：动物世界与国际贸易体系无关。", "体育运动": "搭配：“网络”不与“体育运动”搭配，且与供应链语境不合。"}, "sentence_index": 0, "correct_answer": "商品流通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位商品流通很有名。", "explanation": "这里应该用〈商人〉。商品流通指流转过程，不指从事买卖的人，不能用“位”计量。"}, {"text": "这家店每周商品流通两次。", "explanation": "这里应该用〈进货〉。商品流通指整个转移过程，不能当作一次进货的动作来计次。"}, {"text": "我在超市买了一个商品流通。", "explanation": "这里应该用〈商品〉。商品流通是抽象的流转过程，不是可以买的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10399, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "商品流通", "is_correct": true, "explanation": "商品流通指商品的转移过程，与“网上购物让……更方便了”相合。"}, {"text": "天气变化", "is_correct": false, "explanation": "语义：网上购物不能让天气变化更方便。"}, {"text": "身体健康", "is_correct": false, "explanation": "搭配：“方便”不修饰“身体健康”。"}, {"text": "课堂纪律", "is_correct": false, "explanation": "语义：网上购物与课堂纪律无关。"}], "explanations": {"商品流通": "商品流通指商品的转移过程，与“网上购物让……更方便了”相合。", "天气变化": "语义：网上购物不能让天气变化更方便。", "身体健康": "搭配：“方便”不修饰“身体健康”。", "课堂纪律": "语义：网上购物与课堂纪律无关。"}, "sentence_index": 6, "correct_answer": "商品流通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们商品流通了三箱苹果。", "explanation": "这里应该用〈运送〉。商品流通是名词，表示整个流转过程，不能当动词带宾语。"}, {"text": "妈妈把商品流通放进了冰箱。", "explanation": "这里应该用〈商品〉。商品流通是抽象过程，不能放进冰箱。"}, {"text": "仓库每天商品流通上百件。", "explanation": "这里应该用〈发货〉。商品流通是名词，不能当动词带宾语表示发出物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10399, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "北方的商品流通了很顺畅。", "corrected_sentence": "北方的商品流通很顺畅。", "error_description": "“商品流通”后不能加“了”接形容词谓语；应说“商品流通很顺畅”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10399, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "南方的商品流通很发达着。", "corrected_sentence": "南方的商品流通很发达。", "error_description": "“很发达”是形容词谓语，后面不能加“着”；应说“南方的商品流通很发达”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
