INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10401, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "交易量指在特定时间段内，市场或平台上完成买卖的商品、股票等数量总和。", "primary_collocate": null, "pronunciation": "jiāo yì liàng", "ipa": "tɕjɑʊ˥ i˥˩ ljɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "作为世界上交易量最大的农产品之一，咖啡豆的流动贯穿了从热带农业种植到全球都市消费终端的漫长链条。", "target_word": "交易量", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今年双十一，网店的交易量比去年增加了。", "target_word": "交易量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，菜市场的交易量会减少。", "target_word": "交易量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只股票昨天的交易量很大。", "target_word": "交易量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春节前，花市的交易量上升得很快。", "target_word": "交易量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "交易量越大，平台的收入就越高。", "target_word": "交易量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的月交易量已经超过一万单了。", "target_word": "交易量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格太高，今天的交易量只有平时的一半。", "target_word": "交易量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新政策出台后，房子的交易量下降了。", "target_word": "交易量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板每天都记录当天的交易量。", "target_word": "交易量", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "交易", "label": "复合"}, {"form": "交易额", "label": "复合"}], "register": "书面语", "sense_fingerprint": "一定时期内市场或平台完成买卖的数量总和", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b00e750-9992-41a7-9c7a-85867ab1d091') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10401, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人口", "is_correct": false, "explanation": "语义：农产品不是人群，不能说人口最大。"}, {"text": "交易量", "is_correct": true, "explanation": "交易量指市场上完成买卖的总数，这里说世界上成交数量居首的农产品。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”只用于人或生物，不能修饰农产品。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”不能用来说农产品的大小，这样说不通。"}], "explanations": {"人口": "语义：农产品不是人群，不能说人口最大。", "交易量": "交易量指市场上完成买卖的总数，这里说世界上成交数量居首的农产品。", "年龄": "搭配：“年龄”只用于人或生物，不能修饰农产品。", "温度": "搭配：“温度”不能用来说农产品的大小，这样说不通。"}, "sentence_index": 0, "correct_answer": "交易量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只股票昨天的交易量是两亿元。", "explanation": "这里应该用〈交易额〉。交易量统计的是股数、件数等数量，不以金额计算；说金额要用交易额。"}, {"text": "这只股票昨天的交易量是三块钱一股。", "explanation": "这里应该用〈股价〉。交易量统计的是股数总量，每股多少钱是股价；说每股价格要用股价。"}, {"text": "这只股票昨天的交易量很贵。", "explanation": "这里应该用〈价格〉。交易量是数量，不能说贵或便宜；说贵贱要用价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10401, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "搭配：店铺没有身高，“身高”只用于人，不能这样说。"}, {"text": "交易量", "is_correct": true, "explanation": "交易量指一个月内完成的买卖总数，这里说超过一万单，与数量相符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”只用于人或动物，不能用来描述店铺。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：“寿命”指存在的年限，与“超过一万单”这种数量说法不符。"}], "explanations": {"身高": "搭配：店铺没有身高，“身高”只用于人，不能这样说。", "交易量": "交易量指一个月内完成的买卖总数，这里说超过一万单，与数量相符。", "体重": "搭配：“体重”只用于人或动物，不能用来描述店铺。", "寿命": "语义：“寿命”指存在的年限，与“超过一万单”这种数量说法不符。"}, "sentence_index": 6, "correct_answer": "交易量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板每天都把当天的交易量吃掉。", "explanation": "这里应该用〈记录〉。“吃”的对象是食物，交易量是数字，不能吃。"}, {"text": "老板每天都给当天的交易量打五折。", "explanation": "这里应该用〈售价〉。打折针对的是价格，交易量是数量，不能打折。"}, {"text": "老板每天都给当天的交易量发工资。", "explanation": "这里应该用〈员工〉。发工资是给人的，交易量只是数量，不能拿来发工资。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10401, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个平台今天的交易量很长。", "corrected_sentence": "这个平台今天的交易量很大。", "error_description": "交易量是数量，说“大/小”或“高/低”，不能说“长”；应说“交易量很大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10401, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的月交易量已经有一万多只了。", "corrected_sentence": "这家店的月交易量已经有一万多单了。", "error_description": "交易量的计数单位是“单”，说“只”不对；正确说法是“一万多单”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10402, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最小", "is_correct": true, "explanation": "最大与最小互为反义，指数量、尺寸、程度的两个极端。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、不模糊，与“最大”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与“最大”不构成反义。"}, {"text": "安静", "is_correct": false, "explanation": "安静与“吵闹”构成反义，与“最大”无关。"}], "correct_answer": "最小", "explanations": {"最小": "最大与最小互为反义，指数量、尺寸、程度的两个极端。", "清楚": "清楚指明白、不模糊，与“最大”没有反义关系。", "明亮": "明亮形容光线或颜色，与“最大”不构成反义。", "安静": "安静与“吵闹”构成反义，与“最大”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10402, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最小", "is_correct": true, "explanation": "最大与最小互为反义，指数量、尺寸、程度的两个极端。"}, {"text": "温柔", "is_correct": false, "explanation": "温柔形容性格或态度，与“最大”不构成反义。"}, {"text": "干净", "is_correct": false, "explanation": "干净指整洁，与“最大”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐形容排列有序，与“最大”没有反义关系。"}], "correct_answer": "最小", "explanations": {"最小": "最大与最小互为反义，指数量、尺寸、程度的两个极端。", "温柔": "温柔形容性格或态度，与“最大”不构成反义。", "干净": "干净指整洁，与“最大”没有反义关系。", "整齐": "整齐形容排列有序，与“最大”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10402, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "在数量、尺寸、程度等方面超过所有其他事物的。", "primary_collocate": null, "pronunciation": "zuì dà", "ipa": "tswei̯˥˩ ta˥˩", "syllable_count": 2, "sentences": [{"text": "这是全市面积最大的公园，走一圈要两个小时。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我们家，哥哥年纪最大，今年已经三十岁了。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "非洲象是陆地上最大的动物，体重可以超过六吨。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服太小了，我要店里最大的号。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对我来说，健康是最大的幸福，钱不是。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛中，我们遇到的最大困难是天气太热。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂是我们城市里最大的，有五千名工人。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "非洲最大的沙漠是撒哈拉沙漠。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹的优点很多，最大的优点是爱笑。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次地震造成的最大损失是房子倒了很多。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "最大|形容词|数量尺寸程度超过其他一切", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b00e750-9992-41a7-9c7a-85867ab1d091') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10402, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "最大", "is_correct": true, "explanation": "最大 zuì dà：本词，指数量、尺寸、程度超过其他一切。"}, {"text": "自大", "is_correct": false, "explanation": "zì 与 zuì 韵母不同，意思是自以为了不起。"}, {"text": "做大", "is_correct": false, "explanation": "zuò 与 zuì 韵母不同，意思是使变大。"}, {"text": "嘴大", "is_correct": false, "explanation": "zuǐ（第三声）与 zuì（第四声）声调不同，意思是嘴巴大。"}], "explanations": {"最大": "最大 zuì dà：本词，指数量、尺寸、程度超过其他一切。", "自大": "zì 与 zuì 韵母不同，意思是自以为了不起。", "做大": "zuò 与 zuì 韵母不同，意思是使变大。", "嘴大": "zuǐ（第三声）与 zuì（第四声）声调不同，意思是嘴巴大。"}, "sentence_index": null, "correct_answer": "最大"}, "level_3": {"options": [{"text": "最便宜", "is_correct": false, "explanation": "搭配：“便宜”说价格，不能修饰“面积”。"}, {"text": "最大", "is_correct": true, "explanation": "最大修饰“面积”，表示全市第一，与“走一圈要两个小时”相符。"}, {"text": "最热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或人，不能修饰“面积”。"}, {"text": "最年轻", "is_correct": false, "explanation": "搭配：“年轻”只说人或生物的年龄，不能修饰“面积”。"}], "explanations": {"最便宜": "搭配：“便宜”说价格，不能修饰“面积”。", "最大": "最大修饰“面积”，表示全市第一，与“走一圈要两个小时”相符。", "最热闹": "搭配：“热闹”形容场面或人，不能修饰“面积”。", "最年轻": "搭配：“年轻”只说人或生物的年龄，不能修饰“面积”。"}, "sentence_index": 0, "correct_answer": "最大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的汉语水平最大，已经能看懂报纸了。", "explanation": "这里应该用〈最高〉。水平、成绩说“最高”，“最大”多用于面积、数量、体积。"}, {"text": "他家离学校最大，所以每天要走很久。", "explanation": "这里应该用〈最远〉。说距离的远近要用“最远”或“最近”，不用“最大”。"}, {"text": "他的表现最大，老师很满意。", "explanation": "这里应该用〈最好〉。说表现、质量的优劣要用“最好”，不说“最大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人，不能修饰工厂。"}, {"text": "最大", "is_correct": true, "explanation": "最大修饰“工厂”，表示城里规模第一，与“五千名工人”相符。"}, {"text": "最甜", "is_correct": false, "explanation": "搭配：“甜”说味道，不能修饰工厂。"}, {"text": "最和蔼", "is_correct": false, "explanation": "搭配：“和蔼”形容人的态度，不能用于工厂。"}], "explanations": {"最聪明": "搭配：“聪明”形容人，不能修饰工厂。", "最大": "最大修饰“工厂”，表示城里规模第一，与“五千名工人”相符。", "最甜": "搭配：“甜”说味道，不能修饰工厂。", "最和蔼": "搭配：“和蔼”形容人的态度，不能用于工厂。"}, "sentence_index": 6, "correct_answer": "最大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子的礼貌最大，见了人就打招呼。", "explanation": "这里应该用〈最有礼貌〉。说礼貌的程度要用“有礼貌”一类的说法，“最大”不能直接用于礼貌。"}, {"text": "这座老房子的历史最大，已经有三百年了。", "explanation": "这里应该用〈最长〉。说历史的长短要用“最长”，不用“最大”。"}, {"text": "他在这里待的时间最大，已经十年了。", "explanation": "这里应该用〈最长〉。说时间的长短要用“最长”，不用“最大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是全校很最大的教室，能坐五百人。", "corrected_sentence": "这是全校最大的教室，能坐五百人。", "error_description": "“最大”前不能加“很”，“很最大”是错误的；正确说法是直接用“最大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条街上，他的房子比我的最大。", "corrected_sentence": "这条街上，他的房子最大。", "error_description": "最高级“最大”不能与“比我的”同用：“比”引出比较句，应去掉比较成分，说“这条街上，他的房子最大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
