INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10403, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "农业生产的物品，如粮食、蔬菜、水果等。", "primary_collocate": null, "pronunciation": "nóng chǎn pǐn", "ipa": "noŋ˧˥ tʂʰan˨˩˦ pin˨˩˦", "syllable_count": 3, "sentences": [{"text": "作为世界上交易量最大的农产品之一，咖啡豆的流动贯穿了从热带农业种植到全球都市消费终端的漫长链条。", "target_word": "农产品", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个村子的农产品都卖到城里去了。", "target_word": "农产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米、菜和水果都是农产品。", "target_word": "农产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年天气好，农产品的价格比去年高。", "target_word": "农产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里有一个专门卖农产品的柜台。", "target_word": "农产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些农产品从田里运到市场，只用了一天。", "target_word": "农产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家都从中国买农产品，比如大米和茶叶。", "target_word": "农产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上卖自己家种的农产品。", "target_word": "农产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司把农产品做成了饮料和点心。", "target_word": "农产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农产品要保持新鲜，所以要很快送到商店。", "target_word": "农产品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "農產品", "label": "繁体"}, {"form": "种", "label": "量词"}, {"form": "批", "label": "量词"}], "register": "中性", "sense_fingerprint": "农产品|名词|农业生产出的粮食蔬菜水果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b00e750-9992-41a7-9c7a-85867ab1d091') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10403, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哲学", "is_correct": false, "explanation": "语义：哲学是思想体系，不能说有“交易量”。"}, {"text": "农产品", "is_correct": true, "explanation": "正确：句中指世界上交易量最大的农业物品，咖啡豆属于这一类。"}, {"text": "诗歌", "is_correct": false, "explanation": "搭配：“交易量”只说商品，诗歌不能与之搭配。"}, {"text": "方言", "is_correct": false, "explanation": "语义：方言是语言的地域变体，不是可以交易的物品。"}], "explanations": {"哲学": "语义：哲学是思想体系，不能说有“交易量”。", "农产品": "正确：句中指世界上交易量最大的农业物品，咖啡豆属于这一类。", "诗歌": "搭配：“交易量”只说商品，诗歌不能与之搭配。", "方言": "语义：方言是语言的地域变体，不是可以交易的物品。"}, "sentence_index": 0, "correct_answer": "农产品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们每天在农产品里上课。", "explanation": "这里应该用〈教室〉。农产品是农业生产的物品，不是上课的地方。"}, {"text": "这位农民每周往田里喷一次农产品。", "explanation": "这里应该用〈农药〉。“喷”的对象是农药，农产品是收获后的食物，不能拿来喷。"}, {"text": "这家公司的农产品是电脑和手机。", "explanation": "这里应该用〈电子产品〉。农产品指农业生产的物品，电脑和手机不属于此类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10403, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩具", "is_correct": false, "explanation": "语义：玩具与“大米和茶叶”不是同类，句中的例子对不上。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“买”的对象不能是天空，两者不搭配。"}, {"text": "农产品", "is_correct": true, "explanation": "正确：“大米和茶叶”是农产品，这里说的是从中国买的农产品。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具不属于“大米和茶叶”所在的类别，句中的例子对不上。"}], "explanations": {"玩具": "语义：玩具与“大米和茶叶”不是同类，句中的例子对不上。", "天空": "搭配：“买”的对象不能是天空，两者不搭配。", "农产品": "正确：“大米和茶叶”是农产品，这里说的是从中国买的农产品。", "家具": "语义：家具不属于“大米和茶叶”所在的类别，句中的例子对不上。"}, "sentence_index": 6, "correct_answer": "农产品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在院子里玩农产品。", "explanation": "这里应该用〈玩具〉。“玩”的对象是玩具、游戏等，农产品不能拿来玩。"}, {"text": "图书馆里的农产品可以借回家看。", "explanation": "这里应该用〈书籍〉。图书馆藏的是书，农产品不能借阅。"}, {"text": "妈妈每天在家里听农产品。", "explanation": "这里应该用〈音乐〉。“听”的对象是声音作品，农产品不是可以听的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10403, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只农产品今天运到了市场。", "corrected_sentence": "这批农产品今天运到了市场。", "error_description": "量词错误：“农产品”应该用量词“批”或“种”，“只”用于动物等，不能用来数农产品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10403, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些农产品们卖得很快。", "corrected_sentence": "这些农产品卖得很快。", "error_description": "“们”只用于指人的复数，“农产品”是物，不能加“们”；应说“这些农产品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10404, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静止", "is_correct": true, "explanation": "反义：“静止”指不动，与“流动”（液体或气体连续移动）相对，空气不流动即是静止。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：“唱歌”是发声的动作，与“流动”不构成反义。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：“睡觉”是休息的行为，与“流动”不构成反义。"}, {"text": "思考", "is_correct": false, "explanation": "无关：“思考”指用脑，与“流动”不构成反义。"}], "correct_answer": "静止", "explanations": {"静止": "反义：“静止”指不动，与“流动”（液体或气体连续移动）相对，空气不流动即是静止。", "唱歌": "无关：“唱歌”是发声的动作，与“流动”不构成反义。", "睡觉": "无关：“睡觉”是休息的行为，与“流动”不构成反义。", "思考": "无关：“思考”指用脑，与“流动”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10404, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静止", "is_correct": true, "explanation": "反义：“静止”指不动，与“流动”（液体或气体连续移动）相对，海水不流动即是静止。"}, {"text": "跳舞", "is_correct": false, "explanation": "无关：“跳舞”是身体的律动，与“流动”不构成反义。"}, {"text": "写字", "is_correct": false, "explanation": "无关：“写字”是书写的动作，与“流动”不构成反义。"}, {"text": "吃饭", "is_correct": false, "explanation": "无关：“吃饭”是进食的行为，与“流动”不构成反义。"}], "correct_answer": "静止", "explanations": {"静止": "反义：“静止”指不动，与“流动”（液体或气体连续移动）相对，海水不流动即是静止。", "跳舞": "无关：“跳舞”是身体的律动，与“流动”不构成反义。", "写字": "无关：“写字”是书写的动作，与“流动”不构成反义。", "吃饭": "无关：“吃饭”是进食的行为，与“流动”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10404, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指液体或气体等物质连续地移动、变化。", "primary_collocate": null, "pronunciation": "liú dòng", "ipa": "liou̯˧˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "作为亚洲流量最大的河流，长江水常年不停地流动，贯穿了从青藏高原到东海的漫长流域。", "target_word": "流动", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "从宏观视角看，洋流在全球范围内持续流动，不仅影响了海洋生态，也深刻改变了沿岸地区的气候格局。", "target_word": "流动", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "河水慢慢地流动，声音很轻。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气不流动，房间里很热。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "血液在身体里不停地流动。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水在管子里流动，我们听得见声音。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太冷，管子里的水不再流动了。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开窗户，让新鲜的空气流动起来。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖里的水不流动，所以夏天会有臭味。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温暖的海水沿着海岸流动，带来了很多鱼。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流动着", "label": "体标"}, {"form": "流动了", "label": "体标"}, {"form": "流动过", "label": "体标"}, {"form": "流動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "流动|动词|液体气体连续移动变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b00e750-9992-41a7-9c7a-85867ab1d091') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10404, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "语义：水不会睡觉，句意不通。"}, {"text": "流动", "is_correct": true, "explanation": "正确：长江水连续移动，即“流动”，这里作动词。"}, {"text": "思考", "is_correct": false, "explanation": "语义：水不会思考，“思考”指用脑，与句意不符。"}, {"text": "生气", "is_correct": false, "explanation": "语义：水不会生气，句意不通。"}], "explanations": {"睡觉": "语义：水不会睡觉，句意不通。", "流动": "正确：长江水连续移动，即“流动”，这里作动词。", "思考": "语义：水不会思考，“思考”指用脑，与句意不符。", "生气": "语义：水不会生气，句意不通。"}, "sentence_index": 0, "correct_answer": "流动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "球在地上流动，跑得很快。", "explanation": "这里应该用〈滚〉。固体物体翻转着移动用“滚”，“流动”只用于液体或气体。"}, {"text": "灯笼在风中流动，很好看。", "explanation": "这里应该用〈晃动〉。灯笼来回摆动用“晃动”，“流动”指液体或气体的连续移动，不能用于灯笼。"}, {"text": "小狗在草地上流动，跳得很高。", "explanation": "这里应该用〈奔跑〉。“流动”指液体或气体的连续移动，小狗在草地上奔跑不能说“流动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱歌", "is_correct": false, "explanation": "语义：水不会唱歌，句中“天气太冷”也与此不合。"}, {"text": "流动", "is_correct": true, "explanation": "正确：天冷时管子里的水不再连续移动，即“流动”。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：水不会跳舞，这样的说法与句意不符。"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”的动作者须是人或动物，水不能喝。"}], "explanations": {"唱歌": "语义：水不会唱歌，句中“天气太冷”也与此不合。", "流动": "正确：天冷时管子里的水不再连续移动，即“流动”。", "跳舞": "语义：水不会跳舞，这样的说法与句意不符。", "喝": "配价：“喝”的动作者须是人或动物，水不能喝。"}, "sentence_index": 6, "correct_answer": "流动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "琴弦在风中流动，发出好听的声音。", "explanation": "这里应该用〈振动〉。琴弦的来回颤动用“振动”，“流动”只用于液体或气体。"}, {"text": "车轮在泥地上飞快地流动。", "explanation": "这里应该用〈旋转〉。车轮绕轴转动，不说“流动”。"}, {"text": "树枝在风中轻轻流动。", "explanation": "这里应该用〈摇摆〉。树枝来回晃动用“摇摆”，不用“流动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风从窗户吹进来，让屋里的空气流动下来。", "corrected_sentence": "风从窗户吹进来，让屋里的空气流动起来。", "error_description": "补语错误：空气开始流动应说“流动起来”，“流动下来”不是正确的补语搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水把管子里流动。", "corrected_sentence": "水在管子里流动。", "error_description": "“流动”是不及物动词，不能用“把”字句；应把“把”改为“在”，说“水在管子里流动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
