INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10405, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指从头到尾一直存在或体现在某个过程中。", "primary_collocate": null, "pronunciation": "guàn chuān", "ipa": "kwan˥˩ tʂʰwan˥", "syllable_count": 2, "sentences": [{"text": "此类义务不仅涉及法律文本的字面遵循，更要求企业构建一套贯穿产品生命周期的伦理—合规架构。", "target_word": "贯穿", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "作为世界上交易量最大的农产品之一，咖啡豆的流动贯穿了从热带农业种植到全球都市消费终端的漫长链条。", "target_word": "贯穿", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个故事的主题贯穿全书。", "target_word": "贯穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱国精神贯穿了他的一生。", "target_word": "贯穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安全意识要贯穿整个工作过程。", "target_word": "贯穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个问题贯穿了整场讨论。", "target_word": "贯穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条线索贯穿整部电影。", "target_word": "贯穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习汉语的热情贯穿她的大学生活。", "target_word": "贯穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诚实的原则贯穿了公司的发展。", "target_word": "贯穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种想法贯穿了他所有的文章。", "target_word": "贯穿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "贯穿了", "label": "完成体"}, {"form": "贯穿着", "label": "持续体"}, {"form": "贯穿过", "label": "经历体"}, {"form": "貫穿", "label": "繁体"}], "register": "中性", "sense_fingerprint": "贯穿：某种思想、主题或要求从头到尾存在于整个过程中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b82ebd84-cad9-43e3-91eb-87aa720f70fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10405, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贯穿", "is_correct": true, "explanation": "贯穿指从头到尾存在于整个过程中。此处说企业要构建一套贯穿产品生命周期的架构，语义和搭配都吻合。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：“忽略”是不予理会，与“贯穿产品生命周期”的要求相反，架构不能忽略生命周期。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是商品，“购买产品生命周期”不成立，架构也不能购买东西。"}, {"text": "违反", "is_correct": false, "explanation": "语义：“违反”表示违背规定，与前文的“合规架构”相悖，句子会变成合规架构违背生命周期。"}], "explanations": {"贯穿": "贯穿指从头到尾存在于整个过程中。此处说企业要构建一套贯穿产品生命周期的架构，语义和搭配都吻合。", "忽略": "语义：“忽略”是不予理会，与“贯穿产品生命周期”的要求相反，架构不能忽略生命周期。", "购买": "搭配：“购买”的对象是商品，“购买产品生命周期”不成立，架构也不能购买东西。", "违反": "语义：“违反”表示违背规定，与前文的“合规架构”相悖，句子会变成合规架构违背生命周期。"}, "sentence_index": 0, "correct_answer": "贯穿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府要认真贯穿这项政策。", "explanation": "这里应该用〈贯彻〉。贯彻指执行、落实政策方针，贯穿指一直存在于整个过程之中，二者不能互换。"}, {"text": "我们必须贯穿交通规则。", "explanation": "这里应该用〈遵守〉。遵守指依照规定行事，“贯穿”不表示遵守规则，这里的用法不成立。"}, {"text": "他很快贯穿了这个问题。", "explanation": "这里应该用〈解决〉。解决指消除问题、使问题有结论，“贯穿”表示从头到尾一直存在，不表示解决问题，二者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e88780-b700-499f-a570-98f01fe9a484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10405, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贯穿", "is_correct": true, "explanation": "贯穿指从头到尾存在于整个过程中。此处说线索从头到尾存在于整部电影中，语义吻合。"}, {"text": "抵达", "is_correct": false, "explanation": "语义：“抵达”指到达某个地点，线索不能抵达电影，句意不通。"}, {"text": "离开", "is_correct": false, "explanation": "语义：“离开”表示脱离某处，与线索从头到尾存在于电影中的意思相反。"}, {"text": "逃离", "is_correct": false, "explanation": "搭配：“逃离”的主体通常是有意愿的人或动物，线索不能逃离整部电影。"}], "explanations": {"贯穿": "贯穿指从头到尾存在于整个过程中。此处说线索从头到尾存在于整部电影中，语义吻合。", "抵达": "语义：“抵达”指到达某个地点，线索不能抵达电影，句意不通。", "离开": "语义：“离开”表示脱离某处，与线索从头到尾存在于电影中的意思相反。", "逃离": "搭配：“逃离”的主体通常是有意愿的人或动物，线索不能逃离整部电影。"}, "sentence_index": 6, "correct_answer": "贯穿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很擅长贯穿团队的和谐。", "explanation": "这里应该用〈维持〉。维持指保持某种状态，与贯穿“从头到尾存在于过程中”的意思不同，这里不能用“贯穿”。"}, {"text": "我们终于贯穿了理想。", "explanation": "这里应该用〈实现〉。实现指使理想变为现实，“贯穿”不能与“理想”搭配，句子不成立。"}, {"text": "他迅速贯穿了问题的本质。", "explanation": "这里应该用〈抓住〉。“贯穿”表示从头到尾一直存在于某个过程中，不表示迅速抓住本质，这里不能用“贯穿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e88780-b700-499f-a570-98f01fe9a484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10405, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种精神贯穿起全书。", "corrected_sentence": "这种精神贯穿全书。", "error_description": "“贯穿”后多加了补语“起”。“起”通常与“来”搭配构成“贯穿起来”，“贯穿”直接带宾语时不能加“起”，应为“贯穿全书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e88780-b700-499f-a570-98f01fe9a484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10405, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份信念被贯穿了他的整个人生。", "corrected_sentence": "这份信念贯穿了他的整个人生。", "error_description": "多用了“被”。“贯穿”是动词，“这份信念”是施事，句子不能用“被”把施事变成受事，应去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e88780-b700-499f-a570-98f01fe9a484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
