INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10406, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指赤道两侧、全年气温较高的气候带或地区。", "primary_collocate": null, "pronunciation": "rè dài", "ipa": "ʐɤ⁵¹ taɪ⁵¹", "syllable_count": 2, "sentences": [{"text": "作为世界上交易量最大的农产品之一，咖啡豆的流动贯穿了从热带农业种植到全球都市消费终端的漫长链条。", "target_word": "热带", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "热带地区全年都很热。", "target_word": "热带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热带的水果又甜又好吃。", "target_word": "热带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花只能在热带生长。", "target_word": "热带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去热带的海边玩。", "target_word": "热带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热带森林里有很多动物。", "target_word": "热带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热带没有冬天，一年四季都热。", "target_word": "热带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在热带住过十年。", "target_word": "热带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热带的雨下得很大。", "target_word": "热带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "香蕉多长在热带。", "target_word": "热带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "热带雨林", "label": "复合"}, {"form": "热带气候", "label": "复合"}, {"form": "熱帶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "赤道两侧全年气温高的气候带或地区", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abfcfa9a-a51d-42c1-8ec4-e1f3a9b309a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10406, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热带", "is_correct": true, "explanation": "正确。咖啡产自热带农业区，只有“热带”符合语境。"}, {"text": "寒带", "is_correct": false, "explanation": "语义：咖啡不在寒带种植，“寒带”与句中咖啡豆的产地语境矛盾。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：咖啡不在沙漠中种植，“沙漠农业种植”与句中咖啡豆的产区语境不符。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：“海洋农业种植”不指咖啡产区，与句意不符。"}], "explanations": {"热带": "正确。咖啡产自热带农业区，只有“热带”符合语境。", "寒带": "语义：咖啡不在寒带种植，“寒带”与句中咖啡豆的产地语境矛盾。", "沙漠": "语义：咖啡不在沙漠中种植，“沙漠农业种植”与句中咖啡豆的产区语境不符。", "海洋": "语义：“海洋农业种植”不指咖啡产区，与句意不符。"}, "sentence_index": 0, "correct_answer": "热带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市四季分明，冬天会下雪，属于热带。", "explanation": "这里应该用〈温带〉。热带全年高温、没有冬天；四季分明、冬天下雪的地方属于温带。"}, {"text": "西伯利亚冬天很长，属于热带。", "explanation": "这里应该用〈寒带〉。冬天漫长寒冷的地方属于寒带，热带全年气温很高。"}, {"text": "成都冬天有霜，属于热带。", "explanation": "这里应该用〈亚热带〉。冬天有霜说明不是全年高温的热带，成都属于亚热带。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10406, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热带", "is_correct": true, "explanation": "正确。没有冬天、一年四季都热的地区就是热带。"}, {"text": "北极", "is_correct": false, "explanation": "语义：北极冬天极冷，与“一年四季都热”矛盾。"}, {"text": "北方", "is_correct": false, "explanation": "语义：北方有明显的冬天，与“没有冬天”矛盾。"}, {"text": "春天", "is_correct": false, "explanation": "搭配：“春天”是季节，不能作“没有冬天，一年四季都热”的地理主语。"}], "explanations": {"热带": "正确。没有冬天、一年四季都热的地区就是热带。", "北极": "语义：北极冬天极冷，与“一年四季都热”矛盾。", "北方": "语义：北方有明显的冬天，与“没有冬天”矛盾。", "春天": "搭配：“春天”是季节，不能作“没有冬天，一年四季都热”的地理主语。"}, "sentence_index": 6, "correct_answer": "热带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "青藏高原海拔很高，夏天凉爽，属于热带气候。", "explanation": "这里应该用〈高原〉。海拔高、夏天凉爽的地区属于高原气候，与热带的全年高温不符。"}, {"text": "西西里岛夏天干燥、冬天湿润，属于热带气候。", "explanation": "这里应该用〈地中海〉。夏干冬湿的气候属于地中海气候，不符合热带特点。"}, {"text": "我国东北冬天很冷，属于热带气候。", "explanation": "这里应该用〈温带〉。东北冬天寒冷、四季分明，属于温带气候；热带全年高温，没有寒冷的冬天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多鸟类生活热带。", "corrected_sentence": "很多鸟类生活在热带。", "error_description": "漏了介词“在”。“生活”后接表示地点的成分时要用“生活在……”，应说“生活在热带”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们打算搬在热带去。", "corrected_sentence": "我们打算搬到热带去。", "error_description": "介词错误：“搬”表示迁移到某处，地点前要用“到”，不能用“在”，应说“搬到热带去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
