INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10408, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "计算机系统中，用于输入输出数据的设备", "primary_collocate": null, "pronunciation": "zhōng duān", "ipa": "ʈʂʊŋ˥ twan˥", "syllable_count": 2, "sentences": [{"text": "该系统在全国各地部署了数千个终端，各网点的交易数据经加密通道实时同步至总部服务器，形成统一的风险监控网络。", "target_word": "终端", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这家跨国零售集团在全球设有数万台终端，所有门店的销售数据都经由加密网络汇总到总部。", "target_word": "终端", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这台终端可以输入和显示数据。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在终端上输入你的名字。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室里有十台终端。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "终端坏了，我们不能查资料。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行的终端正在打印单子。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在终端前看了一个小时。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把新终端放在桌子上。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个终端连着公司的大电脑。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "终端机", "label": "复合"}], "register": "中性", "sense_fingerprint": "计算机系统里输入输出数据的设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8eb6ea89-b4e2-487f-9034-a8829d8e7345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10408, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "终端", "is_correct": true, "explanation": "正确答案：终端（zhōng duān）。"}, {"text": "中断", "is_correct": false, "explanation": "“中断”（zhōng duàn）与“终端”只有第二音节声调不同，意思是中途停止。"}, {"text": "中段", "is_correct": false, "explanation": "“中段”（zhōng duàn）与“终端”只有第二音节声调不同，意思是中间的一段。"}, {"text": "争端", "is_correct": false, "explanation": "“争端”（zhēng duān）与“终端”韵母不同（ong/eng），意思是冲突。"}], "explanations": {"终端": "正确答案：终端（zhōng duān）。", "中断": "“中断”（zhōng duàn）与“终端”只有第二音节声调不同，意思是中途停止。", "中段": "“中段”（zhōng duàn）与“终端”只有第二音节声调不同，意思是中间的一段。", "争端": "“争端”（zhēng duān）与“终端”韵母不同（ong/eng），意思是冲突。"}, "sentence_index": null, "correct_answer": "终端"}, "level_3": {"options": [{"text": "终端", "is_correct": true, "explanation": "终端：计算机系统中用于输入输出数据的设备，可以部署在各地并与服务器同步数据，符合句意。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是生产场所，不能被“部署”为接入系统、同步数据的设备，句意不通。"}, {"text": "农田", "is_correct": false, "explanation": "语义：农田用于种植，不能接入系统同步数据，句意不通。"}, {"text": "矿山", "is_correct": false, "explanation": "搭配：“部署”不搭配“矿山”，矿山不能同步数据，句意不通。"}], "explanations": {"终端": "终端：计算机系统中用于输入输出数据的设备，可以部署在各地并与服务器同步数据，符合句意。", "工厂": "语义：工厂是生产场所，不能被“部署”为接入系统、同步数据的设备，句意不通。", "农田": "语义：农田用于种植，不能接入系统同步数据，句意不通。", "矿山": "搭配：“部署”不搭配“矿山”，矿山不能同步数据，句意不通。"}, "sentence_index": 0, "correct_answer": "终端"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只终端。", "explanation": "量词：终端作为设备用量词“台”，“只”不用于这类机器。"}, {"text": "我买了一把终端。", "explanation": "量词：终端作为设备用量词“台”，“把”用于有柄的器具，不能用来计量终端。"}, {"text": "我们公司买了一条终端。", "explanation": "量词：终端作为设备用量词“台”，“条”用于细长的物件，不能用来计量终端。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '563d4160-02a3-4e8c-b5c0-0b1913a44586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10408, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "终端", "is_correct": true, "explanation": "“银行的终端”指银行使用的设备，能够打印单子，符合句意。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不能打印单子，“银行的花园正在打印单子”说不通。"}, {"text": "显示屏", "is_correct": false, "explanation": "搭配：显示屏只显示内容，不打印，与“打印单子”搭配不当。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不能打印，“黑板正在打印单子”与常识不符。"}], "explanations": {"终端": "“银行的终端”指银行使用的设备，能够打印单子，符合句意。", "花园": "语义：花园不能打印单子，“银行的花园正在打印单子”说不通。", "显示屏": "搭配：显示屏只显示内容，不打印，与“打印单子”搭配不当。", "黑板": "语义：黑板不能打印，“黑板正在打印单子”与常识不符。"}, "sentence_index": 6, "correct_answer": "终端"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在厨房里用这台终端煮了一锅粥。", "explanation": "这里应该用〈锅〉。“终端”是计算机设备，不能用来煮粥，煮粥要用锅。"}, {"text": "这部电影的终端很感人。", "explanation": "这里应该用〈结局〉。“终端”不指情节的结尾，电影的结尾要说“结局”。"}, {"text": "他终于喝完了这杯终端。", "explanation": "这里应该用〈咖啡〉。“终端”是计算机设备，不能被喝，应说“喝完了这杯咖啡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '563d4160-02a3-4e8c-b5c0-0b1913a44586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "图书馆有五本终端。", "corrected_sentence": "图书馆有五台终端。", "error_description": "量词错误：终端作为设备用量词“台”，“本”只用于书册，应说“五台终端”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '563d4160-02a3-4e8c-b5c0-0b1913a44586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师办公桌上摆着三张终端。", "corrected_sentence": "老师办公桌上摆着三台终端。", "error_description": "量词错误：“张”用于平面的物品，终端作为设备用量词“台”，应说“三台终端”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '563d4160-02a3-4e8c-b5c0-0b1913a44586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
