INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10409, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容时间、距离等延续很久或很远。", "primary_collocate": null, "pronunciation": "màn cháng", "ipa": "man˥˩ ʈʂʰaŋ˧˥", "syllable_count": 2, "sentences": [{"text": "在人类文明的漫长演进中，叙事作为最古老的认知方式之一，始终承载着超越语言本身的文化重量。", "target_word": "漫长", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "作为世界上交易量最大的农产品之一，咖啡豆的流动贯穿了从热带农业种植到全球都市消费终端的漫长链条。", "target_word": "漫长", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "冬天的夜晚很漫长。", "target_word": "漫长", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是一条漫长的路。", "target_word": "漫长", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他等了很久，觉得时间很漫长。", "target_word": "漫长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "漫长的假期结束了，学生们回到学校。", "target_word": "漫长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过漫长的旅行，我们终于到家了。", "target_word": "漫长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在医院里度过了漫长的一夜。", "target_word": "漫长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从北京到那个小镇，路途非常漫长。", "target_word": "漫长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走过漫长的山路，终于看到了村子。", "target_word": "漫长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "漫長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "漫长：时间、距离延续很久很远", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3e4321f-de6e-46a4-8743-02c784fb0964') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10409, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "漫长", "is_correct": true, "explanation": "漫长：形容时间延续很久，与“人类文明的演进”这种长久过程相合。"}, {"text": "短暂", "is_correct": false, "explanation": "语义：文明的演进与“最古老”的时间跨度相悖，“短暂”与之矛盾。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”用于空间，不能修饰“演进”这类时间过程。"}, {"text": "笔直", "is_correct": false, "explanation": "搭配：“笔直”描述线形，不能修饰抽象的“演进”过程。"}], "explanations": {"漫长": "漫长：形容时间延续很久，与“人类文明的演进”这种长久过程相合。", "短暂": "语义：文明的演进与“最古老”的时间跨度相悖，“短暂”与之矛盾。", "狭窄": "搭配：“狭窄”用于空间，不能修饰“演进”这类时间过程。", "笔直": "搭配：“笔直”描述线形，不能修饰抽象的“演进”过程。"}, "sentence_index": 0, "correct_answer": "漫长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他住在一个很漫长的村庄。", "explanation": "这里应该用〈遥远〉。“漫长”形容时间或路程延续得很久，说村庄离得远要用“遥远”。"}, {"text": "这家公司的规模很漫长。", "explanation": "这里应该用〈庞大〉。“漫长”说时间或距离的延续，不形容规模的大小，规模要说“庞大”。"}, {"text": "这座大楼很漫长。", "explanation": "这里应该用〈高大〉。“漫长”说时间或距离延续很久，不形容楼房的高矮，要说“高大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10409, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "漫长", "is_correct": true, "explanation": "漫长：形容旅行的时间很长，与“终于到家”所含的漫长感相合。"}, {"text": "鲜红", "is_correct": false, "explanation": "搭配：“鲜红”形容颜色，不能修饰“旅行”，句意讲不通。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或颜色，不能修饰“旅行”。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能修饰“旅行”。"}], "explanations": {"漫长": "漫长：形容旅行的时间很长，与“终于到家”所含的漫长感相合。", "鲜红": "搭配：“鲜红”形容颜色，不能修饰“旅行”，句意讲不通。", "明亮": "搭配：“明亮”形容光线或颜色，不能修饰“旅行”。", "清脆": "搭配：“清脆”形容声音，不能修饰“旅行”。"}, "sentence_index": 6, "correct_answer": "漫长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间教室很漫长。", "explanation": "这里应该用〈宽敞〉。“漫长”说时间或距离很久，不形容空间的大小，要说“宽敞”。"}, {"text": "他的性格很漫长。", "explanation": "这里应该用〈开朗〉。“漫长”形容时间或距离延续很久，不能用来形容性格，要说“开朗”。"}, {"text": "这朵花很漫长。", "explanation": "这里应该用〈鲜艳〉。“漫长”只形容时间或距离延续很久，不能用来描写花的样子，形容花要说“鲜艳”等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10409, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们走了一段漫长地路。", "corrected_sentence": "他们走了一段漫长的路。", "error_description": "错误在结构助词：“漫长”修饰名词“路”时应用“的”，“地”用于修饰动词，不能用于此处。应为“一段漫长的路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10409, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个冬天的夜晚非常很漫长。", "corrected_sentence": "这个冬天的夜晚非常漫长。", "error_description": "错误在程度副词：“漫长”前同时用了“非常”和“很”，程度副词重复。只保留一个，说“非常漫长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
