INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10411, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在赤道以南的纬度，从0°到90°S。", "primary_collocate": null, "pronunciation": "nán wěi", "ipa": "nan³⁵ weɪ²¹⁴", "syllable_count": 2, "sentences": [{"text": "在南纬25度与北纬25度之间的“咖啡带”内，数十个发展中国家依靠小农经济与大型种植园并存的模式进行咖啡种植，构成了全球农业供给的基础环节。", "target_word": "南纬", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座岛在南纬二十度附近。", "target_word": "南纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南纬和北纬以赤道分开。", "target_word": "南纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "澳大利亚大部分位于南纬十度到四十度之间。", "target_word": "南纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上写着南纬三十度。", "target_word": "南纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南纬四十度的风很大。", "target_word": "南纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条船开到了南纬六十度。", "target_word": "南纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企鹅住在南纬六十度左右的地方。", "target_word": "南纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的位置是东经一百度，南纬十度。", "target_word": "南纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "智利在南美洲，位于南纬十七度到五十六度之间。", "target_word": "南纬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "南緯", "label": "繁体"}], "register": "书面", "sense_fingerprint": "赤道以南的纬度，0°至90°S", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abfcfa9a-a51d-42c1-8ec4-e1f3a9b309a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10411, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "南纬", "is_correct": true, "explanation": "正确。咖啡带位于南纬25度与北纬25度之间，“南纬”与句中“北纬”相对，构成完整范围。"}, {"text": "北纬", "is_correct": false, "explanation": "语义：“北纬25度与北纬25度之间”两端相同，无法构成一个范围。"}, {"text": "东经", "is_correct": false, "explanation": "搭配：经度与纬度不能并列构成同类范围，“东经25度与北纬25度之间”不成立。"}, {"text": "赤道", "is_correct": false, "explanation": "搭配：“赤道”是纬度为零的线，不能加“25度”。"}], "explanations": {"南纬": "正确。咖啡带位于南纬25度与北纬25度之间，“南纬”与句中“北纬”相对，构成完整范围。", "北纬": "语义：“北纬25度与北纬25度之间”两端相同，无法构成一个范围。", "东经": "搭配：经度与纬度不能并列构成同类范围，“东经25度与北纬25度之间”不成立。", "赤道": "搭配：“赤道”是纬度为零的线，不能加“25度”。"}, "sentence_index": 0, "correct_answer": "南纬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地区的南纬很高，冬天很冷。", "explanation": "这里应该用〈纬度〉。“南纬”是具体的纬线位置，不能用来描述高低程度；说高低要用“纬度”。"}, {"text": "杭州位于南纬三十度。", "explanation": "这里应该用〈北纬〉。杭州在赤道以北，描述位置要说“北纬”；“南纬”指赤道以南的纬度。"}, {"text": "火车向南纬开去。", "explanation": "这里应该用〈南方〉。“南纬”是纬度坐标，不表示方向，表示方向应说“南方”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10411, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "南纬", "is_correct": true, "explanation": "正确。南纬六十度是一个纬度位置，船可以开到那里。"}, {"text": "时速", "is_correct": false, "explanation": "搭配：时速以公里计，不能说“开到了时速六十度”。"}, {"text": "赤道", "is_correct": false, "explanation": "搭配：赤道是纬度为零的线，后面不能接“六十度”，“开到了赤道六十度”不成立。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不是地点，不能作“开到了”的宾语。"}], "explanations": {"南纬": "正确。南纬六十度是一个纬度位置，船可以开到那里。", "时速": "搭配：时速以公里计，不能说“开到了时速六十度”。", "赤道": "搭配：赤道是纬度为零的线，后面不能接“六十度”，“开到了赤道六十度”不成立。", "温度": "语义：温度不是地点，不能作“开到了”的宾语。"}, "sentence_index": 6, "correct_answer": "南纬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新西兰位于南纬。", "explanation": "这里应该用〈南半球〉。“南纬”必须带具体度数，单说“南纬”不能表示地区位置；描述半球位置要用“南半球”。"}, {"text": "这座城市的南纬有三百公里。", "explanation": "这里应该用〈距离〉。“南纬”是纬线的位置（度数），不能表示长度；说离赤道多远要用“距离”，如“离赤道三百公里”。"}, {"text": "这座小岛靠近南纬。", "explanation": "这里应该用〈赤道〉。表示靠近的位置要说“靠近赤道”；“南纬”需带具体度数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10411, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个岛位于南纬三十左右。", "corrected_sentence": "这个岛位于南纬三十度左右。", "error_description": "漏了单位“度”。纬度数值后要带“度”，应说“南纬三十度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10411, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条船在南纬四十度南的海域航行。", "corrected_sentence": "这条船在南纬四十度以南的海域航行。", "error_description": "漏了方位词“以”。表示某纬度以南要说“南纬四十度以南”，不能省略“以”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10417, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "商品经济", "is_correct": true, "explanation": "〈商品经济〉以交换和销售为目的，与以自给自足为主、商品率低的小农经济相对，构成反义关系。"}, {"text": "高速公路", "is_correct": false, "explanation": "〈高速公路〉是交通设施，与经济形态没有反义关系。"}, {"text": "海洋生物", "is_correct": false, "explanation": "〈海洋生物〉指海洋中的生物，与农业经济形态无关。"}, {"text": "文学作品", "is_correct": false, "explanation": "〈文学作品〉指文学创作成果，与生产规模和经济形态无关。"}], "correct_answer": "商品经济", "explanations": {"商品经济": "〈商品经济〉以交换和销售为目的，与以自给自足为主、商品率低的小农经济相对，构成反义关系。", "高速公路": "〈高速公路〉是交通设施，与经济形态没有反义关系。", "海洋生物": "〈海洋生物〉指海洋中的生物，与农业经济形态无关。", "文学作品": "〈文学作品〉指文学创作成果，与生产规模和经济形态无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10417, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "商品经济", "is_correct": true, "explanation": "〈商品经济〉以交换和销售为目的，与以自给自足为主、商品率低的小农经济相对，构成反义关系。"}, {"text": "天气预报", "is_correct": false, "explanation": "〈天气预报〉是对天气变化的预测信息，与经济形态没有关系。"}, {"text": "电子游戏", "is_correct": false, "explanation": "〈电子游戏〉是娱乐产品，与农业经济形态没有反义关系。"}, {"text": "博物馆", "is_correct": false, "explanation": "〈博物馆〉是收藏展示文物的场所，与经济形态无关。"}], "correct_answer": "商品经济", "explanations": {"商品经济": "〈商品经济〉以交换和销售为目的，与以自给自足为主、商品率低的小农经济相对，构成反义关系。", "天气预报": "〈天气预报〉是对天气变化的预测信息，与经济形态没有关系。", "电子游戏": "〈电子游戏〉是娱乐产品，与农业经济形态没有反义关系。", "博物馆": "〈博物馆〉是收藏展示文物的场所，与经济形态无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10417, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以家庭为单位、生产规模小、商品率低、自给自足为主的农业经济形态。", "primary_collocate": null, "pronunciation": "xiǎo nóng jīng jì", "ipa": "ɕjɑʊ²¹⁴ nʊŋ³⁵ tɕiŋ⁵⁵ tɕi⁵¹", "syllable_count": 4, "sentences": [{"text": "在南纬25度与北纬25度之间的“咖啡带”内，数十个发展中国家依靠小农经济与大型种植园并存的模式进行咖啡种植，构成了全球农业供给的基础环节。", "target_word": "小农经济", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "小农经济以一家人种地为主。", "target_word": "小农经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去很多国家都是小农经济。", "target_word": "小农经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小农经济生产的粮食，自己家吃。", "target_word": "小农经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说小农经济的特点是自给自足。", "target_word": "小农经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在小农经济里，农民很少卖东西。", "target_word": "小农经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂多了以后，小农经济慢慢变少了。", "target_word": "小农经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小农经济的生产规模很小。", "target_word": "小农经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家还过着小农经济的生活。", "target_word": "小农经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，小农经济就是一家一户自己种地，粮食自己吃。", "target_word": "小农经济", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小農經濟", "label": "繁体"}], "register": "书面", "sense_fingerprint": "以家庭为单位、规模小、自给自足的农业经济形态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abfcfa9a-a51d-42c1-8ec4-e1f3a9b309a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10417, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小农经济", "is_correct": true, "explanation": "正确：与后文“大型种植园”对照的、以家庭为单位的小规模农业形态，句意通顺。"}, {"text": "冷链物流", "is_correct": false, "explanation": "语义：物流不是一种种植模式，不能说“依靠冷链物流与大型种植园并存的模式进行咖啡种植”。"}, {"text": "汽车制造", "is_correct": false, "explanation": "语义：汽车制造属于工业生产，不能作为“进行咖啡种植”的依靠方式。"}, {"text": "城市商业", "is_correct": false, "explanation": "搭配：“依靠……并存的模式”后接的是生产方式，“城市商业”不能充当种植的生产方式。"}], "explanations": {"小农经济": "正确：与后文“大型种植园”对照的、以家庭为单位的小规模农业形态，句意通顺。", "冷链物流": "语义：物流不是一种种植模式，不能说“依靠冷链物流与大型种植园并存的模式进行咖啡种植”。", "汽车制造": "语义：汽车制造属于工业生产，不能作为“进行咖啡种植”的依靠方式。", "城市商业": "搭配：“依靠……并存的模式”后接的是生产方式，“城市商业”不能充当种植的生产方式。"}, "sentence_index": 0, "correct_answer": "小农经济"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家小农经济每年都在证券交易所挂牌上市。", "explanation": "这里应该用〈股份公司〉。小农经济以家庭为单位、规模小，不能挂牌上市；能上市的是〈股份公司〉。"}, {"text": "我们村是小农经济，产品大量出口到国外。", "explanation": "这里应该用〈外向型经济〉。小农经济以自给自足为主、商品率低，产品大量出口到国外要用〈外向型经济〉。"}, {"text": "这家小农经济有二十条生产线，雇了五百名工人。", "explanation": "这里应该用〈工厂〉。小农经济规模小，不会有生产线和大量雇工；说规模大的企业要用〈工厂〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10417, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小农经济", "is_correct": true, "explanation": "正确：说的是小农经济的形态在减少，与“工厂多了”形成对照，句意通顺。"}, {"text": "城市化", "is_correct": false, "explanation": "语义：“城市化”是一个进程，不能说“慢慢变少”，也与“工厂多了”的因果对不上。"}, {"text": "工业生产", "is_correct": false, "explanation": "语义：“工厂多了”意味着工业生产增加，接“慢慢变少”会与前半句矛盾。"}, {"text": "人口老龄化", "is_correct": false, "explanation": "搭配：“老龄化”是一种趋势，一般说“加深”，不与“变少”搭配。"}], "explanations": {"小农经济": "正确：说的是小农经济的形态在减少，与“工厂多了”形成对照，句意通顺。", "城市化": "语义：“城市化”是一个进程，不能说“慢慢变少”，也与“工厂多了”的因果对不上。", "工业生产": "语义：“工厂多了”意味着工业生产增加，接“慢慢变少”会与前半句矛盾。", "人口老龄化": "搭配：“老龄化”是一种趋势，一般说“加深”，不与“变少”搭配。"}, "sentence_index": 6, "correct_answer": "小农经济"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们村的小农经济很发达，家家都开了店。", "explanation": "这里应该用〈农村经济〉。小农经济特指以家庭为单位、自给自足的形态，“家家开店”属于商业经营，与它的定义不符。"}, {"text": "这家小农经济每天都在网上直播带货。", "explanation": "这里应该用〈公司〉。小农经济是经济形态，不能充当直播带货的经营主体。"}, {"text": "我们村的小农经济发展得很快，农民把粮食都卖到城里。", "explanation": "这里应该用〈商品经济〉。小农经济以自给自足为主、商品率低，不能说农民把粮食都卖到城里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10417, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在那个年代，把小农经济占主导地位。", "corrected_sentence": "在那个年代，小农经济占主导地位。", "error_description": "多了“把”。“小农经济”是主语，应直接放在动词“占”之前，不能用“把”引出；正确形式是“小农经济占主导地位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10417, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个村子现在还小农经济。", "corrected_sentence": "那个村子现在还是小农经济。", "error_description": "漏字：“是”漏掉了。“小农经济”作谓语，前面要用“是”。错误形式是“还小农经济”，正确形式是“还是小农经济”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
