INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10418, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "种植园是指大规模集中种植某种经济作物（如茶叶、橡胶、甘蔗等）的农场或庄园。", "primary_collocate": null, "pronunciation": "zhòng zhí yuán", "ipa": "ʈʂʊŋ˥˩ ʈʂɨ˧˥ ɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "在南纬25度与北纬25度之间的“咖啡带”内，数十个发展中国家依靠小农经济与大型种植园并存的模式进行咖啡种植，构成了全球农业供给的基础环节。", "target_word": "种植园", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个种植园很大，里面种满了茶树。", "target_word": "种植园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐车去了山上的种植园。", "target_word": "种植园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种植园里的工人每天很早就起床。", "target_word": "种植园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家种植园专门种橡胶树。", "target_word": "种植园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一个甘蔗种植园工作过。", "target_word": "种植园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种植园的老板请我们喝了茶。", "target_word": "种植园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，种植园里来了很多游客。", "target_word": "种植园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那片种植园离我家不远。", "target_word": "种植园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种植园的工人正在摘咖啡豆。", "target_word": "种植园", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "茶叶种植园", "label": "复合"}, {"form": "橡胶种植园", "label": "复合"}, {"form": "種植園", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大规模集中种植单一经济作物的农场或庄园", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abfcfa9a-a51d-42c1-8ec4-e1f3a9b309a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10418, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "种植园", "is_correct": true, "explanation": "正确：指大规模种植作物的农场，与“小农经济”并列对照，句意通顺。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂不是种植作物的场所，不能用于“进行咖啡种植”。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是销售场所，与“咖啡种植”的生产方式不符。"}, {"text": "矿山", "is_correct": false, "explanation": "搭配：“进行……种植”的对象是作物，“矿山”不与“种植”搭配。"}], "explanations": {"种植园": "正确：指大规模种植作物的农场，与“小农经济”并列对照，句意通顺。", "工厂": "语义：工厂不是种植作物的场所，不能用于“进行咖啡种植”。", "超市": "语义：超市是销售场所，与“咖啡种植”的生产方式不符。", "矿山": "搭配：“进行……种植”的对象是作物，“矿山”不与“种植”搭配。"}, "sentence_index": 0, "correct_answer": "种植园"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个种植园一楼卖衣服，二楼卖电器。", "explanation": "这里应该用〈商场〉。种植园是种植经济作物的大农场，没有楼层、不卖商品；分层售卖衣服和电器要用〈商场〉。"}, {"text": "种植园每天生产上千台机器。", "explanation": "这里应该用〈工厂〉。种植园是种植作物的农场，不生产机器；大批量生产机器要用〈工厂〉。"}, {"text": "我们村附近有一个种植园，孩子们每天放学后在那里踢球。", "explanation": "这里应该用〈操场〉。种植园是大规模种植经济作物的农场，不是孩子踢球的场地；踢球的场地要用〈操场〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10418, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "种植园", "is_correct": true, "explanation": "正确：大规模种植作物的农场，与“老板”“喝茶”的语境一致。"}, {"text": "月球", "is_correct": false, "explanation": "语义：月球上没有人经营的农场或店铺，“月球的老板”不成立。"}, {"text": "图书馆", "is_correct": false, "explanation": "搭配：“老板”多用于店铺、企业，图书馆由公共机构管理，不与“老板”搭配。"}, {"text": "博物馆", "is_correct": false, "explanation": "语义：博物馆由机构管理，没有“老板”这种经营者，句意说不通。"}], "explanations": {"种植园": "正确：大规模种植作物的农场，与“老板”“喝茶”的语境一致。", "月球": "语义：月球上没有人经营的农场或店铺，“月球的老板”不成立。", "图书馆": "搭配：“老板”多用于店铺、企业，图书馆由公共机构管理，不与“老板”搭配。", "博物馆": "语义：博物馆由机构管理，没有“老板”这种经营者，句意说不通。"}, "sentence_index": 6, "correct_answer": "种植园"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座种植园的设计师把假山布置得很漂亮。", "explanation": "这里应该用〈园林〉。〈种植园〉是大规模种植作物的农场，不负责景观设计。"}, {"text": "种植园每天有很多人排队进站。", "explanation": "这里应该用〈地铁站〉。种植园是种植作物的大农场，没有车站；排队进站要用〈地铁站〉。"}, {"text": "种植园里的法官正在审理案件，旁听席上坐满了人。", "explanation": "这里应该用〈法院〉。种植园是种植作物的农场，没有法官和旁听席；审理案件、设有旁听席的场所要用〈法院〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我父亲种植园里工作了三年。", "corrected_sentence": "我父亲在种植园里工作了三年。", "error_description": "漏字：表示地点的“在”漏掉了。错误形式是“种植园里工作”，正确形式是“在种植园里工作”，地点要用“在……里”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在一只种植园附近盖了房子。", "corrected_sentence": "他们在一座种植园附近盖了房子。", "error_description": "量词错误：“种植园”应用“座”计量，“只”只用于动物。错误形式是“一只种植园”，正确形式是“一座种植园”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
