INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10419, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10419, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "同时存在", "primary_collocate": null, "pronunciation": "bìng cún", "ipa": "piŋ˥˩ tsʰuən˧˥", "syllable_count": 2, "sentences": [{"text": "在南纬25度与北纬25度之间的“咖啡带”内，数十个发展中国家依靠小农经济与大型种植园并存的模式进行咖啡种植，构成了全球农业供给的基础环节。", "target_word": "并存", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今日，记谱法的发展呈现出多元并存格局。", "target_word": "并存", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "新旧两种方法在这家公司并存。", "target_word": "并存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老城区里，古老的建筑和现代的高楼并存。", "target_word": "并存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市里，两种语言长期并存。", "target_word": "并存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机会和风险常常并存。", "target_word": "并存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个国家，几种宗教并存了很多年。", "target_word": "并存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传统市场与网上商店在这里并存。", "target_word": "并存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里喜悦与不安并存。", "target_word": "并存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种制度曾经并存过一段时间。", "target_word": "并存", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "并存着", "label": "体标"}, {"form": "并存过", "label": "体标"}], "register": "书面", "sense_fingerprint": "两种或多种事物、现象在同一时间、同一地方一起存在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af58cd74-a966-4809-b2bd-5cb92529248a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10419, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "并存", "is_correct": true, "explanation": "正确：“并存”表示两种经济形式同时存在，与句中“依靠……的模式”相符。"}, {"text": "对立", "is_correct": false, "explanation": "语义：“对立”指相互抵触，与“依靠”和“构成全球农业供给的基础环节”的意思相反。"}, {"text": "割裂", "is_correct": false, "explanation": "语义：“割裂”指分开、断开，与两者共同支撑农业供给的语境相反。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“结婚”只用于人与人之间，不能说经济模式与种植园结婚。"}], "explanations": {"并存": "正确：“并存”表示两种经济形式同时存在，与句中“依靠……的模式”相符。", "对立": "语义：“对立”指相互抵触，与“依靠”和“构成全球农业供给的基础环节”的意思相反。", "割裂": "语义：“割裂”指分开、断开，与两者共同支撑农业供给的语境相反。", "结婚": "搭配：“结婚”只用于人与人之间，不能说经济模式与种植园结婚。"}, "sentence_index": 0, "correct_answer": "并存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座大楼并存于老城区。", "explanation": "这里应该用〈存在〉。“存在”可用于单个事物；“并存”指两种或更多事物同时存在，一座大楼不能说并存。"}, {"text": "两人并存于同一个团队。", "explanation": "这里应该用〈共事〉。“共事”指人一起工作；“并存”用于事物或情况同时存在，不用于人共同工作。"}, {"text": "这场比赛并存于下午三点。", "explanation": "这里应该用〈举行〉。“并存”指两种或多种事物同时存在，一场比赛不能并存于某个时间；比赛在某时进行要说“举行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10419, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "并存", "is_correct": true, "explanation": "正确：“并存”指几种宗教长期同时存在，与“了很多年”相符。"}, {"text": "诞生", "is_correct": false, "explanation": "体貌：“诞生”是一次完成的动作，不能和“了很多年”这样的时段连用。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”只用于书籍、报刊等出版物，不能用于宗教。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：“出生”只用于人或动物，不能用于宗教。"}], "explanations": {"并存": "正确：“并存”指几种宗教长期同时存在，与“了很多年”相符。", "诞生": "体貌：“诞生”是一次完成的动作，不能和“了很多年”这样的时段连用。", "出版": "搭配：“出版”只用于书籍、报刊等出版物，不能用于宗教。", "出生": "搭配：“出生”只用于人或动物，不能用于宗教。"}, "sentence_index": 6, "correct_answer": "并存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两张并存的书桌摆在窗边。", "explanation": "这里应该用〈并排〉。“并排”可修饰“书桌”描述摆放；“并存”只表示同时存在，不能描述书桌的摆放。"}, {"text": "两军并存于战场两侧。", "explanation": "这里应该用〈对峙〉。“对峙”指双方对立而相持；“并存”只表示同时存在，不能描述两军的对立状态。"}, {"text": "一位老师并存于两个班级。", "explanation": "这里应该用〈兼任〉。“兼任”指一人同时担任两个职务；“并存”指事物或情况同时存在，不用于一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10419, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小镇里，老房子和新公寓被并存。", "corrected_sentence": "这个小镇里，老房子和新公寓并存。", "error_description": "错误：“并存”前面加了“被”。并存是不及物动词，没有被动用法，应说“老房子和新公寓并存”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10419, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条街上，传统书店和网络咖啡馆并存了着。", "corrected_sentence": "这条街上，传统书店和网络咖啡馆并存着。", "error_description": "错误：“并存”后面同时用了“了”和“着”两个体标。应只用“着”，说“并存着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
