INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10424, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指物品最初生产或出产的地方。", "primary_collocate": null, "pronunciation": "yuán chǎn dì", "ipa": "ɥɛn˧˥ ʈʂʰan˨˩˦ ti˥˩", "syllable_count": 3, "sentences": [{"text": "这些原产地国家，如拉丁美洲的安第斯山麓地区、东非高原以及东南亚的火山群岛，凭借其独特的微气候与海拔条件，培育出具有地域风味特征的咖啡豆品种，其中阿拉比卡与罗布斯塔是最主要的两类。", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "一方面，大众零售市场依赖规模化生产的速溶咖啡与连锁咖啡店标准化产品；另一方面，精品咖啡运动的兴起推动了“从种子到杯子”的溯源理念，消费者愈发关注产地故事、处理工艺与风味谱系，进而反向影响原产地的种植实践与分级标准。", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这种茶叶的原产地是中国。", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买水果的时候，我喜欢看原产地。", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡的原产地在非洲。", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶酒上写着原产地：法国。", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我这些牛肉的原产地。", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "香蕉的原产地很热，一年四季都不冷。", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原产地不同，味道也不一样。", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他特意去了这种水果的原产地。", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原产地国家", "label": "复合"}, {"form": "原產地", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物品最初生产或出产的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abfcfa9a-a51d-42c1-8ec4-e1f3a9b309a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10424, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原产地", "is_correct": true, "explanation": "正确。“这些原产地国家”指咖啡最初出产的国家，与后文的培育条件相符。"}, {"text": "消费", "is_correct": false, "explanation": "语义：“消费国家”指消费咖啡的国家，与后文“培育出咖啡豆品种”矛盾。"}, {"text": "移民", "is_correct": false, "explanation": "语义：“移民国家”指接收移民的国家，与咖啡的生长条件无关。"}, {"text": "邻居", "is_correct": false, "explanation": "语义与语域：句中列举的国家分散在拉美、东非与东南亚，互不相邻；“邻居”又偏口语。"}], "explanations": {"原产地": "正确。“这些原产地国家”指咖啡最初出产的国家，与后文的培育条件相符。", "消费": "语义：“消费国家”指消费咖啡的国家，与后文“培育出咖啡豆品种”矛盾。", "移民": "语义：“移民国家”指接收移民的国家，与咖啡的生长条件无关。", "邻居": "语义与语域：句中列举的国家分散在拉美、东非与东南亚，互不相邻；“邻居”又偏口语。"}, "sentence_index": 0, "correct_answer": "原产地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的弟弟原产地是上海。", "explanation": "这里应该用〈出生地〉。原产地指物品的出产地，说人要用出生地或籍贯。"}, {"text": "这条河的原产地在山上。", "explanation": "这里应该用〈源头〉。原产地指物品的出产地，河流的起点要说源头。"}, {"text": "这场比赛的原产地是北京。", "explanation": "这里应该用〈举办地〉。原产地指物品的出产地，比赛要说举办地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原产地", "is_correct": true, "explanation": "正确。“请告诉我这些牛肉的原产地”问的是牛肉的出产地。"}, {"text": "作者", "is_correct": false, "explanation": "语义：牛肉没有作者，“作者”与这个问题的内容不符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人或动物的高矮，不能用来说牛肉。"}, {"text": "生日", "is_correct": false, "explanation": "语义：牛肉没有生日，“生日”与这个问题无关。"}], "explanations": {"原产地": "正确。“请告诉我这些牛肉的原产地”问的是牛肉的出产地。", "作者": "语义：牛肉没有作者，“作者”与这个问题的内容不符。", "身高": "体貌：“身高”指人或动物的高矮，不能用来说牛肉。", "生日": "语义：牛肉没有生日，“生日”与这个问题无关。"}, "sentence_index": 6, "correct_answer": "原产地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份数据的原产地是政府。", "explanation": "这里应该用〈来源〉。原产地指物品的出产地，数据、信息的出处要说来源。"}, {"text": "这段话的原产地是一本古书。", "explanation": "这里应该用〈出处〉。原产地指物品的出产地，文字从哪里来要说出处。"}, {"text": "他的原产地是山东。", "explanation": "这里应该用〈籍贯〉。原产地只用于物品，人的籍贯要说籍贯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种咖啡的原产地被埃塞俄比亚。", "corrected_sentence": "这种咖啡的原产地是埃塞俄比亚。", "error_description": "误用“被”：“原产地”后应用“是”引出出产地，“被”表被动，与句意不符。错误形式是“原产地被”，正确形式是“原产地是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "埃塞俄比亚是这款咖啡了原产地。", "corrected_sentence": "埃塞俄比亚是这款咖啡的原产地。", "error_description": "用词错误：“的”误用为“了”。“这款咖啡”修饰“原产地”，中间要用结构助词“的”，“了”是体标，不能连接定语和名词。错误形式是“这款咖啡了原产地”，正确形式是“这款咖啡的原产地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
