INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10427, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10427, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "山麓指山脚，即山的底部与平地相接的部分。", "primary_collocate": null, "pronunciation": "shān lù", "ipa": "ʂan˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "这些原产地国家，如拉丁美洲的安第斯山麓地区、东非高原以及东南亚的火山群岛，凭借其独特的微气候与海拔条件，培育出具有地域风味特征的咖啡豆品种，其中阿拉比卡与罗布斯塔是最主要的两类。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我们的帐篷就在山麓。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小村子在山麓，那里很安静。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山麓有一条小河。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走到山麓时，天已经黑了。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山麓的花开了，山顶还有雪。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把车停在了山麓。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从山麓往上看，云在山顶上。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山麓的空气很新鲜。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的房子在山麓，离城里很远。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "山麓地区", "label": "复合"}], "register": "书面", "sense_fingerprint": "山的底部与平地相接的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abfcfa9a-a51d-42c1-8ec4-e1f3a9b309a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10427, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "山麓", "is_correct": true, "explanation": "正确。山麓指山脚，即山的底部与平地相接的部分。"}, {"text": "山雾", "is_correct": false, "explanation": "声母不同：「雾」与「麓」的声母不同，意思是山里的雾气。"}, {"text": "山兔", "is_correct": false, "explanation": "声母不同：「兔」与「麓」只差声母（t / l），声调与韵母相同，意思是山里的野兔。"}, {"text": "山腹", "is_correct": false, "explanation": "声母不同：「腹」与「麓」只差声母（f / l），声调与韵母相同，意思是山的中部。"}], "explanations": {"山麓": "正确。山麓指山脚，即山的底部与平地相接的部分。", "山雾": "声母不同：「雾」与「麓」的声母不同，意思是山里的雾气。", "山兔": "声母不同：「兔」与「麓」只差声母（t / l），声调与韵母相同，意思是山里的野兔。", "山腹": "声母不同：「腹」与「麓」只差声母（f / l），声调与韵母相同，意思是山的中部。"}, "sentence_index": null, "correct_answer": "山麓"}, "level_3": {"options": [{"text": "山麓", "is_correct": true, "explanation": "正确。“安第斯山麓地区”指安第斯山脚的一带，与前文讲的咖啡产地相符。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠干旱，不适合培育咖啡豆，与句中的“微气候与海拔条件”相矛盾。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市不是咖啡的生长地，与“培育出咖啡豆品种”矛盾。"}, {"text": "海洋", "is_correct": false, "explanation": "搭配：“安第斯”是山脉名，不与“海洋”搭配，“安第斯海洋地区”说不通。"}], "explanations": {"山麓": "正确。“安第斯山麓地区”指安第斯山脚的一带，与前文讲的咖啡产地相符。", "沙漠": "语义：沙漠干旱，不适合培育咖啡豆，与句中的“微气候与海拔条件”相矛盾。", "城市": "语义：城市不是咖啡的生长地，与“培育出咖啡豆品种”矛盾。", "海洋": "搭配：“安第斯”是山脉名，不与“海洋”搭配，“安第斯海洋地区”说不通。"}, "sentence_index": 0, "correct_answer": "山麓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山的山麓在半山腰。", "explanation": "这里应该用〈半山腰〉。山麓指山脚，半山腰是山的中段，不能用山麓来指。"}, {"text": "山麓插入了云层。", "explanation": "这里应该用〈山峰〉。插入云层的是山峰，山麓在山底。"}, {"text": "我们爬到了最高的山麓，看到了日出。", "explanation": "这里应该用〈山顶〉。山麓是山脚，最高的地方要说山顶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10427, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "山麓", "is_correct": true, "explanation": "正确。山麓指山脚，即山的底部与平地相接的部分。"}, {"text": "上路", "is_correct": false, "explanation": "音近：「上路」shàng lù 与「山麓」shān lù 只差韵尾与声调，意思是出发。"}, {"text": "仙露", "is_correct": false, "explanation": "声母不同：「仙」与「山」只差声母（x / sh），韵母与声调相同，意思是仙人所饮的露水。"}, {"text": "三路", "is_correct": false, "explanation": "声母不同：「三」与「山」只差声母（s / sh），韵母与声调相同，意思是三条路。"}], "explanations": {"山麓": "正确。山麓指山脚，即山的底部与平地相接的部分。", "上路": "音近：「上路」shàng lù 与「山麓」shān lù 只差韵尾与声调，意思是出发。", "仙露": "声母不同：「仙」与「山」只差声母（x / sh），韵母与声调相同，意思是仙人所饮的露水。", "三路": "声母不同：「三」与「山」只差声母（s / sh），韵母与声调相同，意思是三条路。"}, "sentence_index": null, "correct_answer": "山麓"}, "level_3": {"options": [{"text": "山麓", "is_correct": true, "explanation": "正确。“停在山麓”指把车停在山脚下，与句意相符。"}, {"text": "大海", "is_correct": false, "explanation": "语义：车不能停在大海里，“大海”与“停车”不相容。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“停在”需要地面，“天空”不能让车停靠。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：车不可能停在书桌上，与句子所指的地点不符。"}], "explanations": {"山麓": "正确。“停在山麓”指把车停在山脚下，与句意相符。", "大海": "语义：车不能停在大海里，“大海”与“停车”不相容。", "天空": "搭配：“停在”需要地面，“天空”不能让车停靠。", "书桌": "语义：车不可能停在书桌上，与句子所指的地点不符。"}, "sentence_index": 6, "correct_answer": "山麓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山的山麓很尖。", "explanation": "这里应该用〈山尖〉。山麓是山的底部，不能用“尖”来形容。"}, {"text": "这座山的山麓比云还高。", "explanation": "这里应该用〈山巅〉。山麓在山底，比云还高要说山巅，不能用山麓。"}, {"text": "我家门口有一座山麓，海拔三千米。", "explanation": "这里应该用〈山〉。山麓指山脚，说整座山的海拔要用山，不能说山麓海拔三千米。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10427, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把帐篷搭山麓。", "corrected_sentence": "我们把帐篷搭在山麓。", "error_description": "错误：“搭”后面接处所“山麓”时漏掉了介词“在”。正确：“把帐篷搭在山麓”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10427, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条山麓很安静。", "corrected_sentence": "那片山麓很安静。", "error_description": "错误：“山麓”是一片地方，应用量词“片”；“条”用于细长的东西，不能用来数山麓。正确：“那片山麓很安静”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
