INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10429, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10429, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海拔较高，地势相对平坦开阔的大片地区。", "primary_collocate": null, "pronunciation": "gāo yuán", "ipa": "kau˥ yɛn˧˥", "syllable_count": 2, "sentences": [{"text": "例如，在某些高原农业区，野生蜂类数量锐减已导致本地果树坐果率不足三成，迫使农民转向成本高昂的人工授粉，这不仅增加了农业生产的经济负担，也暴露了食物供应链的脆弱性。", "target_word": "高原", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "高原上的氧气比平原少。", "target_word": "高原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小在高原上长大。", "target_word": "高原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高原上风大，夏天也很冷。", "target_word": "高原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐火车去了高原。", "target_word": "高原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上最高的高原在中国。", "target_word": "高原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高原的冬天又长又冷。", "target_word": "高原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高原上的湖水又蓝又干净。", "target_word": "高原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次上高原，我头有点疼。", "target_word": "高原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牧民在高原上骑着马放羊。", "target_word": "高原", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片高原", "label": "量词"}, {"form": "高原反应", "label": "复合"}], "register": "中性", "sense_fingerprint": "海拔高、地面相对平坦开阔的大片地理区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af58cd74-a966-4809-b2bd-5cb92529248a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10429, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高原", "is_correct": true, "explanation": "正确：“高原”指海拔高、地势平坦开阔的大片地区，与“农业区”相符。"}, {"text": "冰川", "is_correct": false, "explanation": "语义：“冰川”被冰层覆盖，不能进行果树种植和人工授粉，与句中的农业活动矛盾。"}, {"text": "雪原", "is_correct": false, "explanation": "语义：“雪原”是积雪覆盖的平地，不适合果树生长，与句中的农业区矛盾。"}, {"text": "工业", "is_correct": false, "explanation": "搭配：“工业”与“农业区”不能这样组合，说“工业农业区”不成词组。"}], "explanations": {"高原": "正确：“高原”指海拔高、地势平坦开阔的大片地区，与“农业区”相符。", "冰川": "语义：“冰川”被冰层覆盖，不能进行果树种植和人工授粉，与句中的农业活动矛盾。", "雪原": "语义：“雪原”是积雪覆盖的平地，不适合果树生长，与句中的农业区矛盾。", "工业": "搭配：“工业”与“农业区”不能这样组合，说“工业农业区”不成词组。"}, "sentence_index": 0, "correct_answer": "高原"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家住在高原的海边，每天都能听见海浪声。", "explanation": "这里应该用〈沿海〉。高原是海拔较高的内陆地区，不靠海；靠海要说“沿海”。"}, {"text": "这里是一片广阔的高原，地势很低，雨季常有积水。", "explanation": "这里应该用〈平原〉。平原地势低平；高原海拔高，与“地势很低”矛盾。"}, {"text": "这座高原浮在海面上，四周都是海水。", "explanation": "这里应该用〈岛屿〉。“岛屿”四面环水，而高原是陆地上海拔较高的大片地区，不能说四周都是海水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10429, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高原", "is_correct": true, "explanation": "正确：“高原”指海拔高的大片地区，冬天又长又冷，与句意相符。"}, {"text": "热带", "is_correct": false, "explanation": "语义：热带没有明显的冬季，与“又长又冷”的冬天矛盾。"}, {"text": "夏季", "is_correct": false, "explanation": "语义：“夏季”与“冬天”自相矛盾，句子无法成立。"}, {"text": "课堂", "is_correct": false, "explanation": "搭配：“课堂”不是地域，不能说“课堂的冬天”。"}], "explanations": {"高原": "正确：“高原”指海拔高的大片地区，冬天又长又冷，与句意相符。", "热带": "语义：热带没有明显的冬季，与“又长又冷”的冬天矛盾。", "夏季": "语义：“夏季”与“冬天”自相矛盾，句子无法成立。", "课堂": "搭配：“课堂”不是地域，不能说“课堂的冬天”。"}, "sentence_index": 6, "correct_answer": "高原"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块高原比周围的地方低得多，雨季常积水。", "explanation": "这里应该用〈洼地〉。洼地地势低于周围；高原海拔高于周围，说“比周围低得多”与高原的定义矛盾。"}, {"text": "这片高原很深，两边都是陡峭的山壁。", "explanation": "这里应该用〈山谷〉。山谷有深度和两侧陡峭的山壁；高原顶面平坦，不能说“很深”。"}, {"text": "这个高原四面环山，地势很低。", "explanation": "这里应该用〈盆地〉。盆地四周高、中间低；高原海拔高，不能说“地势很低”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10429, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那棵广阔的高原上有很多牛羊。", "corrected_sentence": "那片广阔的高原上有很多牛羊。", "error_description": "错误：“那棵广阔的高原”，量词用错了。大片地区应该用“片”，不能用“棵”。应说“那片广阔的高原上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10429, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一只高原上草场广阔，牛羊很多。", "corrected_sentence": "这一片高原上草场广阔，牛羊很多。", "error_description": "错误：“高原”的量词用错了。大片地区应该用“片”，不能用“只”。应说“这一片高原”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
