INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10431, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "火山是地壳深处岩浆喷出地表堆积形成的山，常有喷发活动。", "primary_collocate": null, "pronunciation": "huǒ shān", "ipa": "xuɔ˨˩˦ ʂan˥˥", "syllable_count": 2, "sentences": [{"text": "这座火山已经几百年没有喷发了。", "target_word": "火山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火山喷发时，热的岩浆会从山顶流出来。", "target_word": "火山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日本有很多火山，所以温泉也很多。", "target_word": "火山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家每天都在观察这座火山的变化。", "target_word": "火山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火山周围的土地很肥沃，农民喜欢在那里种地。", "target_word": "火山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爬上那座火山，看到山顶有一个大坑。", "target_word": "火山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地壳深处的岩浆冲出地面，就形成了火山。", "target_word": "火山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏威夷的火山每年都吸引很多游客。", "target_word": "火山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家说这座火山不会再喷发了。", "target_word": "火山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了火山是怎么形成的。", "target_word": "火山", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "火山灰", "label": "复合"}], "register": "中性", "sense_fingerprint": "火山：岩浆喷出堆积而成、会喷发的山（地理科学义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965d3399-3e60-46ea-aa3b-18edf6edc58a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10431, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "火山", "is_correct": true, "explanation": "正确：火山会喷发，「几百年没有喷发」说的正是火山，量词「座」也合适。"}, {"text": "桥", "is_correct": false, "explanation": "语义：桥是人造的通道，不会喷发，与「喷发」的意思冲突。"}, {"text": "大楼", "is_correct": false, "explanation": "搭配：「喷发」只与火山、间歇泉这类地质现象搭配，不与大楼搭配。"}, {"text": "寺庙", "is_correct": false, "explanation": "语义：寺庙是供人礼佛的建筑，不会喷发，句子说不通。"}], "explanations": {"火山": "正确：火山会喷发，「几百年没有喷发」说的正是火山，量词「座」也合适。", "桥": "语义：桥是人造的通道，不会喷发，与「喷发」的意思冲突。", "大楼": "搭配：「喷发」只与火山、间歇泉这类地质现象搭配，不与大楼搭配。", "寺庙": "语义：寺庙是供人礼佛的建筑，不会喷发，句子说不通。"}, "sentence_index": 0, "correct_answer": "火山"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "科学家每天都在观察这只火山的变化。", "explanation": "这里应该用〈座〉。「只」用于动物，火山是山体，量词要用「座」。"}, {"text": "科学家每天都在观察这棵火山的变化。", "explanation": "这里应该用〈座〉。「棵」用于树木、花草，火山不能用「棵」计量。"}, {"text": "科学家每天都在观察这台火山的变化。", "explanation": "这里应该用〈座〉。「台」用于机器、仪器，火山是山，应说「座」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10431, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火山", "is_correct": true, "explanation": "正确：岩浆冲出地面会形成火山，「就形成了」后接的是地貌名称。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：岩浆是高温熔岩，冲出地面不会形成彩虹。"}, {"text": "珍珠", "is_correct": false, "explanation": "搭配：「形成了」与「珍珠」搭配不当，珍珠是贝类的产物，与岩浆喷出地面无关。"}, {"text": "冰川", "is_correct": false, "explanation": "语义：冰川是低温形成的冰体，与高温岩浆冲出地面的过程矛盾。"}], "explanations": {"火山": "正确：岩浆冲出地面会形成火山，「就形成了」后接的是地貌名称。", "彩虹": "语义：岩浆是高温熔岩，冲出地面不会形成彩虹。", "珍珠": "搭配：「形成了」与「珍珠」搭配不当，珍珠是贝类的产物，与岩浆喷出地面无关。", "冰川": "语义：冰川是低温形成的冰体，与高温岩浆冲出地面的过程矛盾。"}, "sentence_index": 6, "correct_answer": "火山"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师给我们讲了那条火山是怎么形成的。", "explanation": "这里应该用〈座〉。「条」用于细长的东西，火山是山体，要说「那座火山」。"}, {"text": "老师给我们讲了那本火山是怎么形成的。", "explanation": "这里应该用〈座〉。「本」用于书籍，火山不是书，要说「那座火山」。"}, {"text": "老师给我们讲了那辆火山是怎么形成的。", "explanation": "这里应该用〈座〉。「辆」用于车辆，火山不能用「辆」计量，要说「那座火山」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10431, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只火山去年冬天喷发了一次。", "corrected_sentence": "那座火山去年冬天喷发了一次。", "error_description": "量词错误：「火山」指山体，量词应为「座」，「只」用于动物，不能用来数火山。错误形式：那只火山；正确形式：那座火山。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10431, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去看了一只火山，山顶上还有一个湖。", "corrected_sentence": "我们去看了一座火山，山顶上还有一个湖。", "error_description": "量词错误：「火山」应用量词「座」，「只」只用于动物。错误形式：一只火山；正确形式：一座火山。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
