INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10432, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海洋中彼此距离较近的许多岛屿的合称。", "primary_collocate": null, "pronunciation": "qún dǎo", "ipa": "tɕʰyn˧˥ tɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "马尔代夫是由很多小岛组成的群岛。", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个群岛一共有三十多个小岛。", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐船去了南海的一个群岛。", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，群岛的海水又蓝又清。", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个群岛离大陆很远，坐船要两天。", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "群岛上的居民靠打鱼生活。", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日本是一个由群岛组成的国家。", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机飞过海面，下面是一片绿色的群岛。", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在这个群岛上发现了新的鸟。", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多游客喜欢去热带群岛潜水。", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "群島", "label": "繁体"}], "register": "中性", "sense_fingerprint": "群岛：海洋中相互靠近的一组岛屿的合称（地理义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965d3399-3e60-46ea-aa3b-18edf6edc58a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10432, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群岛", "is_correct": true, "explanation": "正确：群岛指由许多小岛组成的岛群，与「由很多小岛组成的」一致。"}, {"text": "山脉", "is_correct": false, "explanation": "语义：山脉由连绵的山峰构成，不是由小岛组成的。"}, {"text": "高原", "is_correct": false, "explanation": "体貌：高原是连成一片的高地，外形与分散的小岛不同。"}, {"text": "湖泊", "is_correct": false, "explanation": "语义：湖泊是陆地上的水域，不是由小岛组成的。"}], "explanations": {"群岛": "正确：群岛指由许多小岛组成的岛群，与「由很多小岛组成的」一致。", "山脉": "语义：山脉由连绵的山峰构成，不是由小岛组成的。", "高原": "体貌：高原是连成一片的高地，外形与分散的小岛不同。", "湖泊": "语义：湖泊是陆地上的水域，不是由小岛组成的。"}, "sentence_index": 0, "correct_answer": "群岛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天，那棵群岛的海水又蓝又清。", "explanation": "这里应该用〈个〉。「棵」用于植物，群岛应说「个」。"}, {"text": "夏天，那辆群岛的海水又蓝又清。", "explanation": "这里应该用〈个〉。「辆」用于车辆，群岛不能用「辆」计量。"}, {"text": "夏天，那本群岛的海水又蓝又清。", "explanation": "这里应该用〈个〉。「本」用于书籍，群岛应说「个」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10432, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群岛", "is_correct": true, "explanation": "正确：日本由许多岛屿组成，「由群岛组成的国家」说的正是群岛。"}, {"text": "冰川", "is_correct": false, "explanation": "语义：冰川是冰体，不能构成一个国家的组成部分。"}, {"text": "沙漠", "is_correct": false, "explanation": "体貌：沙漠是连片的沙地，不是分散的岛屿，外形不符。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是种植花草的园地，不能构成国家。"}], "explanations": {"群岛": "正确：日本由许多岛屿组成，「由群岛组成的国家」说的正是群岛。", "冰川": "语义：冰川是冰体，不能构成一个国家的组成部分。", "沙漠": "体貌：沙漠是连片的沙地，不是分散的岛屿，外形不符。", "花园": "语义：花园是种植花草的园地，不能构成国家。"}, "sentence_index": 6, "correct_answer": "群岛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "很多游客喜欢去那只群岛潜水。", "explanation": "这里应该用〈个〉。「只」用于动物，群岛应说「个」。"}, {"text": "很多游客喜欢去那台群岛潜水。", "explanation": "这里应该用〈个〉。「台」用于机器，群岛不能用「台」计量。"}, {"text": "很多游客喜欢去那把群岛潜水。", "explanation": "这里应该用〈个〉。「把」用于有柄的器具，群岛应说「个」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只群岛由上百个小岛组成。", "corrected_sentence": "那个群岛由上百个小岛组成。", "error_description": "量词错误：「群岛」应用量词「个」，「只」用于动物，不能用来计量群岛。错误形式：那只群岛；正确形式：那个群岛。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10432, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们乘飞机飞过这台群岛。", "corrected_sentence": "我们乘飞机飞过这个群岛。", "error_description": "量词错误：「群岛」应用量词「个」，「台」用于机器，不能用来计量群岛。错误形式：这台群岛；正确形式：这个群岛。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
