INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10433, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10433, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "独有的；与众不同的。", "primary_collocate": null, "pronunciation": "dú tè", "ipa": "tu˧˥ tʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这个城市有独特的历史和文化。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的声音很独特，我一听就知道是她。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅的菜味道独特，客人很多。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用独特的方法解决了这个问题。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个民族都有自己独特的节日。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座房子的样子很独特，和别的房子都不一样。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿了一件设计独特的衣服。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花有独特的香味，很多人都喜欢。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画风格独特，很容易认出来。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的写法很独特，和别的书都不同。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "独特性", "label": "复合"}, {"form": "獨特", "label": "繁体"}], "register": "中性", "sense_fingerprint": "独特：独有的、与众不同的（形容词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965d3399-3e60-46ea-aa3b-18edf6edc58a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10433, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独特", "is_correct": true, "explanation": "独特：独有的、与众不同的，正好形容这座城市的历史和文化。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：“滚烫”说温度，历史和文化没有温度，不能这样形容。"}, {"text": "雪白", "is_correct": false, "explanation": "体貌：“雪白”形容颜色或外形，不能用来形容历史和文化。"}, {"text": "嘹亮", "is_correct": false, "explanation": "语义：“嘹亮”形容声音，历史和文化不能“嘹亮”。"}], "explanations": {"独特": "独特：独有的、与众不同的，正好形容这座城市的历史和文化。", "滚烫": "语义：“滚烫”说温度，历史和文化没有温度，不能这样形容。", "雪白": "体貌：“雪白”形容颜色或外形，不能用来形容历史和文化。", "嘹亮": "语义：“嘹亮”形容声音，历史和文化不能“嘹亮”。"}, "sentence_index": 0, "correct_answer": "独特"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "独特同学没交作业，老师很生气。", "explanation": "这里应该用〈个别〉。“个别”指少数几个，“独特”指与众不同，不能用来表示数量少。"}, {"text": "这次因为独特情况，比赛推迟了。", "explanation": "这里应该用〈特殊〉。“特殊情况”指不寻常、需要另行处理的情况；“独特”强调与别的不同，不说“独特情况”。"}, {"text": "这个孩子独特地自己洗衣服做饭，不用别人帮忙。", "explanation": "这里应该用〈独立〉。「独立」指不依赖别人；「独特」修饰方式时表示与众不同，不能表示「自己做」的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10433, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独特", "is_correct": true, "explanation": "独特：与众不同，正好修饰衣服的设计。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”多用于环境或衣物的状态，不能说“设计潮湿”。"}, {"text": "健谈", "is_correct": false, "explanation": "语义：“健谈”形容人喜欢说话，设计不能健谈。"}, {"text": "清醒", "is_correct": false, "explanation": "语义：“清醒”指头脑明白，设计不能清醒。"}], "explanations": {"独特": "独特：与众不同，正好修饰衣服的设计。", "潮湿": "搭配：“潮湿”多用于环境或衣物的状态，不能说“设计潮湿”。", "健谈": "语义：“健谈”形容人喜欢说话，设计不能健谈。", "清醒": "语义：“清醒”指头脑明白，设计不能清醒。"}, "sentence_index": 6, "correct_answer": "独特"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全班独特三个男生会游泳。", "explanation": "这里应该用〈只有〉。「只有」表示数量少；「独特」指与众不同，不能用来计数。"}, {"text": "他的考试成绩很独特，拿了全班第一名。", "explanation": "这里应该用〈优异〉。「优异」形容成绩好；「独特」只说与众不同，不表示成绩好坏。"}, {"text": "他十八岁就离开家独特生活了。", "explanation": "这里应该用〈独立〉。「独立生活」指不依赖别人；「独特」指与众不同，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10433, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种茶的口感很的独特。", "corrected_sentence": "这种茶的口感很独特。", "error_description": "错误：“很”和“独特”之间多了“的”。正确：“很独特”，程度副词直接修饰形容词，中间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10433, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他设计了一种独特包。", "corrected_sentence": "他设计了一种独特的包。", "error_description": "错误：“独特”修饰名词“包”时漏掉了“的”。正确：“独特的包”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
