INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10434, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一个特定小区域内的气候，比如城市公园或建筑周围，与周边大范围气候不同。", "primary_collocate": null, "pronunciation": "wēi qì hòu", "ipa": "wei˥ tɕʰi˥˩ xou˥˩", "syllable_count": 3, "sentences": [{"text": "这些原产地国家，如拉丁美洲的安第斯山麓地区、东非高原以及东南亚的火山群岛，凭借其独特的微气候与海拔条件，培育出具有地域风味特征的咖啡豆品种，其中阿拉比卡与罗布斯塔是最主要的两类。", "target_word": "微气候", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公园里的树多，微气候比街上凉爽。", "target_word": "微气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖边有一种特别的微气候，夏天不太热。", "target_word": "微气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高楼之间的风大，形成了独特的微气候。", "target_word": "微气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片山谷的微气候很适合种茶。", "target_word": "微气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温室里的微气候可以用机器来调节。", "target_word": "微气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树林能改善周围的微气候。", "target_word": "微气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民很了解自己果园的微气候。", "target_word": "微气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的微气候和郊外不一样。", "target_word": "微气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋顶花园有自己的微气候，夏天比楼下凉。", "target_word": "微气候", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "小区域内与周边不同的局部气候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965d3399-3e60-46ea-aa3b-18edf6edc58a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10434, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "微气候", "is_correct": true, "explanation": "微气候：指小区域内的气候，与海拔条件并列，符合句意。"}, {"text": "乐曲", "is_correct": false, "explanation": "语义：“乐曲”是音乐作品，不能作为“凭借”的自然条件。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：“食谱”是菜谱，与海拔条件不构成并列的自然因素。"}, {"text": "电梯", "is_correct": false, "explanation": "搭配：“凭借”后接的应是自然条件，“电梯”不能与海拔并列作凭借。"}], "explanations": {"微气候": "微气候：指小区域内的气候，与海拔条件并列，符合句意。", "乐曲": "语义：“乐曲”是音乐作品，不能作为“凭借”的自然条件。", "食谱": "语义：“食谱”是菜谱，与海拔条件不构成并列的自然因素。", "电梯": "搭配：“凭借”后接的应是自然条件，“电梯”不能与海拔并列作凭借。"}, "sentence_index": 0, "correct_answer": "微气候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家的微气候很温和，四季都很舒服。", "explanation": "这里应该用〈气候〉。“气候”指大范围的气候，“微气候”只指小区域，不能用于整个国家。"}, {"text": "今天的微气候下了一场大雨，我们只能待在家里。", "explanation": "这里应该用〈天气〉。「天气」指短时间的大气状况，「微气候」指长期稳定的小区域气候，不能说某一天下雨。"}, {"text": "这片树林里有一条微气候。", "explanation": "这里应该用〈种〉。“条”用于长形的东西，“微气候”应该用量词“种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微气候", "is_correct": true, "explanation": "微气候：指小区域内的气候，树林正能改善它，符合句意。"}, {"text": "视力", "is_correct": false, "explanation": "搭配：“视力”是人的感官能力，不能说“周围的视力”。"}, {"text": "词典", "is_correct": false, "explanation": "语义：“词典”是工具书，不能被树林改善。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：“乐器”是器物，树林不能改善周围的乐器。"}], "explanations": {"微气候": "微气候：指小区域内的气候，树林正能改善它，符合句意。", "视力": "搭配：“视力”是人的感官能力，不能说“周围的视力”。", "词典": "语义：“词典”是工具书，不能被树林改善。", "乐器": "语义：“乐器”是器物，树林不能改善周围的乐器。"}, "sentence_index": 6, "correct_answer": "微气候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个教室的微气候很吵闹。", "explanation": "这里应该用〈环境〉。“环境”可指周围的声音和氛围，“微气候”只指温度、湿度等气象条件。"}, {"text": "这间屋子的微气候很新鲜，我们开了窗。", "explanation": "这里应该用〈空气〉。“新鲜”形容空气；“微气候”指温度、湿度等气象条件，不能说新鲜。"}, {"text": "我家楼下有一位微气候。", "explanation": "这里应该用〈种〉。“位”用于人，不能用来计量“微气候”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片果园有一只特别的微气候。", "corrected_sentence": "这片果园有一种特别的微气候。", "error_description": "错误：“只”多用于动物，“微气候”应该用量词“种”。正确：“一种特别的微气候”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "树林让周围的微气候变得的凉爽。", "corrected_sentence": "树林让周围的微气候变得凉爽。", "error_description": "错误：“变得”和“凉爽”之间多了“的”。正确：“变得凉爽”，“变得”后面直接接形容词，中间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
