INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10435, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指从平均海平面到某地点的垂直高度。", "primary_collocate": null, "pronunciation": "hǎi bá", "ipa": "xai˨˩˦ pa˧˥", "syllable_count": 2, "sentences": [{"text": "这座山的海拔有三千米。", "target_word": "海拔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西藏的海拔很高，空气比较稀薄。", "target_word": "海拔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海拔越高，气温就越低。", "target_word": "海拔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们爬到了海拔四千米的地方。", "target_word": "海拔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的海拔只有五十米。", "target_word": "海拔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "登山前要先查一下那座山的海拔。", "target_word": "海拔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海拔高的地方，人容易觉得累。", "target_word": "海拔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条公路的最高海拔是五千米。", "target_word": "海拔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡树喜欢海拔高一点的山坡。", "target_word": "海拔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机场建在海拔很低的平原上。", "target_word": "海拔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "海拔高度", "label": "复合"}], "register": "中性", "sense_fingerprint": "某地点高出平均海平面的垂直高度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965d3399-3e60-46ea-aa3b-18edf6edc58a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10435, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海拔", "is_correct": true, "explanation": "海拔：指山高出海平面的垂直高度，正好说明山的高低，符合“这座山的……有三千米”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人或动物的重量，山没有体重。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：速度以“米每秒”计量，不能和“三千米”这样的高度数值搭配。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄衡量的是时间，不能用“三千米”这种长度来表示。"}], "explanations": {"海拔": "海拔：指山高出海平面的垂直高度，正好说明山的高低，符合“这座山的……有三千米”。", "体重": "语义：体重指人或动物的重量，山没有体重。", "速度": "搭配：速度以“米每秒”计量，不能和“三千米”这样的高度数值搭配。", "年龄": "语义：年龄衡量的是时间，不能用“三千米”这种长度来表示。"}, "sentence_index": 0, "correct_answer": "海拔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋大楼的海拔有一百层。", "explanation": "这里应该用〈层数〉。海拔是高出海平面的高度，大楼有几层要用层数。"}, {"text": "这张桌子的海拔有两米。", "explanation": "这里应该用〈高度〉。海拔专指地方高出海平面的高度，桌子有多高要用高度。"}, {"text": "我家到学校的海拔有两公里。", "explanation": "这里应该用〈距离〉。海拔指高度，两地之间的远近要用距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10435, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "海拔", "is_correct": true, "explanation": "海拔（hǎi bá）指地面高出平均海平面的垂直高度，是本题的正确答案。"}, {"text": "海豹", "is_correct": false, "explanation": "海豹（hǎi bào）是一种海洋哺乳动物。bào（第四声）与 bá（第二声）韵母和声调都不同。"}, {"text": "海坝", "is_correct": false, "explanation": "海坝（hǎi bà）指海边挡潮的堤坝。bà（第四声）与 bá（第二声）只有声调不同。"}, {"text": "海霸", "is_correct": false, "explanation": "海霸（hǎi bà）指横行海上的人。bà（第四声）与 bá（第二声）只有声调不同。"}], "explanations": {"海拔": "海拔（hǎi bá）指地面高出平均海平面的垂直高度，是本题的正确答案。", "海豹": "海豹（hǎi bào）是一种海洋哺乳动物。bào（第四声）与 bá（第二声）韵母和声调都不同。", "海坝": "海坝（hǎi bà）指海边挡潮的堤坝。bà（第四声）与 bá（第二声）只有声调不同。", "海霸": "海霸（hǎi bà）指横行海上的人。bà（第四声）与 bá（第二声）只有声调不同。"}, "sentence_index": null, "correct_answer": "海拔"}, "level_3": {"options": [{"text": "海拔", "is_correct": true, "explanation": "海拔：指地方高出海平面的高度，与“海拔高的地方”搭配，符合句意。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材只用来形容人的体型，地方没有身材。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：人口用“多”或“少”来形容，不能说“人口高”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指人或动物身体的温度，不能用来描述地方的高低。"}], "explanations": {"海拔": "海拔：指地方高出海平面的高度，与“海拔高的地方”搭配，符合句意。", "身材": "体貌：身材只用来形容人的体型，地方没有身材。", "人口": "搭配：人口用“多”或“少”来形容，不能说“人口高”。", "体温": "语义：体温指人或动物身体的温度，不能用来描述地方的高低。"}, "sentence_index": 6, "correct_answer": "海拔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这口井的海拔深二十米。", "explanation": "这里应该用〈深度〉。海拔只说高低，不说深浅；井有多深要用深度。"}, {"text": "我的海拔有五十公斤。", "explanation": "这里应该用〈体重〉。海拔只用于地方的高度，人的重量要用体重。"}, {"text": "这位老人的海拔是八十岁。", "explanation": "这里应该用〈年龄〉。海拔是地方的高度，人的岁数要用年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10435, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座山的海拔的很高，山顶常年有雪。", "corrected_sentence": "这座山的海拔很高，山顶常年有雪。", "error_description": "错误：“海拔”和“很高”之间多了“的”。正确：“海拔很高”，“海拔”作主语，“很高”作谓语，中间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10435, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想知道这座山的海拔有高多。", "corrected_sentence": "我想知道这座山的海拔有多高。", "error_description": "错误形式：“有高多”；正确形式：“有多高”。疑问结构中“多”修饰“高”，顺序固定为“多＋形容词”，不能倒过来说。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
