INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10436, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "经过培养、教育或训练，使生物或事物成长并产生出结果。", "primary_collocate": null, "pronunciation": "péi yù chū", "ipa": "pʰei˧˥ y˥˩ ʈʂʰu˥", "syllable_count": 3, "sentences": [{"text": "这些原产地国家，如拉丁美洲的安第斯山麓地区、东非高原以及东南亚的火山群岛，凭借其独特的微气候与海拔条件，培育出具有地域风味特征的咖啡豆品种，其中阿拉比卡与罗布斯塔是最主要的两类。", "target_word": "培育出", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "农民们培育出了一种很甜的苹果。", "target_word": "培育出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校培育出许多优秀的学生。", "target_word": "培育出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过三年，他们培育出了新的玫瑰。", "target_word": "培育出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用种子培育出了耐旱的小麦。", "target_word": "培育出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师能培育出爱读书的孩子。", "target_word": "培育出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司培育出很多年轻的工程师。", "target_word": "培育出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在花园里培育出一朵蓝色的花。", "target_word": "培育出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们在温室里培育出新品种的西红柿。", "target_word": "培育出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位园艺师培育出了很香的茶花。", "target_word": "培育出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "培育出了", "label": "体标"}], "register": "中性", "sense_fingerprint": "经培养或教育而产生出成果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965d3399-3e60-46ea-aa3b-18edf6edc58a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10436, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "培育出", "is_correct": true, "explanation": "培育出：经过培育产生出新品种，正好说明咖啡豆品种是怎样得来的。"}, {"text": "拍摄出", "is_correct": false, "explanation": "语义：拍摄产生的是影像，不能产生咖啡豆品种。"}, {"text": "哭出", "is_correct": false, "explanation": "配价：哭是不及物动词，不能带“品种”作宾语。"}, {"text": "唱出", "is_correct": false, "explanation": "语义：唱只能发出歌声，不能产生咖啡豆品种。"}], "explanations": {"培育出": "培育出：经过培育产生出新品种，正好说明咖啡豆品种是怎样得来的。", "拍摄出": "语义：拍摄产生的是影像，不能产生咖啡豆品种。", "哭出": "配价：哭是不及物动词，不能带“品种”作宾语。", "唱出": "语义：唱只能发出歌声，不能产生咖啡豆品种。"}, "sentence_index": 0, "correct_answer": "培育出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "经过三年，他们培育出了新的药品。", "explanation": "这里应该用〈研制〉。培育用于生物品种或人才，药品这类产品要用研制。"}, {"text": "作家培育出了一部新小说。", "explanation": "这里应该用〈创作〉。培育用于生物品种或人才，小说这类作品要用创作。"}, {"text": "这家工厂每天培育出一千台机器。", "explanation": "这里应该用〈生产〉。培育用于生物或新品种，工厂的机器产品要用生产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "培育出", "is_correct": true, "explanation": "培育出：经过培育产生出人才，符合“这家公司培育出很多年轻的工程师”的句意。"}, {"text": "测量出", "is_correct": false, "explanation": "语义：测量得到的是数值，不能产生工程师。"}, {"text": "散发出", "is_correct": false, "explanation": "搭配：散发多用于气味、热量，不能搭配“工程师”。"}, {"text": "喷出", "is_correct": false, "explanation": "语义：喷出的是液体或气体，不能用来指人。"}], "explanations": {"培育出": "培育出：经过培育产生出人才，符合“这家公司培育出很多年轻的工程师”的句意。", "测量出": "语义：测量得到的是数值，不能产生工程师。", "散发出": "搭配：散发多用于气味、热量，不能搭配“工程师”。", "喷出": "语义：喷出的是液体或气体，不能用来指人。"}, "sentence_index": 6, "correct_answer": "培育出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们花了三年培育出一座大桥。", "explanation": "这里应该用〈建造〉。培育用于生物和新品种，桥梁这类工程要用建造。"}, {"text": "画家培育出一幅美丽的风景画。", "explanation": "这里应该用〈绘制〉。培育不用于艺术作品，画作要用绘制或画。"}, {"text": "厨师培育出一锅美味的汤。", "explanation": "这里应该用〈烹饪〉。培育不指做饭，做汤要用烹饪或煮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农学家把培育出了一种抗病的水稻。", "corrected_sentence": "农学家培育出了一种抗病的水稻。", "error_description": "错误：多加了“把”，“把”后直接接动词“培育出”不成立，“把”字句须先有受事宾语。正确：去掉“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究员把培育出了一种高产的大豆。", "corrected_sentence": "研究员培育出了一种高产的大豆。", "error_description": "错误：多加了“把”，“把”后直接接动词“培育出”不成立，“把”字句须先有受事宾语。正确：去掉“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
