INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10438, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物所具有的独特滋味或气味，也常用来比喻事物的特色或风格。", "primary_collocate": null, "pronunciation": "fēng wèi", "ipa": "fɤŋ˥ weɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "一方面，大众零售市场依赖规模化生产的速溶咖啡与连锁咖啡店标准化产品；另一方面，精品咖啡运动的兴起推动了“从种子到杯子”的溯源理念，消费者愈发关注产地故事、处理工艺与风味谱系，进而反向影响原产地的种植实践与分级标准。", "target_word": "风味", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家餐厅的菜有浓浓的四川风味。", "target_word": "风味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道汤带着海边小城的风味。", "target_word": "风味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去吃了有北京风味的烤鸭。", "target_word": "风味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶有一股特别的花香风味。", "target_word": "风味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶做的饺子很有家乡风味。", "target_word": "风味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的建筑保留了古老的风味。", "target_word": "风味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画有很浓的民间风味。", "target_word": "风味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌带有很浓的爱尔兰风味。", "target_word": "风味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想尝一尝当地的风味，你有什么推荐吗？", "target_word": "风味", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种风味", "label": "量词"}, {"form": "風味", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物的独特滋味、气味或特色风格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058d721c-6fd8-4b0f-a130-3d7cc342e209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10438, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风味", "is_correct": true, "explanation": "正确：“风味谱系”指风味的分类与来源脉络，与前文的产地故事、处理工艺相合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“谱系”指品类或风格的脉络，不与“价格”搭配，“价格谱系”不成词。"}, {"text": "产量", "is_correct": false, "explanation": "语义：产量说的是数量，不构成可溯源的类别脉络，句中要的是类别。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积是物体占的空间大小，无法构成谱系。"}], "explanations": {"风味": "正确：“风味谱系”指风味的分类与来源脉络，与前文的产地故事、处理工艺相合。", "价格": "搭配：“谱系”指品类或风格的脉络，不与“价格”搭配，“价格谱系”不成词。", "产量": "语义：产量说的是数量，不构成可溯源的类别脉络，句中要的是类别。", "体积": "语义：体积是物体占的空间大小，无法构成谱系。"}, "sentence_index": 0, "correct_answer": "风味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的风味很难。", "explanation": "这里应该用〈难度〉。风味指滋味或特色，考试的难易要说“难度”，不能用“风味”。"}, {"text": "这块蛋糕的风味很松软。", "explanation": "这里应该用〈口感〉。风味指滋味与特色，“松软”形容吃进嘴里的质地，要用“口感”。"}, {"text": "这座房子的风味很宽敞。", "explanation": "这里应该用〈空间〉。风味指滋味或特色，说房子的大小要用“空间”，不能用“风味”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10438, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风味", "is_correct": true, "explanation": "正确：“保留了古老的”之后接的是可以有特色的事物，“风味”与句意相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“古老”修饰事物的历史面貌，不修饰年龄数字，“古老的年龄”不成立。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“古老的”不与“重量”搭配，“保留了古老的重量”不通。"}, {"text": "速度", "is_correct": false, "explanation": "语义：“速度”指快慢，建筑保留的是风貌，“古老的速度”说不通。"}], "explanations": {"风味": "正确：“保留了古老的”之后接的是可以有特色的事物，“风味”与句意相合。", "年龄": "语义：“古老”修饰事物的历史面貌，不修饰年龄数字，“古老的年龄”不成立。", "重量": "搭配：“古老的”不与“重量”搭配，“保留了古老的重量”不通。", "速度": "语义：“速度”指快慢，建筑保留的是风貌，“古老的速度”说不通。"}, "sentence_index": 6, "correct_answer": "风味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜的风味很烫。", "explanation": "这里应该用〈温度〉。风味指滋味或特色，菜的冷热要说“温度”，不能用“风味”。"}, {"text": "这碗汤的风味很贵。", "explanation": "这里应该用〈价格〉。风味指滋味或特色，菜的贵贱要说“价格”，不能用“风味”。"}, {"text": "这杯茶的风味很红。", "explanation": "这里应该用〈颜色〉。风味指滋味或特色，茶的颜色要说“颜色”，不能用“风味”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这碗面有一朵浓浓的家乡风味。", "corrected_sentence": "这碗面有一股浓浓的家乡风味。", "error_description": "错在量词：“风味”指气味或滋味，应用量词“股”，“朵”是花的量词，不能用于风味。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这道菜的风味变淡着。", "corrected_sentence": "这道菜的风味变淡了。", "error_description": "错在动态助词：“变淡”表示已经发生的变化，要用“了”。用“着”表示状态持续，与句意不符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
