INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10440, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指生物分类或物品的类别。", "primary_collocate": null, "pronunciation": "pǐn zhǒng", "ipa": "pʰin˨˩˦ ʈʂʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个超市的水果品种很多。", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民今年种了一个新品种的水稻。", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家花店有二十多个玫瑰品种。", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种狗是很有名的品种。", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家培育出了抗病的小麦品种。", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里的面包品种太多，我不知道买哪个。", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店新到了许多不同品种的笔记本。", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个品种的苹果又大又甜。", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他养了一只品种很特别的猫。", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的饼干品种每年都在增加。", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个品种", "label": "量词"}, {"form": "新品种", "label": "复合"}, {"form": "品種", "label": "繁体"}], "register": "中性", "sense_fingerprint": "生物或物品所分的类别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058d721c-6fd8-4b0f-a130-3d7cc342e209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "品种", "is_correct": true, "explanation": "正确：“品种”指同类水果的不同类别，可以说“很多”。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“很多”说的是可数的类别数量，不与“价格”搭配。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积是物体占的空间，不是可以计数的类别，“水果体积很多”说不通。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不是可以数的类别，“水果温度很多”说不通。"}], "explanations": {"品种": "正确：“品种”指同类水果的不同类别，可以说“很多”。", "价格": "搭配：“很多”说的是可数的类别数量，不与“价格”搭配。", "体积": "语义：体积是物体占的空间，不是可以计数的类别，“水果体积很多”说不通。", "温度": "语义：温度不是可以数的类别，“水果温度很多”说不通。"}, "sentence_index": 0, "correct_answer": "品种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家面包店的面包品种很烫。", "explanation": "这里应该用〈温度〉。品种指类别，面包的冷热要说“温度”，不能用“品种”。"}, {"text": "这台电脑的品种很强。", "explanation": "这里应该用〈性能〉。“品种”不指性能，“强”形容的是性能，要用“性能”。"}, {"text": "这件衣服的品种很鲜艳。", "explanation": "这里应该用〈颜色〉。“品种”不指颜色，“鲜艳”形容的是颜色，要用“颜色”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "品种", "is_correct": true, "explanation": "正确：“不同品种”指笔记本的不同类别，与“新到了许多”相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：笔记本没有年龄，“不同年龄的笔记本”说不通。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“口味”用于食物，不与“笔记本”搭配。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或动物的重量，笔记本没有体重。"}], "explanations": {"品种": "正确：“不同品种”指笔记本的不同类别，与“新到了许多”相合。", "年龄": "语义：笔记本没有年龄，“不同年龄的笔记本”说不通。", "口味": "搭配：“口味”用于食物，不与“笔记本”搭配。", "体重": "语义：“体重”指人或动物的重量，笔记本没有体重。"}, "sentence_index": 6, "correct_answer": "品种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饼干店的品种很重。", "explanation": "这里应该用〈重量〉。品种指类别，饼干的轻重要说“重量”，不能用“品种”。"}, {"text": "这家饼干店的品种很亮。", "explanation": "这里应该用〈光泽〉。品种指类别，饼干表面的光泽要说“光泽”，不能用“品种”。"}, {"text": "这家饼干店的品种很吵。", "explanation": "这里应该用〈声音〉。品种指类别，“吵”说的是声音，不能用“品种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个水果摊上的草莓有三只品种。", "corrected_sentence": "这个水果摊上的草莓有三个品种。", "error_description": "错在量词：“品种”要用通用量词“个”，“只”是动物的量词，不能用于品种。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个研究所刚培育出一个的新品种。", "corrected_sentence": "这个研究所刚培育出一个新品种。", "error_description": "错在助词：“的”不能放在数量词“一个”和“新品种”之间，应说“一个新品种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
