INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10442, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "卡片，如银行卡、生日卡。", "primary_collocate": null, "pronunciation": "kǎ", "ipa": "kʰa˨˩˦", "syllable_count": 1, "sentences": [{"text": "我用这张卡在银行取钱。", "target_word": "卡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天我过生日，朋友送了我一张卡。", "target_word": "卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西时，请把卡给收银员。", "target_word": "卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的卡丢了，要去银行补办。", "target_word": "卡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在卡上写了一句祝福的话。", "target_word": "卡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张卡里还有一百块钱，可以坐车。", "target_word": "卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把卡放进机器里，然后输入密码。", "target_word": "卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "取钱的时候，请先把你的卡插进机器。", "target_word": "卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前，我检查了手机、钥匙和卡。", "target_word": "卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "付钱时，他没有用现金，而是刷了卡。", "target_word": "卡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张卡", "label": "量词"}, {"form": "卡片", "label": "复合"}], "register": "中性", "sense_fingerprint": "银行卡、生日卡等各种用途的卡片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058d721c-6fd8-4b0f-a130-3d7cc342e209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10442, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "卡", "is_correct": true, "explanation": "卡（kǎ）：卡片，如银行卡、生日卡。"}, {"text": "考", "is_correct": false, "explanation": "kǎo（第三声）与 kǎ 的韵母不同（ao / a），意思是考试。"}, {"text": "砍", "is_correct": false, "explanation": "kǎn（第三声）与 kǎ 的韵母不同（an / a），意思是用刀斧砍。"}, {"text": "咖", "is_correct": false, "explanation": "kā（第一声）与 kǎ 仅声调不同，“咖”指咖啡。"}, {"text": "垮", "is_correct": false, "explanation": "kuǎ（第三声）与 kǎ 只差介音 u，“垮”指倒塌、垮掉。"}], "explanations": {"卡": "卡（kǎ）：卡片，如银行卡、生日卡。", "考": "kǎo（第三声）与 kǎ 的韵母不同（ao / a），意思是考试。", "砍": "kǎn（第三声）与 kǎ 的韵母不同（an / a），意思是用刀斧砍。", "咖": "kā（第一声）与 kǎ 仅声调不同，“咖”指咖啡。", "垮": "kuǎ（第三声）与 kǎ 只差介音 u，“垮”指倒塌、垮掉。"}, "sentence_index": null, "correct_answer": "卡"}, "level_3": {"options": [{"text": "卡", "is_correct": true, "explanation": "卡：银行卡，可以用来在银行取钱。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能用来在银行取钱。"}, {"text": "照片", "is_correct": false, "explanation": "语义：照片不能用来取钱，取钱需要银行卡之类的凭证。"}, {"text": "地图", "is_correct": false, "explanation": "搭配：“取钱”的凭借应是银行卡或存折，不说用地图取钱。"}], "explanations": {"卡": "卡：银行卡，可以用来在银行取钱。", "书": "语义：书不能用来在银行取钱。", "照片": "语义：照片不能用来取钱，取钱需要银行卡之类的凭证。", "地图": "搭配：“取钱”的凭借应是银行卡或存折，不说用地图取钱。"}, "sentence_index": 0, "correct_answer": "卡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他端起碗，把这张卡喝了下去。", "explanation": "这里应该用〈汤〉。卡片不能喝，“喝”搭配的是汤、水等液体。"}, {"text": "她在雨里撑开了一张卡。", "explanation": "这里应该用〈伞〉。卡片不能撑开，“撑开”搭配的是伞。"}, {"text": "她用剪刀修剪了一张卡。", "explanation": "这里应该用〈树枝〉。卡片不能修剪，“修剪”搭配的是树枝、头发等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10442, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "卡", "is_correct": true, "explanation": "卡（kǎ）：卡片，如银行卡、生日卡。"}, {"text": "烤", "is_correct": false, "explanation": "kǎo（第三声）与 kǎ 的韵母不同（ao / a），意思是用火加热食物。"}, {"text": "喀", "is_correct": false, "explanation": "kā（第一声）与 kǎ 仅声调不同，“喀”多用于象声词或地名，如“喀什”。"}, {"text": "垮", "is_correct": false, "explanation": "kuǎ（第三声）与 kǎ 只差介音 u，“垮”指倒塌、垮掉。"}, {"text": "码", "is_correct": false, "explanation": "mǎ（第三声）与 kǎ 仅声母不同（m / k），“码”如“号码”。"}], "explanations": {"卡": "卡（kǎ）：卡片，如银行卡、生日卡。", "烤": "kǎo（第三声）与 kǎ 的韵母不同（ao / a），意思是用火加热食物。", "喀": "kā（第一声）与 kǎ 仅声调不同，“喀”多用于象声词或地名，如“喀什”。", "垮": "kuǎ（第三声）与 kǎ 只差介音 u，“垮”指倒塌、垮掉。", "码": "mǎ（第三声）与 kǎ 仅声母不同（m / k），“码”如“号码”。"}, "sentence_index": null, "correct_answer": "卡"}, "level_3": {"options": [{"text": "卡", "is_correct": true, "explanation": "卡：可以插入机器、输入密码的卡片，如银行卡。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能放进取款机，也不能用来输入密码。"}, {"text": "盒子", "is_correct": false, "explanation": "语义：盒子不能用来输入密码，句中要的是能输入密码的卡片。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“输入密码”的对象是银行卡、门禁卡等，钥匙不能输入密码。"}], "explanations": {"卡": "卡：可以插入机器、输入密码的卡片，如银行卡。", "书": "语义：书不能放进取款机，也不能用来输入密码。", "盒子": "语义：盒子不能用来输入密码，句中要的是能输入密码的卡片。", "钥匙": "搭配：“输入密码”的对象是银行卡、门禁卡等，钥匙不能输入密码。"}, "sentence_index": 6, "correct_answer": "卡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张卡很甜，孩子们都爱吃。", "explanation": "这里应该用〈蛋糕〉。卡片没有味道，“甜”形容食物、饮料。"}, {"text": "他在这张卡里住了三年。", "explanation": "这里应该用〈房子〉。卡片不是住所，“住”要搭配房屋、房间等。"}, {"text": "他用这张卡盖了一座房子。", "explanation": "这里应该用〈砖〉。卡片不能盖房子，“盖”搭配砖、瓦、木材等建材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天去银行办了一只新卡。", "corrected_sentence": "我昨天去银行办了一张新卡。", "error_description": "量词错误：“卡”是扁平的卡片，应说“一张卡”，不能说“一只卡”（“只”用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把一本卡放进了机器。", "corrected_sentence": "她把一张卡放进了机器。", "error_description": "量词错误：“卡”应用量词“张”，不能说“一本卡”（“本”用于书籍等）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
