INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10445, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手摘取植物的花、叶、果实等。", "primary_collocate": null, "pronunciation": "cǎi zhāi", "ipa": "tsʰaɪ˨˩˦ ʈʂaɪ˥", "syllable_count": 2, "sentences": [{"text": "采摘后的咖啡果实需经历水洗、日晒或蜜处理等加工方式，随后经脱壳、分拣、烘焙前处理，最终以“生豆”形态进入出口程序。", "target_word": "采摘", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "春天，农民在山上采摘茶叶。", "target_word": "采摘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们正在果园里采摘苹果。", "target_word": "采摘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些草莓是我们早上刚采摘的。", "target_word": "采摘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游客可以进园采摘新鲜的葡萄。", "target_word": "采摘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "采摘花朵时，要小心别弄伤树枝。", "target_word": "采摘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们全家去农场采摘橙子。", "target_word": "采摘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她采摘了一篮蓝莓，准备做果酱。", "target_word": "采摘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要采摘公园里的花。", "target_word": "采摘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "茶农天不亮就上山采摘，因为嫩叶最好。", "target_word": "采摘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "采摘了", "label": "体标"}, {"form": "采摘过", "label": "体标"}, {"form": "採摘", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用手摘取花、叶、果实等植物部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058d721c-6fd8-4b0f-a130-3d7cc342e209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10445, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "采摘", "is_correct": true, "explanation": "采摘：用手摘取植物的花、叶、果实等，这里指采收咖啡果实。"}, {"text": "出售", "is_correct": false, "explanation": "语义：句子讲的是加工流程，出售不是加工前的动作，与后文“需经历水洗、日晒……”的顺序不合。"}, {"text": "品尝", "is_correct": false, "explanation": "语义：果实还没有加工，不能品尝，句中要的是采收的动作。"}, {"text": "饮用", "is_correct": false, "explanation": "搭配：“饮用”的对象是饮品，咖啡果实不能饮用。"}], "explanations": {"采摘": "采摘：用手摘取植物的花、叶、果实等，这里指采收咖啡果实。", "出售": "语义：句子讲的是加工流程，出售不是加工前的动作，与后文“需经历水洗、日晒……”的顺序不合。", "品尝": "语义：果实还没有加工，不能品尝，句中要的是采收的动作。", "饮用": "搭配：“饮用”的对象是饮品，咖啡果实不能饮用。"}, "sentence_index": 0, "correct_answer": "采摘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "科学家在山里采摘了几块岩石。", "explanation": "这里应该用〈采集〉。采摘指用手摘取花、果、叶等植物部分，岩石不属此类，要说“采集”。"}, {"text": "他在银行里采摘了一笔钱。", "explanation": "这里应该用〈取〉。采摘指用手摘取植物的花、果、叶等，取钱要用“取”。"}, {"text": "农民在田里采摘稻子。", "explanation": "这里应该用〈收割〉。采摘用于花、果、叶，稻谷等粮食作物要用收割。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10445, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "采摘", "is_correct": true, "explanation": "采摘：用手从植物上摘取果实，这里指去农场摘橙子。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能说参观橙子。"}, {"text": "喂养", "is_correct": false, "explanation": "语义：橙子是植物，不能被喂养。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：全家去农场的目的不会是丢弃橙子。"}], "explanations": {"采摘": "采摘：用手从植物上摘取果实，这里指去农场摘橙子。", "参观": "搭配：“参观”的对象是场所或展览，不能说参观橙子。", "喂养": "语义：橙子是植物，不能被喂养。", "丢弃": "语义：全家去农场的目的不会是丢弃橙子。"}, "sentence_index": 6, "correct_answer": "采摘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在市场采摘水果。", "explanation": "这里应该用〈挑选〉。采摘指从植物上取下果实，在市场买水果不是采摘。"}, {"text": "农民在地里采摘萝卜。", "explanation": "这里应该用〈拔〉。萝卜长在地下，要拔出来，采摘用于花、果、叶。"}, {"text": "理发师在店里采摘头发。", "explanation": "这里应该用〈剪〉。采摘只用于植物的花、果、叶等，不能用于头发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10445, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "果农们正在树上采摘过桃子。", "corrected_sentence": "果农们正在树上采摘桃子。", "error_description": "体貌错误：“正在”表示动作正在进行，不能和表示经历的“过”一起用。应去掉“过”，说“正在采摘桃子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10445, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她采摘得快很，一会儿就装满了篮子。", "corrected_sentence": "她采摘得很快，一会儿就装满了篮子。", "error_description": "补语错误：“采摘得”后的补语应说“很快”，不能说“快很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
