INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10447, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10447, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "亲身见过、做过或遭受过的事情。", "primary_collocate": null, "pronunciation": "jīng lì", "ipa": "tɕiŋ˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "他很少向别人讲起自己年轻时的经历。", "target_word": "经历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有丰富的工作经历。", "target_word": "经历", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那次旅行是我最难忘的经历。", "target_word": "经历", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "童年的经历影响了他的一生。", "target_word": "经历", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你说说自己在国外生活的经历。", "target_word": "经历", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这段痛苦的经历让她变得更坚强了。", "target_word": "经历", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面试时，他问我有没有海外学习的经历。", "target_word": "经历", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些经历让他懂得了感谢家人。", "target_word": "经历", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把自己的经历写成了一本书。", "target_word": "经历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多一些不同的经历，对年轻人很有好处。", "target_word": "经历", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}, {"form": "次", "label": "量词"}, {"form": "工作经历", "label": "复合"}, {"form": "經歷", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个人亲身见过、做过或遭遇过的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9032895-3c87-4536-a6ce-a44d1ddecd4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10447, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经历", "is_correct": true, "explanation": "正确。「年轻时的经历」指亲身经过的事情，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「年轻时的颜色」不成立，颜色不是亲身经过的事。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」指商品的价值，不能指自己年轻时的事。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：「闹钟」是计时用的物品，不能指年轻时的事。"}], "explanations": {"经历": "正确。「年轻时的经历」指亲身经过的事情，与句意相符。", "颜色": "搭配：「年轻时的颜色」不成立，颜色不是亲身经过的事。", "价格": "语义：「价格」指商品的价值，不能指自己年轻时的事。", "闹钟": "语义：「闹钟」是计时用的物品，不能指年轻时的事。"}, "sentence_index": 0, "correct_answer": "经历"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我从这次失败中学到了很多经历。", "explanation": "这里应该用〈经验〉。经验指从实践中积累的知识和技能，学到的是经验；经历指亲身遭遇的事情，不能说学到经历。"}, {"text": "我们应该从失败中吸取经历，避免重复同样的错误。", "explanation": "这里应该用〈经验〉。吸取的是从实践中得来的经验和教训；经历指亲身遭遇的事，不能用“吸取”来搭配。"}, {"text": "他减了十公斤经历。", "explanation": "这里应该用〈体重〉。减的是体重，指身体的重量；经历指亲身做过或遇到的事，不能用“减”来搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10447, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经历", "is_correct": true, "explanation": "正确。“海外学习的经历”指亲身参与过的学习事件，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的外貌特征，不能说“海外学习的身高”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能与“学习”搭配，句中说不通。"}, {"text": "电话", "is_correct": false, "explanation": "语义：“电话”指通讯工具或号码，不是可以问“有没有”的学习经历。"}], "explanations": {"经历": "正确。“海外学习的经历”指亲身参与过的学习事件，符合句意。", "身高": "体貌：“身高”是人的外貌特征，不能说“海外学习的身高”。", "颜色": "搭配：“颜色”不能与“学习”搭配，句中说不通。", "电话": "语义：“电话”指通讯工具或号码，不是可以问“有没有”的学习经历。"}, "sentence_index": 6, "correct_answer": "经历"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇论文提出了新的经历。", "explanation": "这里应该用〈理论〉。提出的是理论，指系统的观点和原理；经历指亲身做过或遇到的事，不能说“提出经历”。"}, {"text": "这次旅行让我经历很深。", "explanation": "这里应该用〈感受〉。感受指内心的体会，可以说“深”；经历指亲身遭遇的事，不能说“经历很深”。"}, {"text": "这起事故的经历已经查清楚了。", "explanation": "这里应该用〈经过〉。经过指事情发生、发展的全过程，查清的是事件的经过；经历指个人亲身遭遇，不用于说事件的始末。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10447, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只经历让我学会了耐心。", "corrected_sentence": "这段经历让我学会了耐心。", "error_description": "量词错误：“经历”应该用量词“段”，不能用“只”（“只”用于动物或成对物品中的一个）。正确形式是“这段经历”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10447, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些经历们让我学会了珍惜。", "corrected_sentence": "这些经历让我学会了珍惜。", "error_description": "后缀错误：“们”只用于指人的名词，不能加在“经历”后面。正确形式是“这些经历”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
