INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10448, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "太阳光照射，使物体受到阳光的照射。", "primary_collocate": null, "pronunciation": "rì shài", "ipa": "ʐ̩˥˩ ʂaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这些辣椒要经过几天日晒才能保存。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间日晒会让皮肤变黑。", "target_word": "日晒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天日晒很强，出门要涂防晒霜。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布料不怕日晒，也不怕雨淋。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日晒太久，我的脸红了。", "target_word": "日晒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过三天日晒，葡萄变成了葡萄干。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的日晒很厉害，别忘了戴帽子。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木头家具放在阳台上，日晒会让它变旧。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服经过日晒后，有一股阳光的味道。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了避免日晒，她总是打着伞。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日晒雨淋", "label": "复合"}, {"form": "日曬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "阳光照射到物体上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058d721c-6fd8-4b0f-a130-3d7cc342e209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10448, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日晒", "is_correct": true, "explanation": "正确：辣椒要放在太阳下照射几天，晒干后才能保存。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能让辣椒变干，“经过几天声音”说不通。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震与保存辣椒无关，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“经过几天价格”不成立，价格不能“经过”。"}], "explanations": {"日晒": "正确：辣椒要放在太阳下照射几天，晒干后才能保存。", "声音": "语义：声音不能让辣椒变干，“经过几天声音”说不通。", "地震": "语义：地震与保存辣椒无关，句意不通。", "价格": "搭配：“经过几天价格”不成立，价格不能“经过”。"}, "sentence_index": 0, "correct_answer": "日晒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些湿衣服放进烘干机里，半个小时就日晒干了。", "explanation": "这里应该用〈烘干〉。烘干靠机器加热，日晒靠太阳照射，烘干机里没有阳光，不能说“日晒”。"}, {"text": "她每天去海边做日晒，让皮肤变得很健康。", "explanation": "这里应该用〈日光浴〉。“做日光浴”是固定说法；“日晒”是被太阳照射的过程，不能说“做日晒”。"}, {"text": "把鱼放进冰箱里，靠日晒保鲜。", "explanation": "这里应该用〈冷藏〉。冷藏靠低温保鲜，日晒靠太阳照射，冰箱里没有阳光，不能说“靠日晒保鲜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10448, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日晒", "is_correct": true, "explanation": "正确：日晒指太阳照射，夏天海边阳光强，所以要提醒戴帽子。"}, {"text": "海啸", "is_correct": false, "explanation": "语义：海啸是海底地震引起的巨浪，与“别忘了戴帽子”的防晒提醒无关。"}, {"text": "盐分", "is_correct": false, "explanation": "搭配：“盐分”的程度通常说“高”或“多”，不说“很厉害”。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是突发的地壳震动，与“别忘了戴帽子”的提醒对不上，句意不通。"}], "explanations": {"日晒": "正确：日晒指太阳照射，夏天海边阳光强，所以要提醒戴帽子。", "海啸": "语义：海啸是海底地震引起的巨浪，与“别忘了戴帽子”的防晒提醒无关。", "盐分": "搭配：“盐分”的程度通常说“高”或“多”，不说“很厉害”。", "地震": "语义：地震是突发的地壳震动，与“别忘了戴帽子”的提醒对不上，句意不通。"}, "sentence_index": 6, "correct_answer": "日晒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药膏专门用来治疗日晒。", "explanation": "这里应该用〈晒伤〉。日晒是阳光照射的过程，本身不是伤害，不能被“治疗”。"}, {"text": "夏天晚上在院子里日晒，很凉快。", "explanation": "这里应该用〈乘凉〉。乘凉是在树荫或屋里等凉快处休息，夏天晚上也可以乘凉；日晒必须在阳光下进行，晚上没有阳光，所以不能说“晚上日晒”。"}, {"text": "把湿衣服放在阴凉处，靠日晒让它变干。", "explanation": "这里应该用〈晾干〉。晾干是把湿物放在通风的阴凉处自然变干；日晒要靠阳光直接照射，阴凉处没有阳光，不能说“靠日晒让它变干”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种塑料椅子怕不日晒，可以一直放在院子里。", "corrected_sentence": "这种塑料椅子不怕日晒，可以一直放在院子里。", "error_description": "语序错误：否定词“不”要放在“怕”的前面，应说“不怕日晒”，不能说“怕不日晒”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "为了避免日晒了，他总是戴着帽子。", "corrected_sentence": "为了避免日晒，他总是戴着帽子。", "error_description": "体标错误：“避免日晒”是目的状语，动词后不能加“了”，应说“为了避免日晒”，不能说“为了避免日晒了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
