INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10449, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指蜜蜂采集花蜜后经过酿造而成的甜物质，也用来泛称像蜜那样甜美的东西。", "primary_collocate": null, "pronunciation": "mì", "ipa": "mi˥˩", "syllable_count": 1, "sentences": [{"text": "他把刚从蜂箱里取出的蜜装进了玻璃罐。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他往热茶里加了一点蜜。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这罐蜜是朋友从山里带来的。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在面包上抹了一层蜜。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们爱吃涂着蜜的面包。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "苦药里加一勺蜜就好喝了。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "养蜂人春天到山上采蜜。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑得很甜，像吃了蜜一样。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新婚的日子甜得像蜜。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种蜜带着花香，味道很好。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一罐蜜", "label": "量词"}, {"form": "一勺蜜", "label": "量词"}, {"form": "蜂蜜", "label": "复合"}, {"form": "蜜蜂", "label": "复合"}], "register": "中性", "sense_fingerprint": "蜜蜂酿造的甜物质；泛指甜美的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1845352-48be-48eb-9b3d-f37709a0cac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10449, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蜜", "is_correct": true, "explanation": "正确。蜜 mì 指蜜蜂酿造的甜物质。"}, {"text": "米", "is_correct": false, "explanation": "mǐ（第三声）与 mì（第四声）声调不同，意思是大米。"}, {"text": "迷", "is_correct": false, "explanation": "mí（第二声）与 mì（第四声）声调不同，意思是迷恋或迷路。"}, {"text": "闭", "is_correct": false, "explanation": "bì 与 mì 声母不同（b 与 m），意思是关闭。"}, {"text": "逆", "is_correct": false, "explanation": "nì 与 mì 声母不同（n 与 m），意思是相反、逆向。"}], "explanations": {"蜜": "正确。蜜 mì 指蜜蜂酿造的甜物质。", "米": "mǐ（第三声）与 mì（第四声）声调不同，意思是大米。", "迷": "mí（第二声）与 mì（第四声）声调不同，意思是迷恋或迷路。", "闭": "bì 与 mì 声母不同（b 与 m），意思是关闭。", "逆": "nì 与 mì 声母不同（n 与 m），意思是相反、逆向。"}, "sentence_index": null, "correct_answer": "蜜"}, "level_3": {"options": [{"text": "蜜", "is_correct": true, "explanation": "正确。蜜是蜂群采集花蜜后酿成的甜物质，从蜂箱里取出的正是它。"}, {"text": "酒", "is_correct": false, "explanation": "语义：酒不会从蜂箱里取出，与养蜂的情境不符。"}, {"text": "盐", "is_correct": false, "explanation": "语义：盐是调味品，不会从蜂箱里取出，与养蜂的情境不符。"}, {"text": "醋", "is_correct": false, "explanation": "语义：醋是发酵调味品，与蜂箱和蜂蜜无关。"}], "explanations": {"蜜": "正确。蜜是蜂群采集花蜜后酿成的甜物质，从蜂箱里取出的正是它。", "酒": "语义：酒不会从蜂箱里取出，与养蜂的情境不符。", "盐": "语义：盐是调味品，不会从蜂箱里取出，与养蜂的情境不符。", "醋": "语义：醋是发酵调味品，与蜂箱和蜂蜜无关。"}, "sentence_index": 0, "correct_answer": "蜜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蜜在花丛里飞来飞去，好看极了。", "explanation": "这里应该用〈蜜蜂〉。会飞的是蜜蜂，蜜是甜的物质，不会飞。"}, {"text": "他买了一只蜜回家。", "explanation": "这里量词用错。“只”用于动物，如蜜蜂；蜜是物质，应说“一罐蜜”或“一勺蜜”。"}, {"text": "屋子里的蜜点着了，火光很亮。", "explanation": "这里应该用〈蜡烛〉。蜡烛点燃后发光，蜜不能用来点燃照明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10449, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "蜜", "is_correct": true, "explanation": "正确。蜜 mì 指蜜蜂酿造的甜物质。"}, {"text": "利", "is_correct": false, "explanation": "lì 与 mì 声母不同（l 与 m），意思是利益、锋利。"}, {"text": "地", "is_correct": false, "explanation": "dì 与 mì 声母不同（d 与 m），意思是土地。"}, {"text": "戏", "is_correct": false, "explanation": "xì 与 mì 声母不同（x 与 m），意思是戏剧。"}, {"text": "必", "is_correct": false, "explanation": "bì 与 mì 声母不同（b 与 m），意思是必定。"}], "explanations": {"蜜": "正确。蜜 mì 指蜜蜂酿造的甜物质。", "利": "lì 与 mì 声母不同（l 与 m），意思是利益、锋利。", "地": "dì 与 mì 声母不同（d 与 m），意思是土地。", "戏": "xì 与 mì 声母不同（x 与 m），意思是戏剧。", "必": "bì 与 mì 声母不同（b 与 m），意思是必定。"}, "sentence_index": null, "correct_answer": "蜜"}, "level_3": {"options": [{"text": "蜜", "is_correct": true, "explanation": "正确。“采蜜”指采集花蜜，与句中的“养蜂人”相符。"}, {"text": "布", "is_correct": false, "explanation": "搭配：“采”不能与“布”搭配，没有“采布”的说法。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“采”后一般不接“水”，要说“取水”。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“采”不能与“饭”搭配，没有“采饭”的说法。"}], "explanations": {"蜜": "正确。“采蜜”指采集花蜜，与句中的“养蜂人”相符。", "布": "搭配：“采”不能与“布”搭配，没有“采布”的说法。", "水": "搭配：“采”后一般不接“水”，要说“取水”。", "饭": "搭配：“采”不能与“饭”搭配，没有“采饭”的说法。"}, "sentence_index": 6, "correct_answer": "蜜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片树林很蜜，阳光几乎照不进来。", "explanation": "这里应该用〈密〉。“密”指稠密，树林很密；“蜜”是蜂蜜，不表示稠密。"}, {"text": "这件事是我们俩的蜜，谁也不能说出去。", "explanation": "这里应该用〈秘密〉。“秘密”指不让人知道的事；“蜜”是蜂蜜，不能表示秘密。"}, {"text": "奶奶用蜜给孩子煮了一锅咸粥。", "explanation": "这里应该用〈盐〉。咸粥要用盐调味；蜜是甜的，不能用来调出咸味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10449, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一颗蜜，放在厨房里。", "corrected_sentence": "我买了一罐蜜，放在厨房里。", "error_description": "量词错误：“蜜”是半流质物质，应说“一罐蜜”，不能用“颗”，“颗”只用于颗粒状的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10449, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了两罐蜜的。", "corrected_sentence": "我买了两罐蜜。", "error_description": "助词错误：“两罐蜜”是数量名结构，“蜜”后不能加“的”，句末多出“的”不通，应说“我买了两罐蜜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
