INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10451, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10451, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示时间或顺序上紧接在某个事件或动作之后。", "primary_collocate": null, "pronunciation": "suí hòu", "ipa": "suei˧˥ xou˥˩", "syllable_count": 2, "sentences": [{"text": "他先打了电话，随后就出门了。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先讲了课文，随后让我们读。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人刚坐下，随后又来了两位。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先喝汤，随后再吃主菜。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她走进教室，随后老师也来了。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先去买票，你随后跟上来。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说了声再见，随后关上了门。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了一会儿，随后又下起来了。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理先介绍了计划，随后回答了大家的问题。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子先吃完饭，随后去写作业了。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隨後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "时间或顺序上紧接在前一件事之后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1845352-48be-48eb-9b3d-f37709a0cac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10451, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "随后", "is_correct": true, "explanation": "正确。“随后”表示紧接在前一动作之后，与“先打了电话”形成先后顺序。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示从未如此，与“先打了电话”的已发生事件矛盾。"}, {"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示同时发生，与“先”所表示的先后顺序矛盾。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续，不能与“就出门了”这种一次性动作搭配。"}], "explanations": {"随后": "正确。“随后”表示紧接在前一动作之后，与“先打了电话”形成先后顺序。", "从来": "语义：“从来”表示从未如此，与“先打了电话”的已发生事件矛盾。", "同时": "语义：“同时”表示同时发生，与“先”所表示的先后顺序矛盾。", "一直": "搭配：“一直”表示持续，不能与“就出门了”这种一次性动作搭配。"}, "sentence_index": 0, "correct_answer": "随后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我先下班，随后他早就到家了。", "explanation": "这里应该用〈原来〉。“随后”表示紧接在后，与“早就”所示的很早以前相矛盾；“原来”表示发现先前已发生的事，应说“我先下班，原来他早就到家了”。"}, {"text": "他随后才听说这件事，比大家都早。", "explanation": "这里应该用〈早就〉。“随后”指之后发生，与“比大家都早”矛盾；表示更早知道应说“他早就听说这件事”。"}, {"text": "他随后在前年结了婚。", "explanation": "这里应该去掉〈随后〉。“随后”指紧接之后，不能和“前年”这种过去的时间连用，应说“他前年结了婚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10451, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "随后", "is_correct": true, "explanation": "正确。“随后”表示紧接在“说了声再见”之后关门，与句中的先后顺序相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与紧接着的一次性动作不符。"}, {"text": "从没", "is_correct": false, "explanation": "搭配：“从没”通常与否定或“过”搭配，不与“关上了门”这样已发生的完成动作搭配。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”表示过去的经历，与“说了声再见”后立即发生的动作不符。"}], "explanations": {"随后": "正确。“随后”表示紧接在“说了声再见”之后关门，与句中的先后顺序相符。", "偶尔": "语义：“偶尔”表示不常发生，与紧接着的一次性动作不符。", "从没": "搭配：“从没”通常与否定或“过”搭配，不与“关上了门”这样已发生的完成动作搭配。", "曾经": "语义：“曾经”表示过去的经历，与“说了声再见”后立即发生的动作不符。"}, "sentence_index": 6, "correct_answer": "随后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把护照随后带着，怕丢了。", "explanation": "这里应该用〈随身〉。“随身”指带在身上；“随后”只表示时间先后，不能表示随身携带。"}, {"text": "他把急救药随后放在身边，以备不时之需。", "explanation": "这里应该用〈随时〉。“随时”指任何时候都可以，“随后”只表示之后，不能表示随时准备着。"}, {"text": "这本书随后是我的，后来我送给了他。", "explanation": "这里应该用〈以前〉。“随后”表示紧接在某事之后，不能指更早的过去，应说“这本书以前是我的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10451, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚到家，很随后又出去了。", "corrected_sentence": "他刚到家，随后又出去了。", "error_description": "错误：副词“随后”不能受程度副词“很”修饰，应去掉“很”，说“他刚到家，随后又出去了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10451, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他先关了灯，随后的睡着了。", "corrected_sentence": "他先关了灯，随后睡着了。", "error_description": "助词错误：“随后”是副词，作状语后不能加“的”，应说“随后睡着了”，不能说“随后的睡着了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
