INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10452, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "指通过、经历某个过程或空间。", "primary_collocate": null, "pronunciation": "jīng", "ipa": "tɕiŋ˥", "syllable_count": 1, "sentences": [{"text": "他经朋友介绍认识了王老师。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经医生检查，孩子没有大问题。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经大家讨论，办法定下来了。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经老师修改，这篇文章好多了。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信经几个人的手才送到我这里。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经工人修理，机器又能用了。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事经记者报道，很多人都知道了。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经公司研究，他得到了新工作。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方案经领导同意，才可以开始做。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文章经他一改，意思更清楚了。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "經", "label": "繁体"}], "register": "书面", "sense_fingerprint": "介词，经过某个过程、人手或途径", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1845352-48be-48eb-9b3d-f37709a0cac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10452, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "经", "is_correct": true, "explanation": "正确。经 jīng 为本词，介词，表示经过某个过程或途径。"}, {"text": "金", "is_correct": false, "explanation": "韵母不同（-in 与 -ing），jīn 意思是金子，与 jīng 不同。"}, {"text": "井", "is_correct": false, "explanation": "声调不同（第三声与第一声），jǐng 意思是水井，与 jīng 不同。"}, {"text": "静", "is_correct": false, "explanation": "声调不同（第四声与第一声），jìng 意思是安静，与 jīng 不同。"}, {"text": "警", "is_correct": false, "explanation": "声调不同（第三声与第一声），jǐng 意思是警察，与 jīng 不同。"}], "explanations": {"经": "正确。经 jīng 为本词，介词，表示经过某个过程或途径。", "金": "韵母不同（-in 与 -ing），jīn 意思是金子，与 jīng 不同。", "井": "声调不同（第三声与第一声），jǐng 意思是水井，与 jīng 不同。", "静": "声调不同（第四声与第一声），jìng 意思是安静，与 jīng 不同。", "警": "声调不同（第三声与第一声），jǐng 意思是警察，与 jīng 不同。"}, "sentence_index": null, "correct_answer": "经"}, "level_3": {"options": [{"text": "经", "is_correct": true, "explanation": "正确。经：介词，表示经由朋友介绍这一途径，与句意相符。"}, {"text": "用", "is_correct": false, "explanation": "搭配：“用”后接工具或方法，不能说“用朋友介绍”。"}, {"text": "按", "is_correct": false, "explanation": "语义：“按”表示依据某种标准或规定，与“朋友介绍认识”这一途径不相容。"}, {"text": "对", "is_correct": false, "explanation": "配价：“对”引出交涉或对待的对象，“对……介绍认识”的结构不成立。"}], "explanations": {"经": "正确。经：介词，表示经由朋友介绍这一途径，与句意相符。", "用": "搭配：“用”后接工具或方法，不能说“用朋友介绍”。", "按": "语义：“按”表示依据某种标准或规定，与“朋友介绍认识”这一途径不相容。", "对": "配价：“对”引出交涉或对待的对象，“对……介绍认识”的结构不成立。"}, "sentence_index": 0, "correct_answer": "经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服经很贵。", "explanation": "这里应该用〈很〉。“经”是介词，不能作程度副词修饰形容词，应说“这件衣服很贵”。"}, {"text": "他的经很丰富。", "explanation": "这里应该用〈经验〉。“经验”指从实践中积累的知识，“经”不单独表示此义，应说“经验丰富”。"}, {"text": "我们经到过北京。", "explanation": "这里应该用〈曾经〉。“经”表示经由某个途径，不能直接修饰动词“到过”，应说“我们曾经到过北京”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10452, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "经", "is_correct": true, "explanation": "正确。经 jīng 为本词，介词，表示经过某个过程或途径。"}, {"text": "今", "is_correct": false, "explanation": "韵母不同（-in 与 -ing），jīn 意思是今天，与 jīng 不同。"}, {"text": "景", "is_correct": false, "explanation": "声调不同（第三声与第一声），jǐng 意思是风景，与 jīng 不同。"}, {"text": "镜", "is_correct": false, "explanation": "声调不同（第四声与第一声），jìng 意思是镜子，与 jīng 不同。"}, {"text": "竞", "is_correct": false, "explanation": "声调不同（第四声与第一声），jìng 意思是竞争，与 jīng 不同。"}], "explanations": {"经": "正确。经 jīng 为本词，介词，表示经过某个过程或途径。", "今": "韵母不同（-in 与 -ing），jīn 意思是今天，与 jīng 不同。", "景": "声调不同（第三声与第一声），jǐng 意思是风景，与 jīng 不同。", "镜": "声调不同（第四声与第一声），jìng 意思是镜子，与 jīng 不同。", "竞": "声调不同（第四声与第一声），jìng 意思是竞争，与 jīng 不同。"}, "sentence_index": null, "correct_answer": "经"}, "level_3": {"options": [{"text": "经", "is_correct": true, "explanation": "正确。经：介词，表示经由记者报道这一途径，与句意相符。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替某人去做某事，句中没有可代替的人。"}, {"text": "同", "is_correct": false, "explanation": "搭配：“同”后接共同行为的对象，不能说“同记者报道”来表示经由途径。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”字句需要对具体宾语进行处置，“把记者报道”的结构不成立。"}], "explanations": {"经": "正确。经：介词，表示经由记者报道这一途径，与句意相符。", "替": "语义：“替”表示代替某人去做某事，句中没有可代替的人。", "同": "搭配：“同”后接共同行为的对象，不能说“同记者报道”来表示经由途径。", "把": "配价：“把”字句需要对具体宾语进行处置，“把记者报道”的结构不成立。"}, "sentence_index": 6, "correct_answer": "经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "经老师，我应该关心每一个学生。", "explanation": "这里应该用〈作为〉。“作为”引出身份，说“作为老师”；“经”表示经过某个过程，不能用来引出身份。"}, {"text": "这个团队经五个人组成。", "explanation": "这里应该用〈由〉。“由”可引出构成成分，说“由五个人组成”；“经”表示经过某个过程，不能用于引出构成成分。"}, {"text": "他经很高兴地说了声谢谢。", "explanation": "这里应该去掉〈经〉。“经”是介词，不能作状语修饰形容词，应说“他很高兴地说了声谢谢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经了多次反复讨论，这个方案终于定下来了。", "corrected_sentence": "经多次反复讨论，这个方案终于定下来了。", "error_description": "错误：介词“经”后面不能直接加“了”。应去掉“了”，改为“经多次反复讨论”。“了”应加在动词之后，而不是介词之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经双方协商的，这个合同终于签下来了。", "corrected_sentence": "经双方协商，这个合同终于签下来了。", "error_description": "错误：“经”引出的介词短语作状语，后面不能加“的”。应去掉“的”，改为“经双方协商，”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
