INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10453, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指去除软件程序外层的加密或压缩保护壳。", "primary_collocate": null, "pronunciation": "tuō ké", "ipa": "tʰwo˥ kʰɤ˧˥", "syllable_count": 2, "sentences": [{"text": "研究人员先给样本程序脱壳，随后再分析它的功能。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病毒分析员先给这个软件脱壳，再看里面的代码。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个程序加了壳，不脱壳就看不到源代码。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安全专家用工具给可疑文件脱壳。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "软件脱壳以后，我们才能检查它有没有病毒。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在学习怎么给游戏软件脱壳。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款杀毒软件能自动给文件脱壳。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "软件脱壳失败了，因为外面的保护太复杂。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了软件脱壳的基本方法。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个安装包有保护壳，必须先脱壳再检查。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "脱了壳", "label": "体标"}, {"form": "脱壳机", "label": "复合"}], "register": "中性", "sense_fingerprint": "去掉软件外层的保护壳（加壳的反面）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1845352-48be-48eb-9b3d-f37709a0cac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10453, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脱壳", "is_correct": true, "explanation": "正确。脱壳：去掉程序的保护壳，之后才能分析其功能。"}, {"text": "浇水", "is_correct": false, "explanation": "语义：“浇水”用于植物，程序不能浇水。"}, {"text": "剪发", "is_correct": false, "explanation": "语义：“剪发”针对人的头发，与程序无关。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”是人的行为，不能用于程序。"}], "explanations": {"脱壳": "正确。脱壳：去掉程序的保护壳，之后才能分析其功能。", "浇水": "语义：“浇水”用于植物，程序不能浇水。", "剪发": "语义：“剪发”针对人的头发，与程序无关。", "洗澡": "语义：“洗澡”是人的行为，不能用于程序。"}, "sentence_index": 0, "correct_answer": "脱壳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把信封脱了壳。", "explanation": "这里应该用〈拆开〉。“脱壳”指去掉软件的保护壳，信封不是软件，应说“拆开信封”。"}, {"text": "他把眼镜脱了壳。", "explanation": "这里应该用〈摘下〉。“脱壳”指去掉硬壳，眼镜没有保护壳，不能说“脱壳”，应说“摘下”。"}, {"text": "他把筷子脱了壳。", "explanation": "这里应该用〈拿起〉。筷子没有保护壳，“脱壳”不能用于筷子，应说“拿起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10453, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脱壳", "is_correct": true, "explanation": "正确。脱壳：去掉文件的保护壳，与“杀毒软件能自动处理文件”的语境相符。"}, {"text": "涂色", "is_correct": false, "explanation": "语义：“涂色”指给物体上色，与软件自动处理文件的功能不符。"}, {"text": "晾干", "is_correct": false, "explanation": "搭配：“晾干”用于湿润的物体，文件不能用于晾干。"}, {"text": "煮熟", "is_correct": false, "explanation": "语义：“煮熟”针对食物，与文件处理无关。"}], "explanations": {"脱壳": "正确。脱壳：去掉文件的保护壳，与“杀毒软件能自动处理文件”的语境相符。", "涂色": "语义：“涂色”指给物体上色，与软件自动处理文件的功能不符。", "晾干": "搭配：“晾干”用于湿润的物体，文件不能用于晾干。", "煮熟": "语义：“煮熟”针对食物，与文件处理无关。"}, "sentence_index": 6, "correct_answer": "脱壳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给头发脱了壳。", "explanation": "这里应该用〈梳理〉。头发没有保护壳，“脱壳”只用于软件，应说“梳理头发”。"}, {"text": "他给窗户脱了壳。", "explanation": "这里应该用〈打开〉。窗户没有保护壳，“脱壳”不能用于窗户，应说“打开”。"}, {"text": "他给一张纸脱了壳。", "explanation": "这里应该用〈折叠〉。纸没有保护壳，“脱壳”不能用于纸，应说“折叠”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10453, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "安全专家先这个程序脱壳，才能看到代码。", "corrected_sentence": "安全专家先给这个程序脱壳，才能看到代码。", "error_description": "错误：“脱壳”的对象“这个程序”前缺少介词“给”，应说“先给这个程序脱壳”，不能直接说“先这个程序脱壳”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10453, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究员先跟这个软件脱壳，再分析代码。", "corrected_sentence": "研究员先给这个软件脱壳，再分析代码。", "error_description": "错误：表示为谁去除保护壳，应用介词“给”引出，不能用“跟”。应改为“给这个软件脱壳”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
