INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10454, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按一定规则将物品分类并拣选出来。", "primary_collocate": null, "pronunciation": "fēn jiǎn", "ipa": "fən˥ tɕjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "采摘后的咖啡果实需经历水洗、日晒或蜜处理等加工方式，随后经脱壳、分拣、烘焙前处理，最终以“生豆”形态进入出口程序。", "target_word": "分拣", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "快递员每天早上先分拣包裹。", "target_word": "分拣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把水果分拣成大的和小的两类。", "target_word": "分拣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器能按大小分拣苹果。", "target_word": "分拣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邮局的工人正在分拣今天的信件。", "target_word": "分拣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾要先分拣，才能送去回收。", "target_word": "分拣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库里有十个人专门负责分拣货物。", "target_word": "分拣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用颜色分拣不同的零件。", "target_word": "分拣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡豆分拣的时候，要把坏豆子拿出来。", "target_word": "分拣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递站的工人整夜分拣新到的货。", "target_word": "分拣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分拣了", "label": "体标"}, {"form": "分拣机", "label": "复合"}, {"form": "分拣中心", "label": "复合"}], "register": "中性", "sense_fingerprint": "按规则把货物、包裹等分类拣出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1845352-48be-48eb-9b3d-f37709a0cac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10454, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "演奏", "is_correct": false, "explanation": "语义：“演奏”的对象是乐器或乐曲，咖啡果实不能被演奏。"}, {"text": "分拣", "is_correct": true, "explanation": "分拣：脱壳后按规则把果实挑拣分开，正是加工流程中的一步，符合语境。"}, {"text": "吞咽", "is_correct": false, "explanation": "语义：“吞咽”是把东西咽下去，不是加工果实的步骤。"}, {"text": "宣布", "is_correct": false, "explanation": "搭配：“宣布”的对象是消息或决定，不能用来处理果实。"}], "explanations": {"演奏": "语义：“演奏”的对象是乐器或乐曲，咖啡果实不能被演奏。", "分拣": "分拣：脱壳后按规则把果实挑拣分开，正是加工流程中的一步，符合语境。", "吞咽": "语义：“吞咽”是把东西咽下去，不是加工果实的步骤。", "宣布": "搭配：“宣布”的对象是消息或决定，不能用来处理果实。"}, "sentence_index": 0, "correct_answer": "分拣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在店里分拣了一件新大衣。", "explanation": "这里应该用〈挑选〉。分拣要把一批东西按规则分成几类，只挑一件大衣时要用挑选。"}, {"text": "他把这些观点分拣了。", "explanation": "这里应该用〈分类〉。分拣指按规则挑拣实物，观点等抽象内容要用分类。"}, {"text": "老师把试卷分拣给学生。", "explanation": "这里应该用〈分发〉。分拣只表示按规则挑拣分类，不表示把东西发给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10454, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆，不能说驾驶货物。"}, {"text": "分拣", "is_correct": true, "explanation": "分拣：仓库工人按规则把货物挑拣分类，正符合语境。"}, {"text": "饲养", "is_correct": false, "explanation": "语义：“饲养”指喂养动物，货物不是动物，不能饲养。"}, {"text": "品尝", "is_correct": false, "explanation": "语义：“品尝”指尝食物或饮品的味道，与整理货物无关。"}], "explanations": {"驾驶": "搭配：“驾驶”的对象是车辆，不能说驾驶货物。", "分拣": "分拣：仓库工人按规则把货物挑拣分类，正符合语境。", "饲养": "语义：“饲养”指喂养动物，货物不是动物，不能饲养。", "品尝": "语义：“品尝”指尝食物或饮品的味道，与整理货物无关。"}, "sentence_index": 6, "correct_answer": "分拣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "快递站的工人分拣了新来的员工。", "explanation": "这里应该用〈招聘〉。分拣的对象是货物、包裹等物品，不能用于人。"}, {"text": "快递站的工人分拣了地面。", "explanation": "这里应该用〈打扫〉。分拣要挑拣分类的是货物，地面不能分拣。"}, {"text": "快递站的工人分拣了箱子的颜色。", "explanation": "这里应该用〈检查〉。分拣是把货物按规则分开，颜色是属性，要用检查。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人已经把包裹分拣了完。", "corrected_sentence": "工人已经把包裹分拣完了。", "error_description": "错误：补语“完”与“了”的顺序颠倒，写成“分拣了完”。正确说法是“分拣完了”，结果补语“完”要紧跟动词，“了”放在句末。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仓库的工人把退回的商品分拣过好了。", "corrected_sentence": "仓库的工人把退回的商品分拣好了。", "error_description": "错误：动词“分拣”后多用了经历体“过”，写成“分拣过好了”。“过”表示经历，不能与表示完成结果的“好了”同用，正确说法是“分拣好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10455, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10455, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10455, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用烤箱或火对食物进行加热，使其变熟或变色。", "primary_collocate": null, "pronunciation": "hōng bèi", "ipa": "xʊŋ˥ pei˥˩", "syllable_count": 2, "sentences": [{"text": "采摘后的咖啡果实需经历水洗、日晒或蜜处理等加工方式，随后经脱壳、分拣、烘焙前处理，最终以“生豆”形态进入出口程序。", "target_word": "烘焙", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "与此相对，北美、西欧及东亚部分高收入经济体则作为主要进口方，凭借资本与品牌优势，掌控烘焙、包装与市场分销渠道。", "target_word": "烘焙", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "咖啡师把生豆放进机器里烘焙二十分钟。", "target_word": "烘焙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡豆烘焙的时间越长，颜色越深。", "target_word": "烘焙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把杏仁放进烤箱烘焙，直到变成金黄色。", "target_word": "烘焙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶农用火烘焙茶叶，让它更香。", "target_word": "烘焙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批咖啡豆烘焙得太久，味道有点苦。", "target_word": "烘焙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅正在烘焙花生，满屋子都是香味。", "target_word": "烘焙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "芝麻要小火慢慢烘焙，才不会变黑。", "target_word": "烘焙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烘焙咖啡豆以前，要先把坏豆子挑出来。", "target_word": "烘焙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "烘焙了", "label": "体标"}, {"form": "烘焙过", "label": "体标"}, {"form": "烘焙师", "label": "复合"}], "register": "中性", "sense_fingerprint": "加热咖啡豆、坚果等使其变熟变色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1845352-48be-48eb-9b3d-f37709a0cac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10455, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "熨烫", "is_correct": false, "explanation": "语义：“熨烫”是用熨斗压平织物，咖啡果实不能熨烫。"}, {"text": "烘焙", "is_correct": true, "explanation": "烘焙：指之后加热咖啡豆的工序；“烘焙前处理”就是在烘焙之前做的加工，生豆还没有被烘焙，符合语境。"}, {"text": "吟诵", "is_correct": false, "explanation": "语义：“吟诵”是朗读诗文，与咖啡果实的加工无关。"}, {"text": "装订", "is_correct": false, "explanation": "搭配：“装订”用于书本纸张，不能用于咖啡果实。"}], "explanations": {"熨烫": "语义：“熨烫”是用熨斗压平织物，咖啡果实不能熨烫。", "烘焙": "烘焙：指之后加热咖啡豆的工序；“烘焙前处理”就是在烘焙之前做的加工，生豆还没有被烘焙，符合语境。", "吟诵": "语义：“吟诵”是朗读诗文，与咖啡果实的加工无关。", "装订": "搭配：“装订”用于书本纸张，不能用于咖啡果实。"}, "sentence_index": 0, "correct_answer": "烘焙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在院子里烘焙羊肉。", "explanation": "这里应该用〈烤〉。烘焙多用于咖啡豆、坚果、面点等干燥食材，烤羊肉这类肉食要用烤。"}, {"text": "他在锅里烘焙鸡蛋。", "explanation": "这里应该用〈煎〉。烘焙靠干热烘烤使食材变熟变色，煎鸡蛋要用煎。"}, {"text": "她用烘干机烘焙湿衣服。", "explanation": "这里应该用〈烘干〉。烘焙是加热食物使其变熟变色，让湿衣服变干应说烘干，句中的“烘干机”已点明这一点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10455, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "批阅", "is_correct": false, "explanation": "搭配：“批阅”的对象是作业、文章，不能批阅咖啡豆。"}, {"text": "放映", "is_correct": false, "explanation": "语义：“放映”的对象是影片，咖啡豆不能放映。"}, {"text": "烘焙", "is_correct": true, "explanation": "烘焙：加热咖啡豆过久，味道就会发苦，符合语境。"}, {"text": "哼", "is_correct": false, "explanation": "语义：“哼”是轻声唱，与烘焙豆子的过程无关。"}], "explanations": {"批阅": "搭配：“批阅”的对象是作业、文章，不能批阅咖啡豆。", "放映": "语义：“放映”的对象是影片，咖啡豆不能放映。", "烘焙": "烘焙：加热咖啡豆过久，味道就会发苦，符合语境。", "哼": "语义：“哼”是轻声唱，与烘焙豆子的过程无关。"}, "sentence_index": 6, "correct_answer": "烘焙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用小火烘焙汤。", "explanation": "这里应该用〈炖〉。烘焙是靠干热让食材变干、变色，汤是液体，要用炖。"}, {"text": "他在炉子上烘焙开水。", "explanation": "这里应该用〈烧〉。烘焙用于干燥食材，开水是液体，要烧。"}, {"text": "妈妈用电饭煲烘焙饭。", "explanation": "这里应该用〈煮〉。烘焙靠干热烘烤使食材变熟变色，米饭要用煮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10455, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "咖啡师把咖啡豆烘焙了好。", "corrected_sentence": "咖啡师把咖啡豆烘焙好了。", "error_description": "错误：结果补语“好”放在了“了”之后，写成“烘焙了好”。正确说法是“烘焙好了”，结果补语要紧跟动词，“了”放在句末。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10455, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "咖啡师了烘焙咖啡豆。", "corrected_sentence": "咖啡师烘焙咖啡豆。", "error_description": "错误：动态助词“了”放在了动词“烘焙”之前，写成“了烘焙”。“了”不能放在动词前，应去掉，说“咖啡师烘焙咖啡豆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
