INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10457, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10457, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指未经烹饪、保持原始状态的豆类，通常需要加工后才能食用。", "primary_collocate": null, "pronunciation": "shēng dòu", "ipa": "ʂɤŋ˥ tou˥˩", "syllable_count": 2, "sentences": [{"text": "采摘后的咖啡果实需经历水洗、日晒或蜜处理等加工方式，随后经脱壳、分拣、烘焙前处理，最终以“生豆”形态进入出口程序。", "target_word": "生豆", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "出口环节往往由跨国贸易公司主导，通过期货市场与长期合同锁定价格，将生豆批量运输至消费国。", "target_word": "生豆", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "咖啡生豆是绿色的，烘焙以后才会变成棕色。", "target_word": "生豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店从国外买了很多咖啡生豆，再自己烘焙。", "target_word": "生豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生豆没有香味，要烘焙以后才有咖啡的香气。", "target_word": "生豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把五公斤生豆倒进了烘焙机里。", "target_word": "生豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这袋生豆放在干燥的地方，不容易坏。", "target_word": "生豆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我朋友喜欢自己买生豆，在家烘焙咖啡。", "target_word": "生豆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生豆的价格每天都在变，咖啡店很关心。", "target_word": "生豆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烘焙师先检查生豆，把坏豆子挑出来。", "target_word": "生豆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一颗生豆", "label": "量词"}, {"form": "一袋生豆", "label": "量词"}, {"form": "咖啡生豆", "label": "复合"}], "register": "中性", "sense_fingerprint": "未经烹饪或烘焙的原始豆类，如咖啡生豆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae77ee84-c07a-4548-b32e-52b3c05e79c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10457, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生豆", "is_correct": true, "explanation": "正确。句中指未经烘焙的原始咖啡豆，在脱壳、分拣之后以“生豆”形态出口，符合语境。"}, {"text": "熟豆", "is_correct": false, "explanation": "语义：熟豆已经烘焙，与句中“烘焙前处理”之后才出口的语境相反。"}, {"text": "咖啡粉", "is_correct": false, "explanation": "语义：咖啡粉是烘焙并研磨后的产品，不是出口前的原始豆形态。"}, {"text": "咖啡果", "is_correct": false, "explanation": "语义：咖啡果是脱壳前的果实，句中已写明经过“脱壳”，阶段不符。"}], "explanations": {"生豆": "正确。句中指未经烘焙的原始咖啡豆，在脱壳、分拣之后以“生豆”形态出口，符合语境。", "熟豆": "语义：熟豆已经烘焙，与句中“烘焙前处理”之后才出口的语境相反。", "咖啡粉": "语义：咖啡粉是烘焙并研磨后的产品，不是出口前的原始豆形态。", "咖啡果": "语义：咖啡果是脱壳前的果实，句中已写明经过“脱壳”，阶段不符。"}, "sentence_index": 0, "correct_answer": "生豆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店从国外买了很多生豆，直接磨成粉卖给客人。", "explanation": "这里应该用〈熟豆〉。生豆未经烘焙，不能直接磨粉卖给客人。"}, {"text": "这家店从国外买了很多生豆，直接冲泡给客人喝。", "explanation": "这里应该用〈咖啡粉〉。生豆没有烘焙，不能直接冲泡。"}, {"text": "这家店从国外买了很多生豆，然后送去脱壳。", "explanation": "这里应该用〈咖啡果〉。生豆已经脱壳，不能再送去脱壳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10457, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生豆", "is_correct": true, "explanation": "正确。“这袋”计量的是生豆，放在干燥处不容易变质，句意合理。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：“牛奶”通常要冷藏保存，与“放在干燥的地方”不搭配，句意不通。"}, {"text": "冰淇淋", "is_correct": false, "explanation": "语义：冰淇淋放在干燥处会融化，与“不容易坏”的语境矛盾。"}, {"text": "鲜虾", "is_correct": false, "explanation": "语义：鲜虾极易变质，放在干燥的地方不可能“不容易坏”。"}], "explanations": {"生豆": "正确。“这袋”计量的是生豆，放在干燥处不容易变质，句意合理。", "牛奶": "搭配：“牛奶”通常要冷藏保存，与“放在干燥的地方”不搭配，句意不通。", "冰淇淋": "语义：冰淇淋放在干燥处会融化，与“不容易坏”的语境矛盾。", "鲜虾": "语义：鲜虾极易变质，放在干燥的地方不可能“不容易坏”。"}, "sentence_index": 6, "correct_answer": "生豆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "烘焙师先闻一闻生豆浓浓的咖啡香，再把坏豆子挑出来。", "explanation": "这里应该用〈熟豆〉。生豆没有烘焙，没有咖啡香气。"}, {"text": "烘焙师先检查生豆，再直接用它冲了一杯咖啡。", "explanation": "这里应该用〈咖啡粉〉。生豆不能直接冲泡咖啡。"}, {"text": "烘焙师先检查生豆，发现它们还是红红的果实。", "explanation": "这里应该用〈咖啡果〉。生豆是脱壳后的种子，不是红色果实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10457, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从网上买了一张生豆。", "corrected_sentence": "他从网上买了一袋生豆。", "error_description": "量词错误：“张”用于平面的东西，不能计量生豆；成袋购买的生豆应说“一袋生豆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10457, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店员把一条生豆搬进了仓库。", "corrected_sentence": "店员把一袋生豆搬进了仓库。", "error_description": "量词错误：“生豆”应搭配量词“袋”，不能用“条”（“条”多用于细长的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
