INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10460, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "期货市场是买卖未来某一时间交付的商品或金融资产的标准化合约的交易场所。", "primary_collocate": null, "pronunciation": "qī huò shì chǎng", "ipa": "tɕʰi˥ xuo˥˩ ʂɨ˥˩ ʈʂʰɑŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "出口环节往往由跨国贸易公司主导，通过期货市场与长期合同锁定价格，将生豆批量运输至消费国。", "target_word": "期货市场", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "期货市场里可以买卖将来才交货的东西。", "target_word": "期货市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在期货市场工作，每天看价格。", "target_word": "期货市场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "期货市场上的价格每天都在变。", "target_word": "期货市场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多农民通过期货市场卖出明年的粮食。", "target_word": "期货市场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "期货市场不是商店，你不能在那里直接买菜。", "target_word": "期货市场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在期货市场赚了钱，也赔过钱。", "target_word": "期货市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡公司常常到期货市场去买咖啡豆。", "target_word": "期货市场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新手进入期货市场以前，要先学习规则。", "target_word": "期货市场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天期货市场的咖啡价格上涨了。", "target_word": "期货市场", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个期货市场", "label": "量词"}, {"form": "期貨市場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "买卖未来交割的标准化合约的交易场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae77ee84-c07a-4548-b32e-52b3c05e79c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10460, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "期货市场", "is_correct": true, "explanation": "正确。期货市场可以提前锁定价格，与长期合同配合使用，符合句意。"}, {"text": "农贸市场", "is_correct": false, "explanation": "语义：农贸市场是零售性的即时交易场所，与跨国贸易、锁定未来价格的语境不符。"}, {"text": "游乐场", "is_correct": false, "explanation": "语义：游乐场不是交易场所，无法通过它与合同锁定价格。"}, {"text": "超市", "is_correct": false, "explanation": "搭配：“通过超市……锁定价格”不成立，超市不用于锁定价格。"}], "explanations": {"期货市场": "正确。期货市场可以提前锁定价格，与长期合同配合使用，符合句意。", "农贸市场": "语义：农贸市场是零售性的即时交易场所，与跨国贸易、锁定未来价格的语境不符。", "游乐场": "语义：游乐场不是交易场所，无法通过它与合同锁定价格。", "超市": "搭配：“通过超市……锁定价格”不成立，超市不用于锁定价格。"}, "sentence_index": 0, "correct_answer": "期货市场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "期货市场的交易是即时完成的，钱货两清。", "explanation": "这里应该用〈现货市场〉。期货市场的交割在将来，不能说交易即时完成、钱货两清。"}, {"text": "期货市场上的价格每天都在变，所以我去那里买了一斤苹果。", "explanation": "这里应该用〈菜市场〉。期货市场交易的是标准化合约，不零售苹果。"}, {"text": "我每天早上去期货市场买股票。", "explanation": "这里应该用〈股票市场〉。期货市场交易的是未来交货的标准化合约，股票要在股票市场买卖，不能在期货市场买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "期货市场", "is_correct": true, "explanation": "正确。期货市场是金融交易场所，既可能盈利，也可能亏损，符合句意。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不是交易场所，不能在那里“赚钱”或“赔钱”。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是公共服务场所，不以赚钱、赔钱为经营方式。"}, {"text": "电梯", "is_correct": false, "explanation": "配价：“赚”需要有经营的场所，电梯不能作为赚钱的场所。"}], "explanations": {"期货市场": "正确。期货市场是金融交易场所，既可能盈利，也可能亏损，符合句意。", "教室": "语义：教室不是交易场所，不能在那里“赚钱”或“赔钱”。", "图书馆": "语义：图书馆是公共服务场所，不以赚钱、赔钱为经营方式。", "电梯": "配价：“赚”需要有经营的场所，电梯不能作为赚钱的场所。"}, "sentence_index": 6, "correct_answer": "期货市场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去期货市场存了一笔钱，每个月都有利息。", "explanation": "这里应该用〈银行〉。期货市场买卖的是未来交货的合约，不吸收存款，也不付利息，存钱要去银行。"}, {"text": "我在期货市场买了一件衣服。", "explanation": "这里应该用〈服装店〉。期货市场交易的是合约，不卖衣服，买衣服要去服装店。"}, {"text": "我今晚去期货市场看比赛，票已经买好了。", "explanation": "这里应该用〈体育场〉。期货市场是交易合约的场所，不举办比赛，看比赛要去体育场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司期货市场卖出了合约。", "corrected_sentence": "这家公司在期货市场卖出了合约。", "error_description": "漏掉了“在”。表示动作发生的场所要用“在+地点”，应说“在期货市场卖出了合约”，不能省去“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去了一张期货市场。", "corrected_sentence": "我们去了一个期货市场。", "error_description": "“张”应改为“个”。“张”用于平面的东西，不能用来计量市场，通用量词“个”才正确。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
