INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10462, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10462, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "双方或多方之间订立并共同遵守的协议，通常具有法律效力。", "primary_collocate": null, "pronunciation": "hé tong", "ipa": "xɤ˧˥ tʰʊŋ", "syllable_count": 2, "sentences": [{"text": "出口环节往往由跨国贸易公司主导，通过期货市场与长期合同锁定价格，将生豆批量运输至消费国。", "target_word": "合同", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们和公司签了一份工作合同。", "target_word": "合同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "合同上写着工作时间和工资。", "target_word": "合同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你先看清楚合同，再签名。", "target_word": "合同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房东把租房合同给了我。", "target_word": "合同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合同到期以后，公司不想继续合作了。", "target_word": "合同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有遵守合同，所以要赔钱。", "target_word": "合同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份合同一共有五页，我看了一个小时。", "target_word": "合同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子的时候，一定要签合同。", "target_word": "合同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "双方在合同里写清楚了价格和时间。", "target_word": "合同", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份合同", "label": "量词"}, {"form": "劳动合同", "label": "复合"}, {"form": "租房合同", "label": "复合"}], "register": "中性", "sense_fingerprint": "双方或多方订立的有法律效力的协议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae77ee84-c07a-4548-b32e-52b3c05e79c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10462, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合同", "is_correct": true, "explanation": "正确。“长期合同”指双方订立的协议，可以用来锁定价格。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能作为“通过期货市场与……锁定价格”的手段或对象。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这句书面化的贸易描述不协调。"}, {"text": "距离", "is_correct": false, "explanation": "搭配：“长期距离”不能成立，“长期”一般修饰合同、合作、贷款等。"}], "explanations": {"合同": "正确。“长期合同”指双方订立的协议，可以用来锁定价格。", "天气": "语义：天气不能作为“通过期货市场与……锁定价格”的手段或对象。", "玩意儿": "语域：“玩意儿”是口语说法，与这句书面化的贸易描述不协调。", "距离": "搭配：“长期距离”不能成立，“长期”一般修饰合同、合作、贷款等。"}, "sentence_index": 0, "correct_answer": "合同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国签了一份合同，结束了这场战争。", "explanation": "这里应该用〈条约〉。合同多用于个人、公司之间的约定；国家之间结束战争的正式约定要用条约。"}, {"text": "买了新手机，盒子里有一份合同，教我们怎么充电。", "explanation": "这里应该用〈说明书〉。合同是双方约定的协议，介绍产品用法的文件要用“说明书”。"}, {"text": "我们班的合同很严格，学生不能迟到。", "explanation": "这里应该用〈班规〉。合同是双方订立的协议，全班共同遵守的纪律要用“班规”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合同", "is_correct": true, "explanation": "正确。“遵守合同”指履行双方约定的义务，违约才需要赔钱。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“遵守”后面接规定、规则、协议，不能说“遵守作业”，作业应该“完成”。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间是场所，不是需要遵守的规范，不能说“没有遵守房间”。"}, {"text": "人", "is_correct": false, "explanation": "配价：“遵守”的对象是规则或约定，“人”不能作为被遵守的对象。"}], "explanations": {"合同": "正确。“遵守合同”指履行双方约定的义务，违约才需要赔钱。", "作业": "搭配：“遵守”后面接规定、规则、协议，不能说“遵守作业”，作业应该“完成”。", "房间": "语义：房间是场所，不是需要遵守的规范，不能说“没有遵守房间”。", "人": "配价：“遵守”的对象是规则或约定，“人”不能作为被遵守的对象。"}, "sentence_index": 6, "correct_answer": "合同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两国政府签订了一份边界合同，划定了新的国界。", "explanation": "这里应该用〈协定〉。划定国界这类国家之间的正式约定用协定或条约，合同多用于个人、公司之间。"}, {"text": "我用合同量了一下房间的面积。", "explanation": "这里应该用〈尺子〉。合同指双方订立、有法律效力的协议，不能用来测量长度，量面积要用尺子。"}, {"text": "他下雨天拿合同挡雨，结果淋湿了。", "explanation": "这里应该用〈雨伞〉。合同不能用来挡雨，下雨天应该用雨伞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们和房东签了一只租房合同。", "corrected_sentence": "我们和房东签了一份租房合同。", "error_description": "量词错误：“合同”应搭配量词“份”，不能用“只”（“只”多用于动物或单个物件）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条合同写得很清楚。", "corrected_sentence": "那份合同写得很清楚。", "error_description": "量词错误：“合同”应搭配量词“份”，不能用“条”（“条”多用于细长的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10463, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10463, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10463, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使固定不动或确定目标。", "primary_collocate": null, "pronunciation": "suǒ dìng", "ipa": "swɔ˨˩˦ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "出口环节往往由跨国贸易公司主导，通过期货市场与长期合同锁定价格，将生豆批量运输至消费国。", "target_word": "锁定", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "警方已经锁定了那名嫌疑人。", "target_word": "锁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先锁定目标，再想办法。", "target_word": "锁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想提前锁定原料价格。", "target_word": "锁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队提前一轮锁定了冠军。", "target_word": "锁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼睛一直锁定着那个包。", "target_word": "锁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先锁定你想买的房子。", "target_word": "锁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生很快锁定了病因。", "target_word": "锁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司把价格锁定在一百元。", "target_word": "锁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用手机锁定了他的位置。", "target_word": "锁定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "锁定了", "label": "体标（了）"}, {"form": "锁定着", "label": "体标（着）"}, {"form": "锁定过", "label": "体标（过）"}, {"form": "鎖定", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把价格、目标、对象等确定下来，不再变动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae77ee84-c07a-4548-b32e-52b3c05e79c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10463, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "锁定", "is_correct": true, "explanation": "正确。“锁定价格”指把价格提前确定下来，不再变动。"}, {"text": "运输", "is_correct": false, "explanation": "搭配：“运输”的对象是货物，不能说运输价格。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”不能用来表示确定价格，这句话说的是把价格固定下来。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”的对象是长度、面积等可以量的东西，价格不能测量，句中是通过合同确定价格。"}], "explanations": {"锁定": "正确。“锁定价格”指把价格提前确定下来，不再变动。", "运输": "搭配：“运输”的对象是货物，不能说运输价格。", "烧": "语义：“烧”不能用来表示确定价格，这句话说的是把价格固定下来。", "测量": "搭配：“测量”的对象是长度、面积等可以量的东西，价格不能测量，句中是通过合同确定价格。"}, "sentence_index": 0, "correct_answer": "锁定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到这个消息，他努力锁定自己的情绪，不让别人看出来。", "explanation": "这里应该用〈控制〉。锁定只用于使东西固定不动或确定目标，情绪不能被锁定，克制情绪要用“控制”。"}, {"text": "他一听这话就锁定脾气，没有发火。", "explanation": "这里应该用〈忍住〉。锁定表示使东西固定不动或确定目标，不能用来表示忍住脾气。"}, {"text": "这种药很快就锁定了病人的发烧，他很快好起来了。", "explanation": "这里应该用〈退〉。锁定表示使东西固定不动或确定目标，不能用来表示退烧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10463, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "锁定", "is_correct": true, "explanation": "正确。“锁定”在这里指先确定下来要买的房子。"}, {"text": "咀嚼", "is_correct": false, "explanation": "语义：“咀嚼”的对象是食物，不能说咀嚼房子。"}, {"text": "推迟", "is_correct": false, "explanation": "搭配：“推迟”的对象是时间或事项，不能说推迟房子。"}, {"text": "修理", "is_correct": false, "explanation": "语义：这套房子还没买，不能先去修理，句子要的是提前确定目标。"}], "explanations": {"锁定": "正确。“锁定”在这里指先确定下来要买的房子。", "咀嚼": "语义：“咀嚼”的对象是食物，不能说咀嚼房子。", "推迟": "搭配：“推迟”的对象是时间或事项，不能说推迟房子。", "修理": "语义：这套房子还没买，不能先去修理，句子要的是提前确定目标。"}, "sentence_index": 6, "correct_answer": "锁定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每天晚上都锁定英语。", "explanation": "这里应该用〈预习〉。锁定用于目标、价格、位置等可以被确定的对象，学习外语要用“预习”或“学习”。"}, {"text": "妈妈每天晚饭后锁定碗。", "explanation": "这里应该用〈洗〉。锁定表示把对象确定下来，不能表示清洗餐具。"}, {"text": "他在厨房里锁定了一碗汤。", "explanation": "这里应该用〈喝〉。锁定的对象是目标、价格等，汤不能被锁定，喝汤要用“喝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10463, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警方很快锁定着那名嫌疑人。", "corrected_sentence": "警方很快锁定了那名嫌疑人。", "error_description": "体标误用：“很快”表示动作已经完成，“锁定”后应该用“了”，不能用表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10463, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们昨天用电脑锁定着了那辆车的位置。", "corrected_sentence": "我们昨天用电脑锁定了那辆车的位置。", "error_description": "体标误用：“着”和“了”不能同时用在“锁定”后；动作已完成，只用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
