INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10465, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "指同时处理或安排很多相同或相似的事物。", "primary_collocate": null, "pronunciation": "pī liàng", "ipa": "pʰi˥ ljaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "出口环节往往由跨国贸易公司主导，通过期货市场与长期合同锁定价格，将生豆批量运输至消费国。", "target_word": "批量", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工厂批量生产这种杯子。", "target_word": "批量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想批量购买新书。", "target_word": "批量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师批量修改了作业。", "target_word": "批量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件可以批量改名字。", "target_word": "批量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司批量订了一百台电脑。", "target_word": "批量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手机批量发送照片。", "target_word": "批量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上批量卖这种衣服，价格便宜。", "target_word": "批量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器批量做出了很多零件。", "target_word": "批量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在批量检查产品。", "target_word": "批量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "批量生产", "label": "复合"}], "register": "中性", "sense_fingerprint": "一次处理或安排大量相同的东西，修饰动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae77ee84-c07a-4548-b32e-52b3c05e79c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10465, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "批量", "is_correct": true, "explanation": "“批量”表示同时成批处理同类货物，与“将生豆……运输至消费国”的大宗运输相符。"}, {"text": "逐个", "is_correct": false, "explanation": "语义：“逐个”指一个一个地进行，与大宗货物成批运输的做法不符。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已完成，与句中的“往往”（惯常做法）互相冲突。"}, {"text": "亲自", "is_correct": false, "explanation": "配价：“亲自”要求由人本人施行，而句中的施事是跨国贸易公司主导的运输环节，不能说亲自运输。"}], "explanations": {"批量": "“批量”表示同时成批处理同类货物，与“将生豆……运输至消费国”的大宗运输相符。", "逐个": "语义：“逐个”指一个一个地进行，与大宗货物成批运输的做法不符。", "已经": "体貌：“已经”表示动作已完成，与句中的“往往”（惯常做法）互相冲突。", "亲自": "配价：“亲自”要求由人本人施行，而句中的施事是跨国贸易公司主导的运输环节，不能说亲自运输。"}, "sentence_index": 0, "correct_answer": "批量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他批量修改了这份作业。", "explanation": "这里应该用〈单独〉。“批量”要求同时处理很多相同或相似的东西，“这份作业”只有一份，只能说单独修改。"}, {"text": "我批量喝了一杯水。", "explanation": "这里应该用〈一口气〉。“批量”指同时处理很多相同或相似的事物，“喝一杯水”只是一次单个的动作，不能用批量。"}, {"text": "妈妈批量买了一个蛋糕。", "explanation": "这里应该用〈特意〉。“批量”指同时处理很多相同或相似的东西，“一个蛋糕”只有一个，不能说批量买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10465, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "批量", "is_correct": true, "explanation": "“批量”表示成批同时发送同类的东西，与“用手机发送照片”搭配。"}, {"text": "逐字", "is_correct": false, "explanation": "语义：“逐字”指一个字一个字地进行，照片不是文字，不能逐字发送。"}, {"text": "当面", "is_correct": false, "explanation": "搭配：“当面”指面对面，与“用手机发送”互相矛盾。"}, {"text": "逐页", "is_correct": false, "explanation": "语义：“逐页”指一页一页地处理，照片不是书页，与句中的对象不符。"}], "explanations": {"批量": "“批量”表示成批同时发送同类的东西，与“用手机发送照片”搭配。", "逐字": "语义：“逐字”指一个字一个字地进行，照片不是文字，不能逐字发送。", "当面": "搭配：“当面”指面对面，与“用手机发送”互相矛盾。", "逐页": "语义：“逐页”指一页一页地处理，照片不是书页，与句中的对象不符。"}, "sentence_index": 6, "correct_answer": "批量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们批量休息了一个小时。", "explanation": "这里应该用〈一起〉。“批量”要求同时处理很多相同的东西，“休息”不是处理事物的动作，不能用批量。"}, {"text": "老板批量检查空气。", "explanation": "这里应该用〈全面〉。“批量”只用于可以逐个计数、成批处理的东西，“空气”是不可数的物质，不能成批检查。"}, {"text": "小王批量毕业了。", "explanation": "这里应该用〈顺利〉。“批量”要求同时成批处理很多相同或相似的事物，小王只是一个人，他毕业不能说批量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10465, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂很批量印刷了一千张传单。", "corrected_sentence": "工厂批量印刷了一千张传单。", "error_description": "错误：副词“批量”前不能加程度副词“很”，应说“批量印刷”，不能说“很批量印刷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10465, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用电脑很批量下载了照片。", "corrected_sentence": "他用电脑批量下载了照片。", "error_description": "错误：副词“批量”前不能加程度副词“很”，应说“批量下载了照片”，不能说“很批量下载”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
