INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10466, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指大量购买和消耗商品或服务的国家，在国际贸易中通常指进口国。", "primary_collocate": null, "pronunciation": "xiāo fèi guó", "ipa": "ɕiɑʊ˥ feɪ˥˩ ku̯ɔ˧˥", "syllable_count": 3, "sentences": [{"text": "出口环节往往由跨国贸易公司主导，通过期货市场与长期合同锁定价格，将生豆批量运输至消费国。", "target_word": "消费国", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "中国是咖啡的新兴消费国。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美国是世界上最大的石油消费国之一。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些货物将运往几个主要消费国。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡豆从产地运到消费国要一个月。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家不产茶叶，是有名的茶叶消费国。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消费国提高关税，生产国的出口就会受影响。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产国把粮食卖给消费国。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为牛肉消费国，日本每年进口很多牛肉。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消费国的人喜欢买进口的水果。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "消费国:大量购买消耗商品的国家,国际贸易中的进口国", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50c9095a-030e-4bc4-9e56-90be58a29a83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消费国", "is_correct": true, "explanation": "消费国指大量购买商品的国家，生豆运往这里符合句意。"}, {"text": "生产国", "is_correct": false, "explanation": "语义：生豆正是从生产国出口的，“运输至”的终点应是买方国家，不能再运回生产国。"}, {"text": "老外", "is_correct": false, "explanation": "语域：“老外”是口语词，与本句的书面语体不协调；且它指人，不指国家，不能作运输终点。"}, {"text": "农场", "is_correct": false, "explanation": "语义：农场是生豆的产地，“批量运输至农场”与句中“出口环节”的语境相矛盾。"}], "explanations": {"消费国": "消费国指大量购买商品的国家，生豆运往这里符合句意。", "生产国": "语义：生豆正是从生产国出口的，“运输至”的终点应是买方国家，不能再运回生产国。", "老外": "语域：“老外”是口语词，与本句的书面语体不协调；且它指人，不指国家，不能作运输终点。", "农场": "语义：农场是生豆的产地，“批量运输至农场”与句中“出口环节”的语境相矛盾。"}, "sentence_index": 0, "correct_answer": "消费国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家跨国公司每年大量买进咖啡，是重要的消费国。", "explanation": "这里应该用〈采购商〉。消费国指国家，公司买进咖啡应说〈采购商〉，不能作为消费国。"}, {"text": "这个国家几乎所有咖啡都用于出口，自己几乎不喝，是咖啡的消费国。", "explanation": "这里应该用〈生产国〉。句中说这个国家几乎所有咖啡都用于出口、自己几乎不喝，是咖啡的生产国，不是消费国。"}, {"text": "我哥哥是一个消费国。", "explanation": "这里指人不妥：〈消费国〉指国家，不能指个人，指人应说〈消费者〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消费国", "is_correct": true, "explanation": "消费国是买入商品的国家，可以在进口环节提高关税，句意通顺。"}, {"text": "咖啡馆", "is_correct": false, "explanation": "语义：关税由政府制定，咖啡馆无权提高关税。"}, {"text": "大爷", "is_correct": false, "explanation": "语域：“大爷”是口语词，与本句的书面语体不协调；且个人也无权提高关税。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民不能决定关税，句中主语应是有关税权的国家。"}], "explanations": {"消费国": "消费国是买入商品的国家，可以在进口环节提高关税，句意通顺。", "咖啡馆": "语义：关税由政府制定，咖啡馆无权提高关税。", "大爷": "语域：“大爷”是口语词，与本句的书面语体不协调；且个人也无权提高关税。", "农民": "语义：农民不能决定关税，句中主语应是有关税权的国家。"}, "sentence_index": 6, "correct_answer": "消费国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个消费国每年向世界各地大量卖出咖啡。", "explanation": "这里应该用〈出口国〉。消费国指大量买入商品的国家，向外大量卖出应说出口国。"}, {"text": "这个消费国的农民每年种植大量咖啡，全部运往别国。", "explanation": "这里应该用〈生产国〉。消费国指大量买入商品的国家，此句说本国农民种植咖啡并全部外运，应称生产国。"}, {"text": "上海是一个消费国。", "explanation": "这里指城市不妥：〈消费国〉指国家，城市不能作为消费国。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座主要消费国去年大量进口了咖啡。", "corrected_sentence": "这个主要消费国去年大量进口了咖啡。", "error_description": "量词错误：国家应用“个”，不用“座”。“座”多用于山、桥、城市等固定建筑，应改为“这个主要消费国”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些咖啡豆每年都运往那只消费国。", "corrected_sentence": "这些咖啡豆每年都运往那个消费国。", "error_description": "量词错误：国家应用“个”，不用“只”。“只”多用于动物等，应改为“那个消费国”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
