INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10468, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在买卖双方之间进行交易撮合或商品流通的个人或企业。", "primary_collocate": null, "pronunciation": "zhōng jiān shāng", "ipa": "ʈ͡ʂʊŋ˥ tɕjɛn˥ ʂɑŋ˥", "syllable_count": 3, "sentences": [{"text": "这一过程涉及多重中间商、质量认证体系（如公平贸易、有机认证）以及复杂的物流协调，以确保从产地仓库到目的港的供应链稳定性。", "target_word": "中间商", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "中间商从农民那里买水果，再卖给超市。", "target_word": "中间商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去掉中间商，价格会便宜一些。", "target_word": "中间商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司做中间商，每年赚不少钱。", "target_word": "中间商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中间商把工厂的衣服卖给小商店。", "target_word": "中间商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中间商在买家和卖家之间牵线。", "target_word": "中间商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了少给中间商钱，他直接去农场买菜。", "target_word": "中间商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中间商的利润不低，所以东西贵了。", "target_word": "中间商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先当了几年中间商，后来自己开了工厂。", "target_word": "中间商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买家和卖家都要付钱给中间商。", "target_word": "中间商", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "家", "label": "量词"}], "register": "书面", "sense_fingerprint": "中间商:买卖双方之间撮合交易的个人或企业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50c9095a-030e-4bc4-9e56-90be58a29a83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10468, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中间商", "is_correct": true, "explanation": "中间商指在买卖双方之间撮合交易或流通商品的个人或企业，正是供应链中的环节。"}, {"text": "乐队", "is_correct": false, "explanation": "语义：乐队是演奏音乐的团体，与供应链环节无关，“涉及多重乐队”不成立。"}, {"text": "老外", "is_correct": false, "explanation": "语域：“老外”是口语词，与本句的书面语体不协调；且它指人，不指交易环节。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：动物园是展示动物的场所，不参与交易流通，句中语境不符。"}], "explanations": {"中间商": "中间商指在买卖双方之间撮合交易或流通商品的个人或企业，正是供应链中的环节。", "乐队": "语义：乐队是演奏音乐的团体，与供应链环节无关，“涉及多重乐队”不成立。", "老外": "语域：“老外”是口语词，与本句的书面语体不协调；且它指人，不指交易环节。", "动物园": "语义：动物园是展示动物的场所，不参与交易流通，句中语境不符。"}, "sentence_index": 0, "correct_answer": "中间商"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家中间商每年生产不少产品。", "explanation": "这里应该用〈工厂〉。中间商只在买卖之间撮合或流通，不负责生产，生产产品应说〈工厂〉。"}, {"text": "这只猫是中间商，每年赚不少钱。", "explanation": "这里指动物不妥：〈中间商〉指个人或企业，猫不能作中间商。"}, {"text": "这首歌是中间商，帮买家卖了很多东西。", "explanation": "这里指作品不妥：〈中间商〉指个人或企业，歌曲不能作中间商。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10468, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中间商", "is_correct": true, "explanation": "中间商可以收取差价，“少给中间商钱”说的正是买卖之间的中间人，句意通顺。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆不是买卖环节，“少给图书馆钱”与“直接去农场买菜”的语境不符。"}, {"text": "篮球队", "is_correct": false, "explanation": "语义：篮球队是体育团体，不参与商品买卖，“少给篮球队钱”不合逻辑。"}, {"text": "游泳池", "is_correct": false, "explanation": "语义：游泳池是运动场所，不参与买卖，“少给游泳池钱”与“直接去农场买菜”无关。"}], "explanations": {"中间商": "中间商可以收取差价，“少给中间商钱”说的正是买卖之间的中间人，句意通顺。", "图书馆": "语义：图书馆不是买卖环节，“少给图书馆钱”与“直接去农场买菜”的语境不符。", "篮球队": "语义：篮球队是体育团体，不参与商品买卖，“少给篮球队钱”不合逻辑。", "游泳池": "语义：游泳池是运动场所，不参与买卖，“少给游泳池钱”与“直接去农场买菜”无关。"}, "sentence_index": 6, "correct_answer": "中间商"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中间商是工厂的老板，负责生产衣服，然后卖给买家。", "explanation": "这里应该用〈生产商〉。中间商不负责生产，只在买卖之间撮合或流通。"}, {"text": "这台机器是中间商，帮买家付了钱。", "explanation": "这里指机器不妥：〈中间商〉指个人或企业，机器不能作中间商。"}, {"text": "这棵大树每年都替买家找货源，是中间商。", "explanation": "这里指植物不妥：〈中间商〉指个人或企业，树不能作中间商。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10468, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他当了一只中间商，专门帮农民卖水果。", "corrected_sentence": "他当了一名中间商，专门帮农民卖水果。", "error_description": "量词错误：指人应用“名”或“个”，不用“只”。“只”多用于动物等，应改为“一名中间商”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10468, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只中间商每年帮两家工厂卖出很多衣服。", "corrected_sentence": "这位中间商每年帮两家工厂卖出很多衣服。", "error_description": "量词错误：指人应用“位”，不用“只”。“只”多用于动物等，应改为“这位中间商”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
