INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10472, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指不含人工化学合成成分的，多指食品、农产品。", "primary_collocate": null, "pronunciation": "yǒu jī", "ipa": "joʊ˨˩˦ tɕi˥", "syllable_count": 2, "sentences": [{"text": "这一过程涉及多重中间商、质量认证体系（如公平贸易、有机认证）以及复杂的物流协调，以确保从产地仓库到目的港的供应链稳定性。", "target_word": "有机", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家店只卖有机蔬菜。", "target_word": "有机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机苹果不用化学肥料。", "target_word": "有机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈喜欢买有机牛奶给孩子喝。", "target_word": "有机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个农场种的米是有机的，不用农药。", "target_word": "有机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机食品比普通食品贵一些。", "target_word": "有机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的农场不用化学肥料，所有菜都是有机的。", "target_word": "有机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里有一个专卖有机食品的区域。", "target_word": "有机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了健康，我们全家改吃有机大米。", "target_word": "有机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机茶没有农药，喝起来很放心。", "target_word": "有机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有机食品", "label": "复合"}, {"form": "有机蔬菜", "label": "复合"}], "register": "中性", "sense_fingerprint": "有机:不含人工化学合成成分的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50c9095a-030e-4bc4-9e56-90be58a29a83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10472, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有机", "is_correct": true, "explanation": "正确答案。有机 yǒujī，指不含人工化学合成成分。"}, {"text": "游击", "is_correct": false, "explanation": "游击 yóujī：第一个音节声调不同（第二声，有机为第三声），意思是游击，不是有机。"}, {"text": "幼鸡", "is_correct": false, "explanation": "幼鸡 yòujī：第一个音节声调不同（第四声，有机为第三声），意思是小鸡。"}, {"text": "优级", "is_correct": false, "explanation": "优级 yōují：两个音节的声调都不同（第一声、第二声），意思是优等级别。"}], "explanations": {"有机": "正确答案。有机 yǒujī，指不含人工化学合成成分。", "游击": "游击 yóujī：第一个音节声调不同（第二声，有机为第三声），意思是游击，不是有机。", "幼鸡": "幼鸡 yòujī：第一个音节声调不同（第四声，有机为第三声），意思是小鸡。", "优级": "优级 yōují：两个音节的声调都不同（第一声、第二声），意思是优等级别。"}, "sentence_index": null, "correct_answer": "有机"}, "level_3": {"options": [{"text": "有机", "is_correct": true, "explanation": "有机：指不含人工化学合成成分，与前文的质量认证体系、公平贸易相符。"}, {"text": "业余", "is_correct": false, "explanation": "语义：“业余”指非专业，认证需要权威机构和统一标准，“业余认证”说不通。"}, {"text": "手工", "is_correct": false, "explanation": "搭配：“手工”说的是人工制作方式，不能作“认证”的限定语。"}, {"text": "有趣", "is_correct": false, "explanation": "语义：“有趣”形容使人感兴趣，与认证的标准化含义不符，无法修饰“认证”。"}], "explanations": {"有机": "有机：指不含人工化学合成成分，与前文的质量认证体系、公平贸易相符。", "业余": "语义：“业余”指非专业，认证需要权威机构和统一标准，“业余认证”说不通。", "手工": "搭配：“手工”说的是人工制作方式，不能作“认证”的限定语。", "有趣": "语义：“有趣”形容使人感兴趣，与认证的标准化含义不符，无法修饰“认证”。"}, "sentence_index": 0, "correct_answer": "有机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山是有机的，没有人工开发的痕迹。", "explanation": "这里应该用〈天然〉。有机用于食品、农产品等，指不含人工化学合成成分，不用来形容一座山。"}, {"text": "这家公司生产有机环保的汽车。", "explanation": "这里应该用〈绿色〉。有机只说食品、农产品未经人工化学合成，汽车这类工业产品不能用有机修饰。"}, {"text": "这把刀是有机的，很锋利。", "explanation": "这里应该用〈金属〉。有机只用于食品、农产品，指未经人工化学合成；刀具是金属制品，不能用有机修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10472, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "有机", "is_correct": true, "explanation": "正确答案。有机 yǒujī，指不含人工化学合成成分。"}, {"text": "游击", "is_correct": false, "explanation": "游击 yóujī：第一个音节声调不同（第二声，有机为第三声），意思是分散流动地作战。"}, {"text": "游记", "is_correct": false, "explanation": "游记 yóujì：两个音节的声调都不同（第二声、第四声），意思是旅行记录。"}, {"text": "邮寄", "is_correct": false, "explanation": "邮寄 yóujì：两个音节的声调都不同（第二声、第四声），意思是通过邮局寄送。"}], "explanations": {"有机": "正确答案。有机 yǒujī，指不含人工化学合成成分。", "游击": "游击 yóujī：第一个音节声调不同（第二声，有机为第三声），意思是分散流动地作战。", "游记": "游记 yóujì：两个音节的声调都不同（第二声、第四声），意思是旅行记录。", "邮寄": "邮寄 yóujì：两个音节的声调都不同（第二声、第四声），意思是通过邮局寄送。"}, "sentence_index": null, "correct_answer": "有机"}, "level_3": {"options": [{"text": "有机", "is_correct": true, "explanation": "有机：不含人工化学合成成分，与“不用化学肥料”相呼应。"}, {"text": "化学", "is_correct": false, "explanation": "语义：“化学的”与前句“不用化学肥料”直接矛盾，句子说菜是化学的，不能成立。"}, {"text": "有毒", "is_correct": false, "explanation": "语义：“有毒的”与“所有菜”的安全之意相反，与前句“不用化学肥料”的说明不相符。"}, {"text": "人造", "is_correct": false, "explanation": "搭配：“人造”多修饰材料、纤维，一般不说人造的菜。"}], "explanations": {"有机": "有机：不含人工化学合成成分，与“不用化学肥料”相呼应。", "化学": "语义：“化学的”与前句“不用化学肥料”直接矛盾，句子说菜是化学的，不能成立。", "有毒": "语义：“有毒的”与“所有菜”的安全之意相反，与前句“不用化学肥料”的说明不相符。", "人造": "搭配：“人造”多修饰材料、纤维，一般不说人造的菜。"}, "sentence_index": 6, "correct_answer": "有机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种塑料袋很有机，可以降解。", "explanation": "这里应该用〈环保〉。有机指未经人工化学合成的农产品、食品，塑料袋不属于这类，不能用有机修饰。"}, {"text": "这块手表是有机的，走得很准。", "explanation": "这里应该用〈名牌〉。有机只用于食品、农产品，指不含人工化学合成成分，手表不能用有机修饰。"}, {"text": "这台电脑是有机的，屏幕很清晰。", "explanation": "这里应该用〈电子〉。有机只用于食品、农产品，电脑属于电子产品，不能用有机修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家买的大米都是有机。", "corrected_sentence": "我们家买的大米都是有机的。", "error_description": "“有机”是非谓形容词，不能直接作谓语，要用“是有机的”，不能说“是有机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些西红柿都是有机。", "corrected_sentence": "这些西红柿都是有机的。", "error_description": "“有机”是非谓形容词，作谓语时要说“是有机的”，缺少“的”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10476, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10476, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10476, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指物品出产或来源的地方。", "primary_collocate": null, "pronunciation": "chǎn dì", "ipa": "ʈʂʰan˨˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这些国家，如拉丁美洲的安第斯山麓地区、东非高原以及东南亚的火山群岛，都是咖啡豆的主要产地，凭借其独特的微气候与海拔条件，培育出具有地域风味特征的咖啡豆品种，其中阿拉比卡与罗布斯塔是最主要的两类。", "target_word": "产地", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这一过程涉及多重中间商、质量认证体系（如公平贸易、有机认证）以及复杂的物流协调，以确保从产地仓库到目的港的供应链稳定性。", "target_word": "产地", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "一方面，大众零售市场依赖规模化生产的速溶咖啡与连锁咖啡店标准化产品；另一方面，精品咖啡运动的兴起推动了“从种子到杯子”的溯源理念，消费者愈发关注产地故事、处理工艺与风味谱系，进而反向影响原产地的种植实践与分级标准。", "target_word": "产地", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种茶叶的产地在云南。", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请看一下包装上写的产地。", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "苹果的产地不同，味道也不一样。", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这批咖啡豆的产地是哥伦比亚。", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买水果时，我喜欢先问产地。", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海关要检查货物的产地证明。", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的海鲜都标着产地。", "target_word": "产地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "產地", "label": "繁体"}, {"form": "原产地", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "产地：物品出产或来源的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 山麓 (Zipf 3.33), 咖啡豆 (Zipf 3.01), 咖啡豆 (Zipf 3.01), 罗布 (Zipf 3.01)']::text[], '50c9095a-030e-4bc4-9e56-90be58a29a83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10476, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产地", "is_correct": true, "explanation": "产地：物品出产的地方，“咖啡豆的主要产地”指这些国家是咖啡豆的出产地，符合句意。"}, {"text": "产量", "is_correct": false, "explanation": "搭配：“产量”说数量高低，不能说国家是“咖啡豆的主要产量”，句中语义不通。"}, {"text": "产业", "is_correct": false, "explanation": "语义：“产业”指行业，不指出产地点，放入句中句意不通。"}, {"text": "展厅", "is_correct": false, "explanation": "语义：展厅是展示物品的场所，不是出产的地方，“咖啡豆的主要展厅”与句意不符。"}], "explanations": {"产地": "产地：物品出产的地方，“咖啡豆的主要产地”指这些国家是咖啡豆的出产地，符合句意。", "产量": "搭配：“产量”说数量高低，不能说国家是“咖啡豆的主要产量”，句中语义不通。", "产业": "语义：“产业”指行业，不指出产地点，放入句中句意不通。", "展厅": "语义：展厅是展示物品的场所，不是出产的地方，“咖啡豆的主要展厅”与句意不符。"}, "sentence_index": 0, "correct_answer": "产地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这笔钱的产地是工资。", "explanation": "这里应该用〈来源〉。产地只指物品出产的地方，钱或收入的来源要说来源，不能说产地。"}, {"text": "这件衣服的产地是棉花。", "explanation": "这里应该用〈原料〉。产地是地方，棉花是原料，不能说产地是棉花。"}, {"text": "我同学的产地是上海。", "explanation": "这里应该用〈老家〉。产地指物品出产的地方，人的出生或来源地要说老家或籍贯，不能说产地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10476, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产地", "is_correct": true, "explanation": "产地：物品出产的地方，哥伦比亚是咖啡豆的出产地，符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”是金额，不能等同于国名哥伦比亚，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”说口感，不说“味道是哥伦比亚”。"}, {"text": "包装", "is_correct": false, "explanation": "语义：“包装”指外层容器，不能是国名哥伦比亚，句意不通。"}], "explanations": {"产地": "产地：物品出产的地方，哥伦比亚是咖啡豆的出产地，符合句意。", "价格": "语义：“价格”是金额，不能等同于国名哥伦比亚，句意不通。", "味道": "搭配：“味道”说口感，不说“味道是哥伦比亚”。", "包装": "语义：“包装”指外层容器，不能是国名哥伦比亚，句意不通。"}, "sentence_index": 6, "correct_answer": "产地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首诗的产地是《诗经》。", "explanation": "这里应该用〈出处〉。产地指物品出产的地方，作品的来源要说出处，不能说产地。"}, {"text": "这本书的产地是鲁迅。", "explanation": "这里应该用〈作者〉。产地只用于物品，人或作品的创作者不能说产地。"}, {"text": "我家的产地在北京。", "explanation": "这里应该用〈地址〉。产地指物品出产的地方，家的所在地要说地址，不能说产地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批苹果有一条著名的产地，在山东。", "corrected_sentence": "这批苹果有一个著名的产地，在山东。", "error_description": "错误在量词：产地是地方，应说「一个产地」或「一处产地」，「条」用于长的东西，不能修饰产地。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批大米的产地到东北，颗粒很饱满。", "corrected_sentence": "这批大米的产地在东北，颗粒很饱满。", "error_description": "错误在介词：表示「产地」所在的位置应用「在」，「到」表示到达的终点，「产地到东北」不通，应说「产地在东北」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
