INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10477, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "储存货物或物品的建筑物或场所。", "primary_collocate": null, "pronunciation": "cāng kù", "ipa": "tsʰɑŋ˥ kʰu˥˩", "syllable_count": 2, "sentences": [{"text": "这一过程涉及多重中间商、质量认证体系（如公平贸易、有机认证）以及复杂的物流协调，以确保从产地仓库到目的港的供应链稳定性。", "target_word": "仓库", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工人把货物搬进了仓库。", "target_word": "仓库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库里堆满了刚到的大米。", "target_word": "仓库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂有三个大仓库。", "target_word": "仓库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板每天去仓库检查货物。", "target_word": "仓库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大，仓库的门关着。", "target_word": "仓库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把旧桌子放在仓库里。", "target_word": "仓库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库离码头很近，运货方便。", "target_word": "仓库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新到的货物先存进仓库。", "target_word": "仓库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "仓库里的货物要按时清点。", "target_word": "仓库", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "倉庫", "label": "繁体"}, {"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "仓库：储存货物的建筑或场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50c9095a-030e-4bc4-9e56-90be58a29a83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10477, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "仓库", "is_correct": true, "explanation": "正确答案：仓库，指储存货物的建筑或场所。"}, {"text": "仓促", "is_correct": false, "explanation": "第二音节 cù 与 kù 声母不同（c 与 k），仓促意为匆忙。"}, {"text": "残酷", "is_correct": false, "explanation": "cán（第二声）与 cāng 韵尾不同（an 与 ang）且声调不同，残酷意为残忍。"}, {"text": "长裤", "is_correct": false, "explanation": "长裤 chángkù：第一个音节声母和声调不同（ch、第二声，仓为 c、第一声），第二音节同为 kù，意思是长的裤子。"}], "explanations": {"仓库": "正确答案：仓库，指储存货物的建筑或场所。", "仓促": "第二音节 cù 与 kù 声母不同（c 与 k），仓促意为匆忙。", "残酷": "cán（第二声）与 cāng 韵尾不同（an 与 ang）且声调不同，残酷意为残忍。", "长裤": "长裤 chángkù：第一个音节声母和声调不同（ch、第二声，仓为 c、第一声），第二音节同为 kù，意思是长的裤子。"}, "sentence_index": null, "correct_answer": "仓库"}, "level_3": {"options": [{"text": "仓库", "is_correct": true, "explanation": "正确：仓库是储存货物的场所，符合从产地到目的港的物流语境。"}, {"text": "客厅", "is_correct": false, "explanation": "语义：客厅是家中待客的房间，不是货物运输的节点，无法放在产地与目的港之间。"}, {"text": "木箱", "is_correct": false, "explanation": "体貌：木箱体积太小，不能作为供应链中大批货物的存放场所。"}, {"text": "办公室", "is_correct": false, "explanation": "语义：办公室是办公用的房间，不是储存货物的场所，与「从产地到目的港」的语境不符。"}], "explanations": {"仓库": "正确：仓库是储存货物的场所，符合从产地到目的港的物流语境。", "客厅": "语义：客厅是家中待客的房间，不是货物运输的节点，无法放在产地与目的港之间。", "木箱": "体貌：木箱体积太小，不能作为供应链中大批货物的存放场所。", "办公室": "语义：办公室是办公用的房间，不是储存货物的场所，与「从产地到目的港」的语境不符。"}, "sentence_index": 0, "correct_answer": "仓库"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上在仓库里刷牙。", "explanation": "这里应该用〈卫生间〉。刷牙要在卫生间，仓库是存放货物的场所。"}, {"text": "妈妈在仓库里做饭。", "explanation": "这里应该用〈厨房〉。做饭要在厨房，仓库是存放货物的场所。"}, {"text": "我周末去仓库里游泳。", "explanation": "这里应该用〈游泳池〉。游泳要去游泳池，仓库是存放货物的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10477, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仓库", "is_correct": true, "explanation": "正确：仓库是可以放置旧桌子的场所。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是可以放桌子的地方，「放在海洋里」不成立。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以放东西的地方，「放在天空里」不成立。"}, {"text": "口袋", "is_correct": false, "explanation": "体貌：旧桌子远大于口袋，放不进去。"}], "explanations": {"仓库": "正确：仓库是可以放置旧桌子的场所。", "海洋": "语义：海洋不是可以放桌子的地方，「放在海洋里」不成立。", "天空": "语义：天空不是可以放东西的地方，「放在天空里」不成立。", "口袋": "体貌：旧桌子远大于口袋，放不进去。"}, "sentence_index": 6, "correct_answer": "仓库"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂里有一张仓库，里面的货物要按时清点。", "explanation": "这里应该用〈座〉或〈个〉。〈张〉用于平面的东西，仓库是建筑，不能用〈张〉来数。"}, {"text": "我们新租了一辆仓库，里面的货物要按时清点。", "explanation": "这里应该用〈座〉或〈个〉。〈辆〉用于车辆，仓库不是车辆，不能用〈辆〉来数。"}, {"text": "他们新建了一本仓库，里面的货物要按时清点。", "explanation": "这里应该用〈座〉或〈个〉。〈本〉用于书籍，仓库是建筑，不能用〈本〉来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10477, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那批大米已经搬进仓库着。", "corrected_sentence": "那批大米已经搬进仓库了。", "error_description": "「搬进仓库」是一次完成的动作，应用「了」表示完成，不能用「着」（着表示持续的状态）。错误形式「搬进仓库着」应改为「搬进仓库了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10477, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只仓库是去年建的。", "corrected_sentence": "那座仓库是去年建的。", "error_description": "量词用错：仓库是建筑，应用量词「座」，不能用「只」（只用于动物或零散的小东西）。错误形式「那只仓库」应改为「那座仓库」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
