INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10478, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "货物运输最终要到达的港口。", "primary_collocate": null, "pronunciation": "mù dì gǎng", "ipa": "mu˥˩ ti˥˩ kɑŋ˨˩", "syllable_count": 3, "sentences": [{"text": "这一过程涉及多重中间商、质量认证体系（如公平贸易、有机认证）以及复杂的物流协调，以确保从产地仓库到目的港的供应链稳定性。", "target_word": "目的港", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这艘船的目的港是上海。", "target_word": "目的港", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "货物到了目的港，还要检查。", "target_word": "目的港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目的港的码头上停着很多船。", "target_word": "目的港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长说，目的港还有两天就到。", "target_word": "目的港", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在单子上写清目的港的名字。", "target_word": "目的港", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为大雾，船晚到了目的港。", "target_word": "目的港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目的港的工人正在卸货。", "target_word": "目的港", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这批货的目的港在新加坡。", "target_word": "目的港", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到目的港以后，公司会通知你。", "target_word": "目的港", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "目的港：货物运输最终到达的港口", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50c9095a-030e-4bc4-9e56-90be58a29a83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10478, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "目的港", "is_correct": true, "explanation": "正确：目的港是货物最终到达的港口，符合从产地到目的港的语境。"}, {"text": "卧室", "is_correct": false, "explanation": "语义：卧室是住人的房间，不是货物运输的终点港口。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是供人游玩的地方，不能作为货物运输的目的港。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的房间，不是货物运输的终点，句意不通。"}], "explanations": {"目的港": "正确：目的港是货物最终到达的港口，符合从产地到目的港的语境。", "卧室": "语义：卧室是住人的房间，不是货物运输的终点港口。", "公园": "语义：公园是供人游玩的地方，不能作为货物运输的目的港。", "教室": "语义：教室是上课的房间，不是货物运输的终点，句意不通。"}, "sentence_index": 0, "correct_answer": "目的港"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "货物在目的港换船。", "explanation": "这里应该用〈中转港〉。换船发生在途中，目的港是货物最终到达的港口，不能在这里换船。"}, {"text": "我的目的港是当一名医生。", "explanation": "这里应该用〈目标〉。目的港是货物最终到达的港口，不能指人生的志向。"}, {"text": "这辆公交车的目的港是火车站。", "explanation": "这里应该用〈终点站〉。公交车的终点是车站，目的港只用于船舶运输。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "目的港", "is_correct": true, "explanation": "正确：船晚到的地方是目的港，符合语境。"}, {"text": "医院", "is_correct": false, "explanation": "语义：船不能开到医院去，「晚到了医院」不成立。"}, {"text": "机场", "is_correct": false, "explanation": "语义：船不能到达机场，「晚到了机场」不合逻辑。"}, {"text": "茶杯", "is_correct": false, "explanation": "体貌：船与茶杯的体积相差悬殊，船不可能「晚到」茶杯。"}], "explanations": {"目的港": "正确：船晚到的地方是目的港，符合语境。", "医院": "语义：船不能开到医院去，「晚到了医院」不成立。", "机场": "语义：船不能到达机场，「晚到了机场」不合逻辑。", "茶杯": "体貌：船与茶杯的体积相差悬殊，船不可能「晚到」茶杯。"}, "sentence_index": 6, "correct_answer": "目的港"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "货物到了一只目的港，公司会通知你。", "explanation": "这里应该用〈个〉。〈只〉用于动物或零散的小东西，港口应用〈个〉。"}, {"text": "货物到了一张目的港，公司会通知你。", "explanation": "这里应该用〈个〉。〈张〉用于平面的东西，港口不是平面物，应用〈个〉。"}, {"text": "货物到了一本目的港，公司会通知你。", "explanation": "这里应该用〈个〉。〈本〉用于书籍，港口不是书，应用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批货已经到着目的港。", "corrected_sentence": "这批货已经到了目的港。", "error_description": "「到达」是一次完成的动作，应用「了」表示完成；「着」表示持续的状态，不能用于此处。错误形式「到着目的港」应改为「到了目的港」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条目的港很繁忙。", "corrected_sentence": "那个目的港很繁忙。", "error_description": "量词用错：目的港应用量词「个」，不能用「条」（条用于细长的东西）。错误形式「那条目的港」应改为「那个目的港」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10479, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10479, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10479, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "事物保持原有状态或性质，不容易改变的特性。", "primary_collocate": null, "pronunciation": "wěn dìng xìng", "ipa": "wən˨˩˦ tiŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这一过程涉及多重中间商、质量认证体系（如公平贸易、有机认证）以及复杂的物流协调，以确保从产地仓库到目的港的供应链稳定性。", "target_word": "稳定性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "气候变化导致适宜种植区收缩，极端天气频发影响产量稳定性；全球航运成本波动、地缘政治紧张以及关税政策调整均可能扰乱贸易流向；同时，小农户在面对市场风险时普遍缺乏金融工具与信息支持。", "target_word": "稳定性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座桥的稳定性很好，大风也不怕。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师正在检查大楼的稳定性。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种材料的稳定性差，容易变形。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们想提高产品质量的稳定性。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "价格的稳定性对小店老板很重要。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个实验需要保持温度的稳定性。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水质的稳定性不够，鱼会生病。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家说，药品的稳定性必须经过长期测试。", "target_word": "稳定性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "穩定性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物状态或性质保持不变的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '578294a7-0823-4619-bc2b-d5210b7acc13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10479, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "搭配：“味道”指气味或滋味，不能用来说供应链。"}, {"text": "稳定性", "is_correct": true, "explanation": "稳定性指供应链保持平稳、不中断的特性，与“确保”以及前文的物流协调相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”说事物的外观，供应链没有颜色，“供应链颜色”不成立。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，与供应链这一物流系统无关。"}], "explanations": {"味道": "搭配：“味道”指气味或滋味，不能用来说供应链。", "稳定性": "稳定性指供应链保持平稳、不中断的特性，与“确保”以及前文的物流协调相符。", "颜色": "搭配：“颜色”说事物的外观，供应链没有颜色，“供应链颜色”不成立。", "脾气": "语义：“脾气”指人的性情，与供应链这一物流系统无关。"}, "sentence_index": 0, "correct_answer": "稳定性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的稳定性很漂亮，是红色的。", "explanation": "这里说的是外观和颜色。稳定性指保持原状、不易改变的特性，不指好不好看；“漂亮”“红色”说的是外观。"}, {"text": "这块玻璃的稳定性很高，每平方米只有两公斤重。", "explanation": "这里说的是重量。稳定性指保持原状、不易改变，不指轻重；“每平方米只有两公斤重”说的是重量。"}, {"text": "这根绳子的稳定性很大，直径只有三厘米。", "explanation": "这里说的是粗细。稳定性指保持原状、不易改变，不指粗细；“直径只有三厘米”说的是粗细。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10479, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "形状", "is_correct": false, "explanation": "语义：“形状”指物体的外形，价格没有形状，与“对小店老板很重要”无关。"}, {"text": "长度", "is_correct": false, "explanation": "搭配：“长度”多用于物体或距离，不能说价格的长度。"}, {"text": "稳定性", "is_correct": true, "explanation": "稳定性指价格保持不剧烈变化的特性，对小店老板来说价格稳定很重要，与句意相符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身体高矮，不能用于价格。"}], "explanations": {"形状": "语义：“形状”指物体的外形，价格没有形状，与“对小店老板很重要”无关。", "长度": "搭配：“长度”多用于物体或距离，不能说价格的长度。", "稳定性": "稳定性指价格保持不剧烈变化的特性，对小店老板来说价格稳定很重要，与句意相符。", "身高": "体貌：“身高”指人的身体高矮，不能用于价格。"}, "sentence_index": 6, "correct_answer": "稳定性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "专家说，这种药的药效很快，半小时就能见效，稳定性很快，必须经过长期测试。", "explanation": "这里应该用〈速度〉。稳定性指保持不变的特性，不指快慢；“很快”说的是速度，不能用来形容稳定性。"}, {"text": "专家说，这种药的稳定性很甜，孩子爱吃。", "explanation": "这里说的是味道。稳定性指保持不变的特性，不指味道；“很甜”说的是口味。"}, {"text": "这家店的稳定性很大，店面只有十平方米。", "explanation": "这里说的是面积。稳定性指保持不变的特性，不指面积大小；“店面只有十平方米”说的是面积。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10479, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台冰箱的稳定性好很，运行时几乎没有声音。", "corrected_sentence": "这台冰箱的稳定性很好，运行时几乎没有声音。", "error_description": "错误：“好很”。“很”是程度副词，应放在形容词前面。正确说法是“稳定性很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10479, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种电池得稳定性很高，充电次数多也不会衰减。", "corrected_sentence": "这种电池的稳定性很高，充电次数多也不会衰减。", "error_description": "错误：“得”。“稳定性”前的定语应用“的”，不能用“得”。正确说法是“这种电池的稳定性很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10482, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10482, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10482, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "abstract", "definition": "指生产过程中需要大量人力劳动，而不是机器或技术。", "primary_collocate": null, "pronunciation": "láo dòng mì jí xíng", "ipa": "lau˧˥ tʊŋ˥˩ mi˥˩ tɕi˧˥ ɕiŋ˧˥", "syllable_count": 5, "sentences": [{"text": "值得注意的是，尽管原产国承担了劳动密集型的种植与初加工任务，其在最终价值链中所获收益比例却长期偏低，形成典型的“初级产品依赖”困境。", "target_word": "劳动密集型", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "服装加工属于劳动密集型产业。", "target_word": "劳动密集型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂属于劳动密集型，需要很多工人。", "target_word": "劳动密集型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "劳动密集型企业主要靠工人，不靠机器。", "target_word": "劳动密集型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "许多国家的早期工业都是劳动密集型。", "target_word": "劳动密集型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "劳动密集型工厂招了几百名工人。", "target_word": "劳动密集型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "随着工资上涨，劳动密集型行业越来越难做。", "target_word": "劳动密集型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "采茶和手工缝制都属于劳动密集型工作。", "target_word": "劳动密集型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器越来越多，劳动密集型行业的工作正在减少。", "target_word": "劳动密集型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "该地区发展劳动密集型产业，增加了就业。", "target_word": "劳动密集型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "劳动密集型产业", "label": "复合"}, {"form": "勞動密集型", "label": "繁体"}], "register": "书面", "sense_fingerprint": "生产主要依靠大量人力而非机器技术的类型", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '578294a7-0823-4619-bc2b-d5210b7acc13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10482, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "金融服务", "is_correct": false, "explanation": "语义：“金融服务”属于服务业，与“种植与初加工”这类农业生产无关，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指气候状况，不能作为“承担……的种植”的对象。"}, {"text": "劳动密集型", "is_correct": true, "explanation": "劳动密集型指生产主要依靠大量人力，与句中“种植与初加工”的人工劳作相符。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”指气味或滋味，不能说“味道的种植”。"}], "explanations": {"金融服务": "语义：“金融服务”属于服务业，与“种植与初加工”这类农业生产无关，句意不通。", "天气": "语义：“天气”指气候状况，不能作为“承担……的种植”的对象。", "劳动密集型": "劳动密集型指生产主要依靠大量人力，与句中“种植与初加工”的人工劳作相符。", "味道": "搭配：“味道”指气味或滋味，不能说“味道的种植”。"}, "sentence_index": 0, "correct_answer": "劳动密集型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "劳动密集型企业主要靠机器，不靠工人。", "explanation": "这里应该用〈资本密集型〉。劳动密集型指主要靠人工，与“靠机器”相矛盾。"}, {"text": "这家芯片厂是劳动密集型，主要依靠先进设备。", "explanation": "这里应该用〈技术密集型〉。依靠先进设备的芯片厂属于技术密集型，劳动密集型指依靠人力。"}, {"text": "这家工厂全部用机器人生产，只有三名工人，是劳动密集型企业。", "explanation": "这里应该用〈技术密集型〉。劳动密集型指主要依靠大量人力，只有三名工人的全自动工厂恰恰相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”说事物的外观，行业没有颜色，“颜色行业”不成立。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，与行业无关，不能放进句中。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身体高矮，不能用于行业。"}, {"text": "劳动密集型", "is_correct": true, "explanation": "劳动密集型行业依赖人工，工资上涨会提高成本，所以越来越难做，与句意相符。"}], "explanations": {"颜色": "搭配：“颜色”说事物的外观，行业没有颜色，“颜色行业”不成立。", "脾气": "语义：“脾气”指人的性情，与行业无关，不能放进句中。", "身高": "体貌：“身高”指人的身体高矮，不能用于行业。", "劳动密集型": "劳动密集型行业依赖人工，工资上涨会提高成本，所以越来越难做，与句意相符。"}, "sentence_index": 6, "correct_answer": "劳动密集型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "该地区发展劳动密集型产业，依靠大量矿产和石油。", "explanation": "这里应该用〈资源密集型〉。劳动密集型主要靠人力，不靠矿产；“依靠大量矿产和石油”说的是资源。"}, {"text": "该地区发展劳动密集型产业，几乎不需要工人。", "explanation": "这里应该用〈技术密集型〉。劳动密集型产业需要大量工人，与“几乎不需要工人”相矛盾。"}, {"text": "该地区发展劳动密集型产业，需要大型机器，投入很大。", "explanation": "这里应该用〈重工业〉。劳动密集型主要靠人工，与“需要大型机器”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种玩具的生产主要靠手工，属于很劳动密集型。", "corrected_sentence": "这种玩具的生产主要靠手工，属于劳动密集型。", "error_description": "错误：“很劳动密集型”。“劳动密集型”是类别名词，不能受“很”修饰，应直接说“属于劳动密集型”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家鞋厂是一只劳动密集型企业，工人手工缝制鞋子。", "corrected_sentence": "这家鞋厂是一家劳动密集型企业，工人手工缝制鞋子。", "error_description": "错误形式“一只”，正确形式“一家”。“只”用于动物或单个物体，企业应用“家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10483, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10483, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10483, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "对原材料进行初步的加工处理，使其成为半成品或可直接使用的初级产品。", "primary_collocate": null, "pronunciation": "chū jiā gōng", "ipa": "ʈʂʰu˥ tɕja˥ kʊŋ˥", "syllable_count": 3, "sentences": [{"text": "值得注意的是，尽管原产国承担了劳动密集型的种植与初加工任务，其在最终价值链中所获收益比例却长期偏低，形成典型的“初级产品依赖”困境。", "target_word": "初加工", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "茶叶采下来后，要先做初加工。", "target_word": "初加工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "咖啡豆的初加工包括去皮和晒干。", "target_word": "初加工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农产品初加工可以让它们保存更久。", "target_word": "初加工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村子有几家做水果初加工的小厂。", "target_word": "初加工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "初加工完成后，原料才能运往大工厂。", "target_word": "初加工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "棉花的初加工是去掉棉籽。", "target_word": "初加工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只做初加工，农民赚的钱比较少。", "target_word": "初加工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "初加工的产品还要经过深加工。", "target_word": "初加工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这批可可豆已经完成了初加工。", "target_word": "初加工", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "初加工产品", "label": "复合"}], "register": "书面", "sense_fingerprint": "对原材料做初步处理，得到半成品或初级产品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '578294a7-0823-4619-bc2b-d5210b7acc13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10483, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "初加工", "is_correct": true, "explanation": "正确。句中说原产国承担种植与初加工任务，初加工是最初步的加工环节。"}, {"text": "高端制造", "is_correct": false, "explanation": "语义：句中强调“初级产品依赖”和收益偏低，高端制造是增值更高的环节，与语境相矛盾。"}, {"text": "研发设计", "is_correct": false, "explanation": "语义：研发设计依靠知识而非劳动投入，与“劳动密集型的种植”相矛盾。"}, {"text": "机械化", "is_correct": false, "explanation": "语义：“机械化”指以机器代替人力，与句中前面的“劳动密集型”相矛盾。"}], "explanations": {"初加工": "正确。句中说原产国承担种植与初加工任务，初加工是最初步的加工环节。", "高端制造": "语义：句中强调“初级产品依赖”和收益偏低，高端制造是增值更高的环节，与语境相矛盾。", "研发设计": "语义：研发设计依靠知识而非劳动投入，与“劳动密集型的种植”相矛盾。", "机械化": "语义：“机械化”指以机器代替人力，与句中前面的“劳动密集型”相矛盾。"}, "sentence_index": 0, "correct_answer": "初加工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "牛奶初加工能做出酸奶和奶酪。", "explanation": "这里应该用〈深加工〉。初加工只是最初步的处理，做出酸奶和奶酪属于深加工。"}, {"text": "这家厂每天初加工两百台电脑。", "explanation": "这里应该用〈生产〉。初加工针对原料做最初步的处理，电脑是整机成品，应该用〈生产〉。"}, {"text": "稻子成熟后，农民就去初加工了。", "explanation": "这里应该用〈收割〉。初加工是对收获后的原料做最初步的处理，稻子成熟后要先收割，“初加工”用在这里是误用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10483, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初加工", "is_correct": true, "explanation": "正确。去掉棉籽是棉花最初步的加工，属于初加工。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植是在田里栽培作物，与“去掉棉籽”这一加工步骤不符。"}, {"text": "运输", "is_correct": false, "explanation": "语义：运输是搬运货物，不是去掉棉籽的加工。"}, {"text": "成品", "is_correct": false, "explanation": "搭配：“成品”是加工完成的产品，不能与“去掉棉籽”这一步骤搭配。"}], "explanations": {"初加工": "正确。去掉棉籽是棉花最初步的加工，属于初加工。", "种植": "语义：种植是在田里栽培作物，与“去掉棉籽”这一加工步骤不符。", "运输": "语义：运输是搬运货物，不是去掉棉籽的加工。", "成品": "搭配：“成品”是加工完成的产品，不能与“去掉棉籽”这一步骤搭配。"}, "sentence_index": 6, "correct_answer": "初加工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批面包已经初加工好了，可以直接装盒。", "explanation": "这里应该用〈烘焙〉。初加工针对原料做最初步的处理，面包要经过烘焙才能做成，应该用〈烘焙〉。"}, {"text": "这块蛋糕已经完成了初加工，正等着点上蜡烛。", "explanation": "这里应该用〈装饰〉。初加工针对原料做最初步的处理，蛋糕是已经做好的食品，给蛋糕做装饰应该用〈装饰〉。"}, {"text": "这种零件经过初加工，尺寸才准确。", "explanation": "这里应该用〈精加工〉。初加工只是最初步的处理，不能保证尺寸精确，尺寸要求高应该用〈精加工〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10483, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些玉米收割后要先经过一把初加工，才能运出去。", "corrected_sentence": "这些玉米收割后要先经过一道初加工，才能运出去。", "error_description": "错误形式“一把初加工”，正确形式“一道初加工”。“把”用于有柄的器具，初加工是一道工序，应用“道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10483, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批咖啡豆在出口前还要做一场初加工。", "corrected_sentence": "这批咖啡豆在出口前还要做一道初加工。", "error_description": "错误形式“一场初加工”，正确形式“一道初加工”。“场”用于比赛、演出等活动，工序应用“道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10485, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10485, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10485, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一系列创造价值的活动，从原材料到最终产品，每个环节都增加价值。", "primary_collocate": null, "pronunciation": "jià zhí liàn", "ipa": "tɕja˥˩ ʈʂɻ̩˧˥ ljɛn˥˩", "syllable_count": 3, "sentences": [{"text": "值得注意的是，尽管原产国承担了劳动密集型的种植与初加工任务，其在最终价值链中所获收益比例却长期偏低，形成典型的“初级产品依赖”困境。", "target_word": "价值链", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司想进入全球价值链。", "target_word": "价值链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价值链的每个环节都能增加价值。", "target_word": "价值链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要提高产品在价值链中的位置。", "target_word": "价值链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计和销售是价值链上最赚钱的两个环节。", "target_word": "价值链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家正在向价值链的高端走。", "target_word": "价值链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从种植到卖出，整条价值链都要管好。", "target_word": "价值链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司分析了价值链，发现包装环节成本太高。", "target_word": "价值链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小工厂常常处在价值链的最下面。", "target_word": "价值链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究汽车产业的价值链已经十年了。", "target_word": "价值链", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全球价值链", "label": "复合"}, {"form": "产业价值链", "label": "复合"}], "register": "书面", "sense_fingerprint": "经济学术语，从原材料到成品各环节逐步增值的一系列活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '578294a7-0823-4619-bc2b-d5210b7acc13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10485, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价值链", "is_correct": true, "explanation": "正确。句中说在最终价值链中获得收益比例，价值链指从原料到最终产品的一系列增值环节。"}, {"text": "教育体系", "is_correct": false, "explanation": "语义：教育体系不是产品从原料到成品的增值环节，与句中的收益比例语境不符。"}, {"text": "食品安全", "is_correct": false, "explanation": "搭配：“最终食品安全中”不成立，食品安全不能作为获取收益的环节。"}, {"text": "文化遗产", "is_correct": false, "explanation": "语义：文化遗产不是增值的生产环节，无法从中获得收益比例。"}], "explanations": {"价值链": "正确。句中说在最终价值链中获得收益比例，价值链指从原料到最终产品的一系列增值环节。", "教育体系": "语义：教育体系不是产品从原料到成品的增值环节，与句中的收益比例语境不符。", "食品安全": "搭配：“最终食品安全中”不成立，食品安全不能作为获取收益的环节。", "文化遗产": "语义：文化遗产不是增值的生产环节，无法从中获得收益比例。"}, "sentence_index": 0, "correct_answer": "价值链"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "自行车的价值链断了，骑不了了。", "explanation": "这里应该用〈链条〉。价值链指产品从原料到成品的一系列增值环节，自行车上断掉的是机械零件，应该用〈链条〉。"}, {"text": "这批货的价值链下降了三成。", "explanation": "这里应该用〈价格〉。价值链是一系列环节，不能像价格那样说“下降了三成”。"}, {"text": "他是一条价值链。", "explanation": "这里应该用〈人才〉。价值链是经济学术语，指产品增值的一系列环节，不能用来指人；形容一个人有价值，应该用〈人才〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10485, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价值链", "is_correct": true, "explanation": "正确。“从种植到卖出”正是一条完整的价值链，句中要求整条都管好。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“从种植到卖出”讲的是产品流转，河流不能指这一流程。"}, {"text": "铁路", "is_correct": false, "explanation": "语义：铁路是交通设施，不是从种植到卖出的增值流程。"}, {"text": "马路", "is_correct": false, "explanation": "语义：马路是供车辆行人通行的道路，不是从种植到卖出的增值流程。"}], "explanations": {"价值链": "正确。“从种植到卖出”正是一条完整的价值链，句中要求整条都管好。", "河流": "语义：“从种植到卖出”讲的是产品流转，河流不能指这一流程。", "铁路": "语义：铁路是交通设施，不是从种植到卖出的增值流程。", "马路": "语义：马路是供车辆行人通行的道路，不是从种植到卖出的增值流程。"}, "sentence_index": 6, "correct_answer": "价值链"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市是价值链的，市民很多。", "explanation": "这里应该用〈工业城市〉。价值链是产品增值环节的经济学术语，不用来形容城市；说明一个城市的产业特点，应该用〈工业城市〉。"}, {"text": "工厂新装了一条价值链，效率提高了。", "explanation": "这里应该用〈生产线〉。价值链是一系列增值环节，不是可以安装的实体设备，安装设备应该用〈生产线〉。"}, {"text": "这场比赛是价值链的，选手都很努力。", "explanation": "这里应该用〈激烈〉。价值链是描述产品增值环节的经济学术语，不能用来形容比赛；形容比赛竞争性强，应该用〈激烈〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10485, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们正在梳理一把价值链。", "corrected_sentence": "我们正在梳理一条价值链。", "error_description": "错误形式“一把价值链”，正确形式“一条价值链”。“把”用于有柄的器具，价值链是链状的一系列环节，应用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10485, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家企业重新设计了一根价值链，覆盖了三个国家。", "corrected_sentence": "这家企业重新设计了一条价值链，覆盖了三个国家。", "error_description": "错误形式“一根价值链”，正确形式“一条价值链”。“根”多用于细长的物体，价值链应用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
