INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10486, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "得到，取得。", "primary_collocate": null, "pronunciation": "huò", "ipa": "xwo˥˩", "syllable_count": 1, "sentences": [{"text": "他在比赛中获冠军。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位年轻选手在游泳比赛中获金牌。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李的书获一等奖。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的合唱团获第一名。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的新电影获好评。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划已获批准。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师的想法获大家支持。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国队在比赛中获全胜。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在画画比赛中获二等奖。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家今年获大奖。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "獲", "label": "繁体"}], "register": "书面", "sense_fingerprint": "书面语，后接奖项、名次、评价等，表示得到、取得", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '578294a7-0823-4619-bc2b-d5210b7acc13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10486, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "获", "is_correct": true, "explanation": "获（huò）即得到、取得，是本词的读音和意思。"}, {"text": "火", "is_correct": false, "explanation": "huǒ（第三声）与 huò（第四声）声调不同，意思是火。"}, {"text": "活", "is_correct": false, "explanation": "huó（第二声）与 huò（第四声）声调不同，意思是活。"}, {"text": "户", "is_correct": false, "explanation": "hù（第四声）与 huò 韵母不同（u 与 uo），意思是户。"}], "explanations": {"获": "获（huò）即得到、取得，是本词的读音和意思。", "火": "huǒ（第三声）与 huò（第四声）声调不同，意思是火。", "活": "huó（第二声）与 huò（第四声）声调不同，意思是活。", "户": "hù（第四声）与 huò 韵母不同（u 与 uo），意思是户。"}, "sentence_index": null, "correct_answer": "获"}, "level_3": {"options": [{"text": "获", "is_correct": true, "explanation": "获：得到，与“冠军”搭配，符合比赛获胜的语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃冠军。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣物，不能说穿冠军。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指用火加热，冠军不能被烧，句子不通。"}], "explanations": {"获": "获：得到，与“冠军”搭配，符合比赛获胜的语境。", "吃": "搭配：“吃”的对象是食物，不能说吃冠军。", "穿": "搭配：“穿”的对象是衣物，不能说穿冠军。", "烧": "语义：“烧”指用火加热，冠军不能被烧，句子不通。"}, "sentence_index": 0, "correct_answer": "获"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从书包里获出了作业本。", "explanation": "这里应该用〈拿〉。获指得到奖项、名次、评价，从书包里取东西要用“拿”。"}, {"text": "他跑完步获了一身汗。", "explanation": "这里应该用〈出〉。获指得到奖项、名次、评价，出汗要用“出”。"}, {"text": "他昨天获了一场大雨，很高兴。", "explanation": "这里应该用〈下〉。获指得到奖项、名次、评价，下雨要用“下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10486, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "获", "is_correct": true, "explanation": "获（huò）即得到、取得，是本词的读音和意思。"}, {"text": "会", "is_correct": false, "explanation": "huì（第四声）与 huò 韵母不同（ui 与 uo），意思是会。"}, {"text": "化", "is_correct": false, "explanation": "huà（第四声）与 huò 韵母不同（a 与 uo），意思是化。"}, {"text": "过", "is_correct": false, "explanation": "guò（第四声）与 huò 声母不同（g 与 h），其余相同，意思是经过。"}], "explanations": {"获": "获（huò）即得到、取得，是本词的读音和意思。", "会": "huì（第四声）与 huò 韵母不同（ui 与 uo），意思是会。", "化": "huà（第四声）与 huò 韵母不同（a 与 uo），意思是化。", "过": "guò（第四声）与 huò 声母不同（g 与 h），其余相同，意思是经过。"}, "sentence_index": null, "correct_answer": "获"}, "level_3": {"options": [{"text": "获", "is_correct": true, "explanation": "获：得到，与“支持”搭配，表示得到大家的支持，符合语境。"}, {"text": "挡", "is_correct": false, "explanation": "语义：“挡”是阻拦，与“支持”意思相反，句意不通。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的对象是球等，不能说踢支持。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洗，支持不能被洗，句子不通。"}], "explanations": {"获": "获：得到，与“支持”搭配，表示得到大家的支持，符合语境。", "挡": "语义：“挡”是阻拦，与“支持”意思相反，句意不通。", "踢": "搭配：“踢”的对象是球等，不能说踢支持。", "洗": "语义：“洗”指清洗，支持不能被洗，句子不通。"}, "sentence_index": 6, "correct_answer": "获"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天在超市获了一个喷嚏。", "explanation": "这里应该用〈打〉。获指得到奖项、名次、评价，打喷嚏要用“打”。"}, {"text": "我在路上获了一位老朋友。", "explanation": "这里应该用〈遇到〉。获不用于偶然碰见人，在路上碰到老朋友要用“遇到”。"}, {"text": "图书馆的书我获了三本，还没还。", "explanation": "这里应该用〈借〉。获指得到奖项、评价等，从图书馆拿书回家要用“借”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在比赛中获到了冠军。", "corrected_sentence": "他在比赛中获得了冠军。", "error_description": "词形错误：“获”后应接“得”组成“获得”，写成“获到”不对，正确形式是“获得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份申请已被获老师的同意。", "corrected_sentence": "这份申请已获老师的同意。", "error_description": "多余成分：“获”本身就表示得到，前面不能再加“被”，“被获”不对，正确说法是“已获老师的同意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10487, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亏损", "is_correct": true, "explanation": "反义：“收益”指获得的利润，“亏损”指经营或投资中的损失，二者意思相反。"}, {"text": "存款", "is_correct": false, "explanation": "无关：“存款”是存放在银行里的钱，并不与“收益”构成反义关系。"}, {"text": "桌子", "is_correct": false, "explanation": "无关：“桌子”是家具，与“收益”的任何义项都没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”是自然事物，与“收益”的任何义项都没有反义关系。"}], "correct_answer": "亏损", "explanations": {"亏损": "反义：“收益”指获得的利润，“亏损”指经营或投资中的损失，二者意思相反。", "存款": "无关：“存款”是存放在银行里的钱，并不与“收益”构成反义关系。", "桌子": "无关：“桌子”是家具，与“收益”的任何义项都没有反义关系。", "河流": "无关：“河流”是自然事物，与“收益”的任何义项都没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10487, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亏损", "is_correct": true, "explanation": "反义：句中说“没有收益”，即没有利润，与之相反的是“亏损”。"}, {"text": "钥匙", "is_correct": false, "explanation": "无关：“钥匙”是开锁的工具，与“收益”没有反义关系。"}, {"text": "大海", "is_correct": false, "explanation": "无关：“大海”是自然景观，与“收益”没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "无关：“窗户”是建筑部件，与“收益”没有反义关系。"}], "correct_answer": "亏损", "explanations": {"亏损": "反义：句中说“没有收益”，即没有利润，与之相反的是“亏损”。", "钥匙": "无关：“钥匙”是开锁的工具，与“收益”没有反义关系。", "大海": "无关：“大海”是自然景观，与“收益”没有反义关系。", "窗户": "无关：“窗户”是建筑部件，与“收益”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10487, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指获得的利润、利益或好处。", "primary_collocate": null, "pronunciation": "shōu yì", "ipa": "ʂoʊ⁵⁵ i⁵¹", "syllable_count": 2, "sentences": [{"text": "这种公私协作的创新融资模式，催生了新型金融工具，将碳汇增量、能源节约与居民健康改善等外部性效益证券化，并以债券形式向投资者分配收益，开辟了可持续投资的量化回报路径。", "target_word": "收益", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这笔投资的收益很高。", "target_word": "收益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买股票有收益，也有风险。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱存进银行，每年有一点收益。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司今年的收益比去年多了。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的年收益是一百万元。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收益越高，风险往往越大。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期投资的收益更稳定。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民种茶叶，收益比种粮食高。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目没有收益，公司不想做。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "投资收益", "label": "复合"}, {"form": "收益率", "label": "复合"}], "register": "书面语", "sense_fingerprint": "投资或经营所得的利润、回报", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45fe73ad-99b7-41e9-9b37-32d47e8af85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10487, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "收益", "is_correct": true, "explanation": "正确：环境方面的金融工具以投资回报为核心，“收益”正好符合语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能作为分配给投资者的对象，与“债券”的金融语境冲突。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语、随意的说法，不适合“债券”这类书面金融术语。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能分配给投资者，与金融语境冲突。"}], "explanations": {"收益": "正确：环境方面的金融工具以投资回报为核心，“收益”正好符合语境。", "颜色": "语义：颜色不能作为分配给投资者的对象，与“债券”的金融语境冲突。", "玩意儿": "语域：“玩意儿”是口语、随意的说法，不适合“债券”这类书面金融术语。", "天气": "语义：天气是自然现象，不能分配给投资者，与金融语境冲突。"}, "sentence_index": 0, "correct_answer": "收益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他为了这次比赛，付出了很多收益。", "explanation": "这里应该用〈努力〉。收益指得到的利润或好处，不能说“付出”；付出的应是努力、时间等成本。"}, {"text": "他去年赚了一颗收益。", "explanation": "这里应该用〈笔〉。收益的计量用“笔”，“颗”多用于粒状的小东西。"}, {"text": "这件衣服的收益很便宜。", "explanation": "这里应该用〈价格〉。收益指获得的利润或好处，不能用“便宜”来形容；衣服的价钱应说〈价格〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10487, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收益", "is_correct": true, "explanation": "正确：“收益越高，风险往往越大”指投资回报与风险的关系，“收益”正好符合语境。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是场所，不能说“越高”，与“收益越高，风险越大”的意义不符。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格不能用“高低”来衡量，也不是经济指标，“性格越高，风险往往越大”说不通。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不是可以衡量高低的经济指标，与风险的语境冲突。"}], "explanations": {"收益": "正确：“收益越高，风险往往越大”指投资回报与风险的关系，“收益”正好符合语境。", "教室": "语义：教室是场所，不能说“越高”，与“收益越高，风险越大”的意义不符。", "性格": "语义：性格不能用“高低”来衡量，也不是经济指标，“性格越高，风险往往越大”说不通。", "玩具": "语义：玩具不是可以衡量高低的经济指标，与风险的语境冲突。"}, "sentence_index": 6, "correct_answer": "收益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这次志愿服务的收益寄给了远方的朋友。", "explanation": "这里应该用〈礼物〉。收益指利润或好处，是抽象的，不是可以寄出去的实物。"}, {"text": "这次事故让公司遭受了巨大的收益。", "explanation": "这里应该用〈损失〉。“遭受”搭配不好的结果，收益是好的结果，不能与“遭受”搭配。"}, {"text": "这次比赛点燃了他的收益。", "explanation": "这里应该用〈热情〉。收益不能被“点燃”，被点燃的应是热情、斗志等情绪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10487, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔投资带来了一只收益。", "corrected_sentence": "这笔投资带来了一笔收益。", "error_description": "量词错误：“只”不能用于“收益”，应用“笔”，正确说法是“一笔收益”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10487, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个基金的收益的很稳定。", "corrected_sentence": "这个基金的收益很稳定。", "error_description": "“收益”后多出一个“的”，应去掉，正确说法是“这个基金的收益很稳定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
