INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10488, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个数量之间的关系，比如一个数是另一个数的几倍或几分之几。", "primary_collocate": null, "pronunciation": "bǐ lì", "ipa": "pi˨˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这个班男生和女生的比例是一比一。", "target_word": "比例", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的工资和奖金比例不太合理。", "target_word": "比例", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做蛋糕时，糖和面粉的比例很重要。", "target_word": "比例", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张地图的比例是一比一百万。", "target_word": "比例", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在城市里老人的比例越来越高了。", "target_word": "比例", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请按比例把这张照片放大。", "target_word": "比例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画中人物的身体比例看起来很自然。", "target_word": "比例", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在我们公司，女员工的比例是三成。", "target_word": "比例", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水和盐的比例不对，汤太咸了。", "target_word": "比例", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子里窗户占墙的比例太小，所以很暗。", "target_word": "比例", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "比例尺", "label": "复合"}], "register": "中性", "sense_fingerprint": "数量之间的比值或所占的份额", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7cbd58c-699e-471e-90b4-643ce1bb9923') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10488, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比例", "is_correct": true, "explanation": "正确：“比例”指两个数量之间的比，这里是男生与女生人数之比为一比一。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：“成绩”指考试或学习的结果，不能表示男女人数之间的比值。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”是具体的数值，不能与“一比一”这样的比值搭配。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人的岁数，句中说的是两类人的数量关系，不能用它。"}], "explanations": {"比例": "正确：“比例”指两个数量之间的比，这里是男生与女生人数之比为一比一。", "成绩": "语义：“成绩”指考试或学习的结果，不能表示男女人数之间的比值。", "身高": "搭配：“身高”是具体的数值，不能与“一比一”这样的比值搭配。", "年龄": "语义：“年龄”指人的岁数，句中说的是两类人的数量关系，不能用它。"}, "sentence_index": 0, "correct_answer": "比例"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班男生的比例是二十人。", "explanation": "这里应该用〈人数〉。“比例”表示两个数量之间的比，不能直接表示具体的人数。"}, {"text": "这个苹果的比例是三块钱。", "explanation": "这里应该用〈价格〉。“比例”表示比值，不能用来表示金额。"}, {"text": "他的比例是六十岁，已经退休了。", "explanation": "这里应该用〈年龄〉。“比例”表示两个数量之间的比，不能直接表示一个人的岁数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10488, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比例", "is_correct": true, "explanation": "正确：“比例”指两个数量之间的关系，这里指人物身体各部分大小之间的比例。"}, {"text": "速度", "is_correct": false, "explanation": "语义：“速度”指运动的快慢，画中人物是静止的，不能说它的速度看起来自然。"}, {"text": "音量", "is_correct": false, "explanation": "语义：“音量”指声音的大小，画作没有声音，句子说的是外形。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“看起来”只能用于可以看见的外形，“温度”看不出来，不能与之搭配。"}], "explanations": {"比例": "正确：“比例”指两个数量之间的关系，这里指人物身体各部分大小之间的比例。", "速度": "语义：“速度”指运动的快慢，画中人物是静止的，不能说它的速度看起来自然。", "音量": "语义：“音量”指声音的大小，画作没有声音，句子说的是外形。", "温度": "搭配：“看起来”只能用于可以看见的外形，“温度”看不出来，不能与之搭配。"}, "sentence_index": 6, "correct_answer": "比例"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路的比例是三公里。", "explanation": "这里应该用〈距离〉。“比例”表示比值，不能直接表示路程的长短。"}, {"text": "他跑步的比例是每分钟二百米。", "explanation": "这里应该用〈速度〉。“比例”表示比值，不能直接表示每分钟跑多远。"}, {"text": "这座楼的比例是五十米。", "explanation": "这里应该用〈高度〉。“比例”表示比值，不能用来表示楼的高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个模型的尺寸与真实物体比例。", "corrected_sentence": "这个模型的尺寸与真实物体成比例。", "error_description": "错误：“与真实物体比例”，缺少动词“成”。正确：“与真实物体成比例”。“成比例”是固定说法，“比例”前必须有动词“成”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请比例把这幅画缩小。", "corrected_sentence": "请按比例把这幅画缩小。", "error_description": "错误：缺少介词“按”，写成“请比例把”。正确：“请按比例把”。“按比例”作状语，表示依照比例，前面要用“按”引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10490, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "偏高", "is_correct": true, "explanation": "正确：“偏高”与“偏低”构成反义，指比平均水平或标准高。"}, {"text": "热闹", "is_correct": false, "explanation": "与“偏低”没有反义关系，“热闹”指人多、声音大。"}, {"text": "清楚", "is_correct": false, "explanation": "与“偏低”没有反义关系，“清楚”指看得或听得明白。"}, {"text": "认真", "is_correct": false, "explanation": "与“偏低”没有反义关系，“认真”指做事专心、不马虎。"}], "correct_answer": "偏高", "explanations": {"偏高": "正确：“偏高”与“偏低”构成反义，指比平均水平或标准高。", "热闹": "与“偏低”没有反义关系，“热闹”指人多、声音大。", "清楚": "与“偏低”没有反义关系，“清楚”指看得或听得明白。", "认真": "与“偏低”没有反义关系，“认真”指做事专心、不马虎。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10490, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "偏高", "is_correct": true, "explanation": "正确：“偏高”与“偏低”构成反义，指比平均水平或标准高。"}, {"text": "复杂", "is_correct": false, "explanation": "与“偏低”没有反义关系，“复杂”指事物头绪多、不简单。"}, {"text": "聪明", "is_correct": false, "explanation": "与“偏低”没有反义关系，“聪明”指人的智力高。"}, {"text": "干净", "is_correct": false, "explanation": "与“偏低”没有反义关系，“干净”指没有污垢。"}], "correct_answer": "偏高", "explanations": {"偏高": "正确：“偏高”与“偏低”构成反义，指比平均水平或标准高。", "复杂": "与“偏低”没有反义关系，“复杂”指事物头绪多、不简单。", "聪明": "与“偏低”没有反义关系，“聪明”指人的智力高。", "干净": "与“偏低”没有反义关系，“干净”指没有污垢。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10490, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思是比平均水平或标准低一些。", "primary_collocate": null, "pronunciation": "piān dī", "ipa": "pʰjɛn˥ ti˥", "syllable_count": 2, "sentences": [{"text": "值得注意的是，尽管原产国承担了劳动密集型的种植与初加工任务，其在最终价值链中所获收益比例却长期偏低，形成典型的“初级产品依赖”困境。", "target_word": "偏低", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今年的苹果价格偏低。", "target_word": "偏低", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的体温偏低，要多休息。", "target_word": "偏低", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天的气温偏低，出门要多穿衣服。", "target_word": "偏低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说我的血压有点儿偏低。", "target_word": "偏低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月的用电量偏低，因为天气不热。", "target_word": "偏低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班的考试成绩偏低，老师不高兴。", "target_word": "偏低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的工资水平偏低，很多人去外地工作。", "target_word": "偏低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水温偏低，茶叶泡不开。", "target_word": "偏低", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个地区的人口数量偏低，商店也不多。", "target_word": "偏低", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "价格、温度、水平等比标准略低", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7cbd58c-699e-471e-90b4-643ce1bb9923') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10490, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偏低", "is_correct": true, "explanation": "正确：“偏低”指低于正常水平，与后文“依赖困境”的因果一致。"}, {"text": "偏高", "is_correct": false, "explanation": "语义：收益比例偏高与“形成依赖困境”相矛盾，句中要表达的是比例过低。"}, {"text": "偏快", "is_correct": false, "explanation": "搭配：“快”说速度，不能用来形容收益比例。"}, {"text": "偏热", "is_correct": false, "explanation": "搭配：“热”说温度，不能用来形容收益比例。"}], "explanations": {"偏低": "正确：“偏低”指低于正常水平，与后文“依赖困境”的因果一致。", "偏高": "语义：收益比例偏高与“形成依赖困境”相矛盾，句中要表达的是比例过低。", "偏快": "搭配：“快”说速度，不能用来形容收益比例。", "偏热": "搭配：“热”说温度，不能用来形容收益比例。"}, "sentence_index": 0, "correct_answer": "偏低"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的爱好偏低，喜欢看书。", "explanation": "这里不能用“偏低”。“偏低”用于数量、价格、水平等，不用于形容爱好或兴趣。"}, {"text": "这所学校到车站的距离偏低，走路只要十分钟。", "explanation": "这里应该用〈偏短〉。“偏低”用于数量、价格、水平等，不用于距离的长短。"}, {"text": "这座桥的宽度偏低，两辆车不能同时通过。", "explanation": "这里应该用〈偏窄〉。“偏低”不用于宽度，宽度只说宽或窄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偏低", "is_correct": true, "explanation": "正确：成绩低于标准，才会让老师不高兴。"}, {"text": "偏瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人的体形，不能用体形词来形容考试成绩。"}, {"text": "偏轻", "is_correct": false, "explanation": "搭配：“轻”说分量或程度，不用来形容考试成绩。"}, {"text": "偏硬", "is_correct": false, "explanation": "语义：“硬”形容物体的质地，不能用来形容考试成绩。"}], "explanations": {"偏低": "正确：成绩低于标准，才会让老师不高兴。", "偏瘦": "体貌：“瘦”形容人的体形，不能用体形词来形容考试成绩。", "偏轻": "搭配：“轻”说分量或程度，不用来形容考试成绩。", "偏硬": "语义：“硬”形容物体的质地，不能用来形容考试成绩。"}, "sentence_index": 6, "correct_answer": "偏低"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间的面积偏低，放不下一张床。", "explanation": "这里应该用〈偏小〉。面积只说大或小，“偏低”不用于面积。"}, {"text": "这次旅行的时间偏低，一共有两个星期。", "explanation": "这里应该用〈偏长〉。“偏低”不用于时间的长短。"}, {"text": "这个箱子的体积偏低，能装下两件大衣。", "explanation": "这里应该用〈偏大〉。体积只说大或小，“偏低”不用于体积。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年的鸡蛋价格偏低过，大家都很高兴。", "corrected_sentence": "今年的鸡蛋价格偏低，大家都很高兴。", "error_description": "错误：“偏低过”。正确：“偏低”。形容词不能直接加“过”，“过”只用于动词后表示经历。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家超市的蔬菜价格被偏低，很受欢迎。", "corrected_sentence": "这家超市的蔬菜价格偏低，很受欢迎。", "error_description": "错误：“被偏低”。正确：“偏低”。“被”字句需要动词，“偏低”是形容词，不能用“被”构成被动句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
