INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10491, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "具有代表性或象征性的人或事物。", "primary_collocate": null, "pronunciation": "diǎn xíng", "ipa": "tjɛn˨˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他是我们班学习上的好典型。", "target_word": "典型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请大家向这个典型学习。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里把种树最多的人当作典型。", "target_word": "典型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上介绍了一个助人为乐的典型。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事里的小王是勤劳的典型。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校每年都会树立学习典型。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想当典型，只想安静地工作。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人是中国农民的一个典型。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都想了解这个先进典型的故事。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小村子成了新农村建设的典型。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "典型性", "label": "复合"}], "register": "中性", "sense_fingerprint": "被树立或介绍的有代表性的人或事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7cbd58c-699e-471e-90b4-643ce1bb9923') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10491, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "典型", "is_correct": true, "explanation": "正确：“典型”指作为榜样的人，这里指学习上的好榜样。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是书本，不指可以作为榜样的人。"}, {"text": "名人", "is_correct": false, "explanation": "搭配：“名人”指有名气的人，不说“学习上的好名人”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”指练习任务，不能用来指人。"}], "explanations": {"典型": "正确：“典型”指作为榜样的人，这里指学习上的好榜样。", "课本": "语义：“课本”是书本，不指可以作为榜样的人。", "名人": "搭配：“名人”指有名气的人，不说“学习上的好名人”。", "作业": "语义：“作业”指练习任务，不能用来指人。"}, "sentence_index": 0, "correct_answer": "典型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的典型是十平方米。", "explanation": "这里应该用〈面积〉。“典型”指有代表性的人或事，不能用来表示面积。"}, {"text": "这块面包的典型是三块钱。", "explanation": "这里应该用〈价格〉。“典型”指有代表性的人或事，不能用来表示价钱。"}, {"text": "他的典型是六十公斤，看起来很结实。", "explanation": "这里应该用〈体重〉。“典型”指有代表性的人或事，不能直接用来表示体重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10491, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "典型", "is_correct": true, "explanation": "正确：“当典型”指被树立为代表或榜样，符合句中“不想当”的语境。"}, {"text": "厨房", "is_correct": false, "explanation": "配价：“当”后接的是角色或身份，“厨房”是处所，不能充当。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是无生命的物体，不能理解为要去工作的角色。"}, {"text": "春天", "is_correct": false, "explanation": "语义：“春天”是季节，不能指人，句中“当春天”说不通。"}], "explanations": {"典型": "正确：“当典型”指被树立为代表或榜样，符合句中“不想当”的语境。", "厨房": "配价：“当”后接的是角色或身份，“厨房”是处所，不能充当。", "石头": "语义：“石头”是无生命的物体，不能理解为要去工作的角色。", "春天": "语义：“春天”是季节，不能指人，句中“当春天”说不通。"}, "sentence_index": 6, "correct_answer": "典型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次活动的典型是两个小时。", "explanation": "这里应该用〈时长〉。“典型”指有代表性的人或事，不能用来表示时间的长短。"}, {"text": "他的典型是司机，每天都很忙。", "explanation": "这里应该用〈职业〉。“典型”指有代表性的人或事，不指职业或身份。"}, {"text": "这台电脑的典型很好，运行很快。", "explanation": "这里应该用〈性能〉。“典型”指有代表性的人或事，不能用来形容电脑的质量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10491, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所中学树立了一本学习典型。", "corrected_sentence": "这所中学树立了一个学习典型。", "error_description": "错误：“一本学习典型”。正确：“一个学习典型”。“本”用于书籍，“典型”指人或事，应用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10491, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老人被选为全省的一条学习典型。", "corrected_sentence": "这位老人被选为全省的一个学习典型。", "error_description": "错误：“一条学习典型”。正确：“一个学习典型”。“条”用于细长的东西，“典型”指人或事，应用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10492, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10492, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10492, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指未经加工或只经过初步加工，作为生产其他产品的原料或基础的产品。", "primary_collocate": null, "pronunciation": "chū jí chǎn pǐn", "ipa": "ʈʂʰu˥ tɕi˧˥ ʈʂʰan˨˩˦ pʰin˨˩˦", "syllable_count": 4, "sentences": [{"text": "值得注意的是，尽管原产国承担了劳动密集型的种植与初加工任务，其在最终价值链中所获收益比例却长期偏低，形成典型的“初级产品依赖”困境。", "target_word": "初级产品", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "咖啡豆、棉花和铁矿石都是初级产品。", "target_word": "初级产品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家主要出口石油等初级产品。", "target_word": "初级产品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "初级产品只经过简单加工，所以价格不太高。", "target_word": "初级产品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂买来初级产品，加工成各种商品。", "target_word": "初级产品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只卖初级产品的国家，收入常常不高。", "target_word": "初级产品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小麦和大米是农业的初级产品。", "target_word": "初级产品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在公司负责买卖初级产品，比如矿石和棉花。", "target_word": "初级产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与初级产品相比，加工后的商品更值钱。", "target_word": "初级产品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世界上很多国家靠出口初级产品发展经济。", "target_word": "初级产品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "初級產品", "label": "繁体"}], "register": "书面", "sense_fingerprint": "经济学用语：未加工或只初步加工、供生产其他产品用的原料类产品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7cbd58c-699e-471e-90b4-643ce1bb9923') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10492, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "初级产品", "is_correct": true, "explanation": "正确。“初级产品”是未加工或只初步加工的原料类产品，放在“___依赖”处，句意通顺。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是演奏用的器具，不是经济上的原料类产品，“乐器依赖”不成立，句意不通。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是季节，与产品和经济依赖无关，句意不通。"}, {"text": "诗歌", "is_correct": false, "explanation": "搭配：“依赖”一般搭配物质、药物、网络等对象，“诗歌依赖”不成词，不能放在这里。"}], "explanations": {"初级产品": "正确。“初级产品”是未加工或只初步加工的原料类产品，放在“___依赖”处，句意通顺。", "乐器": "语义：乐器是演奏用的器具，不是经济上的原料类产品，“乐器依赖”不成立，句意不通。", "春天": "语义：春天是季节，与产品和经济依赖无关，句意不通。", "诗歌": "搭配：“依赖”一般搭配物质、药物、网络等对象，“诗歌依赖”不成词，不能放在这里。"}, "sentence_index": 0, "correct_answer": "初级产品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店卖的初级产品都是现成的，可以直接吃。", "explanation": "这里应该用〈熟食〉。“初级产品”指未加工或只初步加工的原料，不能指可以直接吃的熟食。"}, {"text": "工厂买来半成品，加工成初级产品卖出去。", "explanation": "这里应该用〈成品〉。初级产品指未加工或只初步加工的产品，不能指加工后的成品。"}, {"text": "他是一个初级产品。", "explanation": "这里指的是人。“初级产品”只指未加工的物品，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初级产品", "is_correct": true, "explanation": "正确。“初级产品”指农业等领域未加工的原料类产品，放在“农业的___”处，句意通顺。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格指买卖时的钱数，小麦和大米不是农业的价格，句意不通。"}, {"text": "剧本", "is_correct": false, "explanation": "语义：剧本是戏剧的文字底本，与农作物无关，句意不通。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“寿命”指生物或物品存在的年限，“农业的寿命”不能这样搭配。"}], "explanations": {"初级产品": "正确。“初级产品”指农业等领域未加工的原料类产品，放在“农业的___”处，句意通顺。", "价格": "语义：价格指买卖时的钱数，小麦和大米不是农业的价格，句意不通。", "剧本": "语义：剧本是戏剧的文字底本，与农作物无关，句意不通。", "寿命": "搭配：“寿命”指生物或物品存在的年限，“农业的寿命”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "初级产品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌是初级产品，唱起来很好听。", "explanation": "这里应该用〈作品〉。“初级产品”指未加工或只初步加工的原料类物品，不能指歌曲等艺术作品。"}, {"text": "这家公司的股票是初级产品，可以在交易所买卖。", "explanation": "这里应该用〈证券〉。股票属于金融资产，不属于初级产品，初级产品指未加工或初步加工的原料类物品。"}, {"text": "这家公司主要做咨询服务，初级产品是它的核心业务。", "explanation": "这里应该用〈服务〉。“初级产品”指原料类的物品，不能用来指咨询等服务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个地区主要出口一只初级产品。", "corrected_sentence": "这个地区主要出口一种初级产品。", "error_description": "量词错误：“初级产品”应搭配量词“种”，“只”多用于动物等，不能用于“产品”。正确：“一种初级产品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家企业主要生产很初级产品，再卖给加工厂。", "corrected_sentence": "这家企业主要生产初级产品，再卖给加工厂。", "error_description": "错误：“很初级产品”。“很”修饰“初级”后，后面的名词前须带“的”（如“很初级的产品”）；本句应删去“很”，写作“初级产品”。正确：“主要生产初级产品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10493, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "顺境", "is_correct": true, "explanation": "反义：“顺境”指顺利的境遇，与“困境”构成反义。"}, {"text": "花园", "is_correct": false, "explanation": "无反义关系：“花园”指种植花草供人游赏的地方，与“困境”的意思不相对。"}, {"text": "河流", "is_correct": false, "explanation": "无反义关系：“河流”指流动的水体，与“困境”不构成反义。"}, {"text": "书桌", "is_correct": false, "explanation": "无反义关系：“书桌”指供读书写字用的家具，与“困境”没有对立关系。"}], "correct_answer": "顺境", "explanations": {"顺境": "反义：“顺境”指顺利的境遇，与“困境”构成反义。", "花园": "无反义关系：“花园”指种植花草供人游赏的地方，与“困境”的意思不相对。", "河流": "无反义关系：“河流”指流动的水体，与“困境”不构成反义。", "书桌": "无反义关系：“书桌”指供读书写字用的家具，与“困境”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10493, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "顺境", "is_correct": true, "explanation": "反义：“顺境”指顺利的境遇，与“困境”构成反义。"}, {"text": "窗帘", "is_correct": false, "explanation": "无反义关系：“窗帘”指挂在窗户上遮挡光线的织物，与“困境”不构成反义。"}, {"text": "山脉", "is_correct": false, "explanation": "无反义关系：“山脉”指连绵的山岭，与“困境”的意思不相对。"}, {"text": "钢笔", "is_correct": false, "explanation": "无反义关系：“钢笔”指书写用的笔，与“困境”没有对立关系。"}], "correct_answer": "顺境", "explanations": {"顺境": "反义：“顺境”指顺利的境遇，与“困境”构成反义。", "窗帘": "无反义关系：“窗帘”指挂在窗户上遮挡光线的织物，与“困境”不构成反义。", "山脉": "无反义关系：“山脉”指连绵的山岭，与“困境”的意思不相对。", "钢笔": "无反义关系：“钢笔”指书写用的笔，与“困境”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10493, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "困难的处境；艰难的境地。", "primary_collocate": null, "pronunciation": "kùn jìng", "ipa": "kʰwən˥˩ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "当一则民间传说跨越千年仍能引发共鸣，其力量不在于事件的考古真实性，而在于它对人性困境的原型性捕捉。", "target_word": "困境", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司没有钱发工资，陷入了困境。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他努力工作，想早日走出生活的困境。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在大家的帮助下，他终于摆脱了困境。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对困境，我们不能放弃希望。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂关门以后，许多工人陷入困境。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小国经济很差，正面临严重的困境。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的困境告诉了老师。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到困境时，她总是先想办法，不哭。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是一家人在战争中的困境。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生存困境", "label": "复合"}, {"form": "经济困境", "label": "复合"}], "register": "中性", "sense_fingerprint": "困境:困难的处境，艰难的境地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3e4321f-de6e-46a4-8743-02c784fb0964') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10493, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "困境", "is_correct": true, "explanation": "正确：“人性困境”指人性中艰难的处境，与“原型性捕捉”搭配自然。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能作为“人性”的内容，句子讲不通。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线是输送电流的器材，不能作为“人性”的内容，“人性电线”讲不通。"}, {"text": "体形", "is_correct": false, "explanation": "体貌：“体形”指身体外形，与抽象的“人性”不搭，无法被“原型性捕捉”。"}], "explanations": {"困境": "正确：“人性困境”指人性中艰难的处境，与“原型性捕捉”搭配自然。", "天气": "语义：天气是自然现象，不能作为“人性”的内容，句子讲不通。", "电线": "语义：电线是输送电流的器材，不能作为“人性”的内容，“人性电线”讲不通。", "体形": "体貌：“体形”指身体外形，与抽象的“人性”不搭，无法被“原型性捕捉”。"}, "sentence_index": 0, "correct_answer": "困境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他现在的困境很好，工作和生活都很顺利。", "explanation": "这里应该用〈处境〉。困境专指艰难的处境，不能用来形容顺利、良好的情况。"}, {"text": "他的修养已经达到了很高的困境。", "explanation": "这里应该用〈境界〉。困境指艰难的处境，不指修养所达到的水平。"}, {"text": "这所学校的困境很安静，很适合学习。", "explanation": "这里应该用〈环境〉。困境指人所处的艰难处境，不能用来描述学校周围的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10493, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "困境", "is_correct": true, "explanation": "正确：“严重的困境”指艰难的处境，与“面临”搭配自然，符合国家经济很差的语境。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是电子用品，不能作为“严重”的对象，“面临严重的手机”讲不通。"}, {"text": "体形", "is_correct": false, "explanation": "体貌：“体形”指身体外形，与一个国家的经济状况无关。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭是一顿饭，不是可以“面临”的严重局面，句意讲不通。"}], "explanations": {"困境": "正确：“严重的困境”指艰难的处境，与“面临”搭配自然，符合国家经济很差的语境。", "手机": "语义：手机是电子用品，不能作为“严重”的对象，“面临严重的手机”讲不通。", "体形": "体貌：“体形”指身体外形，与一个国家的经济状况无关。", "早饭": "语义：早饭是一顿饭，不是可以“面临”的严重局面，句意讲不通。"}, "sentence_index": 6, "correct_answer": "困境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一生的困境很幸福，朋友很多。", "explanation": "这里应该用〈境遇〉。困境指艰难的处境，不能用来形容幸福的生活状况。"}, {"text": "这次考试的困境很小，大家都考得不错。", "explanation": "这里应该用〈困难〉。困难可指事情难做的程度，困境指人所处的艰难处境，不能用来说考试的难度。"}, {"text": "他的困境越来越好，工作稳定，收入也高。", "explanation": "这里应该用〈境况〉。困境指艰难的处境，不能用来形容越来越好、收入也高的状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10493, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个家庭曾经陷入困境过，但最后走了出来。", "corrected_sentence": "这个家庭曾经陷入困境，但最后走了出来。", "error_description": "体标错误。“过”紧跟在宾语“困境”后面，不正确；“曾经”已表示经历过，应删去句末多余的“过”，说“曾经陷入困境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10493, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场战争让他们一家人陷入了很困境。", "corrected_sentence": "这场战争让他们一家人陷入了困境。", "error_description": "错误在程度副词：“困境”是名词，不能受“很”修饰，“陷入了很困境”不成立，应删去“很”，说“陷入了困境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10497, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "矮", "is_correct": true, "explanation": "矮：与“高”构成反义，指从底部到顶部的距离小，适用于“那座楼”。"}, {"text": "轻", "is_correct": false, "explanation": "轻与“高”不构成反义，轻的反义是重。"}, {"text": "亮", "is_correct": false, "explanation": "亮与“高”不构成反义，亮的反义是暗。"}, {"text": "窄", "is_correct": false, "explanation": "窄与“高”不构成反义，窄的反义是宽。"}], "correct_answer": "矮", "explanations": {"矮": "矮：与“高”构成反义，指从底部到顶部的距离小，适用于“那座楼”。", "轻": "轻与“高”不构成反义，轻的反义是重。", "亮": "亮与“高”不构成反义，亮的反义是暗。", "窄": "窄与“高”不构成反义，窄的反义是宽。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10497, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低", "is_correct": true, "explanation": "低：与“高”构成反义，指位置从底部到顶部的距离小。"}, {"text": "宽", "is_correct": false, "explanation": "宽与“高”不构成反义，宽的反义是窄。"}, {"text": "粗", "is_correct": false, "explanation": "粗与“高”不构成反义，粗的反义是细。"}, {"text": "圆", "is_correct": false, "explanation": "圆与“高”不构成反义，圆的反义是方。"}], "correct_answer": "低", "explanations": {"低": "低：与“高”构成反义，指位置从底部到顶部的距离小。", "宽": "宽与“高”不构成反义，宽的反义是窄。", "粗": "粗与“高”不构成反义，粗的反义是细。", "圆": "圆与“高”不构成反义，圆的反义是方。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10497, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指从底部到顶部的距离大。", "primary_collocate": null, "pronunciation": "gāo", "ipa": "kɑʊ˥", "syllable_count": 1, "sentences": [{"text": "这座山很高。", "target_word": "高", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他比我高十厘米。", "target_word": "高", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "姐姐个子高，喜欢打篮球。", "target_word": "高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那座楼高得看不到顶。", "target_word": "高", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这棵树很高，比房子还高。", "target_word": "高", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个门太高了，我得踮起脚才能摸到顶。", "target_word": "高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟飞得很高。", "target_word": "高", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他长得很高，站在后面。", "target_word": "高", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "飞机飞得越来越高，看不见了。", "target_word": "高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书架太高，我够不到。", "target_word": "高", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "矮", "label": "反义词"}, {"form": "低", "label": "反义词"}, {"form": "高度", "label": "复合词"}, {"form": "高大", "label": "复合词"}], "register": "中性", "sense_fingerprint": "距离地面或底部远，身材、山、楼、树等物体高大，如山很高、个子高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: contains vocabulary far above tier T1: 踮 (Zipf 2.12)']::text[], '911ce2b6-7d1d-4794-8ddb-56c9662d33c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10497, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高", "is_correct": true, "explanation": "高（gāo）：从底部到顶部的距离大，如“那座楼很高”。"}, {"text": "猫", "is_correct": false, "explanation": "māo（第一声）与 gāo 声母不同（m 与 g），韵母与声调相同，意思是猫。"}, {"text": "稿", "is_correct": false, "explanation": "gǎo（第三声）与 gāo 声调不同，意思是稿子。"}, {"text": "刀", "is_correct": false, "explanation": "dāo（第一声）与 gāo 声母不同（d 与 g），韵母与声调相同，意思是刀子。"}, {"text": "烧", "is_correct": false, "explanation": "shāo（第一声）与 gāo 声母不同（sh 与 g），韵母与声调相同，意思是燃烧、加热。"}, {"text": "包", "is_correct": false, "explanation": "bāo（第一声）与 gāo 声母不同（b 与 g），韵母与声调相同，意思是包裹、包子。"}, {"text": "告", "is_correct": false, "explanation": "gào（第四声）与 gāo 声调不同，意思是告诉。"}], "explanations": {"高": "高（gāo）：从底部到顶部的距离大，如“那座楼很高”。", "猫": "māo（第一声）与 gāo 声母不同（m 与 g），韵母与声调相同，意思是猫。", "稿": "gǎo（第三声）与 gāo 声调不同，意思是稿子。", "刀": "dāo（第一声）与 gāo 声母不同（d 与 g），韵母与声调相同，意思是刀子。", "烧": "shāo（第一声）与 gāo 声母不同（sh 与 g），韵母与声调相同，意思是燃烧、加热。", "包": "bāo（第一声）与 gāo 声母不同（b 与 g），韵母与声调相同，意思是包裹、包子。", "告": "gào（第四声）与 gāo 声调不同，意思是告诉。"}, "sentence_index": null, "correct_answer": "高"}, "level_3": {"options": [{"text": "高", "is_correct": true, "explanation": "高：“这座山很高”说明高度大，符合句意。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”说速度，山不能说快。"}, {"text": "重", "is_correct": false, "explanation": "语义：“重”说分量，与山的高矮无关。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”形容质地柔软，不用于形容山的高度或大小。"}], "explanations": {"高": "高：“这座山很高”说明高度大，符合句意。", "快": "语义：“快”说速度，山不能说快。", "重": "语义：“重”说分量，与山的高矮无关。", "软": "搭配：“软”形容质地柔软，不用于形容山的高度或大小。"}, "sentence_index": 0, "correct_answer": "高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个湖很高，不能游泳。", "explanation": "这里应该用〈深〉。高指从底部到顶部的距离，湖的深浅要用深。"}, {"text": "这条路很高，车很好开。", "explanation": "这里应该用〈宽〉。高说从下到上的距离，路的宽窄要用宽，不说路很高。"}, {"text": "这根绳子很高，拿来捆箱子正好。", "explanation": "这里应该用〈长〉。高指从下到上的距离，绳子的长短要用长，不说绳子很高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10497, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "高", "is_correct": true, "explanation": "高（gāo）：从底部到顶部的距离大，如“书架太高”。"}, {"text": "该", "is_correct": false, "explanation": "gāi（第一声）与 gāo 韵母不同（ai 与 ao），声母与声调相同，意思是应该。"}, {"text": "沟", "is_correct": false, "explanation": "gōu（第一声）与 gāo 韵母不同（ou 与 ao），声母与声调相同，意思是水沟。"}, {"text": "糟", "is_correct": false, "explanation": "zāo（第一声）与 gāo 声母不同（z 与 g），韵母与声调相同，意思是糟糕、腐坏。"}, {"text": "操", "is_correct": false, "explanation": "cāo（第一声）与 gāo 声母不同（c 与 g），韵母与声调相同，意思是操练、操作。"}, {"text": "蒿", "is_correct": false, "explanation": "hāo（第一声）与 gāo 声母不同（h 与 g），韵母与声调相同，意思是蒿草。"}, {"text": "搞", "is_correct": false, "explanation": "gǎo（第三声）与 gāo 声调不同，意思是做、弄。"}], "explanations": {"高": "高（gāo）：从底部到顶部的距离大，如“书架太高”。", "该": "gāi（第一声）与 gāo 韵母不同（ai 与 ao），声母与声调相同，意思是应该。", "沟": "gōu（第一声）与 gāo 韵母不同（ou 与 ao），声母与声调相同，意思是水沟。", "糟": "zāo（第一声）与 gāo 声母不同（z 与 g），韵母与声调相同，意思是糟糕、腐坏。", "操": "cāo（第一声）与 gāo 声母不同（c 与 g），韵母与声调相同，意思是操练、操作。", "蒿": "hāo（第一声）与 gāo 声母不同（h 与 g），韵母与声调相同，意思是蒿草。", "搞": "gǎo（第三声）与 gāo 声调不同，意思是做、弄。"}, "sentence_index": null, "correct_answer": "高"}, "level_3": {"options": [{"text": "高", "is_correct": true, "explanation": "高：“小鸟飞得很高”说明飞行的高度大，符合句意。"}, {"text": "胖", "is_correct": false, "explanation": "语义：“胖”形容身体，不能用来形容小鸟飞行的高度。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”不能用来形容飞行的高度。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”说厚度，与飞行的高度无关。"}], "explanations": {"高": "高：“小鸟飞得很高”说明飞行的高度大，符合句意。", "胖": "语义：“胖”形容身体，不能用来形容小鸟飞行的高度。", "硬": "搭配：“硬”不能用来形容飞行的高度。", "厚": "语义：“厚”说厚度，与飞行的高度无关。"}, "sentence_index": 6, "correct_answer": "高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这口古井很高，别靠太近。", "explanation": "这里应该用〈深〉。高说从底到顶的距离，井的深浅要用深，不说井很高。"}, {"text": "这里离海很高，交通不方便。", "explanation": "这里应该用〈远〉。高说从下到上的距离，离海的距离是水平距离，要用远，不说离海很高。"}, {"text": "他的腿很高，跑起来很快。", "explanation": "这里应该用〈长〉。高说从下到上的距离，腿的长短要说长，不说腿很高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10497, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这棵树高太了，遮住了阳光。", "corrected_sentence": "这棵树太高了，遮住了阳光。", "error_description": "语序错误：程度副词“太”应放在形容词前，说“太高”，不说“高太”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10497, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个书架高的我够不着。", "corrected_sentence": "这个书架高得我够不着。", "error_description": "助词错误：“高”后表示结果的补语要用“得”，不能用“的”。应说“高得我够不着”，不说“高的我够不着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10498, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "支出", "is_correct": true, "explanation": "正确。“支出”与“收入”互为反义词，指花费出去的钱。"}, {"text": "天气", "is_correct": false, "explanation": "天气是名词，但与收入没有反义关系，句义不符。"}, {"text": "教室", "is_correct": false, "explanation": "教室是名词，但与收入没有反义关系，句义不符。"}, {"text": "钥匙", "is_correct": false, "explanation": "钥匙是名词，但与收入没有反义关系，句义不符。"}], "correct_answer": "支出", "explanations": {"支出": "正确。“支出”与“收入”互为反义词，指花费出去的钱。", "天气": "天气是名词，但与收入没有反义关系，句义不符。", "教室": "教室是名词，但与收入没有反义关系，句义不符。", "钥匙": "钥匙是名词，但与收入没有反义关系，句义不符。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
