INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10498, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "个人或组织通过劳动、投资、出售商品等方式获得的经济收益。", "primary_collocate": null, "pronunciation": "shōu rù", "ipa": "ʂou˥ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "城市和农村居民的收入差距越来越小。", "target_word": "收入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民的主要收入来自卖粮食和蔬菜。", "target_word": "收入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的收入比支出多，每个月都能存钱。", "target_word": "收入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人刚工作，收入不多，花钱要小心。", "target_word": "收入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除了工资，他还有一笔别的收入。", "target_word": "收入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家想办法提高农民的收入。", "target_word": "收入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的收入主要靠投资，不是靠工作。", "target_word": "收入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家庭收入低的学生可以申请帮助。", "target_word": "收入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家商店的收入每个月都在增加。", "target_word": "收入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "交税以后，他的收入少了一些。", "target_word": "收入", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "高收入", "label": "复合"}, {"form": "低收入", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：个人或组织靠劳动、投资、卖商品等得到的经济收益", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7cbd58c-699e-471e-90b4-643ce1bb9923') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "收入", "is_correct": true, "explanation": "正确。“收入差距”指不同人群收入水平的差别，放在“居民的___差距”处，句意通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是视觉属性，居民之间不存在“颜色差距”，句意不通。"}, {"text": "方向", "is_correct": false, "explanation": "语义：方向指位置走向，与居民的差距无关，句意不通。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“差距”一般用于可以比较水平或数量的事物，“课本差距”不能这样搭配。"}], "explanations": {"收入": "正确。“收入差距”指不同人群收入水平的差别，放在“居民的___差距”处，句意通顺。", "颜色": "语义：颜色是视觉属性，居民之间不存在“颜色差距”，句意不通。", "方向": "语义：方向指位置走向，与居民的差距无关，句意不通。", "课本": "搭配：“差距”一般用于可以比较水平或数量的事物，“课本差距”不能这样搭配。"}, "sentence_index": 0, "correct_answer": "收入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的收入很多，每小时能做两百个零件。", "explanation": "这里应该用〈产量〉。“收入”指人或组织获得的经济收益，不能用来指机器的产出。"}, {"text": "这次旅行给我的收入很大，让我大开眼界。", "explanation": "这里应该用〈收获〉。“收入”指经济上的收益，不能用于经验、知识等方面。"}, {"text": "店员给了我一张收入，上面写着三百块。", "explanation": "这里应该用〈收据〉。“收入”指个人或组织获得的经济收益，不指付款后的凭证。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收入", "is_correct": true, "explanation": "正确。“他的收入主要靠投资”说明收益的来源，放在“他的___主要靠投资”处，句意通顺。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格是人的性情特点，不能靠投资获得，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是身体的高矮，不能靠投资获得，句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不能与“靠投资”搭配表示来源，这里不成立。"}], "explanations": {"收入": "正确。“他的收入主要靠投资”说明收益的来源，放在“他的___主要靠投资”处，句意通顺。", "性格": "语义：性格是人的性情特点，不能靠投资获得，句意不通。", "身高": "语义：身高是身体的高矮，不能靠投资获得，句意不通。", "年龄": "搭配：“年龄”不能与“靠投资”搭配表示来源，这里不成立。"}, "sentence_index": 6, "correct_answer": "收入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜有浓浓的收入。", "explanation": "这里应该用〈香味〉。“收入”是经济上的收益，不能用来形容气味。"}, {"text": "我的朋友是一笔收入。", "explanation": "这里说的是人，但“收入”只指经济收益，不能用来指人。"}, {"text": "这次考试他的收入很好。", "explanation": "这里应该用〈成绩〉。“收入”指经济收益，不能用于考试结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年多挣了一个收入。", "corrected_sentence": "他去年多挣了一笔收入。", "error_description": "量词错误：“收入”的量词是“笔”，不用“个”，应写作“一笔收入”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的收入吃了很多。", "corrected_sentence": "这家公司的收入增加了。", "error_description": "搭配错误：经济收入不能说“吃”，应说“增加”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10499, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10499, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10499, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一定范围内所有生产、消费、交换等活动组成的整体系统。", "primary_collocate": null, "pronunciation": "jīng jì tǐ", "ipa": "tɕiŋ˥ tɕi˥˩ tʰi˨˩˦", "syllable_count": 3, "sentences": [{"text": "该进程试图平衡各国差异，兼顾工业化国家的技术优势与发展中经济体的过渡需求，力图构建公平而有效的全球治理体系。", "target_word": "经济体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "与此相对，北美、西欧及东亚部分高收入经济体则作为主要进口方，凭借资本与品牌优势，掌控烘焙、包装与市场分销渠道。", "target_word": "经济体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "中国是世界上最大的经济体之一。", "target_word": "经济体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个经济体去年增长了百分之五。", "target_word": "经济体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新兴经济体需要更多的外国投资。", "target_word": "经济体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个经济体签了贸易合作协议。", "target_word": "经济体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小的经济体也会受到世界市场的影响。", "target_word": "经济体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家认为，这个经济体的前景很好。", "target_word": "经济体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发达经济体的利率变化会影响其他国家。", "target_word": "经济体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究亚洲各个经济体的发展情况。", "target_word": "经济体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "新兴经济体", "label": "复合"}, {"form": "发达经济体", "label": "复合"}], "register": "书面", "sense_fingerprint": "经济体：由生产、消费、交换等活动构成的国家或地区经济整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd34bc2cc-089b-431f-93cf-0515a2573957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10499, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "企业", "is_correct": false, "explanation": "语义：本句论述的是国家层面的全球治理，“发展中企业”的过渡需求与语境不合。"}, {"text": "经济体", "is_correct": true, "explanation": "正确。“发展中经济体”指发展中的国家或地区经济整体，与“工业化国家”相对，符合句意。"}, {"text": "人民", "is_correct": false, "explanation": "搭配：“发展中”通常修饰国家、地区或经济体，“发展中人民”不是常用搭配。"}, {"text": "行业", "is_correct": false, "explanation": "语义：“行业”指单一产业部门，而句中的“各国”“全球治理”需要国家或地区层面的整体概念，“行业”不符。"}], "explanations": {"企业": "语义：本句论述的是国家层面的全球治理，“发展中企业”的过渡需求与语境不合。", "经济体": "正确。“发展中经济体”指发展中的国家或地区经济整体，与“工业化国家”相对，符合句意。", "人民": "搭配：“发展中”通常修饰国家、地区或经济体，“发展中人民”不是常用搭配。", "行业": "语义：“行业”指单一产业部门，而句中的“各国”“全球治理”需要国家或地区层面的整体概念，“行业”不符。"}, "sentence_index": 0, "correct_answer": "经济体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个经济体每年治疗很多病人。", "explanation": "这里应该用〈医院〉。经济体指一定范围内生产、消费、交换等活动组成的整体系统，不是医疗机构，不能治疗病人。"}, {"text": "这个经济体今年的利润很高。", "explanation": "这里应该用〈企业〉。经济体指整体经济系统，不是单个企业，不能说它的利润高。"}, {"text": "他是一个很聪明的经济体。", "explanation": "这里应该用〈人〉。经济体指整体经济系统，不能指人；说某人聪明应用〈人〉，如「他是一个很聪明的人」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10499, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "房间", "is_correct": false, "explanation": "语义：房间不会受到世界市场的影响，与句意不合。"}, {"text": "经济体", "is_correct": true, "explanation": "正确。“小的经济体”指规模较小的国家或地区经济，句意是它们同样受世界市场影响。"}, {"text": "宝宝", "is_correct": false, "explanation": "语义：“宝宝”指婴儿，句意讨论的是经济体受世界市场影响，“小的宝宝”与此语境不符。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生是人，句意讨论的是经济体受世界市场影响，“学生”与此语境不符。"}], "explanations": {"房间": "语义：房间不会受到世界市场的影响，与句意不合。", "经济体": "正确。“小的经济体”指规模较小的国家或地区经济，句意是它们同样受世界市场影响。", "宝宝": "语义：“宝宝”指婴儿，句意讨论的是经济体受世界市场影响，“小的宝宝”与此语境不符。", "学生": "语义：学生是人，句意讨论的是经济体受世界市场影响，“学生”与此语境不符。"}, "sentence_index": 6, "correct_answer": "经济体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个经济体的员工都很年轻。", "explanation": "这里应该用〈公司〉。经济体指国家或地区的整体经济，没有员工，员工属于具体企业。"}, {"text": "这个经济体每小时能跑一百公里。", "explanation": "这里应该用〈汽车〉。经济体是整体系统，不能用来说跑的速度。"}, {"text": "这个经济体的眼睛很大。", "explanation": "这里应该用〈人〉。经济体是抽象的整体系统，没有眼睛，不能说它的眼睛大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10499, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "欧盟是一只重要的经济体。", "corrected_sentence": "欧盟是一个重要的经济体。", "error_description": "量词错误：经济体应配量词「个」，「一只」用于动物等，应改为「一个」，正确说法为「欧盟是一个重要的经济体」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10499, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多经济体们都在增长。", "corrected_sentence": "很多经济体都在增长。", "error_description": "词尾错误：「们」只用于指人，「经济体」不能加「们」表示复数，应改为「很多经济体都在增长」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
