INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10502, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10502, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "品牌在市场竞争中相对于其他品牌所具有的独特长处，能吸引更多顾客购买。", "primary_collocate": null, "pronunciation": "pǐn pái yōu shì", "ipa": "pʰin˨˩˦ pʰaɪ˧˥ joʊ˥ ʂɻ̩˥˩", "syllable_count": 4, "sentences": [{"text": "与此相对，北美、西欧及东亚部分高收入经济体则作为主要进口方，凭借资本与品牌优势，掌控烘焙、包装与市场分销渠道。", "target_word": "品牌优势", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司的品牌优势很明显。", "target_word": "品牌优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好品质是我们最大的品牌优势。", "target_word": "品牌优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老字号有很强的品牌优势。", "target_word": "品牌优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新广告扩大了公司的品牌优势。", "target_word": "品牌优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店靠品牌优势吸引了很多顾客。", "target_word": "品牌优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小公司没有大公司那样的品牌优势。", "target_word": "品牌优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想靠品牌优势把价格提高一点。", "target_word": "品牌优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要保持品牌优势，质量不能差。", "target_word": "品牌优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进入新市场，品牌优势很重要。", "target_word": "品牌优势", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词：品牌在竞争中比别的品牌更强的长处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1de80df8-30f4-4a4d-832e-d5d2f03764c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10502, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "品牌优势", "is_correct": true, "explanation": "正确：「凭借资本与品牌优势」指凭借资本和品牌的长处。"}, {"text": "颜色", "is_correct": false, "explanation": "配价：「颜色」不是可以依靠的资源，不能与「资本」并列作「凭借」。"}, {"text": "声音", "is_correct": false, "explanation": "配价：「声音」不能被「凭借」，句中「凭借」要求的是资本、优势一类的资源。"}, {"text": "天气", "is_correct": false, "explanation": "配价：「凭借」要求可以依靠的资源，「天气」不能被凭借。"}], "explanations": {"品牌优势": "正确：「凭借资本与品牌优势」指凭借资本和品牌的长处。", "颜色": "配价：「颜色」不是可以依靠的资源，不能与「资本」并列作「凭借」。", "声音": "配价：「声音」不能被「凭借」，句中「凭借」要求的是资本、优势一类的资源。", "天气": "配价：「凭借」要求可以依靠的资源，「天气」不能被凭借。"}, "sentence_index": 0, "correct_answer": "品牌优势"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把品牌优势装进了箱子里。", "explanation": "〈品牌优势〉是品牌相对其他品牌的长处，是抽象概念，不能装进箱子。"}, {"text": "这家饭店的品牌优势很厚。", "explanation": "〈厚〉用于有体积或层次的东西，不能用来形容抽象的〈品牌优势〉。"}, {"text": "这一只品牌优势很明显。", "explanation": "〈品牌优势〉是抽象名词，量词用〈种〉或〈个〉，不说〈只〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "品牌优势", "is_correct": true, "explanation": "正确：「那样的品牌优势」指大公司拥有的品牌长处。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：公司的「年龄」不是可比较的优势，与「那样的」不搭。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「体重」只用于人或动物，公司没有体重，不能说「大公司那样的体重」。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」与公司的竞争长处无关，不能与「没有……那样的」搭配。"}], "explanations": {"品牌优势": "正确：「那样的品牌优势」指大公司拥有的品牌长处。", "年龄": "语义：公司的「年龄」不是可比较的优势，与「那样的」不搭。", "体重": "语义：「体重」只用于人或动物，公司没有体重，不能说「大公司那样的体重」。", "颜色": "语义：「颜色」与公司的竞争长处无关，不能与「没有……那样的」搭配。"}, "sentence_index": 6, "correct_answer": "品牌优势"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们把品牌优势切成几块，价格就低了。", "explanation": "〈品牌优势〉是抽象的长处，不能切成几块，也不能当作可分割的东西。"}, {"text": "这座品牌优势很大。", "explanation": "〈座〉用于山、桥等大型物体，不用于抽象的〈品牌优势〉。"}, {"text": "他把品牌优势借给了朋友。", "explanation": "〈品牌优势〉是品牌的长处，不能借出或转让。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只品牌优势很少见。", "corrected_sentence": "这种品牌优势很少见。", "error_description": "「品牌优势」是抽象名词，量词用「种」，不说「只」。错误：这只；正确：这种。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们的品牌优势了很稳定。", "corrected_sentence": "他们的品牌优势很稳定。", "error_description": "「了」多放在「品牌优势」与「很稳定」之间，这里不需要「了」。错误：优势了很；正确：优势很。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10505, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10505, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10505, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "企业将产品或服务通过中间商（如批发商、零售商）进行销售，而非直接卖给最终消费者。", "primary_collocate": null, "pronunciation": "fēn xiāo", "ipa": "fən˥ ɕiɑʊ˥", "syllable_count": 2, "sentences": [{"text": "与此相对，北美、西欧及东亚部分高收入经济体则作为主要进口方，凭借资本与品牌优势，掌控烘焙、包装与市场分销渠道。", "target_word": "分销", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司通过经销商分销产品。", "target_word": "分销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂不直接卖货，而是找代理分销。", "target_word": "分销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把新手机交给代理商分销。", "target_word": "分销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种饮料通过批发商分销到三十个城市。", "target_word": "分销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想找更多批发商帮忙分销。", "target_word": "分销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小品牌很难找到批发商来分销。", "target_word": "分销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们决定分销这个牌子的牛奶。", "target_word": "分销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批水果由批发商分销到各个超市。", "target_word": "分销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司先生产，再交给零售商分销。", "target_word": "分销", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分销商", "label": "复合"}, {"form": "分销渠道", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：企业通过批发商、零售商等中间商销售产品，不直接卖给消费者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1de80df8-30f4-4a4d-832e-d5d2f03764c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10505, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研发", "is_correct": false, "explanation": "语义：“研发”指研究开发产品，不指销售渠道，与“掌控……市场”的语境不合。"}, {"text": "分销", "is_correct": true, "explanation": "“分销”指通过中间商销售，与“渠道”搭配成“分销渠道”，在这里正确。"}, {"text": "设计", "is_correct": false, "explanation": "搭配：“设计”不能修饰“渠道”，“市场设计渠道”不成立。"}, {"text": "制造", "is_correct": false, "explanation": "语义：“制造”指生产物品，不指市场上的渠道，“市场制造渠道”与语境不合。"}], "explanations": {"研发": "语义：“研发”指研究开发产品，不指销售渠道，与“掌控……市场”的语境不合。", "分销": "“分销”指通过中间商销售，与“渠道”搭配成“分销渠道”，在这里正确。", "设计": "搭配：“设计”不能修饰“渠道”，“市场设计渠道”不成立。", "制造": "语义：“制造”指生产物品，不指市场上的渠道，“市场制造渠道”与语境不合。"}, "sentence_index": 0, "correct_answer": "分销"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂分销自己做的产品，不经过任何中间商。", "explanation": "这里应该用〈直销〉。分销要经过批发商、零售商等中间商，与“不经过任何中间商”矛盾；厂家直接卖给消费者应说直销。"}, {"text": "他把自己做的蛋糕分销给街上的路人。", "explanation": "这里应该用〈销售〉。分销面向的是批发商、零售商等中间商，卖给街上的路人这样的消费者要说销售。"}, {"text": "他挨家挨户分销保险。", "explanation": "这里应该用〈推销〉。分销要经过中间商，挨家挨户上门卖是直接推销，应说推销。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10505, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分销", "is_correct": true, "explanation": "“分销”指通过中间商销售产品，“找批发商来分销”语义通顺，在这里正确。"}, {"text": "继承", "is_correct": false, "explanation": "语义：“继承”指接受遗产或传承，“找批发商来继承”不通。"}, {"text": "应聘", "is_correct": false, "explanation": "语义：“应聘”指求职，“找批发商来应聘”与语境不合。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：“出生”只用于人或动物，“找批发商来出生”不通。"}], "explanations": {"分销": "“分销”指通过中间商销售产品，“找批发商来分销”语义通顺，在这里正确。", "继承": "语义：“继承”指接受遗产或传承，“找批发商来继承”不通。", "应聘": "语义：“应聘”指求职，“找批发商来应聘”与语境不合。", "出生": "搭配：“出生”只用于人或动物，“找批发商来出生”不通。"}, "sentence_index": 6, "correct_answer": "分销"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店每天分销几百杯咖啡，全部卖给路过的顾客。", "explanation": "这里应该用〈零售〉。分销是把货交给中间商再转卖，店铺直接把咖啡卖给路过的顾客应说零售。"}, {"text": "这家公司既自己生产，又自己分销，不找任何中间商。", "explanation": "这里应该用〈直销〉。分销要借助中间商，与“不找任何中间商”矛盾；厂家自己生产、直接卖给消费者应说直销。"}, {"text": "志愿者在地铁口分销传单，每人发一张。", "explanation": "这里应该用〈派发〉。分销指经中间商卖货，在地铁口直接把传单发给每个人应说派发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10505, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家品牌把饮料分销了到各个城市。", "corrected_sentence": "这家品牌把饮料分销到各个城市。", "error_description": "错误在「了」：它插在动词「分销」与补语「到」之间，动词和补语之间不能加「了」。正确：「分销到各个城市」。", "correct_sentence_indices": [1, 2, 4]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10505, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把咖啡豆分销海外的经销商。", "corrected_sentence": "他们把咖啡豆分销给海外的经销商。", "error_description": "错误在“分销”后面表示对象的“给”被省略了。应说“分销给海外的经销商”，去掉“给”后句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
