INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10506, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "通过某种途径获取信息、商品或办成事情的门路。", "primary_collocate": null, "pronunciation": "qú dào", "ipa": "tɕʰy˧˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "与此相对，北美、西欧及东亚部分高收入经济体则作为主要进口方，凭借资本与品牌优势，掌控烘焙、包装与市场分销渠道。", "target_word": "渠道", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他想找一个可靠的渠道买便宜的机票。", "target_word": "渠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的新闻主要来自网络渠道。", "target_word": "渠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店同时使用线上和线下两种渠道。", "target_word": "渠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你从什么渠道知道这个消息的？", "target_word": "渠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生可以通过正规渠道申请奖学金。", "target_word": "渠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在开辟新渠道。", "target_word": "渠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，学习的渠道有很多种。", "target_word": "渠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些药不是从正规渠道买来的。", "target_word": "渠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想用更多渠道让大家认识新产品。", "target_word": "渠道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "获取信息、商品或办成事情的途径、门路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1de80df8-30f4-4a4d-832e-d5d2f03764c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10506, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工厂", "is_correct": false, "explanation": "语义：“工厂”是生产场所，不是销售途径，“市场分销工厂”不通。"}, {"text": "渠道", "is_correct": true, "explanation": "“渠道”指销售或传递的途径，与“市场分销”搭配，构成“市场分销渠道”，在这里正确。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”是自然水体，不是商品流通的途径，“市场分销河流”与语境不合。"}, {"text": "大坝", "is_correct": false, "explanation": "搭配：“分销”多接“产品、渠道、网络”一类词，不接“大坝”。"}], "explanations": {"工厂": "语义：“工厂”是生产场所，不是销售途径，“市场分销工厂”不通。", "渠道": "“渠道”指销售或传递的途径，与“市场分销”搭配，构成“市场分销渠道”，在这里正确。", "河流": "语义：“河流”是自然水体，不是商品流通的途径，“市场分销河流”与语境不合。", "大坝": "搭配：“分销”多接“产品、渠道、网络”一类词，不接“大坝”。"}, "sentence_index": 0, "correct_answer": "渠道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条渠道把煤气送到厨房。", "explanation": "这里应该用〈管道〉。输送煤气要用管道；“渠道”在这里指传递的途径，不能用来输送煤气。"}, {"text": "他用渠道一步步算出了这道数学题的答案。", "explanation": "这里应该用〈方法〉。渠道指获取东西或办事的途径，计算、解题要说方法，不能说“用渠道算出”。"}, {"text": "雨水顺着屋顶的渠道流进了桶里。", "explanation": "这里应该用〈水槽〉。本句教的“渠道”指获取信息或商品的途径，屋顶接雨水的槽应说水槽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：“空气”看不见、摸不着，不能“开辟”，“他们正在开辟新空气”不通。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“开辟”不接“感情”，“开辟新感情”不是通常的说法。"}, {"text": "渠道", "is_correct": true, "explanation": "“开辟新渠道”是常见搭配，“渠道”指途径，与“开辟”搭配自然，在这里正确。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是实物，不能被“开辟”，“开辟新石头”与语境不合。"}], "explanations": {"空气": "语义：“空气”看不见、摸不着，不能“开辟”，“他们正在开辟新空气”不通。", "感情": "搭配：“开辟”不接“感情”，“开辟新感情”不是通常的说法。", "渠道": "“开辟新渠道”是常见搭配，“渠道”指途径，与“开辟”搭配自然，在这里正确。", "石头": "语义：“石头”是实物，不能被“开辟”，“开辟新石头”与语境不合。"}, "sentence_index": 6, "correct_answer": "渠道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座大桥有五条渠道，每条都很宽。", "explanation": "这里应该用〈车道〉。渠道指水沟或传递消息、办事的途径，供车辆行驶的路面要说车道。"}, {"text": "我们穿过地下渠道去车站。", "explanation": "这里应该用〈通道〉。渠道指输水的沟或传递的途径，人穿行的地下通道应说通道。"}, {"text": "他找到了一张新渠道。", "explanation": "这里应该用〈条〉。“渠道”用“条”，“张”用于纸、桌子等平面的东西，不能说“一张渠道”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市出现了一只新渠道。", "corrected_sentence": "这个城市出现了一条新渠道。", "error_description": "量词错误：“渠道”用量词“条”，不用“只”。错误：一只新渠道；正确：一条新渠道。", "correct_sentence_indices": [1, 2, 4]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家网店通过多只渠道销售图书。", "corrected_sentence": "这家网店通过多条渠道销售图书。", "error_description": "错误在“渠道”的量词：“渠道”用量词“条”，“多只渠道”不通，应说“多条渠道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
