INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10507, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指从其他国家购买商品或服务的国家。", "primary_collocate": null, "pronunciation": "jìn kǒu guó", "ipa": "tɕin˥˩ kʰoʊ˨˩˦ kwo˧˥", "syllable_count": 3, "sentences": [{"text": "进口国的消费市场呈现出高度分化的格局。", "target_word": "进口国", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "中国是很多水果的进口国。", "target_word": "进口国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家是石油进口国。", "target_word": "进口国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进口国要先检查这些食品。", "target_word": "进口国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为进口国，他们需要很多粮食。", "target_word": "进口国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种汽车的主要进口国是哪几个？", "target_word": "进口国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进口国提高了咖啡的关税。", "target_word": "进口国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日本是大米的进口国，不是出口国。", "target_word": "进口国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进口国的人也能喝到这种茶。", "target_word": "进口国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批咖啡的进口国是日本。", "target_word": "进口国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "進口國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从别国购买商品或服务的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1de80df8-30f4-4a4d-832e-d5d2f03764c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10507, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不是国家，不能作“消费市场”的修饰对象，“天气的消费市场”说不通。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“房间的消费市场”不成立，“消费市场”通常与国家、地区或行业搭配。"}, {"text": "进口国", "is_correct": true, "explanation": "进口国指从别国购买商品的国家，与句中的“消费市场”语境相符。"}, {"text": "仓库", "is_correct": false, "explanation": "语义：仓库是存放货物的场所，不是买入商品的一方，不能作“消费市场”的修饰语。"}], "explanations": {"天气": "语义：天气不是国家，不能作“消费市场”的修饰对象，“天气的消费市场”说不通。", "房间": "搭配：“房间的消费市场”不成立，“消费市场”通常与国家、地区或行业搭配。", "进口国": "进口国指从别国购买商品的国家，与句中的“消费市场”语境相符。", "仓库": "语义：仓库是存放货物的场所，不是买入商品的一方，不能作“消费市场”的修饰语。"}, "sentence_index": 0, "correct_answer": "进口国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的公司是这种红酒的进口国。", "explanation": "这里应该用〈进口商〉。进口国指国家，“我的公司”是企业，应说进口商。"}, {"text": "这个进口国每天在工厂里工作八个小时。", "explanation": "这里应该用〈工人〉。进口国指从外国买入商品的国家，不能指人；句中说在工厂里工作八个小时，应说工人。"}, {"text": "这个国家每年把大量汽车运往外国，所以是汽车的进口国。", "explanation": "这里应该用〈出口国〉。进口国指从外国买入商品的国家，句中说把汽车运往外国，是卖出，应说出口国。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10507, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作家", "is_correct": false, "explanation": "语义：作家没有制定关税的权力，句中“提高关税”的主语须是能征税的国家。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“提高……的关税”需要能征收关税的主体，“窗户”不能与之搭配。"}, {"text": "进口国", "is_correct": true, "explanation": "进口国是从外国购买商品的国家，可以作主语并决定提高关税。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是征税的主体，不能作“提高了咖啡的关税”的主语。"}], "explanations": {"作家": "语义：作家没有制定关税的权力，句中“提高关税”的主语须是能征税的国家。", "窗户": "搭配：“提高……的关税”需要能征收关税的主体，“窗户”不能与之搭配。", "进口国": "进口国是从外国购买商品的国家，可以作主语并决定提高关税。", "歌曲": "语义：歌曲不是征税的主体，不能作“提高了咖啡的关税”的主语。"}, "sentence_index": 6, "correct_answer": "进口国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司是这批货的进口国。", "explanation": "这里应该用〈买家〉。进口国指国家，“我们公司”是企业，应说买家。"}, {"text": "这个进口国只种小麦，从不向外国买粮食。", "explanation": "这里应该用〈农场〉。进口国指从外国买入商品的国家，句中说只种小麦、从不向外国买粮，应说农场。"}, {"text": "这个国家从不买外国汽车，它的汽车全部在国内生产，是世界上最大的汽车进口国。", "explanation": "这里应该用〈生产国〉。进口国指从外国买入商品的国家，句中说汽车全部在国内生产、从不买外国车，应说生产国。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10507, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家成了咖啡的一只进口国。", "corrected_sentence": "这个国家成了咖啡的进口国。", "error_description": "量词错误：「进口国」是国家，不用量词「只」（「只」多用于动物或单个的小物件）。错误：一只进口国；正确：「咖啡的进口国」，或用量词「个」说「一个进口国」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10507, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个国家成了咖啡的很进口国。", "corrected_sentence": "这个国家成了咖啡的进口国。", "error_description": "程度副词误用：「进口国」是名词，不能用程度副词「很」修饰。错误：咖啡的很进口国；正确：咖啡的进口国。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
