INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10508, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指消费者购买商品和服务的市场，包括零售、服务等。", "primary_collocate": null, "pronunciation": "xiāo fèi shì chǎng", "ipa": "ɕiɑʊ˥ feɪ˥˩ ʂɻ˥˩ ʈʂʰɑŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "进口国的消费市场呈现出高度分化的格局。", "target_word": "消费市场", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "中国的消费市场越来越大。", "target_word": "消费市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的消费市场正在快速发展。", "target_word": "消费市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人是消费市场的重要力量。", "target_word": "消费市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机让线上消费市场变得更大了。", "target_word": "消费市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司想进入海外消费市场。", "target_word": "消费市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日期间，消费市场特别活跃。", "target_word": "消费市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老年人的消费市场也很有潜力。", "target_word": "消费市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展带动了消费市场的增长。", "target_word": "消费市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说今年的消费市场比去年好。", "target_word": "消费市场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "国内消费市场", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "消费市场：消费者购买商品和服务的整体市场，抽象的经济概念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d8d8829-6187-4938-b5a2-6292d29cf1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10508, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消费市场", "is_correct": true, "explanation": "正确：消费市场指消费者购买商品和服务的整体市场，可以说「进口国的消费市场呈现出高度分化的格局」。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：「身高」指个人身材的高矮，不能说「呈现出高度分化的格局」。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「体重」指个人的体重，与「进口国的」所限定的国家范围不符。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：「脾气」是个人性情，不能作为国家层面的「格局」来呈现。"}], "explanations": {"消费市场": "正确：消费市场指消费者购买商品和服务的整体市场，可以说「进口国的消费市场呈现出高度分化的格局」。", "身高": "搭配：「身高」指个人身材的高矮，不能说「呈现出高度分化的格局」。", "体重": "语义：「体重」指个人的体重，与「进口国的」所限定的国家范围不符。", "脾气": "搭配：「脾气」是个人性情，不能作为国家层面的「格局」来呈现。"}, "sentence_index": 0, "correct_answer": "消费市场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市的消费市场很高。", "explanation": "这里应该用〈消费水平〉。「消费市场」指消费者整体市场，不能用来说城市消费的高低；「高」应搭配「消费水平」。"}, {"text": "这种商品的消费市场很便宜。", "explanation": "这里应该用〈价格〉。「便宜」形容价钱，「消费市场」指整体市场，不能说它便宜。"}, {"text": "我们这里有一只消费市场。", "explanation": "这里应该用〈个〉。「只」多用于动物或成对的物品，不能用来修饰「消费市场」这类抽象概念。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消费市场", "is_correct": true, "explanation": "正确：「节日期间，消费市场特别活跃」符合购物高峰时期市场活跃的语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有活跃与否的状态，与「特别活跃」不搭。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是无生命的材料，不能说「节日期间特别活跃」。"}, {"text": "作息", "is_correct": false, "explanation": "搭配：「活跃」常用于说人、市场或气氛，「作息」指生活规律，不能说「特别活跃」。"}], "explanations": {"消费市场": "正确：「节日期间，消费市场特别活跃」符合购物高峰时期市场活跃的语境。", "石头": "语义：石头没有活跃与否的状态，与「特别活跃」不搭。", "玻璃": "语义：玻璃是无生命的材料，不能说「节日期间特别活跃」。", "作息": "搭配：「活跃」常用于说人、市场或气氛，「作息」指生活规律，不能说「特别活跃」。"}, "sentence_index": 6, "correct_answer": "消费市场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的消费市场很强。", "explanation": "这里应该用〈消费能力〉。「消费市场」指整体市场，不能用来形容某个人的购买力。"}, {"text": "这个国家有一条很大的消费市场。", "explanation": "这里应该用〈个〉。「条」用于细长的东西，抽象的「消费市场」不能用它计量。"}, {"text": "这家工厂生产的消费市场很受欢迎。", "explanation": "这里应该用〈消费品〉。「消费市场」指整体市场，工厂生产的是商品，不能说生产市场；「消费品」指供人购买使用的产品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市有一条大的消费市场。", "corrected_sentence": "这个城市有一个大的消费市场。", "error_description": "量词错误：「消费市场」应搭配量词「个」，「条」用于细长的物品，不能用于市场。正确说法为「一个大的消费市场」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司正在研究一只新的消费市场。", "corrected_sentence": "我们公司正在研究一个新的消费市场。", "error_description": "量词错误：「消费市场」应搭配量词「个」，「只」用于动物或成对的物品，不能用于市场。正确说法为「一个新的消费市场」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10514, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "批发", "is_correct": true, "explanation": "反义：批发指成批卖给商户，与零售（卖给个人消费者）相对，是该义项的反义词。"}, {"text": "工厂", "is_correct": false, "explanation": "工厂是生产场所，与“零售”在任何义项上都不构成近义或反义关系。"}, {"text": "森林", "is_correct": false, "explanation": "森林是自然地貌，与“零售”在任何义项上都不构成近义或反义关系。"}, {"text": "教室", "is_correct": false, "explanation": "教室是学习场所，与“零售”在任何义项上都不构成近义或反义关系。"}], "correct_answer": "批发", "explanations": {"批发": "反义：批发指成批卖给商户，与零售（卖给个人消费者）相对，是该义项的反义词。", "工厂": "工厂是生产场所，与“零售”在任何义项上都不构成近义或反义关系。", "森林": "森林是自然地貌，与“零售”在任何义项上都不构成近义或反义关系。", "教室": "教室是学习场所，与“零售”在任何义项上都不构成近义或反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10514, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "批发", "is_correct": true, "explanation": "反义：批发指成批卖给商户，与零售（卖给个人消费者）相对，是该义项的反义词。"}, {"text": "银行", "is_correct": false, "explanation": "银行是金融机构，与“零售”在任何义项上都不构成近义或反义关系。"}, {"text": "医院", "is_correct": false, "explanation": "医院是诊疗场所，与“零售”在任何义项上都不构成近义或反义关系。"}, {"text": "花园", "is_correct": false, "explanation": "花园是种植花草的地方，与“零售”在任何义项上都不构成近义或反义关系。"}], "correct_answer": "批发", "explanations": {"批发": "反义：批发指成批卖给商户，与零售（卖给个人消费者）相对，是该义项的反义词。", "银行": "银行是金融机构，与“零售”在任何义项上都不构成近义或反义关系。", "医院": "医院是诊疗场所，与“零售”在任何义项上都不构成近义或反义关系。", "花园": "花园是种植花草的地方，与“零售”在任何义项上都不构成近义或反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10514, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指将商品或服务卖给个人消费者，是商品流通的最终环节。", "primary_collocate": null, "pronunciation": "líng shòu", "ipa": "liŋ˧˥ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "联邦层面长期缺乏统一立法，但多个城市与州级行政区自主推行禁令，涵盖塑料吸管、外卖容器及零售包装等领域。", "target_word": "零售", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "一方面，大众零售市场依赖规模化生产的速溶咖啡与连锁咖啡店标准化产品；另一方面，精品咖啡运动的兴起推动了“从种子到杯子”的溯源理念，消费者愈发关注产地故事、处理工艺与风味谱系，进而反向影响原产地的种植实践与分级标准。", "target_word": "零售", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司的零售业务做得很好。", "target_word": "零售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "批发和零售的价格不一样。", "target_word": "零售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂不做零售，只做批发。", "target_word": "零售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家大型零售企业工作。", "target_word": "零售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络购物改变了零售市场的样子。", "target_word": "零售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "零售是把商品卖给顾客的最后一步。", "target_word": "零售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "零售行业需要很多店员和收银员。", "target_word": "零售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大学毕业后做了三年零售工作。", "target_word": "零售", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "零售业", "label": "复合词"}, {"form": "零售价", "label": "复合词"}, {"form": "零售商", "label": "复合词"}], "register": "书面", "sense_fingerprint": "零售：把商品或服务卖给个人消费者的流通最后环节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af392f55-520a-41c6-8a55-f0d8a216dfb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10514, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "零售", "is_correct": true, "explanation": "零售包装指面向个人消费者的小包装，与前文的塑料吸管、外卖容器同属消费端用品，句意相符。"}, {"text": "批发", "is_correct": false, "explanation": "语义：批发包装是面向商户的大宗包装，与前文列举的消费端用品不属于同一类。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能修饰“包装”，没有“天气包装”的说法，句意不通。"}, {"text": "利润", "is_correct": false, "explanation": "搭配：“利润”一般不用来修饰“包装”，没有“利润包装”这样的常见说法。"}], "explanations": {"零售": "零售包装指面向个人消费者的小包装，与前文的塑料吸管、外卖容器同属消费端用品，句意相符。", "批发": "语义：批发包装是面向商户的大宗包装，与前文列举的消费端用品不属于同一类。", "天气": "搭配：“天气”不能修饰“包装”，没有“天气包装”的说法，句意不通。", "利润": "搭配：“利润”一般不用来修饰“包装”，没有“利润包装”这样的常见说法。"}, "sentence_index": 0, "correct_answer": "零售"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这批货的零售对象主要是政府机构。", "explanation": "这里应该用〈销售〉。零售特指卖给个人消费者，政府机构属于团体买家，不能说零售对象。"}, {"text": "他们的主要业务是零售蔬菜给饭店。", "explanation": "这里应该用〈批发〉。零售面向个人消费者，卖给饭店这类商户要说批发。"}, {"text": "这家厂家长期零售汽车零件给维修公司。", "explanation": "这里应该用〈供应〉。零售面向个人消费者，维修公司是商户，长期向商户供货要说供应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "零售", "is_correct": true, "explanation": "零售市场指面向个人消费者的商品市场，与网络购物改变消费方式的语境相符。"}, {"text": "外汇", "is_correct": false, "explanation": "语义：外汇市场指货币兑换交易，与网络购物改变消费的语境无关。"}, {"text": "股票", "is_correct": false, "explanation": "语义：股票市场是证券交易场所，句中说的是商品的购买方式，两者不相干。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“时间市场”不是常用说法，“市场”前一般是商品或行业名称。"}], "explanations": {"零售": "零售市场指面向个人消费者的商品市场，与网络购物改变消费方式的语境相符。", "外汇": "语义：外汇市场指货币兑换交易，与网络购物改变消费的语境无关。", "股票": "语义：股票市场是证券交易场所，句中说的是商品的购买方式，两者不相干。", "时间": "搭配：“时间市场”不是常用说法，“市场”前一般是商品或行业名称。"}, "sentence_index": 6, "correct_answer": "零售"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂一次就零售了十万件衣服。", "explanation": "这里应该用〈批发〉。零售指按件或少量卖给个人消费者，一次卖出十万件属于大宗交易，要说批发。"}, {"text": "我们公司从市场零售了一批原材料回来。", "explanation": "这里应该用〈采购〉。零售是把商品卖给个人，不能指买进原料，买进要说采购。"}, {"text": "这家公司零售了一座工厂。", "explanation": "这里应该用〈转让〉。零售针对个人消费者的商品，整座工厂的产权转让要说转让，不能说零售。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司零售给了一家大型超市五百箱饮料。", "corrected_sentence": "我们公司批发给了一家大型超市五百箱饮料。", "error_description": "“零售”指卖给个人消费者，卖给超市这类商户要说“批发”，此句用“零售给超市”是义项错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种饼干的零售是三块钱。", "corrected_sentence": "这种饼干的零售价是三块钱。", "error_description": "“零售”作名词表示销售环节，不能单独表示价格，应说“零售价”。错误句漏掉了“价”字，表达不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
