INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10515, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指事物或生产达到较大的范围或规模，比如从少量变成大量。", "primary_collocate": null, "pronunciation": "guī mó huà", "ipa": "kwei̯˥ mwo˧˥ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "一方面，大众零售市场依赖规模化生产的速溶咖啡与连锁咖啡店标准化产品；另一方面，精品咖啡运动的兴起推动了“从种子到杯子”的溯源理念，消费者愈发关注产地故事、处理工艺与风味谱系，进而反向影响原产地的种植实践与分级标准。", "target_word": "规模化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家农场开始规模化种植蔬菜。", "target_word": "规模化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小工厂想规模化生产，需要更多的钱。", "target_word": "规模化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规模化养殖能降低成本。", "target_word": "规模化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种产品还没有规模化，所以价格很高。", "target_word": "规模化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用三年时间实现了规模化经营。", "target_word": "规模化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业规模化以后，农民的收入提高了。", "target_word": "规模化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的网店已经规模化了。", "target_word": "规模化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规模化生产让手机便宜了很多。", "target_word": "规模化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要想规模化，先要有稳定的客户。", "target_word": "规模化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "规模化生产", "label": "复合"}, {"form": "规模化经营", "label": "复合"}, {"form": "規模化", "label": "繁体"}], "register": "书面", "sense_fingerprint": "生产或经营从少量扩大到较大规模", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52a47307-49a6-4e93-9fed-15de8bc7b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10515, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规模化", "is_correct": true, "explanation": "正确：“规模化生产”指大批量、大范围地生产，与“大众零售市场依赖”的语境相符。"}, {"text": "个性化", "is_correct": false, "explanation": "语义：个性化是按每个人的需要单独设计，与“大众零售市场”的批量生产矛盾。"}, {"text": "定制", "is_correct": false, "explanation": "语义：定制是按顾客要求单独做，与“大众零售市场”的批量供应矛盾。"}, {"text": "精品化", "is_correct": false, "explanation": "搭配：“精品化生产”指做高端、小批量的产品，不能与“速溶咖啡”这种大众产品搭配。"}], "explanations": {"规模化": "正确：“规模化生产”指大批量、大范围地生产，与“大众零售市场依赖”的语境相符。", "个性化": "语义：个性化是按每个人的需要单独设计，与“大众零售市场”的批量生产矛盾。", "定制": "语义：定制是按顾客要求单独做，与“大众零售市场”的批量供应矛盾。", "精品化": "搭配：“精品化生产”指做高端、小批量的产品，不能与“速溶咖啡”这种大众产品搭配。"}, "sentence_index": 0, "correct_answer": "规模化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵小树两年就规模化了。", "explanation": "这里应该用〈长大〉。长大指生物生长变大；“规模化”指生产或经营的范围扩大，不用于树木的生长。"}, {"text": "他的个性一直在规模化。", "explanation": "这里应该用〈改变〉。改变指性格或状态发生转变；“规模化”指生产或经营的范围扩大，不用于人的性格。"}, {"text": "这间屋子的温度规模化了。", "explanation": "这里应该用〈升高〉。升高指温度等数值向上增加；“规模化”指生产或经营的范围扩大，不用于温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10515, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规模化", "is_correct": true, "explanation": "正确：“农业规模化以后”指农业生产扩大到较大规模，与“农民的收入提高了”的结果一致。"}, {"text": "萎缩", "is_correct": false, "explanation": "语义：萎缩是缩小、衰退，与“农民的收入提高了”的结果矛盾。"}, {"text": "荒废", "is_correct": false, "explanation": "语义：荒废是土地不再耕种，农业荒废后农民的收入不可能提高。"}, {"text": "繁殖", "is_correct": false, "explanation": "搭配：“繁殖”多用于生物，不能与“农业”组成“农业繁殖以后”这样的说法。"}], "explanations": {"规模化": "正确：“农业规模化以后”指农业生产扩大到较大规模，与“农民的收入提高了”的结果一致。", "萎缩": "语义：萎缩是缩小、衰退，与“农民的收入提高了”的结果矛盾。", "荒废": "语义：荒废是土地不再耕种，农业荒废后农民的收入不可能提高。", "繁殖": "搭配：“繁殖”多用于生物，不能与“农业”组成“农业繁殖以后”这样的说法。"}, "sentence_index": 6, "correct_answer": "规模化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条马路要向东规模化。", "explanation": "这里应该用〈延伸〉。延伸指向某个方向伸展；“规模化”指把小的生产或经营合成更大的规模，马路不能这样。"}, {"text": "他把这篇文章规模化了。", "explanation": "这里应该用〈扩写〉。扩写指增加文章的内容；“规模化”用于生产、经营的规模，不用于文章。"}, {"text": "我的小狗的体重正在规模化。", "explanation": "这里应该用〈增加〉。增加指数量或重量变多；“规模化”指生产或经营的范围扩大，不用于体重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10515, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们计划把养殖场规模化了。", "corrected_sentence": "他们计划把养殖场规模化。", "error_description": "时态错误：“计划”表示将来的打算，规模化还没有发生，不能在“规模化”后加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10515, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂规模化的很快。", "corrected_sentence": "这家工厂规模化得很快。", "error_description": "补语错误：动词后接表示程度的补语时要用“得”，不能用“的”。应说“规模化得很快”，不能说“规模化的很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
