INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10516, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指固体饮料等物质放入水中很容易溶解的性质。", "primary_collocate": null, "pronunciation": "sù róng", "ipa": "su˥˩ ɻʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "一方面，大众零售市场依赖规模化生产的速溶咖啡与连锁咖啡店标准化产品；另一方面，精品咖啡运动的兴起推动了“从种子到杯子”的溯源理念，消费者愈发关注产地故事、处理工艺与风味谱系，进而反向影响原产地的种植实践与分级标准。", "target_word": "速溶", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "早上我常喝一杯速溶咖啡。", "target_word": "速溶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种速溶奶茶用热水就能冲。", "target_word": "速溶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "速溶饮料很方便，出门也能带着。", "target_word": "速溶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一盒速溶茶。", "target_word": "速溶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "速溶咖啡放进水里，很快就化开了。", "target_word": "速溶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这包速溶燕麦片只要两分钟。", "target_word": "速溶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太喜欢速溶咖啡的味道。", "target_word": "速溶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室里放着很多速溶咖啡。", "target_word": "速溶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时，我总是带几包速溶咖啡。", "target_word": "速溶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "速溶咖啡", "label": "复合词"}, {"form": "速溶茶", "label": "复合词"}], "register": "通用", "sense_fingerprint": "速溶：固体饮料等放入水中很容易溶解的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d8d8829-6187-4938-b5a2-6292d29cf1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "速溶", "is_correct": true, "explanation": "正确：「速溶咖啡」指能很快溶于水的咖啡，符合大众零售、规模化生产的语境。"}, {"text": "昂贵", "is_correct": false, "explanation": "语义：「昂贵」与「大众零售」「规模化生产」的大众定位矛盾。"}, {"text": "雪白", "is_correct": false, "explanation": "体貌：咖啡不用「雪白」形容，与句中描述的产品语境不符。"}, {"text": "高端", "is_correct": false, "explanation": "语义：「高端」指面向少数人的产品，与「大众零售市场」矛盾。"}], "explanations": {"速溶": "正确：「速溶咖啡」指能很快溶于水的咖啡，符合大众零售、规模化生产的语境。", "昂贵": "语义：「昂贵」与「大众零售」「规模化生产」的大众定位矛盾。", "雪白": "体貌：咖啡不用「雪白」形容，与句中描述的产品语境不符。", "高端": "语义：「高端」指面向少数人的产品，与「大众零售市场」矛盾。"}, "sentence_index": 0, "correct_answer": "速溶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "速溶面很方便，出门也能带着。", "explanation": "这里应该用〈速食〉。「速溶」指粉末放入水中很快溶解，面条不能溶解，应说「速食面」。"}, {"text": "我用速溶给朋友寄了一个包裹。", "explanation": "这里应该用〈快递〉。「速溶」指粉末放入水中很快溶解，不能指寄送包裹的服务。"}, {"text": "这件衣服很速溶，洗完很快就干。", "explanation": "这里应该用〈速干〉。「速溶」指粉末溶于水，衣服不会溶解；「速干」才指很快干。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "速溶", "is_correct": true, "explanation": "正确：「这包速溶燕麦片只要两分钟」中，「速溶」说明燕麦片能快速冲泡，与「只要两分钟」吻合。"}, {"text": "鲜艳", "is_correct": false, "explanation": "体貌：「鲜艳」形容色彩，燕麦片不这样形容。"}, {"text": "透明", "is_correct": false, "explanation": "体貌：燕麦片不是透明的，「透明」与其外观不符。"}, {"text": "冰凉", "is_correct": false, "explanation": "语义：「冰凉」指温度低，与「只要两分钟」所表达的冲泡语境冲突。"}], "explanations": {"速溶": "正确：「这包速溶燕麦片只要两分钟」中，「速溶」说明燕麦片能快速冲泡，与「只要两分钟」吻合。", "鲜艳": "体貌：「鲜艳」形容色彩，燕麦片不这样形容。", "透明": "体貌：燕麦片不是透明的，「透明」与其外观不符。", "冰凉": "语义：「冰凉」指温度低，与「只要两分钟」所表达的冲泡语境冲突。"}, "sentence_index": 6, "correct_answer": "速溶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门速溶课只要两周就能学完。", "explanation": "这里应该用〈速成〉。「速溶」指粉末放入水中很快溶解，课程不能溶解；「速成」指很快学会或做成。"}, {"text": "速溶饺子放进锅里煮十分钟就能吃。", "explanation": "这里应该用〈速冻〉。「速溶」指粉末溶于水，饺子不能溶解；「速冻」指快速冷冻保存的食品。"}, {"text": "他用铅笔很快画了一张速溶。", "explanation": "这里应该用〈速写〉。「速溶」指粉末溶于水，不能指快速画成的画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一只速溶咖啡。", "corrected_sentence": "我买了一包速溶咖啡。", "error_description": "量词错误：「咖啡」应搭配量词「包」或「杯」等，不能用「只」。正确句为「我买了一包速溶咖啡。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了两包很速溶咖啡。", "corrected_sentence": "他买了两包速溶咖啡。", "error_description": "副词错误：「速溶」是修饰名词的类别性定语，不能受「很」修饰，应说「速溶咖啡」。正确句为「他买了两包速溶咖啡。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
