INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10517, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物之间相互连接、一环扣一环的关系或状态。", "primary_collocate": null, "pronunciation": "lián suǒ", "ipa": "ljɛn˧˥ swo˨˩˦", "syllable_count": 2, "sentences": [{"text": "全球供应链的各个环节之间存在紧密的连锁关系：一处港口停摆，便会层层传导至原材料价格、物流成本与终端零售价格，单个企业很难单独应对风险。", "target_word": "连锁", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这几个问题环环相扣，有连锁关系。", "target_word": "连锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究生态中的连锁关系。", "target_word": "连锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食物链上的生物彼此有连锁关系。", "target_word": "连锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场和工厂之间形成了连锁关系。", "target_word": "连锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几个环节之间有连锁关系，缺一不可。", "target_word": "连锁", "complexity_tier": "T3", "furigana": "zhè jǐ gè huánjié zhījiān yǒu liánsuǒ guānxì, quē yī bù kě。", "sentence_source": "generated"}, {"text": "这几种因素有连锁关系，改变一个就会影响全部。", "target_word": "连锁", "complexity_tier": "T3", "furigana": "zhè jǐ zhǒng yīnsù yǒu liánsuǒ guānxì, gǎibiàn yí gè jiù huì yǐngxiǎng quánbù。", "sentence_source": "generated"}, {"text": "各个问题之间存在连锁关系，不能分开处理。", "target_word": "连锁", "complexity_tier": "T3", "furigana": "gègè wèntí zhījiān cúnzài liánsuǒ guānxì, bùnéng fēnkāi chǔlǐ。", "sentence_source": "generated"}, {"text": "这些问题之间的连锁关系很复杂。", "target_word": "连锁", "complexity_tier": "T3", "furigana": "zhèxiē wèntí zhījiān de liánsuǒ guānxì hěn fùzá。", "sentence_source": "generated"}, {"text": "他想知道两件事有没有连锁关系。", "target_word": "连锁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "連鎖", "label": "繁体"}, {"form": "连锁关系", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物之间一环扣一环的连接关系或状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80f0202-2691-4b52-babe-45032a6cb8ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10517, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "孤立", "is_correct": false, "explanation": "语义：“孤立”指彼此不相关联，与“紧密”的关系相悖。"}, {"text": "连锁", "is_correct": true, "explanation": "连锁关系：环环相扣的关联，与“层层传导”的句意相合。"}, {"text": "独立", "is_correct": false, "explanation": "语义：“独立”指互不依赖，与“紧密”及“层层传导”的句意相悖。"}, {"text": "游牧", "is_correct": false, "explanation": "搭配：“游牧”修饰民族或生活方式，不修饰“关系”。"}], "explanations": {"孤立": "语义：“孤立”指彼此不相关联，与“紧密”的关系相悖。", "连锁": "连锁关系：环环相扣的关联，与“层层传导”的句意相合。", "独立": "语义：“独立”指互不依赖，与“紧密”及“层层传导”的句意相悖。", "游牧": "搭配：“游牧”修饰民族或生活方式，不修饰“关系”。"}, "sentence_index": 0, "correct_answer": "连锁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两个部门之间一直有工作连锁。", "explanation": "这里应该用〈联系〉。连锁关系指事物之间环环相扣的关联，一般的工作往来应说联系。"}, {"text": "亲情是家人之间的连锁。", "explanation": "这里应该用〈纽带〉。连锁关系指事物之间环环相扣的关联；情感上联结家人的东西应说纽带。"}, {"text": "两家的连锁持续了几十年。", "explanation": "这里应该用〈交往〉。连锁关系指事物环环相扣的关联；两家人长期往来应说交往。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07e277-5fc3-44cc-9af2-34f0f1118fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10517, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独立", "is_correct": false, "explanation": "语义：“独立”指互不依赖，与“改变一个就会影响全部”的相互影响相悖。"}, {"text": "分散", "is_correct": false, "explanation": "语义：“分散”指彼此不集中、不相关联，与“改变一个就会影响全部”的相互影响相悖。"}, {"text": "连锁", "is_correct": true, "explanation": "连锁：环环相扣的，修饰“关系”，符合“改变一个就会影响全部”的句意。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”多修饰信息、规则、过程，“透明关系”不成词组。"}], "explanations": {"独立": "语义：“独立”指互不依赖，与“改变一个就会影响全部”的相互影响相悖。", "分散": "语义：“分散”指彼此不集中、不相关联，与“改变一个就会影响全部”的相互影响相悖。", "连锁": "连锁：环环相扣的，修饰“关系”，符合“改变一个就会影响全部”的句意。", "透明": "搭配：“透明”多修饰信息、规则、过程，“透明关系”不成词组。"}, "sentence_index": 6, "correct_answer": "连锁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两组数据是一一连锁的。", "explanation": "这里应该用〈对应〉。“连锁”表示环环相扣，“一一”配合的应是“对应”，不说“一一连锁”。"}, {"text": "这两个词在词源上有很深的连锁。", "explanation": "这里应该用〈关联〉。连锁关系指事物环环相扣的关联；词源上的牵连应说关联。"}, {"text": "他们是多年的老连锁。", "explanation": "这里应该用〈交情〉。连锁关系指事物环环相扣的关联；多年的老朋友之间的情分应说交情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07e277-5fc3-44cc-9af2-34f0f1118fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10517, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两件事之间有连锁。", "corrected_sentence": "这两件事之间有连锁关系。", "error_description": "“连锁”作名词时通常须带“关系”；只说“有连锁”，语义不完整，不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07e277-5fc3-44cc-9af2-34f0f1118fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10517, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些环节之间有连锁了关系。", "corrected_sentence": "这些环节之间有连锁关系。", "error_description": "体标误用：“了”不能插在修饰语“连锁”与中心语“关系”之间；去掉“了”，应说“有连锁关系”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07e277-5fc3-44cc-9af2-34f0f1118fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
