INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10518, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "出售咖啡、茶饮及简餐的店铺。", "primary_collocate": null, "pronunciation": "kā fēi diàn", "ipa": "kʰa˥ feɪ˥ tiɛn˥˩", "syllable_count": 3, "sentences": [{"text": "一方面，大众零售市场依赖规模化生产的速溶咖啡与连锁咖啡店标准化产品；另一方面，精品咖啡运动的兴起推动了“从种子到杯子”的溯源理念，消费者愈发关注产地故事、处理工艺与风味谱系，进而反向影响原产地的种植实践与分级标准。", "target_word": "咖啡店", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我家旁边有一家咖啡店。", "target_word": "咖啡店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常去咖啡店看书。", "target_word": "咖啡店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家咖啡店的蛋糕很好吃。", "target_word": "咖啡店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在咖啡店工作了两年。", "target_word": "咖啡店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡店里放着轻松的音乐。", "target_word": "咖啡店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们约好在咖啡店见面。", "target_word": "咖啡店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡店的老板是个年轻人。", "target_word": "咖啡店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家咖啡店晚上九点关门。", "target_word": "咖啡店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想开一家小小的咖啡店。", "target_word": "咖啡店", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "咖啡店老板", "label": "复合词"}], "register": "通用", "sense_fingerprint": "咖啡店：出售咖啡、茶饮和简餐的店铺", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d8d8829-6187-4938-b5a2-6292d29cf1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10518, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咖啡店", "is_correct": true, "explanation": "符合语境：连锁咖啡店是售卖标准化咖啡产品的零售店铺。"}, {"text": "咖啡师", "is_correct": false, "explanation": "语义：咖啡师是从业的人，不是售卖标准化产品的商业场所，不能被「连锁」修饰。"}, {"text": "咖啡机", "is_correct": false, "explanation": "搭配：“连锁”修饰店铺，不能修饰“咖啡机”。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园不是售卖产品的零售渠道，与前句的零售市场语境不符。"}], "explanations": {"咖啡店": "符合语境：连锁咖啡店是售卖标准化咖啡产品的零售店铺。", "咖啡师": "语义：咖啡师是从业的人，不是售卖标准化产品的商业场所，不能被「连锁」修饰。", "咖啡机": "搭配：“连锁”修饰店铺，不能修饰“咖啡机”。", "公园": "语义：公园不是售卖产品的零售渠道，与前句的零售市场语境不符。"}, "sentence_index": 0, "correct_answer": "咖啡店"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上喝一杯咖啡店。", "explanation": "这里应该用〈咖啡〉。咖啡店指店铺，不能当饮品说“喝一杯”。"}, {"text": "他是咖啡店，每天做很多咖啡。", "explanation": "这里应该用〈咖啡师〉。咖啡店指店铺，不能指做咖啡的人。"}, {"text": "这件外套是咖啡店色的，很好看。", "explanation": "这里应该用〈咖啡色〉。咖啡店指店铺，不能用来指颜色，形容颜色要说咖啡色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "咖啡店", "is_correct": true, "explanation": "符合语境：咖啡店是可以约定见面的公共场所。"}, {"text": "老板", "is_correct": false, "explanation": "配价：“在”后面要接处所，“老板”是人，不能作见面的地点。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是商品，不是可以约定见面的场所。"}, {"text": "咖啡杯", "is_correct": false, "explanation": "语义：咖啡杯是器皿，不能作为见面的地点。"}], "explanations": {"咖啡店": "符合语境：咖啡店是可以约定见面的公共场所。", "老板": "配价：“在”后面要接处所，“老板”是人，不能作见面的地点。", "饮料": "语义：饮料是商品，不是可以约定见面的场所。", "咖啡杯": "语义：咖啡杯是器皿，不能作为见面的地点。"}, "sentence_index": 6, "correct_answer": "咖啡店"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天用咖啡店煮早饭。", "explanation": "这里应该用〈咖啡机〉。咖啡店是店铺，不能当器具用来煮东西。"}, {"text": "我每天坐咖啡店去上班。", "explanation": "这里应该用〈公交车〉。咖啡店是店铺，不能当交通工具坐。"}, {"text": "他穿着咖啡店去上班。", "explanation": "这里应该用〈外套〉。咖啡店是店铺，不能当衣服穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在街角看到一只新开的咖啡店。", "corrected_sentence": "我昨天在街角看到一家新开的咖啡店。", "error_description": "错误形式：“一只咖啡店”；正确形式：“一家咖啡店”。店铺用量词“家”，“只”用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末我们咖啡店聊天。", "corrected_sentence": "周末我们在咖啡店聊天。", "error_description": "错误形式：“我们咖啡店聊天”，表示地点的“咖啡店”前缺少“在”；正确形式：“在咖啡店聊天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
