INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10519, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指质量最好、最出色的物品或作品。", "primary_collocate": null, "pronunciation": "jīng pǐn", "ipa": "tɕiŋ˥ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "一方面，大众零售市场依赖规模化生产的速溶咖啡与连锁咖啡店标准化产品；另一方面，精品咖啡运动的兴起推动了“从种子到杯子”的溯源理念，消费者愈发关注产地故事、处理工艺与风味谱系，进而反向影响原产地的种植实践与分级标准。", "target_word": "精品", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家书店只卖精品，不卖普通的书。", "target_word": "精品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画是画家的精品，值很多钱。", "target_word": "精品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己最好的几件精品送给了博物馆。", "target_word": "精品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个展览里全是精品，没有一件差的。", "target_word": "精品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说这部电影是年度精品。", "target_word": "精品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们认真做每个零件，想做出精品。", "target_word": "精品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商场卖的都是精品，东西贵但质量好。", "target_word": "精品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说写得很用心，是一部精品。", "target_word": "精品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他收藏了很多古代瓷器精品。", "target_word": "精品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件精品", "label": "量词"}, {"form": "精品店", "label": "复合"}], "register": "通用", "sense_fingerprint": "质量最好、最出色的物品或作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d8d8829-6187-4938-b5a2-6292d29cf1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10519, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精品", "is_correct": true, "explanation": "符合语境：“精品咖啡”指品质高、讲究产地与工艺的咖啡。"}, {"text": "数码", "is_correct": false, "explanation": "搭配：「数码」指数字技术，不能修饰「咖啡运动」这种讲究产地与工艺的理念。"}, {"text": "速溶", "is_correct": false, "explanation": "搭配：“速溶”修饰咖啡产品，不能修饰“咖啡运动”。"}, {"text": "连锁", "is_correct": false, "explanation": "搭配：“连锁”修饰店铺，不能修饰“咖啡运动”。"}], "explanations": {"精品": "符合语境：“精品咖啡”指品质高、讲究产地与工艺的咖啡。", "数码": "搭配：「数码」指数字技术，不能修饰「咖啡运动」这种讲究产地与工艺的理念。", "速溶": "搭配：“速溶”修饰咖啡产品，不能修饰“咖啡运动”。", "连锁": "搭配：“连锁”修饰店铺，不能修饰“咖啡运动”。"}, "sentence_index": 0, "correct_answer": "精品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这批精品质量很差，没人要。", "explanation": "这里应该用〈次品〉。精品指质量最好、最出色的东西，与“质量很差”矛盾。"}, {"text": "回收站每天收很多精品。", "explanation": "这里应该用〈废品〉。回收站收的是废弃物，不是质量最好的东西，不能说成“精品”。"}, {"text": "他每天工作十个小时，精品很足。", "explanation": "这里应该用〈精力〉。精品指质量最好的物品或作品，不能指精力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10519, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精品", "is_correct": true, "explanation": "符合语境：“认真做”“想做出”与追求质量最好的东西一致。"}, {"text": "次品", "is_correct": false, "explanation": "语义：“认真做每个零件”的目标不是做出次品。"}, {"text": "废品", "is_correct": false, "explanation": "语义：“认真做”的目标不是做出废品。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：「垃圾」指无用的废弃物，与「认真做」「想做出」的目标相反。"}], "explanations": {"精品": "符合语境：“认真做”“想做出”与追求质量最好的东西一致。", "次品": "语义：“认真做每个零件”的目标不是做出次品。", "废品": "语义：“认真做”的目标不是做出废品。", "垃圾": "语义：「垃圾」指无用的废弃物，与「认真做」「想做出」的目标相反。"}, "sentence_index": 6, "correct_answer": "精品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛很有精品。", "explanation": "这里应该用〈精彩〉。精品指质量最好的物品或作品，不能用来形容比赛。"}, {"text": "垃圾桶里全是精品，应该扔掉。", "explanation": "这里应该用〈垃圾〉。精品指质量最好的东西，不能说成要扔掉的垃圾。"}, {"text": "这家店卖的精品全是假货，质量最差。", "explanation": "这里应该用〈次品〉。精品指质量最好的东西，与“假货”和“质量最差”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10519, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店里有一位难得的精品，我想买下来。", "corrected_sentence": "店里有一件难得的精品，我想买下来。", "error_description": "错误形式：“一位精品”；正确形式：“一件精品”。“位”用于人，“件”用于物品或作品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10519, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了三精品，送给了朋友。", "corrected_sentence": "他买了三件精品，送给了朋友。", "error_description": "错误形式：“三精品”，数词后缺少量词；正确形式：“三件精品”。精品是物品，用量词“件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
