INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10523, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "追本溯源，探寻事物的根源或起源。", "primary_collocate": null, "pronunciation": "sù yuán", "ipa": "su˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "一方面，大众零售市场依赖规模化生产的速溶咖啡与连锁咖啡店标准化产品；另一方面，精品咖啡运动的兴起推动了“从种子到杯子”的溯源理念，消费者愈发关注产地故事、处理工艺与风味谱系，进而反向影响原产地的种植实践与分级标准。", "target_word": "溯源", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "近年来，一些国际组织与私营企业开始推动数字化农业解决方案，如卫星遥感监测、区块链溯源与移动支付平台，以增强供应链透明度与韧性。", "target_word": "溯源", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们要溯源，才能知道问题是从哪里来的。", "target_word": "溯源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词很古老，可以溯源到两千年前。", "target_word": "溯源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出了问题，我们要先溯源，找到是哪一步错了。", "target_word": "溯源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家正在为这批坏牛奶溯源。", "target_word": "溯源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要弄清这个习俗，得先溯源。", "target_word": "溯源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生们已经溯源过，病是从农场开始的。", "target_word": "溯源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了查清问题的根源，工厂开始溯源。", "target_word": "溯源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢研究家谱，一直溯源到祖先。", "target_word": "溯源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "溯源了", "label": "体标"}, {"form": "溯源过", "label": "体标"}, {"form": "追根溯源", "label": "复合"}], "register": "书面", "sense_fingerprint": "追本溯源，探寻事物的根源或起源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d8d8829-6187-4938-b5a2-6292d29cf1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10523, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "溯源", "is_correct": true, "explanation": "正确：溯源指追查事物的源头，修饰「理念」时表示从种子到杯子的追根溯源思路。"}, {"text": "冲泡", "is_correct": false, "explanation": "语义：冲泡是咖啡最后的制作步骤，与「从种子到杯子」的源头追查不符。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙是加工环节，并不表示追查源头的理念，与句意不符。"}, {"text": "采摘", "is_correct": false, "explanation": "搭配：采摘指摘取作物，不能用来修饰「理念」。"}], "explanations": {"溯源": "正确：溯源指追查事物的源头，修饰「理念」时表示从种子到杯子的追根溯源思路。", "冲泡": "语义：冲泡是咖啡最后的制作步骤，与「从种子到杯子」的源头追查不符。", "烘焙": "语义：烘焙是加工环节，并不表示追查源头的理念，与句意不符。", "采摘": "搭配：采摘指摘取作物，不能用来修饰「理念」。"}, "sentence_index": 0, "correct_answer": "溯源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小狗在草地上溯源蝴蝶。", "explanation": "这里应该用〈追逐〉。溯源是追查事物的根源，追赶蝴蝶要用追逐。"}, {"text": "妈妈在房间里溯源我的书包。", "explanation": "这里应该用〈查找〉。溯源指追溯事物的起源，找丢失的物品要用查找。"}, {"text": "孩子在操场上溯源奔跑。", "explanation": "溯源是追查事物的根源，不表示跑动；这里应去掉〈溯源〉，直接说「奔跑」即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10523, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "溯源", "is_correct": true, "explanation": "正确：「得先溯源」指先追查习俗的来源，与「弄清」的目的相合。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：庆祝表示欢庆，与弄清习俗来源的语境无关。"}, {"text": "表演", "is_correct": false, "explanation": "语义：表演指展示节目，不能用来指弄清习俗的来源。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：放弃意味着不再弄清，与句中「弄清」的目的相悖。"}], "explanations": {"溯源": "正确：「得先溯源」指先追查习俗的来源，与「弄清」的目的相合。", "庆祝": "语义：庆祝表示欢庆，与弄清习俗来源的语境无关。", "表演": "语义：表演指展示节目，不能用来指弄清习俗的来源。", "放弃": "语义：放弃意味着不再弄清，与句中「弄清」的目的相悖。"}, "sentence_index": 6, "correct_answer": "溯源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在公园里溯源了一场比赛。", "explanation": "溯源指追查事物的根源，观看比赛应说观看，不能用溯源。"}, {"text": "妈妈每天溯源我的作业，检查有没有错。", "explanation": "溯源指追查事物的根源，批改作业应说〈批改〉，不能用溯源。"}, {"text": "这顿饭很好吃，我们在溯源吃饭。", "explanation": "溯源指追查根源，不能用来指进食，这里应该用〈吃〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10523, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件衣服的来历，我们得一层层的溯源。", "corrected_sentence": "这件衣服的来历，我们得一层层地溯源。", "error_description": "结构助词错误：修饰动词「溯源」的状语应用「地」，不用「的」，说「一层层地溯源」。正确句为「这件衣服的来历，我们得一层层地溯源。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10523, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员已经溯源了过这次事故。", "corrected_sentence": "研究人员已经溯源过这次事故。", "error_description": "体标错误：「了」与「过」不能同时用在同一个动词后，只保留「过」，应说「溯源过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
