INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10525, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词。表示在原有基础上程度进一步加深，相当于‘更加’、‘越加’的意思。", "primary_collocate": null, "pronunciation": "yù fā", "ipa": "y˥˩ fa˥", "syllable_count": 2, "sentences": [{"text": "一方面，大众零售市场依赖规模化生产的速溶咖啡与连锁咖啡店标准化产品；另一方面，精品咖啡运动的兴起推动了“从种子到杯子”的溯源理念，消费者愈发关注产地故事、处理工艺与风味谱系，进而反向影响原产地的种植实践与分级标准。", "target_word": "愈发", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "天黑了，雨下得愈发大了。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了老师的话，他愈发有信心了。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气越来越冷，她愈发想家。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了这么多年，奶奶愈发爱笑。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜深了，街上愈发安静。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他越练越好，对游泳愈发喜欢。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到孩子进步，妈妈愈发高兴。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路越走越远，我们愈发累了。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，花园里愈发漂亮。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "在原有基础上程度进一步加深，相当于更加、越加", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d8d8829-6187-4938-b5a2-6292d29cf1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10525, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "愈发", "is_correct": true, "explanation": "正确：愈发表示程度进一步加深，与“关注”搭配，说明消费者的关注日益增强。"}, {"text": "不再", "is_correct": false, "explanation": "语义：不再与前文兴起、推动的增长趋势相矛盾。"}, {"text": "从未", "is_correct": false, "explanation": "语义：从未与“兴起推动”后消费者关注增强的句意相反。"}, {"text": "白白", "is_correct": false, "explanation": "搭配：白白表示徒然，与“关注产地故事”这样的正面关注不搭配。"}], "explanations": {"愈发": "正确：愈发表示程度进一步加深，与“关注”搭配，说明消费者的关注日益增强。", "不再": "语义：不再与前文兴起、推动的增长趋势相矛盾。", "从未": "语义：从未与“兴起推动”后消费者关注增强的句意相反。", "白白": "搭配：白白表示徒然，与“关注产地故事”这样的正面关注不搭配。"}, "sentence_index": 0, "correct_answer": "愈发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天我愈发去了学校。", "explanation": "这里应该用〈终于〉。愈发表示程度逐步加深，不能修饰“去了”这样的一次性动作，表示事情最后实现要用终于。"}, {"text": "他愈发打破了那只碗。", "explanation": "这里应该用〈居然〉。愈发表示程度逐步加深，不能用于一次性的完成动作，表示出乎意料地发生要用居然。"}, {"text": "书包里愈发有一支笔。", "explanation": "这里应该用〈还〉。愈发表示程度加深，不能用于存现句，表示额外存在要用还。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10525, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "愈发", "is_correct": true, "explanation": "正确：愈发与“越练越好”的递进语气相合，表示对游泳的喜欢程度加深。"}, {"text": "从不", "is_correct": false, "explanation": "语义：从不与“越练越好”的变化趋势相反，不合句意。"}, {"text": "差点", "is_correct": false, "explanation": "语义：差点表示几乎发生而未发生，不能表示喜欢程度随练习加深，与「越练越好」不合。"}, {"text": "不必", "is_correct": false, "explanation": "语义：不必表示没有必要，与“越练越好”带来的兴趣增长不符。"}], "explanations": {"愈发": "正确：愈发与“越练越好”的递进语气相合，表示对游泳的喜欢程度加深。", "从不": "语义：从不与“越练越好”的变化趋势相反，不合句意。", "差点": "语义：差点表示几乎发生而未发生，不能表示喜欢程度随练习加深，与「越练越好」不合。", "不必": "语义：不必表示没有必要，与“越练越好”带来的兴趣增长不符。"}, "sentence_index": 6, "correct_answer": "愈发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的身高愈发保持不变。", "explanation": "这里应该用〈始终〉。愈发表示程度逐步加深，与“保持不变”的含义相矛盾，表示一直不变要用始终。"}, {"text": "妈妈把碗愈发洗完了。", "explanation": "这里应该用〈都〉。愈发表示程度逐步加深，不能用于表示全部完成的把字句，表示全部完成要用都。"}, {"text": "他愈发刚进门就走了。", "explanation": "这里应去掉〈愈发〉，直接说「刚进门就走了」。愈发表示程度逐步加深，不能修饰刚进门就走这样的瞬间动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10525, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这段时间他的学习兴趣很愈发浓厚。", "corrected_sentence": "这段时间他的学习兴趣愈发浓厚。", "error_description": "错误形式：很愈发浓厚；正确形式：愈发浓厚。“愈发”本身已表示程度进一步加深，不能再与程度副词“很”并用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10525, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨水越下越大，路面愈发得湿滑。", "corrected_sentence": "雨水越下越大，路面愈发湿滑。", "error_description": "错误形式：愈发得湿滑；正确形式：愈发湿滑。“愈发”是状语，后面不能加“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
