INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10527, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指真实的或虚构的、用来讲述的事情。", "primary_collocate": null, "pronunciation": "gù shi", "ipa": "ku˥˩ ʂʅ", "syllable_count": 2, "sentences": [{"text": "睡觉前，妈妈给我讲了一个有趣的故事。", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有很多动物的故事。", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷最爱给孩子们讲过去的故事。", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事很感人，我看哭了。", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一个关于爱情的故事。", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请同学们上台讲一个自己的故事。", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影的故事发生在一百年前的上海。", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事的结局让大家都很意外。", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们安静地听老师讲故事。", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天晚上都给女儿读一个故事。", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个故事", "label": "量词"}, {"form": "一则故事", "label": "量词"}, {"form": "故事书", "label": "复合"}], "register": "中性", "sense_fingerprint": "用来讲述的事情，真实或虚构；讲故事、听故事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddebd6cf-17ed-4b0a-b28c-0c938fbac07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10527, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "故事", "is_correct": true, "explanation": "正确答案：听到的是“故事”（gù shi），指讲述的事情。"}, {"text": "古诗", "is_correct": false, "explanation": "古诗（gǔshī）与故事（gù shi）声调不同，意思是古代的诗。"}, {"text": "股市", "is_correct": false, "explanation": "股市（gǔshì）与故事（gù shi）声调不同，意思是股票市场。"}, {"text": "古史", "is_correct": false, "explanation": "古史（gǔshǐ）与故事（gù shi）声调不同，意思是古代的历史。"}], "explanations": {"故事": "正确答案：听到的是“故事”（gù shi），指讲述的事情。", "古诗": "古诗（gǔshī）与故事（gù shi）声调不同，意思是古代的诗。", "股市": "股市（gǔshì）与故事（gù shi）声调不同，意思是股票市场。", "古史": "古史（gǔshǐ）与故事（gù shi）声调不同，意思是古代的历史。"}, "sentence_index": null, "correct_answer": "故事"}, "level_3": {"options": [{"text": "歌", "is_correct": false, "explanation": "搭配：“讲”用于故事、道理，不用于歌曲，唱歌要说“唱”。"}, {"text": "故事", "is_correct": true, "explanation": "正确：“故事”指讲述的事情，与“讲”搭配，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然状况，不是可以讲述的内容。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是供孩子玩耍的物品，不是可以讲述的内容，句意不通。"}], "explanations": {"歌": "搭配：“讲”用于故事、道理，不用于歌曲，唱歌要说“唱”。", "故事": "正确：“故事”指讲述的事情，与“讲”搭配，符合句意。", "天气": "语义：天气是自然状况，不是可以讲述的内容。", "玩具": "语义：玩具是供孩子玩耍的物品，不是可以讲述的内容，句意不通。"}, "sentence_index": 0, "correct_answer": "故事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个故事造成了三人受伤。", "explanation": "这里应该用〈事件〉。“造成伤亡”说的是真实发生的事件或事故，故事只是讲述的内容，不能造成伤亡。"}, {"text": "这个故事很宽敞。", "explanation": "这里应该用〈房间〉。“宽敞”形容空间大，故事是讲述的内容，没有空间，不能说宽敞。"}, {"text": "他把这些故事交给法官，当作证据。", "explanation": "这里应该用〈录音〉。证据需要可核实，故事是讲述的内容，不能当作证据。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10527, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "故事", "is_correct": true, "explanation": "正确答案：听到的是“故事”（gù shi），指讲述的事情。"}, {"text": "护士", "is_correct": false, "explanation": "护士（hùshi）与故事（gù shi）声母不同（h 与 g），意思是护理病人的人。"}, {"text": "古时", "is_correct": false, "explanation": "古时（gǔshí）与故事（gù shi）声调不同，意思是古代。"}, {"text": "古式", "is_correct": false, "explanation": "古式（gǔshì）与故事（gù shi）声调不同，意思是古代的样式。"}], "explanations": {"故事": "正确答案：听到的是“故事”（gù shi），指讲述的事情。", "护士": "护士（hùshi）与故事（gù shi）声母不同（h 与 g），意思是护理病人的人。", "古时": "古时（gǔshí）与故事（gù shi）声调不同，意思是古代。", "古式": "古式（gǔshì）与故事（gù shi）声调不同，意思是古代的样式。"}, "sentence_index": null, "correct_answer": "故事"}, "level_3": {"options": [{"text": "演员", "is_correct": false, "explanation": "配价：“发生”的主语须是事件，“演员”是人，不能作为发生的主体。"}, {"text": "票价", "is_correct": false, "explanation": "语义：票价是金额，不能在时间和地点上“发生”。"}, {"text": "故事", "is_correct": true, "explanation": "正确：“故事”指讲述的事情，可以“发生”在某个时间地点，符合句意。"}, {"text": "导演", "is_correct": false, "explanation": "配价：“发生”需要事件作主语，“导演”是人，不能充当。"}], "explanations": {"演员": "配价：“发生”的主语须是事件，“演员”是人，不能作为发生的主体。", "票价": "语义：票价是金额，不能在时间和地点上“发生”。", "故事": "正确：“故事”指讲述的事情，可以“发生”在某个时间地点，符合句意。", "导演": "配价：“发生”需要事件作主语，“导演”是人，不能充当。"}, "sentence_index": 6, "correct_answer": "故事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生治好了这个故事。", "explanation": "这里应该用〈病〉。“治好”的对象是疾病，故事是讲述的内容，不能治好。"}, {"text": "他安装了这个故事。", "explanation": "这里应该用〈软件〉。“安装”的对象是软件或设备，故事是讲述的内容，不能安装。"}, {"text": "这项工作的故事很充足。", "explanation": "这里应该用〈预算〉。“充足”可以形容预算、资金，故事不能说充足。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10527, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶给我们讲了一本古老的故事。", "corrected_sentence": "奶奶给我们讲了一个古老的故事。", "error_description": "错误在量词。“故事”的量词应为“个”或“则”，“本”用于书籍，不能用于故事。应说“一个古老的故事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10527, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们最爱听这些动物故事们。", "corrected_sentence": "孩子们最爱听这些动物故事。", "error_description": "错误在“故事”后加了“们”。“故事”是名词，“们”只用于指人的名词，这里不能加。应说“这些动物故事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
