INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10528, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对原材料或半成品进行加工、制造或处理的技术方法和过程。", "primary_collocate": null, "pronunciation": "chǔ lǐ gōng yì", "ipa": "ʈʂʰu˨˩˦ li˨˩˦ kʊŋ˥ i˥˩", "syllable_count": 4, "sentences": [{"text": "一方面，大众零售市场依赖规模化生产的速溶咖啡与连锁咖啡店标准化产品；另一方面，精品咖啡运动的兴起推动了“从种子到杯子”的溯源理念，消费者愈发关注产地故事、处理工艺与风味谱系，进而反向影响原产地的种植实践与分级标准。", "target_word": "处理工艺", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种茶的处理工艺很特别。", "target_word": "处理工艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的处理工艺会让咖啡味道不一样。", "target_word": "处理工艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂正在改进布料的处理工艺。", "target_word": "处理工艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种木头用了新的处理工艺，不容易坏。", "target_word": "处理工艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的处理工艺已经很成熟。", "target_word": "处理工艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡豆的处理工艺有水洗和日晒两种。", "target_word": "处理工艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学习金属表面的处理工艺。", "target_word": "处理工艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的处理工艺能让产品更安全。", "target_word": "处理工艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问这个零件用的是什么处理工艺？", "target_word": "处理工艺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种处理工艺", "label": "量词"}, {"form": "一套处理工艺", "label": "量词"}], "register": "书面", "sense_fingerprint": "对原材料或半成品加工处理的技术方法和过程；多用于茶、咖啡、金属等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddebd6cf-17ed-4b0a-b28c-0c938fbac07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10528, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音乐", "is_correct": false, "explanation": "语义：音乐与咖啡的产地、风味谱系无关，不是消费者关注的内容，句意不通。"}, {"text": "作者", "is_correct": false, "explanation": "语义：作者是人，不是消费者关注的加工方法。"}, {"text": "处理工艺", "is_correct": true, "explanation": "正确：“处理工艺”指加工方法，与“风味谱系”并列，符合句意。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是报酬，消费者关注的不是工资。"}], "explanations": {"音乐": "语义：音乐与咖啡的产地、风味谱系无关，不是消费者关注的内容，句意不通。", "作者": "语义：作者是人，不是消费者关注的加工方法。", "处理工艺": "正确：“处理工艺”指加工方法，与“风味谱系”并列，符合句意。", "工资": "语义：工资是报酬，消费者关注的不是工资。"}, "sentence_index": 0, "correct_answer": "处理工艺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂招聘了很多处理工艺。", "explanation": "这里应该用〈工人〉。招聘招的是人员，处理工艺是做东西的方法，不能招聘。"}, {"text": "工厂维修了处理工艺。", "explanation": "这里应该用〈设备〉。“维修”的对象是设备或机器，处理工艺是做东西的方法，不能维修。"}, {"text": "这家公司每月要交很多处理工艺。", "explanation": "这里应该用〈电费〉。“交”的对象是费用，处理工艺不是钱，不能交。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10528, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：价格是金额，不能分成水洗和日晒两种，句意不通。"}, {"text": "处理工艺", "is_correct": true, "explanation": "正确：“处理工艺”指加工方法，“有水洗和日晒两种”符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不分水洗与日晒这样的加工方法。"}, {"text": "产地", "is_correct": false, "explanation": "语义：产地是地点，不是加工方法，不能说有水洗和日晒两种。"}], "explanations": {"价格": "语义：价格是金额，不能分成水洗和日晒两种，句意不通。", "处理工艺": "正确：“处理工艺”指加工方法，“有水洗和日晒两种”符合句意。", "颜色": "语义：颜色不分水洗与日晒这样的加工方法。", "产地": "语义：产地是地点，不是加工方法，不能说有水洗和日晒两种。"}, "sentence_index": 6, "correct_answer": "处理工艺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在处理工艺教书。", "explanation": "这里应该用〈学校〉。教书需要在学校或教育场所，处理工艺是方法，不能当作地点。"}, {"text": "这项处理工艺要在月底付清。", "explanation": "这里应该用〈货款〉。“付清”的对象是钱款或账目，处理工艺是做东西的方法，不能付清。"}, {"text": "他下班后去处理工艺吃饭。", "explanation": "这里应该用〈饭店〉。“去吃饭”需要去场所，处理工艺是方法，不能去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10528, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种布料有一座独特的处理工艺。", "corrected_sentence": "这种布料有一套独特的处理工艺。", "error_description": "错误在量词。“处理工艺”的量词应为“套”或“种”，“座”用于山、桥、建筑等大型物体，不能用于工艺。应说“一套独特的处理工艺”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10528, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们花了三年研究这些处理工艺们。", "corrected_sentence": "他们花了三年研究这些处理工艺。", "error_description": "错误在“处理工艺”后加了“们”。“们”只用于指人的名词，“处理工艺”不能加。应说“这些处理工艺”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
