INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10530, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "指方向或顺序与原来的、通常的相反。", "primary_collocate": null, "pronunciation": "fǎn xiàng", "ipa": "fan˨˩ ɕjaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "一方面，大众零售市场依赖规模化生产的速溶咖啡与连锁咖啡店标准化产品；另一方面，精品咖啡运动的兴起推动了“从种子到杯子”的溯源理念，消费者愈发关注产地故事、处理工艺与风味谱系，进而反向影响原产地的种植实践与分级标准。", "target_word": "反向", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "价格上涨会反向影响销量。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消费者的反馈反向影响了生产计划。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个决定反向影响了很多人。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的反应反向影响父母。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生的意见也能反向影响老师。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电流反向流动时，灯会灭。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮子反向转动，车就往后退。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把开关反向拨一下。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他反向思考问题，找到了办法。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "以相反的方向或顺序（副词，修饰动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b4bed82-fa15-4388-b52a-548bab14ed95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10530, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "反向", "is_correct": true, "explanation": "正确：反向（fǎn xiàng）意思是方向或顺序与通常相反。"}, {"text": "返乡", "is_correct": false, "explanation": "声调不同：第一音节都是 fǎn，第二音节 xiāng（第一声）与 xiàng（第四声）声调不同，返乡意思是回到家乡。"}, {"text": "反响", "is_correct": false, "explanation": "声调不同：第二音节 xiǎng（第三声）与 xiàng（第四声）声调不同，反响意思是回声或反应。"}, {"text": "饭香", "is_correct": false, "explanation": "声调不同：fàn（第四声）与 fǎn（第三声）不同，xiāng（第一声）与 xiàng（第四声）也不同，饭香意思是饭的香气。"}, {"text": "翻箱", "is_correct": false, "explanation": "声调不同：fān（第一声）与 fǎn（第三声）不同，xiāng（第一声）与 xiàng（第四声）也不同，翻箱意思是翻找箱子。"}], "explanations": {"反向": "正确：反向（fǎn xiàng）意思是方向或顺序与通常相反。", "返乡": "声调不同：第一音节都是 fǎn，第二音节 xiāng（第一声）与 xiàng（第四声）声调不同，返乡意思是回到家乡。", "反响": "声调不同：第二音节 xiǎng（第三声）与 xiàng（第四声）声调不同，反响意思是回声或反应。", "饭香": "声调不同：fàn（第四声）与 fǎn（第三声）不同，xiāng（第一声）与 xiàng（第四声）也不同，饭香意思是饭的香气。", "翻箱": "声调不同：fān（第一声）与 fǎn（第三声）不同，xiāng（第一声）与 xiàng（第四声）也不同，翻箱意思是翻找箱子。"}, "sentence_index": null, "correct_answer": "反向"}, "level_3": {"options": [{"text": "反向", "is_correct": true, "explanation": "正确：“反向”作状语，表示消费者的影响方向与常规相反，与“进而”的因果链相符。"}, {"text": "事先", "is_correct": false, "explanation": "语义：“事先”指在某事之前，与“进而”表示随后发生的先后关系相矛盾。"}, {"text": "随便", "is_correct": false, "explanation": "语域：“随便”口语化，与这段书面论述的语体不协调。"}, {"text": "偶然", "is_correct": false, "explanation": "语义：“偶然”指碰巧发生，与前文“愈发关注”的有意过程不符。"}], "explanations": {"反向": "正确：“反向”作状语，表示消费者的影响方向与常规相反，与“进而”的因果链相符。", "事先": "语义：“事先”指在某事之前，与“进而”表示随后发生的先后关系相矛盾。", "随便": "语域：“随便”口语化，与这段书面论述的语体不协调。", "偶然": "语义：“偶然”指碰巧发生，与前文“愈发关注”的有意过程不符。"}, "sentence_index": 0, "correct_answer": "反向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我本来以为他会生气，他反向笑了。", "explanation": "这里应该用〈反过来〉。“反向”修饰可以有方向的动作，表示出人意料的转折要用“反过来”。"}, {"text": "没想到他一说完，我反向更高兴了。", "explanation": "这里应该用〈反倒〉。“反向”说动作的方向相反，表示与预期相反的心理状态要用“反倒”。"}, {"text": "他越解释，我反向越不信。", "explanation": "这里应该用〈反而〉。“反向”表示方向相反，表示与预期相反的结果要用“反而”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10530, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反向", "is_correct": true, "explanation": "正确：“反向流动”指电流方向与常规相反，此时灯会灭，与句意相符。"}, {"text": "正常地", "is_correct": false, "explanation": "语义：“正常地”指按常规方式流动，与“灯会灭”的结果不合理。"}, {"text": "事后", "is_correct": false, "explanation": "语义：“事后”指事情发生之后，不能用来描述电流的流动方式。"}, {"text": "随意", "is_correct": false, "explanation": "搭配：“随意”多修饰行为，不能说“电流随意流动”。"}], "explanations": {"反向": "正确：“反向流动”指电流方向与常规相反，此时灯会灭，与句意相符。", "正常地": "语义：“正常地”指按常规方式流动，与“灯会灭”的结果不合理。", "事后": "语义：“事后”指事情发生之后，不能用来描述电流的流动方式。", "随意": "搭配：“随意”多修饰行为，不能说“电流随意流动”。"}, "sentence_index": 6, "correct_answer": "反向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两台机器的功率反向。", "explanation": "这里应该用〈悬殊〉。“反向”修饰动作，表示方向或顺序相反；功率之间只有大小的差别，差别很大要说“悬殊”。"}, {"text": "这所学校的学费与那所反向。", "explanation": "这里应该用〈相差〉。“反向”指方向或顺序相反，学费之间的数额差别要说“相差”。"}, {"text": "我们的意见反向，谁也不让谁。", "explanation": "这里应该用〈相反〉。“反向”不用于描述意见，观点对立要说“相反”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10530, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项政策会反向了影响农民的收入。", "corrected_sentence": "这项政策会反向影响农民的收入。", "error_description": "错误：“反向了影响”。副词“反向”后不能直接带“了”，应删去“了”；正确为“这项政策会反向影响农民的收入”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10530, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他反向了推门，门就开了。", "corrected_sentence": "他反向推门，门就开了。", "error_description": "错误：“反向了推门”。“了”不能直接接在副词“反向”后面。正确为“他反向推门，门就开了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10532, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10532, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10532, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按照一定标准将事物分成不同的等级或层次。", "primary_collocate": null, "pronunciation": "fēn jí", "ipa": "fən˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "一方面，大众零售市场依赖规模化生产的速溶咖啡与连锁咖啡店标准化产品；另一方面，精品咖啡运动的兴起推动了“从种子到杯子”的溯源理念，消费者愈发关注产地故事、处理工艺与风味谱系，进而反向影响原产地的种植实践与分级标准。", "target_word": "分级", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "学校按水平给学生分级。", "target_word": "分级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院会先给病人分级，再安排治疗。", "target_word": "分级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套英语书按难度分级。", "target_word": "分级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影要分级，小孩不能看太吓人的。", "target_word": "分级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把员工的工作按难度分级，再分配给不同的人。", "target_word": "分级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把地区按人口分级。", "target_word": "分级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试成绩出来后，老师给同学们分级。", "target_word": "分级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳班已经按年龄分级了。", "target_word": "分级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的河水按干净程度分级。", "target_word": "分级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分级了", "label": "体标"}, {"form": "分级管理", "label": "复合"}], "register": "中性", "sense_fingerprint": "按一定标准把事物分成等级或层次；学校、医院、电影等的分级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddebd6cf-17ed-4b0a-b28c-0c938fbac07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10532, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分级", "is_correct": true, "explanation": "正确答案。分级：按照一定标准把事物分成不同的等级。"}, {"text": "分机", "is_correct": false, "explanation": "fēn jī（第一声）与 fēn jí（第二声）只有第二音节声调不同，分机指电话的分机号，意思不同。"}, {"text": "分歧", "is_correct": false, "explanation": "qí 与 jí 声母不同（q 与 j），声调相同，分歧指意见不一致。"}, {"text": "分析", "is_correct": false, "explanation": "xī 与 jí 声母不同（x 与 j），声调也不同（第一声与第二声），分析指把事物拆开研究。"}, {"text": "分期", "is_correct": false, "explanation": "qī 与 jí 声母不同（q 与 j），且声调为第一声，分期指分成几个阶段进行。"}, {"text": "粉剂", "is_correct": false, "explanation": "fěn（第三声）与 fēn（第一声）声调不同，jì（第四声）与 jí（第二声）声调也不同，粉剂指粉末状的药剂。"}], "explanations": {"分级": "正确答案。分级：按照一定标准把事物分成不同的等级。", "分机": "fēn jī（第一声）与 fēn jí（第二声）只有第二音节声调不同，分机指电话的分机号，意思不同。", "分歧": "qí 与 jí 声母不同（q 与 j），声调相同，分歧指意见不一致。", "分析": "xī 与 jí 声母不同（x 与 j），声调也不同（第一声与第二声），分析指把事物拆开研究。", "分期": "qī 与 jí 声母不同（q 与 j），且声调为第一声，分期指分成几个阶段进行。", "粉剂": "fěn（第三声）与 fēn（第一声）声调不同，jì（第四声）与 jí（第二声）声调也不同，粉剂指粉末状的药剂。"}, "sentence_index": null, "correct_answer": "分级"}, "level_3": {"options": [{"text": "分级", "is_correct": true, "explanation": "正确答案。“分级标准”指按等级划分事物所依据的标准，与上文的种植实践、处理工艺相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：句中谈的是咖啡的种植与处理，“唱歌标准”与之无关，句意不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞标准”与咖啡产地和风味谱系毫无关联，句子说不通。"}, {"text": "欢呼", "is_correct": false, "explanation": "搭配：“欢呼”是一次性的动作，不能用来修饰“标准”。"}], "explanations": {"分级": "正确答案。“分级标准”指按等级划分事物所依据的标准，与上文的种植实践、处理工艺相符。", "唱歌": "语义：句中谈的是咖啡的种植与处理，“唱歌标准”与之无关，句意不通。", "跳舞": "语义：“跳舞标准”与咖啡产地和风味谱系毫无关联，句子说不通。", "欢呼": "搭配：“欢呼”是一次性的动作，不能用来修饰“标准”。"}, "sentence_index": 0, "correct_answer": "分级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "图书馆把书按种类分级。", "explanation": "这里应该用〈分类〉。分级强调按等级高低区分，按种类区分要用分类。"}, {"text": "我们把红豆和绿豆分级，放进两个盒子。", "explanation": "这里应该用〈分开〉。分级指按标准分成等级，只是把不同的东西分开时不用分级。"}, {"text": "经理把任务分级给每个人。", "explanation": "这里应该用〈分配〉。分级是按标准划分等级，把任务派给人要用分配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10532, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "分级", "is_correct": true, "explanation": "正确答案。分级：按照一定标准把事物分成不同的等级。"}, {"text": "分局", "is_correct": false, "explanation": "jú（第二声）与 jí（第二声）韵母不同（ü 与 i），声调相同，分局指机构下属的分支机构。"}, {"text": "分子", "is_correct": false, "explanation": "zǐ（第三声）与 jí（第二声）声母不同（z 与 j），且声调不同，分子指构成物质的基本单位。"}, {"text": "分支", "is_correct": false, "explanation": "zhī（第一声）与 jí（第二声）声母不同（zh 与 j），且声调不同，分支指从主体分出的部分。"}, {"text": "愤激", "is_correct": false, "explanation": "fèn（第四声）与 fēn（第一声）声调不同，jī（第一声）与 jí（第二声）声调也不同，愤激指激动愤怒。"}], "explanations": {"分级": "正确答案。分级：按照一定标准把事物分成不同的等级。", "分局": "jú（第二声）与 jí（第二声）韵母不同（ü 与 i），声调相同，分局指机构下属的分支机构。", "分子": "zǐ（第三声）与 jí（第二声）声母不同（z 与 j），且声调不同，分子指构成物质的基本单位。", "分支": "zhī（第一声）与 jí（第二声）声母不同（zh 与 j），且声调不同，分支指从主体分出的部分。", "愤激": "fèn（第四声）与 fēn（第一声）声调不同，jī（第一声）与 jí（第二声）声调也不同，愤激指激动愤怒。"}, "sentence_index": null, "correct_answer": "分级"}, "level_3": {"options": [{"text": "分级", "is_correct": true, "explanation": "正确答案。“按人口分级”指按人口数量把地区划分为不同等级。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”不能用于按人口划分地区，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与按人口给地区定等级无关，句子说不通。"}, {"text": "浇", "is_correct": false, "explanation": "搭配：“浇”的对象通常是植物或土地，不能说“浇地区”。"}], "explanations": {"分级": "正确答案。“按人口分级”指按人口数量把地区划分为不同等级。", "喝": "语义：“喝”不能用于按人口划分地区，句意不通。", "吃": "语义：“吃”与按人口给地区定等级无关，句子说不通。", "浇": "搭配：“浇”的对象通常是植物或土地，不能说“浇地区”。"}, "sentence_index": 6, "correct_answer": "分级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师把试卷分级给同学们。", "explanation": "这里应该用〈分发〉。分级是按标准划分等级，把东西发给别人要用分发。"}, {"text": "我们分级不出这两只小狗有什么不同。", "explanation": "这里应该用〈分辨〉。分级是按标准划分等级，辨认两只狗的不同要用分辨。"}, {"text": "油和水会分级。", "explanation": "这里应该用〈分离〉。分级指按标准划分等级，液体互不相融而分开要用分离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医院先病人分级，再安排治疗。", "corrected_sentence": "医院先把病人分级，再安排治疗。", "error_description": "“把”字缺失：“分级”的受事“病人”需要用“把”字提到动词前，写成“先病人分级”不符合汉语语序。正确形式为“先把病人分级”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批橘子被工人按大小的分级了。", "corrected_sentence": "这批橘子被工人按大小分级了。", "error_description": "多加“的”：“按大小”作状语修饰动词“分级”，中间不能加“的”，写成“按大小的分级”变成名词短语，不能再接“了”。正确形式为“按大小分级了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10534, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降级", "is_correct": true, "explanation": "正确答案。降级指降低等级，与“升级”表示的等级向上变化正相反，是反义词。"}, {"text": "保持", "is_correct": false, "explanation": "“保持”指维持原状，与等级变化无关，不是“升级”的反义词。"}, {"text": "休息", "is_correct": false, "explanation": "“休息”指停下来歇息，与等级的升降无关，不是“升级”的反义词。"}, {"text": "出发", "is_correct": false, "explanation": "“出发”指动身前往某处，与等级的升降无关，不是“升级”的反义词。"}], "correct_answer": "降级", "explanations": {"降级": "正确答案。降级指降低等级，与“升级”表示的等级向上变化正相反，是反义词。", "保持": "“保持”指维持原状，与等级变化无关，不是“升级”的反义词。", "休息": "“休息”指停下来歇息，与等级的升降无关，不是“升级”的反义词。", "出发": "“出发”指动身前往某处，与等级的升降无关，不是“升级”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10534, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降级", "is_correct": true, "explanation": "正确答案。降级指降低等级，与“升级”表示的等级向上变化正相反，是反义词。"}, {"text": "复习", "is_correct": false, "explanation": "“复习”指重新学习已学过的内容，与等级的升降无关，不是“升级”的反义词。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”指交换意见，与等级的升降无关，不是“升级”的反义词。"}, {"text": "等待", "is_correct": false, "explanation": "“等待”指停留到某时刻，与等级的升降无关，不是“升级”的反义词。"}], "correct_answer": "降级", "explanations": {"降级": "正确答案。降级指降低等级，与“升级”表示的等级向上变化正相反，是反义词。", "复习": "“复习”指重新学习已学过的内容，与等级的升降无关，不是“升级”的反义词。", "讨论": "“讨论”指交换意见，与等级的升降无关，不是“升级”的反义词。", "等待": "“等待”指停留到某时刻，与等级的升降无关，不是“升级”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10534, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指事物从较低等级或标准提高到更高等级或标准。", "primary_collocate": null, "pronunciation": "shēng jí", "ipa": "ʂɤŋ˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "我的手机系统昨天升级了。", "target_word": "升级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游戏玩到十级，你的角色会自动升级。", "target_word": "升级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件需要升级，不然用不了。", "target_word": "升级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的设备升级以后，检查快多了。", "target_word": "升级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的关系从朋友升级成了恋人。", "target_word": "升级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店升级后，客人越来越多。", "target_word": "升级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机提醒我，软件可以升级了。", "target_word": "升级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过几年努力，工厂的技术升级了。", "target_word": "升级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会员卡升级以后，可以打八折。", "target_word": "升级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络升级时，大家暂时不能上网。", "target_word": "升级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "升级了", "label": "体标（了）"}, {"form": "升级过", "label": "体标（过）"}, {"form": "升级版", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物自身等级或标准提高（不及物）：系统升级、角色升级、关系升级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddebd6cf-17ed-4b0a-b28c-0c938fbac07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10534, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "升级", "is_correct": true, "explanation": "正确答案。升级：事物从较低等级或标准提高到更高等级或标准。"}, {"text": "生计", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，生计指谋生的办法。"}, {"text": "省级", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，省级指省一级的层次。"}, {"text": "生气", "is_correct": false, "explanation": "qì 与 jí 声母不同（q 与 j），声调也不同，生气指发怒。"}, {"text": "生机", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，生机指生命力。"}], "explanations": {"升级": "正确答案。升级：事物从较低等级或标准提高到更高等级或标准。", "生计": "jì（第四声）与 jí（第二声）声调不同，生计指谋生的办法。", "省级": "shěng（第三声）与 shēng（第一声）声调不同，省级指省一级的层次。", "生气": "qì 与 jí 声母不同（q 与 j），声调也不同，生气指发怒。", "生机": "jī（第一声）与 jí（第二声）声调不同，生机指生命力。"}, "sentence_index": null, "correct_answer": "升级"}, "level_3": {"options": [{"text": "升级", "is_correct": true, "explanation": "正确答案。“系统昨天升级了”表示系统从较低版本提高到较高版本。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物、身体等，不能说“洗系统”。"}, {"text": "熟悉", "is_correct": false, "explanation": "语义：系统不能“熟悉”，句意是系统的等级提高，与“熟悉”不符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”只用于生物，系统不能“吃”。"}], "explanations": {"升级": "正确答案。“系统昨天升级了”表示系统从较低版本提高到较高版本。", "洗": "搭配：“洗”的对象是衣物、身体等，不能说“洗系统”。", "熟悉": "语义：系统不能“熟悉”，句意是系统的等级提高，与“熟悉”不符。", "吃": "语义：“吃”只用于生物，系统不能“吃”。"}, "sentence_index": 0, "correct_answer": "升级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家医院的占地面积升级了。", "explanation": "这里应该用〈扩大〉。升级指事物从较低等级提高到更高等级，面积的增大要用扩大。"}, {"text": "他的汉语词汇数量升级了很多。", "explanation": "这里应该用〈增加〉。升级指等级或标准的提高，词汇数量的增多要用增加。"}, {"text": "他的身高这一年升级了不少。", "explanation": "这里应该用〈长〉。升级指等级或标准的提高，身高的增加要用长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10534, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "升级", "is_correct": true, "explanation": "正确答案。升级：事物从较低等级或标准提高到更高等级或标准。"}, {"text": "生息", "is_correct": false, "explanation": "xī（第一声）与 jí（第二声）声母不同（x 与 j），声调也不同，生息指繁衍、休养。"}, {"text": "生意", "is_correct": false, "explanation": "yì（第四声）与 jí（第二声）声母不同（零声母与 j），声调也不同，生意指买卖。"}, {"text": "省际", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，jì（第四声）与 jí（第二声）声调也不同，省际指各省之间。"}], "explanations": {"升级": "正确答案。升级：事物从较低等级或标准提高到更高等级或标准。", "生息": "xī（第一声）与 jí（第二声）声母不同（x 与 j），声调也不同，生息指繁衍、休养。", "生意": "yì（第四声）与 jí（第二声）声母不同（零声母与 j），声调也不同，生意指买卖。", "省际": "shěng（第三声）与 shēng（第一声）声调不同，jì（第四声）与 jí（第二声）声调也不同，省际指各省之间。"}, "sentence_index": null, "correct_answer": "升级"}, "level_3": {"options": [{"text": "升级", "is_correct": true, "explanation": "正确答案。“软件可以升级了”表示软件可以提高到新版本。"}, {"text": "唱", "is_correct": false, "explanation": "语义：软件不能“唱”，句中是在提醒可以更新，句意不通。"}, {"text": "浇", "is_correct": false, "explanation": "搭配：“浇”用于浇水、浇灌，不能与“软件”搭配。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”的对象是食物或物体，不能说“切软件”。"}], "explanations": {"升级": "正确答案。“软件可以升级了”表示软件可以提高到新版本。", "唱": "语义：软件不能“唱”，句中是在提醒可以更新，句意不通。", "浇": "搭配：“浇”用于浇水、浇灌，不能与“软件”搭配。", "切": "搭配：“切”的对象是食物或物体，不能说“切软件”。"}, "sentence_index": 6, "correct_answer": "升级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "物价升级了。", "explanation": "这里应该用〈上涨〉。升级指等级向上提高，价格的上升要用上涨。"}, {"text": "产量升级了。", "explanation": "这里应该用〈增加〉。升级指等级或版本的提高，数量变多要用增加。"}, {"text": "气温升级了。", "explanation": "这里应该用〈升高〉。升级指事物等级向上提高，气温的上升要用升高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家网站昨晚把升级了。", "corrected_sentence": "这家网站昨晚升级了。", "error_description": "多用“把”：“把”后面必须有宾语，这里“把”后直接接“升级了”，缺少对象。句中是网站自身升级，不需要“把”。正确形式为“这家网站昨晚升级了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的职位从助理升级了经理。", "corrected_sentence": "她的职位从助理升级成了经理。", "error_description": "漏掉“成”：“升级”是不及物动词，表示变成更高的等级，后面要接“成”引出结果，写成“升级了经理”不通。正确形式为“从助理升级成了经理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
