INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10535, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10535, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指商品生产国与消费国之间直接进行的贸易，不通过第三国转手。", "primary_collocate": null, "pronunciation": "zhí jiē mào yì", "ipa": "ʈʂʅ˧˥ tɕjɛ˥ maʊ˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "这种消费升级不仅重塑了贸易结构，也催生了直接贸易、合同农业等新型合作模式，试图缩短供应链层级，提高生产者议价能力。", "target_word": "直接贸易", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "两国之间进行直接贸易，不用第三国转手。", "target_word": "直接贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直接贸易可以让商品更便宜。", "target_word": "直接贸易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国和巴西开展了直接贸易。", "target_word": "直接贸易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "直接贸易减少了中间商，价格更低。", "target_word": "直接贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家多做直接贸易，减少经第三国中转。", "target_word": "直接贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国签了协议，扩大直接贸易。", "target_word": "直接贸易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生产国和消费国之间的直接贸易越来越多。", "target_word": "直接贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直接贸易不通过第三国，成本比较低。", "target_word": "直接贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多农民希望通过直接贸易把茶叶卖到国外。", "target_word": "直接贸易", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "直接貿易", "label": "繁体"}], "register": "书面", "sense_fingerprint": "生产国与消费国之间不经第三国转手的贸易", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddebd6cf-17ed-4b0a-b28c-0c938fbac07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10535, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直接贸易", "is_correct": true, "explanation": "“直接贸易”指不经第三国转手的贸易，与“催生了……新型合作模式”的语境相符。"}, {"text": "银行存款", "is_correct": false, "explanation": "语义：银行存款不是一种合作模式，不能与“合同农业”并列为“新型合作模式”。"}, {"text": "生活水平", "is_correct": false, "explanation": "搭配：“催生”搭配的是新出现的事物，“生活水平”不能被催生为合作模式。"}, {"text": "天气预报", "is_correct": false, "explanation": "语义：天气预报是信息服务，不是合作模式，句意不通。"}], "explanations": {"直接贸易": "“直接贸易”指不经第三国转手的贸易，与“催生了……新型合作模式”的语境相符。", "银行存款": "语义：银行存款不是一种合作模式，不能与“合同农业”并列为“新型合作模式”。", "生活水平": "搭配：“催生”搭配的是新出现的事物，“生活水平”不能被催生为合作模式。", "天气预报": "语义：天气预报是信息服务，不是合作模式，句意不通。"}, "sentence_index": 0, "correct_answer": "直接贸易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这批货经香港直接贸易到美国。", "explanation": "这里应该用〈转口贸易〉。直接贸易不经第三国转手，货物经香港中转，应说转口贸易。"}, {"text": "这家商店的直接贸易都在国内完成，没有涉及外国。", "explanation": "这里应该用〈国内贸易〉。直接贸易指两国之间不经第三国的贸易，只在国内完成的买卖不属于直接贸易。"}, {"text": "两国通过第三方进行直接贸易。", "explanation": "这里应该用〈间接贸易〉。直接贸易不经第三方转手，“通过第三方”应说间接贸易。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10535, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直接贸易", "is_correct": true, "explanation": "“扩大直接贸易”搭配通顺，“扩大”的对象是贸易，句意完整。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被“扩大”，与“签了协议”的语境不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能被“扩大”，句意不通。"}, {"text": "作风", "is_correct": false, "explanation": "搭配：“扩大”搭配的是规模、范围、贸易等，不能搭配“作风”。"}], "explanations": {"直接贸易": "“扩大直接贸易”搭配通顺，“扩大”的对象是贸易，句意完整。", "天气": "语义：天气不能被“扩大”，与“签了协议”的语境不通。", "桌子": "语义：桌子不能被“扩大”，句意不通。", "作风": "搭配：“扩大”搭配的是规模、范围、贸易等，不能搭配“作风”。"}, "sentence_index": 6, "correct_answer": "直接贸易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们和国内的工厂做直接贸易，不涉及外国买家。", "explanation": "这里应该用〈国内贸易〉。直接贸易是两国之间的贸易，与国内工厂的买卖不属于直接贸易。"}, {"text": "这批货经第三国过境，做的是直接贸易。", "explanation": "这里应该用〈过境贸易〉。货物经第三国过境属于过境贸易，直接贸易不经第三国，二者不能互换。"}, {"text": "我们做的是直接贸易，要经过很多中间商。", "explanation": "这里应该用〈间接贸易〉。直接贸易不经中间商，句中说“要经过很多中间商”，应说间接贸易。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10535, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司去年做了一只直接贸易。", "corrected_sentence": "这家公司去年做了一笔直接贸易。", "error_description": "量词错误：「只」用于动物等，贸易应用「笔」，正确说法是「做了一笔直接贸易」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10535, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国之间的直接贸易越来越多过。", "corrected_sentence": "两国之间的直接贸易越来越多了。", "error_description": "体标错误：表示变化的结果应用「了」，「越来越多过」不成立，正确说法是「越来越多了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
