INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10539, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物按照一定标准划分出的不同等级或层次。", "primary_collocate": null, "pronunciation": "céng jí", "ipa": "tsʰɤŋ˧˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这种消费升级不仅重塑了贸易结构，也催生了直接贸易、合同农业等新型合作模式，试图缩短供应链层级，提高生产者议价能力。", "target_word": "层级", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司的管理层级太多，做事很慢。", "target_word": "层级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校减少了管理层级，办事更快了。", "target_word": "层级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这个组织里，每个层级都有自己的工作。", "target_word": "层级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "层级越多，信息传递得越慢。", "target_word": "层级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府的行政层级分为省、市、县。", "target_word": "层级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "军队有严格的层级，下级要听上级的。", "target_word": "层级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张图清楚地画出了公司的层级。", "target_word": "层级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "食物链分成几个层级，草在最下面。", "target_word": "层级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板想把公司的层级从五层减到三层。", "target_word": "层级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "层级结构", "label": "复合"}, {"form": "层级关系", "label": "复合"}], "register": "书面", "sense_fingerprint": "组织、制度或体系中按标准划分的等级层次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98f4a8b1-54f9-4af0-bf82-5bf023832828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10539, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "层级", "is_correct": true, "explanation": "层级（céng jí）：按一定标准划分出的等级层次，是正确答案。"}, {"text": "曾经", "is_correct": false, "explanation": "第二音节 jí 与 jīng 韵母不同（i 与 ing），声调也不同；意思是“以前”。"}, {"text": "城际", "is_correct": false, "explanation": "第一音节声母 c 与 ch 不同，第二音节声调不同（jì）；意思是城市之间的。"}, {"text": "乘积", "is_correct": false, "explanation": "第一音节声母 c 与 ch 不同，第二音节声调不同（jī）；意思是数学中的乘积。"}], "explanations": {"层级": "层级（céng jí）：按一定标准划分出的等级层次，是正确答案。", "曾经": "第二音节 jí 与 jīng 韵母不同（i 与 ing），声调也不同；意思是“以前”。", "城际": "第一音节声母 c 与 ch 不同，第二音节声调不同（jì）；意思是城市之间的。", "乘积": "第一音节声母 c 与 ch 不同，第二音节声调不同（jī）；意思是数学中的乘积。"}, "sentence_index": null, "correct_answer": "层级"}, "level_3": {"options": [{"text": "层级", "is_correct": true, "explanation": "正确。“缩短供应链层级”指减少供应链中间的环节层次，搭配自然。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：供应链没有颜色，“缩短颜色”无法成立。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“缩短”不与“性格”搭配，缩短的一般是距离、时间或层级。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，不适合这段书面化的经济分析。"}], "explanations": {"层级": "正确。“缩短供应链层级”指减少供应链中间的环节层次，搭配自然。", "颜色": "语义：供应链没有颜色，“缩短颜色”无法成立。", "性格": "搭配：“缩短”不与“性格”搭配，缩短的一般是距离、时间或层级。", "玩意儿": "语域：“玩意儿”是口语说法，不适合这段书面化的经济分析。"}, "sentence_index": 0, "correct_answer": "层级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的制作层级很简单，一看就会。", "explanation": "这里应该用〈步骤〉。“层级”指上下等级，说明先后顺序要用“步骤”。"}, {"text": "这个项目的层级很快，一个月就做完了。", "explanation": "这里应该用〈进度〉。“层级”指按标准划分的等级，不表示推进的快慢，快慢要用“进度”。"}, {"text": "这杯水的层级很高，别直接喝。", "explanation": "这里应该用〈温度〉。“层级”指按标准划分的等级，不表示冷热程度，冷热要用“温度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10539, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "层级", "is_correct": true, "explanation": "层级（céng jí）：按一定标准划分出的等级层次，是正确答案。"}, {"text": "成绩", "is_correct": false, "explanation": "第一音节声母 c 与 ch 不同，第二音节声调不同（jì）；意思是考试或工作的成绩。"}, {"text": "能级", "is_correct": false, "explanation": "第一音节 céng 与 néng 声母不同（c 与 n），声调相同；意思是能量的等级，是物理学术语。"}, {"text": "承接", "is_correct": false, "explanation": "第一音节声母 c 与 ch 不同，第二音节 jí 与 jiē 的韵母和声调都不同；意思是承担或接续。"}, {"text": "乘机", "is_correct": false, "explanation": "第一音节声母 c 与 ch 不同，第二音节声调不同（jī）；意思是趁着机会。"}], "explanations": {"层级": "层级（céng jí）：按一定标准划分出的等级层次，是正确答案。", "成绩": "第一音节声母 c 与 ch 不同，第二音节声调不同（jì）；意思是考试或工作的成绩。", "能级": "第一音节 céng 与 néng 声母不同（c 与 n），声调相同；意思是能量的等级，是物理学术语。", "承接": "第一音节声母 c 与 ch 不同，第二音节 jí 与 jiē 的韵母和声调都不同；意思是承担或接续。", "乘机": "第一音节声母 c 与 ch 不同，第二音节声调不同（jī）；意思是趁着机会。"}, "sentence_index": null, "correct_answer": "层级"}, "level_3": {"options": [{"text": "层级", "is_correct": true, "explanation": "正确。“严格的层级”指军队中上下分明的等级，搭配自然。"}, {"text": "味道", "is_correct": false, "explanation": "语义：军队的制度没有味道，“严格的味道”不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以严格规定的制度，句子不通。"}, {"text": "家伙", "is_correct": false, "explanation": "语域：“家伙”是口语，指人或东西，不能作为军队制度的书面说法。"}], "explanations": {"层级": "正确。“严格的层级”指军队中上下分明的等级，搭配自然。", "味道": "语义：军队的制度没有味道，“严格的味道”不通。", "天气": "语义：天气不是可以严格规定的制度，句子不通。", "家伙": "语域：“家伙”是口语，指人或东西，不能作为军队制度的书面说法。"}, "sentence_index": 6, "correct_answer": "层级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板想把公司的层级从五条减到三条。", "explanation": "这里应该用〈层〉。〈条〉用于细长的东西，不能用来计量层级。"}, {"text": "老板想把公司的层级从五只减到三只。", "explanation": "这里应该用〈层〉。〈只〉用于动物或成对物品中的一个，不能用来计量层级。"}, {"text": "老板想把公司的层级从五本减到三本。", "explanation": "这里应该用〈层〉。〈本〉用于书籍，不能用来计量层级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10539, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司有三条管理层级。", "corrected_sentence": "这家公司有三个管理层级。", "error_description": "“层级”的量词应用“个”，不能用“条”（“条”用于细长的东西）。写作：这家公司有三个管理层级。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10539, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司按职位高低划分了几个层级们。", "corrected_sentence": "这家公司按职位高低划分了几个层级。", "error_description": "“层级”是无生命名词，不能加后缀“们”表示复数；“们”只用于指人的名词。写作：这家公司按职位高低划分了几个层级。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
