INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10541, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生产者指从事商品生产、创造产品或提供服务的人或组织。", "primary_collocate": null, "pronunciation": "shēng chǎn zhě", "ipa": "ʂɤŋ˥ ʈʂʰan˨˩˦ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "该立法不仅体现对生产者的延伸责任要求，更推动产品设计向可循环模式转型，形成“污染者付费”的制度逻辑。", "target_word": "生产者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种消费升级不仅重塑了贸易结构，也催生了直接贸易、合同农业等新型合作模式，试图缩短供应链层级，提高生产者议价能力。", "target_word": "生产者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这一链条上的每一个环节，都在不断重新定义生产者与消费者之间的经济与道德关系。", "target_word": "生产者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这位生产者每天都检查产品质量。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产者要对食品安全负责。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民是粮食的生产者。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产者把产品卖给商店。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的生产者会认真听顾客的意见。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂是全国最大的牛奶生产者。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产者和消费者都希望价格合理。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "生产者们", "label": "复数"}], "register": "书面", "sense_fingerprint": "生产者：从事生产、创造产品或提供服务的人或组织，与消费者相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af392f55-520a-41c6-8a55-f0d8a216dfb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10541, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生产者", "is_correct": true, "explanation": "“生产者”指生产商品、提供服务的一方，句中指承担延伸责任的主体，句意相符。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众是观看的人，不承担产品设计与制度责任，与句意不符。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人与产品设计、制度责任无关，句中的责任要求不可能针对病人。"}, {"text": "厂房", "is_correct": false, "explanation": "配价：“责任要求”的对象应是人或组织，厂房不能作为责任的承担者。"}], "explanations": {"生产者": "“生产者”指生产商品、提供服务的一方，句中指承担延伸责任的主体，句意相符。", "观众": "语义：观众是观看的人，不承担产品设计与制度责任，与句意不符。", "病人": "语义：病人与产品设计、制度责任无关，句中的责任要求不可能针对病人。", "厂房": "配价：“责任要求”的对象应是人或组织，厂房不能作为责任的承担者。"}, "sentence_index": 0, "correct_answer": "生产者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台新机器是这家工厂的生产者，每天能做两千个面包。", "explanation": "这里应该用〈生产设备〉。生产者指从事生产的人或组织，机器应说〈生产设备〉。"}, {"text": "这个想法是这次项目的生产者。", "explanation": "这里应该用〈来源〉。生产者指生产商品或服务的人或组织，想法不是生产者，应说〈来源〉。"}, {"text": "这次事故的生产者是我的朋友李华。", "explanation": "这里应该用〈责任人〉。生产者指生产商品或服务的人或组织，事故不是产品，不能说生产者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10541, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生产者", "is_correct": true, "explanation": "“生产者”是制造并出售产品的一方，与句中“卖给商店”的语境相符。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”不能作为买卖的卖方，句意不通。"}, {"text": "警察", "is_correct": false, "explanation": "语义：警察不承担产品买卖，与句意无关。"}, {"text": "游客", "is_correct": false, "explanation": "配价：“卖”的主语应是能出售商品的人或组织，游客一般不作卖方。"}], "explanations": {"生产者": "“生产者”是制造并出售产品的一方，与句中“卖给商店”的语境相符。", "月亮": "语义：“月亮”不能作为买卖的卖方，句意不通。", "警察": "语义：警察不承担产品买卖，与句意无关。", "游客": "配价：“卖”的主语应是能出售商品的人或组织，游客一般不作卖方。"}, "sentence_index": 6, "correct_answer": "生产者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道工序是整条流水线的生产者。", "explanation": "这里应该用〈环节〉。生产者指从事生产的人或组织，工序应说〈环节〉。"}, {"text": "这把刀是厨房里最好的生产者。", "explanation": "这里应该用〈工具〉。生产者指人或组织，刀是工具，不能说生产者。"}, {"text": "这笔钱是村里最重要的生产者。", "explanation": "这里应该用〈来源〉。生产者指生产商品或服务的人或组织，钱不是生产者，应说〈来源〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10541, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这三只生产者都签了环保协议。", "corrected_sentence": "这三位生产者都签了环保协议。", "error_description": "“生产者”指人时量词应用“位”或“个”，不能用“只”。“只”一般用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10541, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一带有五条水果生产者。", "corrected_sentence": "这一带有五个水果生产者。", "error_description": "量词错误：“条”用于细长的东西，“生产者”指人或组织，应用“个”或“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10542, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10542, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10542, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "买卖双方就商品或服务的价格进行协商、讨价还价。", "primary_collocate": null, "pronunciation": "yì jià", "ipa": "i˥˩ tɕja˥˩", "syllable_count": 2, "sentences": [{"text": "这种消费升级不仅重塑了贸易结构，也催生了直接贸易、合同农业等新型合作模式，试图缩短供应链层级，提高生产者议价能力。", "target_word": "议价", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在这个市场，议价是很常见的事。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店老板不接受议价。", "target_word": "议价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过一小时议价，双方终于说好了价格。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议价需要耐心，也需要了解行情。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司很擅长议价，常常能买到便宜货。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方的议价进行得很顺利。", "target_word": "议价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在大商场里，一般没有议价。", "target_word": "议价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅游区的议价常常很激烈。", "target_word": "议价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在议价中少花了五百块。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "议价能力", "label": "复合"}, {"form": "議價", "label": "繁体"}], "register": "中性", "sense_fingerprint": "买卖双方就价格协商这一交易环节（名词用法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddebd6cf-17ed-4b0a-b28c-0c938fbac07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10542, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "议价", "is_correct": true, "explanation": "正确：议价，指买卖双方就价格进行协商。"}, {"text": "衣架", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是衣服架子。"}, {"text": "一家", "is_correct": false, "explanation": "yī 与 yì、jiā 与 jià 声调都不同，意思是一个家庭。"}, {"text": "意见", "is_correct": false, "explanation": "jiàn 与 jià 韵尾不同（多一个 n），意思是看法。"}], "explanations": {"议价": "正确：议价，指买卖双方就价格进行协商。", "衣架": "yī（第一声）与 yì（第四声）声调不同，意思是衣服架子。", "一家": "yī 与 yì、jiā 与 jià 声调都不同，意思是一个家庭。", "意见": "jiàn 与 jià 韵尾不同（多一个 n），意思是看法。"}, "sentence_index": null, "correct_answer": "议价"}, "level_3": {"options": [{"text": "议价", "is_correct": true, "explanation": "“提高生产者议价能力”是固定搭配，指生产者在价格协商中的能力。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温能力”不成立，与“生产者”的语境无关。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：“噪音能力”没有意义，句意不通。"}, {"text": "色调", "is_correct": false, "explanation": "搭配：“色调能力”不是常用搭配，不能用于说明生产者的谈判能力。"}], "explanations": {"议价": "“提高生产者议价能力”是固定搭配，指生产者在价格协商中的能力。", "体温": "语义：“体温能力”不成立，与“生产者”的语境无关。", "噪音": "语义：“噪音能力”没有意义，句意不通。", "色调": "搭配：“色调能力”不是常用搭配，不能用于说明生产者的谈判能力。"}, "sentence_index": 0, "correct_answer": "议价"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国经过一个月议价，终于签订了和平协议。", "explanation": "这里应该用〈谈判〉。议价专指买卖双方讨价还价，不能用于政治协议。"}, {"text": "学生们对这份报告议价了很久，最后没有结论。", "explanation": "这里应该用〈讨论〉。议价专指买卖双方商量价格，讨论报告应说讨论，不能说议价。"}, {"text": "这次会议的第三个议价是预算问题。", "explanation": "这里应该用〈议题〉。议价指买卖双方商量价格，会议的讨论事项应说议题，不能说议价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10542, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "议价", "is_correct": true, "explanation": "“双方的议价进行得很顺利”中，议价指买卖双方的价格协商，搭配通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以“进行”的活动，句意不通。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“进行得很顺利”说的是活动过程，行李不能这样搭配。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：“饭菜进行得很顺利”没有意义，与买卖无关。"}], "explanations": {"议价": "“双方的议价进行得很顺利”中，议价指买卖双方的价格协商，搭配通顺。", "天气": "语义：天气不是可以“进行”的活动，句意不通。", "行李": "搭配：“进行得很顺利”说的是活动过程，行李不能这样搭配。", "饭菜": "语义：“饭菜进行得很顺利”没有意义，与买卖无关。"}, "sentence_index": 6, "correct_answer": "议价"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在公园里，他们一起议价，玩得很开心。", "explanation": "这里应该用〈游玩〉。议价是买卖双方商量价格，去公园玩不涉及价格，不能说议价。"}, {"text": "这篇论文要先议价，然后才能提交答辩。", "explanation": "这里应该用〈评审〉。议价是买卖双方商量价格，论文的审阅应说评审，不能说议价。"}, {"text": "学校每学期的议价是一百块。", "explanation": "这里应该用〈学费〉。学费是学校规定的固定费用，不能说议价，议价是买卖双方商量价格的过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经过一条议价，双方说好了价格。", "corrected_sentence": "经过一次议价，双方说好了价格。", "error_description": "量词错误：议价按「次」计算，「条」用于长条形事物，不能用于议价，正确说法是「经过一次议价」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很议价，常常能买到便宜货。", "corrected_sentence": "他很会议价，常常能买到便宜货。", "error_description": "漏用「会」：「很会议价」表示擅长议价，漏掉「会」则「很议价」不成立，应说「很会议价」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
