INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10545, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指事物内部各组成部分之间相互联系、组合的方式或特征。", "primary_collocate": null, "pronunciation": "jié gòu xìng", "ipa": "tɕiɛ˧˥ kou˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "然而，该体系仍面临多重结构性挑战。", "target_word": "结构性", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "这种“即穿即弃”的文化不仅放大了生产端的环境负荷，也暴露出全球供应链在可持续性治理上的结构性缺陷。", "target_word": "结构性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司的问题是结构性的，不是暂时的。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个结构性问题，不能只靠钱解决。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有结构性失业的问题。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济出现了结构性变化。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两种产品的差异主要是结构性的。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，这次涨价有结构性原因。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥有结构性损伤，要马上修。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校需要做一些结构性调整。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "结构性失业", "label": "复合"}], "register": "书面", "sense_fingerprint": "与事物内部组成方式有关的特征，常用来说明问题或变化来自整体结构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af58cd74-a966-4809-b2bd-5cb92529248a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10545, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结构性", "is_correct": true, "explanation": "“结构性”指事物内部组成方式的特征，修饰“挑战”，说明体系的问题来自内部结构。"}, {"text": "乐趣", "is_correct": false, "explanation": "语义：“乐趣”指愉快的感受，与“挑战”意思相反，句子说不通。"}, {"text": "风景", "is_correct": false, "explanation": "语义：“风景”指景色，不能说“多重风景挑战”。"}, {"text": "酒量", "is_correct": false, "explanation": "搭配：“酒量”指饮酒的能力，“面临”和“挑战”一般不接这类个人能力。"}], "explanations": {"结构性": "“结构性”指事物内部组成方式的特征，修饰“挑战”，说明体系的问题来自内部结构。", "乐趣": "语义：“乐趣”指愉快的感受，与“挑战”意思相反，句子说不通。", "风景": "语义：“风景”指景色，不能说“多重风景挑战”。", "酒量": "搭配：“酒量”指饮酒的能力，“面临”和“挑战”一般不接这类个人能力。"}, "sentence_index": 0, "correct_answer": "结构性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的服务很结构性，菜也上得很快。", "explanation": "这里应该用〈周到〉。“结构性”指事物组成方式的特点，不用来形容服务态度；形容服务要用“周到”等词。"}, {"text": "他的心情是结构性的。", "explanation": "这里应该用〈愉快〉。“结构性”指事物内部组成方式的特点，不用来形容心情；形容心情要说“愉快”等词。"}, {"text": "我和他的结构性很好。", "explanation": "这里应该用〈关系〉。“结构性”指事物内部的组成方式，不用来形容人与人之间的关系；这里要说“关系”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10545, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结构性", "is_correct": true, "explanation": "“结构性”指组成方式的特征，正好说明两种产品差异的来源。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性格，不能用来说产品之间的差异。"}, {"text": "口音", "is_correct": false, "explanation": "搭配：“口音”指说话的腔调，不能用来说产品之间的差异。"}, {"text": "好奇心", "is_correct": false, "explanation": "语义：“好奇心”是人的心理状态，与“产品差异”说不通。"}], "explanations": {"结构性": "“结构性”指组成方式的特征，正好说明两种产品差异的来源。", "脾气": "语义：“脾气”指人的性格，不能用来说产品之间的差异。", "口音": "搭配：“口音”指说话的腔调，不能用来说产品之间的差异。", "好奇心": "语义：“好奇心”是人的心理状态，与“产品差异”说不通。"}, "sentence_index": 6, "correct_answer": "结构性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的天气是结构性的。", "explanation": "这里应该用〈晴朗〉。“结构性”指事物内部各部分的组合方式，不用来描述天气；形容天气要用“晴朗”“多云”等词。"}, {"text": "他结构性地笑了。", "explanation": "这里应该用〈微笑〉。“结构性地”表示从结构层面、系统地处理事情，多用于“解决”“改革”等动作，不用来形容笑的方式；笑的方式要说“微笑”或“大笑”。"}, {"text": "这只猫是结构性的。", "explanation": "这里应该用〈可爱〉。“结构性”指事物组成方式的特点，不用来描述动物；形容猫要用“可爱”等词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10545, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次调整是结构性。", "corrected_sentence": "这次调整是结构性的。", "error_description": "错误：“是结构性”；正确：“是结构性的”。作表语时，“结构性”后面要加“的”，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10545, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的困难主要是结构性了。", "corrected_sentence": "这家公司的困难主要是结构性的。", "error_description": "错误：“结构性了”；正确：“结构性的”。“是……的”结构中，“的”不能换成“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
