INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10549, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指某事物符合要求、条件或需要，没有不合适的地方。", "primary_collocate": null, "pronunciation": "shì yí", "ipa": "ʂɻ̩⁵¹ i³⁵", "syllable_count": 2, "sentences": [{"text": "气候变化导致适宜种植区收缩，极端天气频发影响产量稳定性；全球航运成本波动、地缘政治紧张以及关税政策调整均可能扰乱贸易流向；同时，小农户在面对市场风险时普遍缺乏金融工具与信息支持。", "target_word": "适宜", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这里的土壤很适宜种茶。", "target_word": "适宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云南的气候适宜种咖啡。", "target_word": "适宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花适宜在春天播种。", "target_word": "适宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的冬天不适宜种水稻。", "target_word": "适宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地的条件适宜种玉米。", "target_word": "适宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西红柿适宜的生长温度是二十度左右。", "target_word": "适宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙地适宜种花生，不适宜种水稻。", "target_word": "适宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里雨水多，适宜茶树生长。", "target_word": "适宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡阳光好，适宜种果树。", "target_word": "适宜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不适宜", "label": "否定形式"}, {"form": "适宜于", "label": "复合"}], "register": "书面", "sense_fingerprint": "适宜：事物符合要求或条件，没有不合适之处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b739b74e-8c84-4c81-94e9-a5882880eae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10549, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "适宜", "is_correct": true, "explanation": "正确答案。适宜（shì yí）指事物符合要求或条件，没有不合适的地方。"}, {"text": "示意", "is_correct": false, "explanation": "shìyì（第四声）与 shìyí 只差第二个音节的声调，意思是用动作或表情表达意思。"}, {"text": "试衣", "is_correct": false, "explanation": "shìyī（第一声）与 shìyí 只差第二个音节的声调，意思是穿上衣服看合不合身。"}, {"text": "石椅", "is_correct": false, "explanation": "shíyǐ 与 shìyí 两个音节的声调都不同，意思是石头做的椅子。"}], "explanations": {"适宜": "正确答案。适宜（shì yí）指事物符合要求或条件，没有不合适的地方。", "示意": "shìyì（第四声）与 shìyí 只差第二个音节的声调，意思是用动作或表情表达意思。", "试衣": "shìyī（第一声）与 shìyí 只差第二个音节的声调，意思是穿上衣服看合不合身。", "石椅": "shíyǐ 与 shìyí 两个音节的声调都不同，意思是石头做的椅子。"}, "sentence_index": null, "correct_answer": "适宜"}, "level_3": {"options": [{"text": "适宜", "is_correct": true, "explanation": "正确：“适宜”修饰“种植区”，指适合种植的地区，符合句意。"}, {"text": "好看", "is_correct": false, "explanation": "语义：“好看”形容外观美观，不能说“好看的种植区”，句中谈的是土地的条件。"}, {"text": "繁华", "is_correct": false, "explanation": "搭配：“繁华”多用于街市、城市，不与“种植区”搭配。"}, {"text": "恰当", "is_correct": false, "explanation": "搭配：“恰当”多用于做法、时机，不说“恰当的种植区”。"}], "explanations": {"适宜": "正确：“适宜”修饰“种植区”，指适合种植的地区，符合句意。", "好看": "语义：“好看”形容外观美观，不能说“好看的种植区”，句中谈的是土地的条件。", "繁华": "搭配：“繁华”多用于街市、城市，不与“种植区”搭配。", "恰当": "搭配：“恰当”多用于做法、时机，不说“恰当的种植区”。"}, "sentence_index": 0, "correct_answer": "适宜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脾气很适宜，大家都喜欢和他相处。", "explanation": "这里应该用〈温和〉。适宜指事物符合要求或条件，形容人的脾气要用温和。"}, {"text": "他的刀工很适宜，切的菜又薄又匀。", "explanation": "这里应该用〈熟练〉。说刀工、动作纯熟要用熟练，适宜指符合要求，不用来形容技术的熟练程度。"}, {"text": "这个笑话很适宜，大家都笑了。", "explanation": "这里应该用〈有趣〉。适宜指事物符合要求或条件，说笑话好笑要用有趣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10549, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "适宜", "is_correct": true, "explanation": "正确答案。适宜（shì yí）指事物符合要求或条件，没有不合适的地方。"}, {"text": "十一", "is_correct": false, "explanation": "shíyī 与 shìyí 两个音节的声调都不同，意思是数字“十一”。"}, {"text": "释义", "is_correct": false, "explanation": "shìyì（第四声）与 shìyí 只差第二个音节的声调，意思是解释词语的含义。"}, {"text": "四姨", "is_correct": false, "explanation": "sìyí（第四声）与 shìyí 声母不同（s 与 sh），声调相同，意思是母亲的姐妹。"}, {"text": "侍医", "is_correct": false, "explanation": "shìyī（第一声）与 shìyí 只差第二个音节的声调，意思是古代为帝王治病的医生。"}], "explanations": {"适宜": "正确答案。适宜（shì yí）指事物符合要求或条件，没有不合适的地方。", "十一": "shíyī 与 shìyí 两个音节的声调都不同，意思是数字“十一”。", "释义": "shìyì（第四声）与 shìyí 只差第二个音节的声调，意思是解释词语的含义。", "四姨": "sìyí（第四声）与 shìyí 声母不同（s 与 sh），声调相同，意思是母亲的姐妹。", "侍医": "shìyī（第一声）与 shìyí 只差第二个音节的声调，意思是古代为帝王治病的医生。"}, "sentence_index": null, "correct_answer": "适宜"}, "level_3": {"options": [{"text": "适宜", "is_correct": true, "explanation": "正确：“适宜”修饰“生长温度”，指适合西红柿生长的温度，符合句意。"}, {"text": "重要", "is_correct": false, "explanation": "语义：“重要”说事情的分量，不能用来形容“生长温度”。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体形或建筑，不说“高大的温度”。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：“甜美”多形容声音、笑容或果实的味道，不用于“生长温度”。"}], "explanations": {"适宜": "正确：“适宜”修饰“生长温度”，指适合西红柿生长的温度，符合句意。", "重要": "语义：“重要”说事情的分量，不能用来形容“生长温度”。", "高大": "搭配：“高大”形容体形或建筑，不说“高大的温度”。", "甜美": "搭配：“甜美”多形容声音、笑容或果实的味道，不用于“生长温度”。"}, "sentence_index": 6, "correct_answer": "适宜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们相处得很适宜，从来不吵架。", "explanation": "这里应该用〈融洽〉。说人与人相处和睦要用融洽，适宜指事物符合要求或条件，不用来描写人际关系。"}, {"text": "他对新同学很适宜，大家都愿意和他玩。", "explanation": "这里应该用〈友好〉。说对人的态度亲切和善要用友好，适宜不用来形容待人的态度。"}, {"text": "他和爸爸的关系很适宜，无话不说。", "explanation": "这里应该用〈亲密〉。说两人感情近、关系深要用亲密，适宜不用来形容人与人之间的感情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10549, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块地的土壤很适宜了种茶树。", "corrected_sentence": "这块地的土壤很适宜种茶树。", "error_description": "错误：“了”插在“适宜”和后面的动词“种”之间。正确：“这块地的土壤很适宜种茶树。”“了”不能放在动词前，应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10549, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个山谷的气温很适宜着种苹果。", "corrected_sentence": "这个山谷的气温很适宜种苹果。", "error_description": "错误：“着”插在“适宜”和后面的动词“种”之间。正确：“这个山谷的气温很适宜种苹果。”“着”不能放在这里，直接说“适宜种”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
