INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10550, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专门用来种植农作物、树木或花草的区域。", "primary_collocate": null, "pronunciation": "zhòng zhí qū", "ipa": "ʈʂʊŋ⁵¹ ʈʂɻ̩³⁵ tɕʰy⁵⁵", "syllable_count": 3, "sentences": [{"text": "气候变化导致适宜种植区收缩，极端天气频发影响产量稳定性；全球航运成本波动、地缘政治紧张以及关税政策调整均可能扰乱贸易流向；同时，小农户在面对市场风险时普遍缺乏金融工具与信息支持。", "target_word": "种植区", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个种植区的苹果又大又甜。", "target_word": "种植区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们县有一个大型茶叶种植区。", "target_word": "种植区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南方是水稻的主要种植区。", "target_word": "种植区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片种植区每年春天都很忙。", "target_word": "种植区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府在山边建了新的种植区。", "target_word": "种植区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种植区的农民正在给果树浇水。", "target_word": "种植区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个种植区离城市只有十公里。", "target_word": "种植区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干旱让这个种植区的收成变少了。", "target_word": "种植区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天骑车去种植区照看蔬菜。", "target_word": "种植区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "種植區", "label": "繁体"}], "register": "书面", "sense_fingerprint": "种植区：专门种植农作物、树木或花草的区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b739b74e-8c84-4c81-94e9-a5882880eae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "种植区", "is_correct": true, "explanation": "正确：“种植区”指专门种植作物的区域，句中指适宜种植的地区，符合句意。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“适宜”修饰地区、条件，不与“工资”搭配，“气候变化导致适宜工资收缩”说不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人的品性，与气候、产量无关，句意说不通。"}, {"text": "比赛", "is_correct": false, "explanation": "语义：“比赛”是竞技活动，不是可以收缩的区域，与句中的气候变化无关。"}], "explanations": {"种植区": "正确：“种植区”指专门种植作物的区域，句中指适宜种植的地区，符合句意。", "工资": "搭配：“适宜”修饰地区、条件，不与“工资”搭配，“气候变化导致适宜工资收缩”说不通。", "性格": "语义：“性格”指人的品性，与气候、产量无关，句意说不通。", "比赛": "语义：“比赛”是竞技活动，不是可以收缩的区域，与句中的气候变化无关。"}, "sentence_index": 0, "correct_answer": "种植区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片湖是重要的种植区，养了很多鱼。", "explanation": "这里应该用〈养殖区〉。种植区用于栽种农作物、树木或花草，养鱼、养牲畜要用养殖区。"}, {"text": "我们家的种植区里养了二十只羊。", "explanation": "这里应该用〈农场〉。种植区只指栽种农作物、树木或花草的地方，不用来养牲畜。"}, {"text": "这个种植区里有很多宿舍楼。", "explanation": "这里应该用〈居住区〉。种植区指栽种农作物、树木或花草的地方，住宅楼集中的地方要用居住区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "种植区", "is_correct": true, "explanation": "正确：“种植区”修饰“农民”，指在种植区里劳作的农民，符合句意。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：“工厂”是生产场所，农民不在工厂里给果树浇水，句意不通。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”是上课的地方，与给果树浇水的农民无关。"}, {"text": "操场", "is_correct": false, "explanation": "搭配：“农民”一般在田间、地里劳作，不说“操场的农民”。"}], "explanations": {"种植区": "正确：“种植区”修饰“农民”，指在种植区里劳作的农民，符合句意。", "工厂": "语义：“工厂”是生产场所，农民不在工厂里给果树浇水，句意不通。", "教室": "语义：“教室”是上课的地方，与给果树浇水的农民无关。", "操场": "搭配：“农民”一般在田间、地里劳作，不说“操场的农民”。"}, "sentence_index": 6, "correct_answer": "种植区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每周六都去种植区看电影。", "explanation": "这里应该用〈电影院〉。种植区指栽种农作物、树木或花草的地方，看电影要去电影院。"}, {"text": "他下班以后常去种植区喝咖啡。", "explanation": "这里应该用〈咖啡馆〉。种植区指栽种农作物、树木或花草的地方，喝咖啡要去咖啡馆。"}, {"text": "妈妈在种植区里买了一条新裙子。", "explanation": "这里应该用〈商场〉。种植区指栽种农作物、树木或花草的地方，买衣服要去商场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一带有几只种植区，都种着茶树。", "corrected_sentence": "这一带有几片种植区，都种着茶树。", "error_description": "错误：量词用了“只”。正确：“片”。“只”用于禽兽、手脚等，种植区是一大片地，应该用“片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一带有一间种植区，都种着玉米。", "corrected_sentence": "这一带有一片种植区，都种着玉米。", "error_description": "错误：量词用了“间”。正确：“片”。“间”用于房屋，种植区是一大片地，应该用“片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10551, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "膨胀", "is_correct": true, "explanation": "正确：“膨胀”指体积变大，与“收缩”互为反义。"}, {"text": "保持", "is_correct": false, "explanation": "“保持”指维持原状，与“收缩”没有反义关系。"}, {"text": "冷却", "is_correct": false, "explanation": "“冷却”指温度降低，不是“收缩”的反义词。"}, {"text": "弯曲", "is_correct": false, "explanation": "“弯曲”指形状歪斜，不是“收缩”的反义词。"}], "correct_answer": "膨胀", "explanations": {"膨胀": "正确：“膨胀”指体积变大，与“收缩”互为反义。", "保持": "“保持”指维持原状，与“收缩”没有反义关系。", "冷却": "“冷却”指温度降低，不是“收缩”的反义词。", "弯曲": "“弯曲”指形状歪斜，不是“收缩”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10551, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "舒张", "is_correct": true, "explanation": "正确：“舒张”指肌肉、血管等扩张开，与“收缩”互为反义。"}, {"text": "融化", "is_correct": false, "explanation": "“融化”指固体变成液体，与“收缩”没有反义关系。"}, {"text": "发热", "is_correct": false, "explanation": "“发热”指温度升高，不是“收缩”的反义词。"}, {"text": "扭动", "is_correct": false, "explanation": "“扭动”指身体来回转动，与“收缩”没有反义关系。"}], "correct_answer": "舒张", "explanations": {"舒张": "正确：“舒张”指肌肉、血管等扩张开，与“收缩”互为反义。", "融化": "“融化”指固体变成液体，与“收缩”没有反义关系。", "发热": "“发热”指温度升高，不是“收缩”的反义词。", "扭动": "“扭动”指身体来回转动，与“收缩”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10551, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体体积由大变小，或者长度由长变短。", "primary_collocate": null, "pronunciation": "shōu suō", "ipa": "ʂoʊ⁵⁵ suɔ⁵⁵", "syllable_count": 2, "sentences": [{"text": "冬天气温骤降，铁轨和桥梁的金属结构会明显收缩；工程师因此在接缝处预留空隙，防止结构因温差而开裂。", "target_word": "收缩", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这件毛衣洗了以后收缩了很多。", "target_word": "收缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷，金属会慢慢收缩。", "target_word": "收缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热胀冷缩，铁轨在冬天会收缩。", "target_word": "收缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气球漏气后，慢慢收缩成一小团。", "target_word": "收缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肌肉用力的时候会收缩。", "target_word": "收缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根钢缆在低温环境中会明显收缩。", "target_word": "收缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布料遇水容易收缩。", "target_word": "收缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受到惊吓，瞳孔一下子收缩了。", "target_word": "收缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷水一泼，皮肤立刻收缩起来。", "target_word": "收缩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收缩了", "label": "体标"}, {"form": "收缩过", "label": "体标"}, {"form": "收缩着", "label": "体标"}, {"form": "收缩压", "label": "复合"}, {"form": "收縮", "label": "繁体"}], "register": "书面", "sense_fingerprint": "收缩：体积变小或长度变短", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b739b74e-8c84-4c81-94e9-a5882880eae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10551, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "收缩", "is_correct": true, "explanation": "正确：“收缩”指体积变小，与句中“金属结构”遇冷缩小的语境相符。"}, {"text": "消化", "is_correct": false, "explanation": "语义：“消化”指分解食物，金属结构不会消化。"}, {"text": "饮用", "is_correct": false, "explanation": "搭配：“饮用”的对象是饮品，金属结构不能“饮用”。"}, {"text": "思考", "is_correct": false, "explanation": "语义：“思考”是人的行为，金属结构无法思考。"}], "explanations": {"收缩": "正确：“收缩”指体积变小，与句中“金属结构”遇冷缩小的语境相符。", "消化": "语义：“消化”指分解食物，金属结构不会消化。", "饮用": "搭配：“饮用”的对象是饮品，金属结构不能“饮用”。", "思考": "语义：“思考”是人的行为，金属结构无法思考。"}, "sentence_index": 0, "correct_answer": "收缩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段时间的雨量收缩了不少。", "explanation": "这里应该用〈减少〉。收缩指物体的体积或长度变小，雨量的减少要用“减少”。"}, {"text": "这个视频收缩以后只有几十兆了。", "explanation": "这里应该用〈压缩〉。收缩用于物体自身变小，视频、文件等数据变小要用“压缩”。"}, {"text": "书包的重量收缩了不少。", "explanation": "这里应该用〈减轻〉。收缩说的是体积或长度变小，重量变轻要用“减轻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10551, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收缩", "is_correct": true, "explanation": "正确：“收缩”指低温时钢缆变短变小，与“低温环境”相符。"}, {"text": "膨胀", "is_correct": false, "explanation": "语义：“低温”与“膨胀”的变化方向相反，低温下钢缆不会明显膨胀。"}, {"text": "沸腾", "is_correct": false, "explanation": "语义：钢缆不会沸腾，且低温环境下不会发生这种变化。"}, {"text": "融化", "is_correct": false, "explanation": "搭配：“融化”多用于冰、雪等，不用于钢缆。"}], "explanations": {"收缩": "正确：“收缩”指低温时钢缆变短变小，与“低温环境”相符。", "膨胀": "语义：“低温”与“膨胀”的变化方向相反，低温下钢缆不会明显膨胀。", "沸腾": "语义：钢缆不会沸腾，且低温环境下不会发生这种变化。", "融化": "搭配：“融化”多用于冰、雪等，不用于钢缆。"}, "sentence_index": 6, "correct_answer": "收缩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个星期气温收缩了不少。", "explanation": "这里应该用〈下降〉。收缩指物体体积或长度变小，气温降低要用“下降”。"}, {"text": "今天的风力收缩了很多。", "explanation": "这里应该用〈减弱〉。收缩用于具体物体的体积或长度，风力变弱要用“减弱”。"}, {"text": "他的工资收缩了不少。", "explanation": "这里应该用〈降低〉。收缩指物体的体积或长度变小，工资的下降要用“降低”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10551, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件毛衣洗了以后已经收缩着很多。", "corrected_sentence": "这件毛衣洗了以后已经收缩了很多。", "error_description": "错误：用了“着”。“已经收缩……很多”表示变化已经完成，应用“了”，不能用表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10551, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块铁板遇冷以后被收缩了。", "corrected_sentence": "这块铁板遇冷以后收缩了。", "error_description": "错误：“收缩”是不及物动词，不能用“被”构成被动句。应说“这块铁板遇冷以后收缩了”，去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
