INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10555, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指船舶在江河湖海上运送货物或旅客的行业或行为。", "primary_collocate": null, "pronunciation": "háng yùn", "ipa": "xɑŋ˧˥ yn˥˩", "syllable_count": 2, "sentences": [{"text": "气候变化导致适宜种植区收缩，极端天气频发影响产量稳定性；全球航运成本波动、地缘政治紧张以及关税政策调整均可能扰乱贸易流向；同时，小农户在面对市场风险时普遍缺乏金融工具与信息支持。", "target_word": "航运", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司做航运生意已经十年了。", "target_word": "航运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上海港是中国最大的航运中心。", "target_word": "航运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航运业对世界贸易非常重要。", "target_word": "航运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家航运公司当船长。", "target_word": "航运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨让港口的航运停了两天。", "target_word": "航运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航运比航空便宜，但是速度慢。", "target_word": "航运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥大学学的是航运管理。", "target_word": "航运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海上航运需要很多大船和码头。", "target_word": "航运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水太浅，这里的航运很不方便。", "target_word": "航运", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "航运业", "label": "复合"}, {"form": "航运公司", "label": "复合"}, {"form": "航運", "label": "繁体"}], "register": "书面", "sense_fingerprint": "名词：船舶等运送货物或旅客的行业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b739b74e-8c84-4c81-94e9-a5882880eae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10555, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "航运", "is_correct": true, "explanation": "正确：“航运”指船舶运输的行业，与“全球……成本波动”相符。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌与“贸易流向”无关，不能说“诗歌成本波动”。"}, {"text": "方言", "is_correct": false, "explanation": "语义：方言不是运输行业，与句中的贸易语境不符。"}, {"text": "睡眠", "is_correct": false, "explanation": "搭配：“成本”多指生产或运输的费用，不说“睡眠成本”。"}], "explanations": {"航运": "正确：“航运”指船舶运输的行业，与“全球……成本波动”相符。", "诗歌": "语义：诗歌与“贸易流向”无关，不能说“诗歌成本波动”。", "方言": "语义：方言不是运输行业，与句中的贸易语境不符。", "睡眠": "搭配：“成本”多指生产或运输的费用，不说“睡眠成本”。"}, "sentence_index": 0, "correct_answer": "航运"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们每天下午都去航运散步。", "explanation": "这里应该用〈公园〉。航运指行业或运输行为，不是可以散步的地方，应说公园。"}, {"text": "这块航运很重，要两个人才能搬动。", "explanation": "这里应该用〈石头〉。航运指行业或运输行为，不能指可以搬动的物体。"}, {"text": "他是一名航运。", "explanation": "这里应该用〈船员〉。航运是行业，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10555, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "航运", "is_correct": true, "explanation": "正确：“航运”是运输方式，可与“航空”比较便宜和速度。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说不是运输方式，不能与“航空”比较价格和速度。"}, {"text": "书法", "is_correct": false, "explanation": "搭配：“便宜”和“速度慢”多用于运输，不能用于书法。"}, {"text": "绘画", "is_correct": false, "explanation": "语义：绘画与“航空”不是可比的运输方式。"}], "explanations": {"航运": "正确：“航运”是运输方式，可与“航空”比较便宜和速度。", "小说": "语义：小说不是运输方式，不能与“航空”比较价格和速度。", "书法": "搭配：“便宜”和“速度慢”多用于运输，不能用于书法。", "绘画": "语义：绘画与“航空”不是可比的运输方式。"}, "sentence_index": 6, "correct_answer": "航运"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些航运已经停靠在港口了。", "explanation": "这里应该用〈船只〉。航运指行业或运输行为，能停靠在港口的是船只，不能说“航运”。"}, {"text": "我们在航运见面吧。", "explanation": "这里应该用〈码头〉。航运指行业或运输行为，不能当作见面的地点。"}, {"text": "这份航运很厚，有三百页。", "explanation": "这里应该用〈文件〉。航运指行业或运输行为，不能指纸质的文件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10555, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市的一条航运很发达。", "corrected_sentence": "这座城市的航运很发达。", "error_description": "错误：“航运”指行业，不能用量词“条”计量。应说“这座城市的航运很发达”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10555, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个港口的航运了很发达。", "corrected_sentence": "这个港口的航运很发达。", "error_description": "错误：“航运”后多加了“了”。“了”不能紧跟名词“航运”，此处应去掉。正确：“这个港口的航运很发达。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
