INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10557, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "地缘指地理上的联系，比如国家或地区之间因地理位置相邻而产生的关系。", "primary_collocate": null, "pronunciation": "dì yuán", "ipa": "ti˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "而互联网作为底层基质，不仅连接设备，更重构了归属感的生成路径——归属不再源于地缘或血缘的宿命，而诞生于共同叙事与目标驱动的瞬时共鸣。", "target_word": "地缘", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "气候变化导致适宜种植区收缩，极端天气频发影响产量稳定性；全球航运成本波动、地缘相近国家之间的贸易摩擦以及关税政策调整均可能扰乱贸易流向；同时，小农户在面对市场风险时普遍缺乏金融工具与信息支持。", "target_word": "地缘", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "中国和越南地缘相近，来往很多。", "target_word": "地缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为地缘相近，这两个城市的饮食很像。", "target_word": "地缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲人靠血缘联系，邻居靠地缘联系。", "target_word": "地缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个港口有地缘优势，每天都有很多船。", "target_word": "地缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地缘上，两国是邻居，经济合作很多。", "target_word": "地缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个地区地缘联系很深，常常互相帮助。", "target_word": "地缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，历史和地缘都会影响两国的关系。", "target_word": "地缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家和周围的邻国地缘关系很密切。", "target_word": "地缘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "地緣", "label": "繁体"}, {"form": "地缘关系", "label": "复合"}], "register": "书面", "sense_fingerprint": "地缘:国家或地区因地理位置相邻而产生的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcdeda5-d8c7-49c0-8c4a-eb7c9e6fe46d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10557, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地缘", "is_correct": true, "explanation": "地缘：地理位置相邻而产生的关系，与“归属不再源于……或血缘的宿命”的对比相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是归属感的来源，与“血缘的宿命”并列后语义荒谬。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能作为归属的根源，与“血缘的宿命”并列后不成立。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：“源于……的宿命”要接出身、地域一类的根源，“电影”不能作为归属的根源。"}], "explanations": {"地缘": "地缘：地理位置相邻而产生的关系，与“归属不再源于……或血缘的宿命”的对比相符。", "天气": "语义：天气不是归属感的来源，与“血缘的宿命”并列后语义荒谬。", "手机": "语义：手机不能作为归属的根源，与“血缘的宿命”并列后不成立。", "电影": "搭配：“源于……的宿命”要接出身、地域一类的根源，“电影”不能作为归属的根源。"}, "sentence_index": 0, "correct_answer": "地缘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两座城市的地缘很远，坐车要两个小时。", "explanation": "这里应该用〈距离〉。地缘指地理相邻而产生的关系，不表示空间远近，说两地相隔多远要用距离。"}, {"text": "他们是亲兄弟，靠地缘联系。", "explanation": "这里应该用〈血缘〉。亲属之间的联系靠血缘，地缘只指地理相邻产生的关系。"}, {"text": "这座山的地缘很复杂。", "explanation": "这里应该用〈地形〉。地缘是地区之间的关系，不指地貌，说山的地形要用地形。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10557, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地缘", "is_correct": true, "explanation": "地缘上：从地理位置相邻的角度说明两国是邻居，与句意一致。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“邻居”说的是地理位置相邻，“时间上”与之无关，且句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色上”不能说明两国是邻居，这一判断与颜色无关。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“邻居”指位置关系，不能说“年龄上两国是邻居”，与“年龄”搭配不当。"}], "explanations": {"地缘": "地缘上：从地理位置相邻的角度说明两国是邻居，与句意一致。", "时间": "语义：“邻居”说的是地理位置相邻，“时间上”与之无关，且句意不通。", "颜色": "语义：“颜色上”不能说明两国是邻居，这一判断与颜色无关。", "年龄": "搭配：“邻居”指位置关系，不能说“年龄上两国是邻居”，与“年龄”搭配不当。"}, "sentence_index": 6, "correct_answer": "地缘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在公司的地缘很好，同事都喜欢他。", "explanation": "这里应该用〈人缘〉。人缘指人与人之间的受欢迎程度，地缘只指国家或地区间的位置关系。"}, {"text": "我们两个人很有地缘，常常一起喝茶。", "explanation": "这里应该用〈缘分〉。缘分指人与人之间的机缘，地缘不能用于两个人之间的缘分。"}, {"text": "这个地缘人口很多，交通方便。", "explanation": "这里应该用〈地区〉。地缘是关系，不指地方本身，不能用来指一个地区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10557, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个城市之间有一条很密切的地缘关系。", "corrected_sentence": "这两个城市之间有一种很密切的地缘关系。", "error_description": "错误在于“地缘关系”前的量词。“地缘关系”是抽象的关系，量词应用“种”，不能用细长条状的“条”，应说“一种很密切的地缘关系”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10557, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个国家之间存在一片地缘关系。", "corrected_sentence": "这两个国家之间存在一种地缘关系。", "error_description": "“地缘关系”是抽象的关系，量词应用“种”，不能用表示面积、大片事物的“片”，应说“一种地缘关系”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10559, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放松", "is_correct": true, "explanation": "反义：“紧张”与“放松”相对，指心理由不安转为平静。"}, {"text": "清楚", "is_correct": false, "explanation": "无反义关系：“清楚”形容明白、分明，与“紧张”的心理意义不相对。"}, {"text": "迅速", "is_correct": false, "explanation": "无反义关系：“迅速”形容速度快，与“紧张”不构成反义。"}, {"text": "明亮", "is_correct": false, "explanation": "无反义关系：“明亮”形容光线或颜色，与“紧张”无对应关系。"}], "correct_answer": "放松", "explanations": {"放松": "反义：“紧张”与“放松”相对，指心理由不安转为平静。", "清楚": "无反义关系：“清楚”形容明白、分明，与“紧张”的心理意义不相对。", "迅速": "无反义关系：“迅速”形容速度快，与“紧张”不构成反义。", "明亮": "无反义关系：“明亮”形容光线或颜色，与“紧张”无对应关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10559, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放松", "is_correct": true, "explanation": "反义：“紧张”与“放松”相对，指心理由不安转为平静。"}, {"text": "干净", "is_correct": false, "explanation": "无反义关系：“干净”形容洁净，与“紧张”的心理意义无对应关系。"}, {"text": "宽大", "is_correct": false, "explanation": "无反义关系：“宽大”形容空间或态度宽厚，与“紧张”不构成反义。"}, {"text": "善良", "is_correct": false, "explanation": "无反义关系：“善良”形容品性，与“紧张”的心理状态不相对。"}], "correct_answer": "放松", "explanations": {"放松": "反义：“紧张”与“放松”相对，指心理由不安转为平静。", "干净": "无反义关系：“干净”形容洁净，与“紧张”的心理意义无对应关系。", "宽大": "无反义关系：“宽大”形容空间或态度宽厚，与“紧张”不构成反义。", "善良": "无反义关系：“善良”形容品性，与“紧张”的心理状态不相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10559, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指精神处于高度准备或不安的状态，感到压力或焦虑。", "primary_collocate": null, "pronunciation": "jǐn zhāng", "ipa": "tɕin˨˩ ʈʂɑŋ˥", "syllable_count": 2, "sentences": [{"text": "面对记者接连不断的追问，他的声音一直在发颤，手指不停地绞着衣角，整个人显得十分紧张。", "target_word": "紧张", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "明天要考试，我今天很紧张。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次上台，紧张得说不出话。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别紧张，慢慢说，我们听着呢。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试的时候，她一直很紧张。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一看到老师就紧张。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，大家都紧张起来了。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说手术很简单，让他别太紧张。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，运动员们心里有点紧张。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她紧张地握着我的手。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "紧张感", "label": "复合"}, {"form": "緊張", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容词：精神高度准备、不安、有压力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b739b74e-8c84-4c81-94e9-a5882880eae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10559, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "紧张", "is_correct": true, "explanation": "正确。“整个人显得十分紧张”描写他因追问而精神不安，与“声音发颤”“绞着衣角”的动作相符。"}, {"text": "平静", "is_correct": false, "explanation": "语义：“平静”与“声音发颤”“绞着衣角”的描写相反，句子表现的是内心不安。"}, {"text": "紧凑", "is_correct": false, "explanation": "搭配：“紧凑”形容结构、安排，不说人“显得十分紧凑”。"}, {"text": "紧急", "is_correct": false, "explanation": "搭配：“紧急”多用于事件或措施，不用来形容人的精神状态。"}], "explanations": {"紧张": "正确。“整个人显得十分紧张”描写他因追问而精神不安，与“声音发颤”“绞着衣角”的动作相符。", "平静": "语义：“平静”与“声音发颤”“绞着衣角”的描写相反，句子表现的是内心不安。", "紧凑": "搭配：“紧凑”形容结构、安排，不说人“显得十分紧凑”。", "紧急": "搭配：“紧急”多用于事件或措施，不用来形容人的精神状态。"}, "sentence_index": 0, "correct_answer": "紧张"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "拿到录取通知书，我紧张得跳了起来。", "explanation": "这里应该用〈激动〉。紧张表示担心、不安，因喜事而情绪高涨要用激动。"}, {"text": "下班后，我喜欢躺在沙发上紧张一下。", "explanation": "这里应该用〈休息〉。紧张表示心里不安、戒备，躺在沙发上休息时要用休息，不能用紧张。"}, {"text": "这个周末，我们紧张地去郊外野餐，玩得很开心。", "explanation": "这里应该用〈轻松〉。紧张表示心里不安，去野餐、玩得开心的状态要用轻松。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10559, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "紧张", "is_correct": true, "explanation": "正确。“紧张起来”指情绪由平静转为不安，符合“听到这个消息”的语境。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线、眼神，不说“大家都明亮起来了”。"}, {"text": "坚硬", "is_correct": false, "explanation": "语义：“坚硬”指物体质地或态度强硬，与“听到这个消息”后人的情绪变化不合。"}, {"text": "精确", "is_correct": false, "explanation": "搭配：“精确”修饰数字、描述，不能用来说人的情绪起伏。"}], "explanations": {"紧张": "正确。“紧张起来”指情绪由平静转为不安，符合“听到这个消息”的语境。", "明亮": "搭配：“明亮”形容光线、眼神，不说“大家都明亮起来了”。", "坚硬": "语义：“坚硬”指物体质地或态度强硬，与“听到这个消息”后人的情绪变化不合。", "精确": "搭配：“精确”修饰数字、描述，不能用来说人的情绪起伏。"}, "sentence_index": 6, "correct_answer": "紧张"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他气得脸都红了，紧张地拍了一下桌子。", "explanation": "这里应该用〈生气〉。紧张表示担心、不安，描述发怒时的动作要用生气。"}, {"text": "退休以后，他每天在公园里紧张地下棋。", "explanation": "这里应该用〈悠闲〉。紧张表示心里不安，退休后每天在公园下棋的闲适状态要用悠闲。"}, {"text": "周末，他躺在草地上晒太阳，懒洋洋的，很紧张。", "explanation": "这里应该用〈惬意〉。紧张表示心里不安，躺在草地上晒太阳的舒适状态要用惬意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10559, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "考试前我紧张地得睡不着觉。", "corrected_sentence": "考试前我紧张得睡不着觉。", "error_description": "错误：“紧张”之后的程度补语应用“得”引出，“地”与“得”不能同时用在同一结构中。正确应说「紧张得睡不着觉」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10559, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一开口说话，心里很就紧张。", "corrected_sentence": "她一开口说话，心里就很紧张。", "error_description": "副词「就」与「很」次序颠倒：「很」要紧接在形容词“紧张”之前，应说「心里就很紧张」，不能说「心里很就紧张」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10560, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
