INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10560, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家或地区对进出口商品征收的税收，用以调节贸易、保护国内产业或增加财政收入。", "primary_collocate": null, "pronunciation": "guān shuì", "ipa": "kwan˥ ʂweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "气候变化导致适宜种植区收缩，极端天气频发影响产量稳定性；全球航运成本波动、地缘政治紧张以及关税政策调整均可能扰乱贸易流向；同时，小农户在面对市场风险时普遍缺乏金融工具与信息支持。", "target_word": "关税", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "进口汽车要交很高的关税。", "target_word": "关税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府决定提高对钢铁的关税。", "target_word": "关税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关税太高，外国的水果卖得很贵。", "target_word": "关税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家取消了对大米的关税。", "target_word": "关税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关税是国家收入的一部分。", "target_word": "关税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国谈了三天，终于降低了关税。", "target_word": "关税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司因为关税增加，决定在本地建厂。", "target_word": "关税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的关税政策让商品价格上涨了。", "target_word": "关税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商人说，这笔关税比货物本身还贵。", "target_word": "关税", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进口关税", "label": "复合"}, {"form": "关税壁垒", "label": "复合"}, {"form": "笔", "label": "量词"}, {"form": "關稅", "label": "繁体"}], "register": "书面", "sense_fingerprint": "名词：对进出口商品征收的税", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b739b74e-8c84-4c81-94e9-a5882880eae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10560, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关税", "is_correct": true, "explanation": "正确。“关税政策调整”指对进出口商品征税的政策变动，与贸易流向相关。"}, {"text": "婚姻", "is_correct": false, "explanation": "语义：“婚姻”与“扰乱贸易流向”无关，句子谈的是贸易相关因素。"}, {"text": "时差", "is_correct": false, "explanation": "搭配：“时差”不是可以调整的政策对象，不说“时差政策调整”。"}, {"text": "晚霞", "is_correct": false, "explanation": "搭配：“晚霞”是自然景象，不能作为政策调整的对象。"}], "explanations": {"关税": "正确。“关税政策调整”指对进出口商品征税的政策变动，与贸易流向相关。", "婚姻": "语义：“婚姻”与“扰乱贸易流向”无关，句子谈的是贸易相关因素。", "时差": "搭配：“时差”不是可以调整的政策对象，不说“时差政策调整”。", "晚霞": "搭配：“晚霞”是自然景象，不能作为政策调整的对象。"}, "sentence_index": 0, "correct_answer": "关税"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这批进口钢材，我们要交一台关税。", "explanation": "这里的量词应该用〈笔〉，表示一笔税款；〈台〉用于机器等，不能用来计量关税。"}, {"text": "在国内卖衣服，要交关税。", "explanation": "这里应该用〈增值税〉。关税只针对进出口商品，国内销售要交的是增值税。"}, {"text": "这批国内寄来的快递，我们付了一笔关税。", "explanation": "这里应该用〈运费〉。关税是进出口商品的税，国内寄件的费用叫运费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关税", "is_correct": true, "explanation": "正确。“降低了关税”是常见搭配，符合两国谈判后的语境。"}, {"text": "对手", "is_correct": false, "explanation": "语义：句中谈判降低的是税收，“对手”指竞争方，与降税的语境不符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”可以说“降低年龄”，但句中是两国谈判降税，降低的对象应是关税，年龄不合语境。"}, {"text": "亲情", "is_correct": false, "explanation": "搭配：“亲情”是情感，不说“降低亲情”。"}], "explanations": {"关税": "正确。“降低了关税”是常见搭配，符合两国谈判后的语境。", "对手": "语义：句中谈判降低的是税收，“对手”指竞争方，与降税的语境不符。", "年龄": "语义：“年龄”可以说“降低年龄”，但句中是两国谈判降税，降低的对象应是关税，年龄不合语境。", "亲情": "搭配：“亲情”是情感，不说“降低亲情”。"}, "sentence_index": 6, "correct_answer": "关税"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "租房子时，房东要我交一笔关税。", "explanation": "这里应该用〈押金〉。关税只针对进出口商品，租房时交的押金不叫关税。"}, {"text": "我们买的这批货要交一条关税。", "explanation": "这里的量词应该用〈笔〉，〈条〉用于细长的东西，不能用来计量关税。"}, {"text": "买一辆国产车，要交一笔关税。", "explanation": "这里应该用〈购置税〉。关税只针对进出口商品，买国产车要交的是车辆购置税。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只关税已经算进价格里了。", "corrected_sentence": "这笔关税已经算进价格里了。", "error_description": "「关税」的量词应用“笔”（表示一笔款项），「只」用于动物或成对的东西，不能修饰关税。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司已经交了这根关税。", "corrected_sentence": "我们公司已经交了这笔关税。", "error_description": "「关税」应用量词“笔”，“根”用于细长的东西，不能修饰税款，应说「这笔关税」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10565, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "促进", "is_correct": false, "explanation": "促进与“扰乱”没有对立关系，不构成反义词。"}, {"text": "安定", "is_correct": true, "explanation": "安定与“扰乱”意义相反：“扰乱”使秩序混乱、不安定，“安定”指平稳、有秩序。"}, {"text": "研究", "is_correct": false, "explanation": "研究是对事物的探求，与“扰乱”没有对立关系。"}, {"text": "欢迎", "is_correct": false, "explanation": "欢迎与“扰乱”没有对立关系，不构成反义词。"}], "correct_answer": "安定", "explanations": {"促进": "促进与“扰乱”没有对立关系，不构成反义词。", "安定": "安定与“扰乱”意义相反：“扰乱”使秩序混乱、不安定，“安定”指平稳、有秩序。", "研究": "研究是对事物的探求，与“扰乱”没有对立关系。", "欢迎": "欢迎与“扰乱”没有对立关系，不构成反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10565, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保护", "is_correct": false, "explanation": "保护与“扰乱”没有对立关系，不构成反义词。"}, {"text": "安定", "is_correct": true, "explanation": "安定与“扰乱”意义相反：“扰乱”使秩序混乱、不安定，“安定”指平稳、有秩序。"}, {"text": "参观", "is_correct": false, "explanation": "参观与“扰乱”没有对立关系，不构成反义词。"}, {"text": "宣传", "is_correct": false, "explanation": "宣传与“扰乱”没有对立关系，不构成反义词。"}], "correct_answer": "安定", "explanations": {"保护": "保护与“扰乱”没有对立关系，不构成反义词。", "安定": "安定与“扰乱”意义相反：“扰乱”使秩序混乱、不安定，“安定”指平稳、有秩序。", "参观": "参观与“扰乱”没有对立关系，不构成反义词。", "宣传": "宣传与“扰乱”没有对立关系，不构成反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10565, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使人或事物混乱、不安定，干扰正常秩序。", "primary_collocate": null, "pronunciation": "rǎo luàn", "ipa": "ɻɑʊ˨˩˦ lwan˥˩", "syllable_count": 2, "sentences": [{"text": "气候变化导致适宜种植区收缩，极端天气频发影响产量稳定性；全球航运成本波动、地缘政治紧张以及关税政策调整均可能扰乱贸易流向；同时，小农户在面对市场风险时普遍缺乏金融工具与信息支持。", "target_word": "扰乱", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他在会上大声说话，扰乱了会场秩序。", "target_word": "扰乱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "深夜的施工噪音扰乱了居民的正常生活。", "target_word": "扰乱", "complexity_tier": "T3", "furigana": "shēn yè de shī gōng zào yīn rǎo luàn le jū mín de zhèng cháng shēng huó", "sentence_source": "generated"}, {"text": "这个消息扰乱了市场的正常秩序。", "target_word": "扰乱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "半夜的噪音扰乱了邻居的睡眠。", "target_word": "扰乱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人在网上造谣，扰乱了社会秩序。", "target_word": "扰乱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "突然的大雨扰乱了我们的旅行计划。", "target_word": "扰乱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坏消息扰乱了他平静的生活。", "target_word": "扰乱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "观众的喊叫扰乱了比赛。", "target_word": "扰乱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机铃声扰乱了课堂秩序。", "target_word": "扰乱", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "扰乱了", "label": "体标"}, {"form": "扰乱过", "label": "体标"}, {"form": "擾亂", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "使人或事物混乱不安，破坏正常秩序", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929f630-bb3e-4acd-8c80-d8e8929653e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10565, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保障", "is_correct": false, "explanation": "语义：“保障”指保护、确保，与“可能……”所述的负面风险语境相反。"}, {"text": "扰乱", "is_correct": true, "explanation": "“扰乱”指打乱正常秩序，与“成本波动、地缘政治紧张、关税政策调整”等风险因素可能造成的影响相符。"}, {"text": "维持", "is_correct": false, "explanation": "搭配：“维持”多接“秩序、局面、平衡”，不说“维持贸易流向”。"}, {"text": "稳定", "is_correct": false, "explanation": "语义：“稳定”指平稳不变，与前文列举的“波动、紧张、调整”等不稳定因素相反。"}], "explanations": {"保障": "语义：“保障”指保护、确保，与“可能……”所述的负面风险语境相反。", "扰乱": "“扰乱”指打乱正常秩序，与“成本波动、地缘政治紧张、关税政策调整”等风险因素可能造成的影响相符。", "维持": "搭配：“维持”多接“秩序、局面、平衡”，不说“维持贸易流向”。", "稳定": "语义：“稳定”指平稳不变，与前文列举的“波动、紧张、调整”等不稳定因素相反。"}, "sentence_index": 0, "correct_answer": "扰乱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他扰乱了我的话。", "explanation": "这里应该用〈打断〉。扰乱指打乱秩序或局面，插话、打断别人说话要用打断。"}, {"text": "这场地震扰乱了这座大桥。", "explanation": "这里应该用〈破坏〉。扰乱针对秩序和节奏，建筑物受损要说破坏。"}, {"text": "这杯水扰乱了浓浓的咖啡味。", "explanation": "这里应该用〈冲淡〉。扰乱指打乱秩序或局面，咖啡味变淡要用冲淡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10565, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”表示喜爱、赏识，与“突然的大雨”打乱计划的语境不符。"}, {"text": "完成", "is_correct": false, "explanation": "配价：“完成”的施事应是人，“大雨”不能完成计划。"}, {"text": "扰乱", "is_correct": true, "explanation": "“扰乱”指使原定计划被打乱，与“突然的大雨”造成的影响相符。"}, {"text": "执行", "is_correct": false, "explanation": "配价：“执行”需要人来实施，“大雨”不能执行计划。"}], "explanations": {"欣赏": "语义：“欣赏”表示喜爱、赏识，与“突然的大雨”打乱计划的语境不符。", "完成": "配价：“完成”的施事应是人，“大雨”不能完成计划。", "扰乱": "“扰乱”指使原定计划被打乱，与“突然的大雨”造成的影响相符。", "执行": "配价：“执行”需要人来实施，“大雨”不能执行计划。"}, "sentence_index": 6, "correct_answer": "扰乱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他公然扰乱了学校的操场。", "explanation": "这里应该用〈占用〉。扰乱指打乱秩序或局面，场地被占用要用占用。"}, {"text": "长期熬夜会扰乱他的健康。", "explanation": "这里应该用〈损害〉。扰乱指打乱秩序或节奏，健康受到伤害要用损害。"}, {"text": "这句玩笑扰乱了老师的尊严。", "explanation": "这里应该用〈有损〉。扰乱指打乱秩序或局面，尊严受到损害要说有损。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10565, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一场突如其来的停电很扰乱了全市的交通秩序。", "corrected_sentence": "一场突如其来的停电扰乱了全市的交通秩序。", "error_description": "错误：动作动词“扰乱”前加了程度副词“很”。“很”不修饰这类动作动词，应删去“很”，说“扰乱了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10565, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "突然的停电扰乱着了全市的交通。", "corrected_sentence": "突然的停电扰乱了全市的交通。", "error_description": "错误：“扰乱”后同时用了“着”和“了”两个体标。这里表示已经发生的结果，应只用“了”，说“扰乱了全市的交通”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10567, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大", "is_correct": true, "explanation": "反义：“大”与“小”相对，表示体积、数量、程度、年龄等超过比较对象。"}, {"text": "慢", "is_correct": false, "explanation": "无关：“慢”指速度低，与“小”不构成反义或近义关系。"}, {"text": "硬", "is_correct": false, "explanation": "无关：“硬”指质地坚实，与“小”没有反义关系。"}, {"text": "深", "is_correct": false, "explanation": "无关：“深”指距离或程度深，与“小”不构成反义关系。"}], "correct_answer": "大", "explanations": {"大": "反义：“大”与“小”相对，表示体积、数量、程度、年龄等超过比较对象。", "慢": "无关：“慢”指速度低，与“小”不构成反义或近义关系。", "硬": "无关：“硬”指质地坚实，与“小”没有反义关系。", "深": "无关：“深”指距离或程度深，与“小”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10567, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大", "is_correct": true, "explanation": "反义：“大”与“小”相对，表示体积、数量、程度、年龄等超过比较对象。"}, {"text": "远", "is_correct": false, "explanation": "无关：“远”指距离长，与“小”不构成反义或近义关系。"}, {"text": "厚", "is_correct": false, "explanation": "无关：“厚”指物体两面之间的距离大，与“小”没有反义关系。"}, {"text": "快", "is_correct": false, "explanation": "无关：“快”指速度高，与“小”不构成反义关系。"}], "correct_answer": "大", "explanations": {"大": "反义：“大”与“小”相对，表示体积、数量、程度、年龄等超过比较对象。", "远": "无关：“远”指距离长，与“小”不构成反义或近义关系。", "厚": "无关：“厚”指物体两面之间的距离大，与“小”没有反义关系。", "快": "无关：“快”指速度高，与“小”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10567, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指体积、数量、程度、年龄等不大或比较低。", "primary_collocate": null, "pronunciation": "xiǎo", "ipa": "ɕjɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他年纪还小，不能一个人出门。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子很小，才两岁。", "target_word": "小", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次的错误很小，不用担心。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的声音很小，我听不见。", "target_word": "小", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家公司的规模很小，只有五个人。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间不大，窗户也很小。", "target_word": "小", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们班很小，只有十个学生。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟比我小三岁。", "target_word": "小", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们家的院子很小，只能种几棵花。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年的雨量比去年小得多。", "target_word": "小", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "小小", "label": "重叠"}], "register": "中性", "sense_fingerprint": "体积、数量、程度、年龄等不大或偏低", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19817550-c904-44e4-a2d8-d2169ad3d57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10567, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小", "is_correct": true, "explanation": "本词：小（xiǎo，第三声），指体积、数量、程度、年龄等不大或比较低。"}, {"text": "笑", "is_correct": false, "explanation": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“笑”。"}, {"text": "效", "is_correct": false, "explanation": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“效果”。"}, {"text": "想", "is_correct": false, "explanation": "韵母不同：xiǎng 的韵母是 -ang，xiǎo 的韵母是 -ao，意思是“想念”。"}, {"text": "消", "is_correct": false, "explanation": "声调不同：xiāo（第一声）与 xiǎo（第三声）声调不同，意思是“消除”。"}], "explanations": {"小": "本词：小（xiǎo，第三声），指体积、数量、程度、年龄等不大或比较低。", "笑": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“笑”。", "效": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“效果”。", "想": "韵母不同：xiǎng 的韵母是 -ang，xiǎo 的韵母是 -ao，意思是“想念”。", "消": "声调不同：xiāo（第一声）与 xiǎo（第三声）声调不同，意思是“消除”。"}, "sentence_index": null, "correct_answer": "小"}, "level_3": {"options": [{"text": "小", "is_correct": true, "explanation": "正确：“年纪还小”指年龄不大，“小”与“年纪”搭配，句意通顺。"}, {"text": "老", "is_correct": false, "explanation": "语义：“还”表示尚未，与“老”的含义相冲突，“年纪还老”说不通。"}, {"text": "短", "is_correct": false, "explanation": "搭配：“短”形容长度或时间，不能修饰“年纪”。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容身高，不能用来形容年纪。"}], "explanations": {"小": "正确：“年纪还小”指年龄不大，“小”与“年纪”搭配，句意通顺。", "老": "语义：“还”表示尚未，与“老”的含义相冲突，“年纪还老”说不通。", "短": "搭配：“短”形容长度或时间，不能修饰“年纪”。", "矮": "体貌：“矮”形容身高，不能用来形容年纪。"}, "sentence_index": 0, "correct_answer": "小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们只聊了很小的时间。", "explanation": "这里应该用〈短〉。“小”说体积、数量或程度不大，说时间长短要用“短”，“很小的时间”不这么用。"}, {"text": "他跑得很小，我很容易就追上了他。", "explanation": "这里应该用〈慢〉。“小”说体积、数量、程度不大，说速度要用“快/慢”，“跑得很小”不这么说。"}, {"text": "今天的天气很小，出门要多穿衣服。", "explanation": "这里应该用〈冷〉。“小”不用来说气温，天气冷热要用“冷/热”，“天气很小”不这么说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10567, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "小", "is_correct": true, "explanation": "本词：小（xiǎo，第三声），指体积、数量、程度、年龄等不大或比较低。"}, {"text": "脚", "is_correct": false, "explanation": "声母不同：jiǎo 的声母是 j，xiǎo 的声母是 x，意思是“脚”。"}, {"text": "校", "is_correct": false, "explanation": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“学校”。"}, {"text": "险", "is_correct": false, "explanation": "韵母不同：xiǎn 的韵母是 -an，xiǎo 的韵母是 -ao，意思是“危险”。"}, {"text": "享", "is_correct": false, "explanation": "韵母不同：xiǎng 的韵母是 -ang，xiǎo 的韵母是 -ao，意思是“享受”。"}], "explanations": {"小": "本词：小（xiǎo，第三声），指体积、数量、程度、年龄等不大或比较低。", "脚": "声母不同：jiǎo 的声母是 j，xiǎo 的声母是 x，意思是“脚”。", "校": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“学校”。", "险": "韵母不同：xiǎn 的韵母是 -an，xiǎo 的韵母是 -ao，意思是“危险”。", "享": "韵母不同：xiǎng 的韵母是 -ang，xiǎo 的韵母是 -ao，意思是“享受”。"}, "sentence_index": null, "correct_answer": "小"}, "level_3": {"options": [{"text": "小", "is_correct": true, "explanation": "正确：“我们班很小”指班级人数少，“小”用于数量，与后句“只有十个学生”相符。"}, {"text": "多", "is_correct": false, "explanation": "语义：“多”表示数量大，与后句“只有十个学生”的说明相矛盾。"}, {"text": "长", "is_correct": false, "explanation": "搭配：“长”形容长度，不能用来修饰“班”。"}, {"text": "窄", "is_correct": false, "explanation": "搭配：“窄”形容宽度，不能用来形容“班”的规模。"}], "explanations": {"小": "正确：“我们班很小”指班级人数少，“小”用于数量，与后句“只有十个学生”相符。", "多": "语义：“多”表示数量大，与后句“只有十个学生”的说明相矛盾。", "长": "搭配：“长”形容长度，不能用来修饰“班”。", "窄": "搭配：“窄”形容宽度，不能用来形容“班”的规模。"}, "sentence_index": 6, "correct_answer": "小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家离学校很小，要坐一个小时车。", "explanation": "这里应该用〈远〉。“小”说体积或数量不大，说距离要用“远”，“离学校很小”不这么用。"}, {"text": "我们等了很小的时间，才见到他。", "explanation": "这里应该用〈长〉。“小”不用于说时间的久暂，时间久要用“长”，“很小的时间”不这么用。"}, {"text": "他们之间的感情很小，几乎不往来。", "explanation": "这里应该用〈深〉。“小”说体积、数量或程度不大，感情深厚要用“深”，“感情很小”不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10567, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间屋子小很，只能放一张床。", "corrected_sentence": "这间屋子小得很，只能放一张床。", "error_description": "位置错误：程度副词“很”应放在形容词前，说“很小”；放在形容词后须用“得”，即“小得很”，不能说“小很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10567, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小区的规模小很，只有两栋楼。", "corrected_sentence": "这个小区的规模很小，只有两栋楼。", "error_description": "位置错误：“很”是程度副词，应放在形容词前，说“很小”，不说“小很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10568, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10568, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10568, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以农业为主要经济来源的家庭。", "primary_collocate": null, "pronunciation": "nóng hù", "ipa": "nʊŋ˧˥ xu˥˩", "syllable_count": 2, "sentences": [{"text": "气候变化导致适宜种植区收缩，极端天气频发，产量稳定性受到影响；面对市场风险时，农户普遍缺乏金融工具与信息支持。", "target_word": "农户", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这家农户今年种了二十亩玉米。", "target_word": "农户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府给农户发了补贴。", "target_word": "农户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下大雨以后，农户担心粮食会减产。", "target_word": "农户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "许多农户在春天开始播种。", "target_word": "农户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的农户大多种玉米。", "target_word": "农户", "complexity_tier": "T3", "furigana": "cūn lǐ de nóng hù dà duō zhòng yù mǐ", "sentence_source": "generated"}, {"text": "这家农户通过网络把苹果卖到了城里。", "target_word": "农户", "complexity_tier": "T3", "furigana": "zhè jiā nóng hù tōng guò wǎng luò bǎ píng guǒ mài dào le chéng lǐ", "sentence_source": "generated"}, {"text": "农户们希望今年有个好收成。", "target_word": "农户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "技术员来村里教农户使用新机器。", "target_word": "农户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "贫困农户可以申请小额贷款。", "target_word": "农户", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "户", "label": "量词"}, {"form": "小农户", "label": "复合"}, {"form": "農戶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "靠农业收入生活的家庭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929f630-bb3e-4acd-8c80-d8e8929653e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10568, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小学生", "is_correct": false, "explanation": "语义：“小学生”指儿童，不会面对市场风险、缺乏金融工具，与句子讲的农业经营语境不符。"}, {"text": "农户", "is_correct": true, "explanation": "“农户”指以农业为主要经济来源的家庭，符合“面对市场风险、缺乏金融工具与信息支持”的语境。"}, {"text": "小伙子", "is_correct": false, "explanation": "语域：“小伙子”是口语说法，不适用于这份书面报告的语境。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：“小猫”不是人群，不能面对市场风险或缺乏金融工具。"}], "explanations": {"小学生": "语义：“小学生”指儿童，不会面对市场风险、缺乏金融工具，与句子讲的农业经营语境不符。", "农户": "“农户”指以农业为主要经济来源的家庭，符合“面对市场风险、缺乏金融工具与信息支持”的语境。", "小伙子": "语域：“小伙子”是口语说法，不适用于这份书面报告的语境。", "小猫": "语义：“小猫”不是人群，不能面对市场风险或缺乏金融工具。"}, "sentence_index": 0, "correct_answer": "农户"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我叔叔是个勤劳的农户。", "explanation": "这里应该用〈农民〉。农户指以家庭为单位的经营户，说某个人的身份要用农民。"}, {"text": "这家农户在城里开了三家连锁分店，雇了五十名员工。", "explanation": "这里应该用〈企业〉。农户指家庭经营的小规模农业单位，连锁分店和大量员工的经营不能称农户。"}, {"text": "超市里的农户很新鲜，价格也便宜。", "explanation": "这里应该用〈农产品〉。农户指以农业为生的家庭，超市里卖的蔬菜水果要说农产品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10568, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游客", "is_correct": false, "explanation": "语义：游客不会种苹果并通过网络把苹果卖到城里，与“这家”的经营主体不符。"}, {"text": "农户", "is_correct": true, "explanation": "“农户”指以农业为主要经济来源的家庭，符合“种苹果并通过网络卖到城里”的语境。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人不会经营果园，也不会把苹果卖到城里。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：量词“家”不能与“老师”搭配，应说“这位老师”。"}], "explanations": {"游客": "语义：游客不会种苹果并通过网络把苹果卖到城里，与“这家”的经营主体不符。", "农户": "“农户”指以农业为主要经济来源的家庭，符合“种苹果并通过网络卖到城里”的语境。", "病人": "语义：病人不会经营果园，也不会把苹果卖到城里。", "老师": "搭配：量词“家”不能与“老师”搭配，应说“这位老师”。"}, "sentence_index": 6, "correct_answer": "农户"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家农户已经在纳斯达克上市了。", "explanation": "这里应该用〈公司〉。农户是以家庭为单位的生产单位，不能说上市。"}, {"text": "这家农户的医生很多。", "explanation": "这里应该用〈医院〉。农户是家庭经营的农业单位，不能说有医生。"}, {"text": "这家农户有一千名学生。", "explanation": "这里应该用〈学校〉。农户指家庭经营单位，不能说有学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10568, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里有几只农户已经开始使用无人机喷药。", "corrected_sentence": "村里有几户农户已经开始使用无人机喷药。", "error_description": "错误：量词用错。“农户”以家庭为单位，应用量词“户”，“只”用于动物和部分物品。应改为“几户农户”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10568, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们村有三十多户农户们。", "corrected_sentence": "我们村有三十多户农户。", "error_description": "错误：“农户”前已有数量词“三十多户”，后面不能再加“们”。应删去“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
