INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10574, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10574, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "金融工具是用于资金融通的书面凭证或合约，比如股票、债券、基金等，可以帮助人们投资、融资或管理风险。", "primary_collocate": null, "pronunciation": "jīn róng gōng jù", "ipa": "tɕin˥ ʐʊŋ˧˥ kʊŋ˥ tɕy˥˩", "syllable_count": 4, "sentences": [{"text": "这种公私协作的创新融资模式，催生了“环境收益债券”等新型金融工具，将碳汇增量、能源节约与居民健康改善等外部性效益证券化，开辟了可持续投资的量化回报路径。", "target_word": "金融工具", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "气候变化导致适宜种植区收缩，极端天气频发影响产量稳定性；全球航运成本波动、地缘政治紧张以及关税政策调整均可能扰乱贸易流向；同时，小农户在面对市场风险时普遍缺乏金融工具与信息支持。", "target_word": "金融工具", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "股票是常见的金融工具。", "target_word": "金融工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行提供多种金融工具。", "target_word": "金融工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种金融工具可以帮人管理风险。", "target_word": "金融工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学习怎么用金融工具投资。", "target_word": "金融工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "债券和基金都是金融工具。", "target_word": "金融工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的金融工具让借钱更方便了。", "target_word": "金融工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小公司也需要金融工具来融资。", "target_word": "金融工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们介绍了几种金融工具。", "target_word": "金融工具", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "衍生金融工具", "label": "复合"}, {"form": "新型金融工具", "label": "复合"}], "register": "书面", "sense_fingerprint": "股票、债券、基金等用于投资融资的凭证或合约", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45fe73ad-99b7-41e9-9b37-32d47e8af85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10574, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "金融工具", "is_correct": true, "explanation": "填入“金融工具”：环境收益债券属于一类新型融资凭证，“新型金融工具”指这类新的金融工具，与句意相符。"}, {"text": "金融机构", "is_correct": false, "explanation": "语义：债券是金融凭证，不是机构，“等新型金融机构”与“环境收益债券”并列不通。"}, {"text": "农药", "is_correct": false, "explanation": "语义：农药与债券、碳汇和投资无关，句中催生的是金融创新，不可能是农药。"}, {"text": "乐曲", "is_correct": false, "explanation": "语义：乐曲是音乐作品，与“债券”的金融语境无关，“新型乐曲”不通。"}], "explanations": {"金融工具": "填入“金融工具”：环境收益债券属于一类新型融资凭证，“新型金融工具”指这类新的金融工具，与句意相符。", "金融机构": "语义：债券是金融凭证，不是机构，“等新型金融机构”与“环境收益债券”并列不通。", "农药": "语义：农药与债券、碳汇和投资无关，句中催生的是金融创新，不可能是农药。", "乐曲": "语义：乐曲是音乐作品，与“债券”的金融语境无关，“新型乐曲”不通。"}, "sentence_index": 0, "correct_answer": "金融工具"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "银行提供一本金融工具。", "explanation": "这里应该用〈种〉。“本”用于书籍、册子，金融工具要用“种”或“类”。"}, {"text": "他在金融工具工作。", "explanation": "这里应该用〈金融机构〉。金融工具指股票、债券等金融凭证，不是工作的场所，“在…工作”要用机构。"}, {"text": "工匠用多种金融工具修理房子。", "explanation": "这里应该用〈锤子〉等实体器具。“金融工具”指股票、债券等金融凭证，不能用来修房子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10574, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "金融工具", "is_correct": true, "explanation": "填入“金融工具”：债券和基金都是金融凭证，属于金融工具的范畴，与句意相符。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：债券和基金是金融凭证，不是蔬菜，“都是蔬菜”与句意完全不符。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：债券和基金不能是宠物，与句中所述的金融性质矛盾。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器不是金融凭证，“债券和基金都是乐器”与句意完全不符。"}], "explanations": {"金融工具": "填入“金融工具”：债券和基金都是金融凭证，属于金融工具的范畴，与句意相符。", "蔬菜": "语义：债券和基金是金融凭证，不是蔬菜，“都是蔬菜”与句意完全不符。", "宠物": "语义：债券和基金不能是宠物，与句中所述的金融性质矛盾。", "乐器": "语义：乐器不是金融凭证，“债券和基金都是乐器”与句意完全不符。"}, "sentence_index": 6, "correct_answer": "金融工具"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生用金融工具检查病人。", "explanation": "这里应该用〈仪器〉。金融工具指股票、债券等金融凭证，不能用来检查病人。"}, {"text": "工人用金融工具修好了车床。", "explanation": "这里应该用〈机械〉。金融工具是金融凭证，不能用来修理车床。"}, {"text": "老师给我们介绍了一台金融工具。", "explanation": "这里应该用〈种〉。“台”多用于机器、电器，金融工具要用“种”或“类”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想了解一只金融工具。", "corrected_sentence": "他想了解一种金融工具。", "error_description": "量词错误：“金融工具”应与“种”搭配，说“一只”不对（“只”多用于动物及成对物品中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师给我们介绍了金融工具们。", "corrected_sentence": "老师给我们介绍了金融工具。", "error_description": "“们”只加在指人的名词后，“金融工具”指事物，不能加“们”，应直接说“金融工具”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10576, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "国内", "is_correct": true, "explanation": "与“国际”相对，指一国之内，不涉及其他国家，二者构成反义。"}, {"text": "安静", "is_correct": false, "explanation": "形容声音或环境不吵闹，与“国际”没有反义关系。"}, {"text": "勇敢", "is_correct": false, "explanation": "形容不怕危险，与“国际”没有反义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "形容地势或坡度很陡，与“国际”没有反义关系。"}], "correct_answer": "国内", "explanations": {"国内": "与“国际”相对，指一国之内，不涉及其他国家，二者构成反义。", "安静": "形容声音或环境不吵闹，与“国际”没有反义关系。", "勇敢": "形容不怕危险，与“国际”没有反义关系。", "陡峭": "形容地势或坡度很陡，与“国际”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10576, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "国内", "is_correct": true, "explanation": "与“国际”相对，指一国之内，不涉及其他国家，二者构成反义。"}, {"text": "清楚", "is_correct": false, "explanation": "形容清晰、明白，与“国际”没有反义关系。"}, {"text": "暗淡", "is_correct": false, "explanation": "形容光线微弱或前景不明朗，与“国际”没有反义关系。"}, {"text": "亲切", "is_correct": false, "explanation": "形容态度和蔼、让人感到温暖，与“国际”没有反义关系。"}], "correct_answer": "国内", "explanations": {"国内": "与“国际”相对，指一国之内，不涉及其他国家，二者构成反义。", "清楚": "形容清晰、明白，与“国际”没有反义关系。", "暗淡": "形容光线微弱或前景不明朗，与“国际”没有反义关系。", "亲切": "形容态度和蔼、让人感到温暖，与“国际”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10576, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "国与国之间；世界各国之间。", "primary_collocate": null, "pronunciation": "guó jì", "ipa": "kwo˧˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "这是一场国际比赛。", "target_word": "国际", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天看国际新闻。", "target_word": "国际", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "北京有很大的国际机场。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司有很多国际客户。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际航班因为大雪取消了。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想参加明年的国际会议。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际电话比国内电话贵。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是一位有名的国际歌手。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际市场上，咖啡的价格涨了。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际邮件要等一个星期。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "国际化", "label": "复合"}, {"form": "国际象棋", "label": "复合"}, {"form": "國際", "label": "繁体"}], "register": "中性", "sense_fingerprint": "涉及多个国家、面向世界的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929f630-bb3e-4acd-8c80-d8e8929653e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10576, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "国际", "is_correct": true, "explanation": "正确答案。国际读作 guó jì，指国与国之间的。"}, {"text": "国籍", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，意思是国籍。"}, {"text": "过季", "is_correct": false, "explanation": "guò（第四声）与 guó（第二声）声调不同，意思是过了季节。"}, {"text": "国境", "is_correct": false, "explanation": "jìng 比 jì 多了韵尾 ng，意思是国家的边界。"}], "explanations": {"国际": "正确答案。国际读作 guó jì，指国与国之间的。", "国籍": "jí（第二声）与 jì（第四声）声调不同，意思是国籍。", "过季": "guò（第四声）与 guó（第二声）声调不同，意思是过了季节。", "国境": "jìng 比 jì 多了韵尾 ng，意思是国家的边界。"}, "sentence_index": null, "correct_answer": "国际"}, "level_3": {"options": [{"text": "国际", "is_correct": true, "explanation": "正确：“国际比赛”指国与国之间举行的比赛，与句意相符。"}, {"text": "深刻", "is_correct": false, "explanation": "搭配：“比赛”不能用“深刻”修饰，“深刻”多用于思想、印象等。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容天气或温度，不能修饰比赛这类活动。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”形容心情，不能用来修饰比赛。"}], "explanations": {"国际": "正确：“国际比赛”指国与国之间举行的比赛，与句意相符。", "深刻": "搭配：“比赛”不能用“深刻”修饰，“深刻”多用于思想、印象等。", "寒冷": "语义：“寒冷”形容天气或温度，不能修饰比赛这类活动。", "悲伤": "语义：“悲伤”形容心情，不能用来修饰比赛。"}, "sentence_index": 0, "correct_answer": "国际"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国际的气温这几年一直在升高。", "explanation": "这里应该用〈全球〉。“国际”指国与国之间，说整个地球的气温要用“全球”。"}, {"text": "我为我的国际而骄傲。", "explanation": "这里应该用〈国家〉。“国际”指国与国之间，不能用来指自己所属的国家，表达“我的国家”要用“国家”。"}, {"text": "国际上最高的山是珠峰。", "explanation": "这里应该用〈世界〉。“国际上”指国与国之间的范围，地球上最高的山要说“世界上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10576, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际", "is_correct": true, "explanation": "正确：“国际电话”指打往其他国家的电话，价格比国内电话贵，与句意相符。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“便宜电话比国内电话贵”自相矛盾，与“贵”的比较意思冲突。"}, {"text": "免费", "is_correct": false, "explanation": "语义：免费的电话不会比国内电话贵，与句子的比较意思矛盾。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”形容场所或气氛，不能用来修饰“电话”。"}], "explanations": {"国际": "正确：“国际电话”指打往其他国家的电话，价格比国内电话贵，与句意相符。", "便宜": "语义：“便宜电话比国内电话贵”自相矛盾，与“贵”的比较意思冲突。", "免费": "语义：免费的电话不会比国内电话贵，与句子的比较意思矛盾。", "冷清": "搭配：“冷清”形容场所或气氛，不能用来修饰“电话”。"}, "sentence_index": 6, "correct_answer": "国际"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条国际法律只适用于我们省。", "explanation": "这里应该用〈地方〉。“国际”指国与国之间，只适用于一个省的法规要说“地方法规”。"}, {"text": "我每天都去国际的菜市场买菜。", "explanation": "这里应该用〈本地〉。“国际”指国与国之间，一个城市的菜市场要说“本地的菜市场”。"}, {"text": "他在国际的一个小镇上班。", "explanation": "这里应该用〈国内〉。“国际”指国与国之间，修饰小镇这种地方要用“国内”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们昨天看了一场国际了比赛。", "corrected_sentence": "我们昨天看了一场国际比赛。", "error_description": "语法错误：区别词“国际”修饰名词时后面不能加动态助词“了”，应去掉“了”。正确说法是“看了一场国际比赛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天收到很多国际了邮件。", "corrected_sentence": "我每天收到很多国际邮件。", "error_description": "语法错误：区别词“国际”修饰名词时后面不能加动态助词“了”，应去掉“了”。正确说法是“收到很多国际邮件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10577, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "与“组织”（把分散的人或事物组合成整体）相对，表示使人或事物散开，二者构成反义。"}, {"text": "睡觉", "is_correct": false, "explanation": "指入睡或休息，与“组织”没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "指把坏了的东西弄好，与“组织”没有反义关系。"}, {"text": "吹奏", "is_correct": false, "explanation": "指用乐器演奏，与“组织”没有反义关系。"}], "correct_answer": "分散", "explanations": {"分散": "与“组织”（把分散的人或事物组合成整体）相对，表示使人或事物散开，二者构成反义。", "睡觉": "指入睡或休息，与“组织”没有反义关系。", "修理": "指把坏了的东西弄好，与“组织”没有反义关系。", "吹奏": "指用乐器演奏，与“组织”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10577, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "与“组织”（把分散的人或事物组合成整体）相对，表示使人或事物散开，二者构成反义。"}, {"text": "游泳", "is_correct": false, "explanation": "指在水中划动身体前进，与“组织”没有反义关系。"}, {"text": "洗涤", "is_correct": false, "explanation": "指用水或其他液体清洗，与“组织”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "指用声音演唱，与“组织”没有反义关系。"}], "correct_answer": "分散", "explanations": {"分散": "与“组织”（把分散的人或事物组合成整体）相对，表示使人或事物散开，二者构成反义。", "游泳": "指在水中划动身体前进，与“组织”没有反义关系。", "洗涤": "指用水或其他液体清洗，与“组织”没有反义关系。", "唱歌": "指用声音演唱，与“组织”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
